(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("pausanias-2-e", [{"sp": "HDR", "t": "Ἑλλάδος Περιήγησις"}, {"sp": "HDR", "t": "Βιβλίον Γʹ — Λακωνικά", "st": "3"}, {"sp": "N", "t": "μετὰ δὲ τοὺς Ἑρμᾶς ἐστιν ἤδη Λακωνικὴ τὰ πρὸς ἑσπέρας. ὡς δὲ αὐτοὶ Λακεδαιμόνιοι λέγουσι, Λέλεξ αὐτόχθων ὢν ἐβασίλευσε πρῶτος ἐν τῇ γῇ ταύτῃ καὶ ἀπὸ τούτου Λέλεγες ὧν ἦρχεν ὠνομάσθησαν. Λέλεγος δὲ γίνεται Μύλης καὶ νεώτερος Πολυκάων. Πολυκάων μὲν δὴ ὅποι καὶ δι’ ἥντινα αἰτίαν ἀπεχώρησεν, ἑτέρωθι δηλώσω· Μύλητος δὲ τελευτήσαντος παρέλαβεν ὁ παῖς Εὐρώτας τὴν ἀρχήν. οὗτος τὸ ὕδωρ τὸ λιμνάζον ἐν τῷ πεδίῳ διώρυγι κατήγαγεν ἐπὶ θάλασσαν, ἀπορρυέντος δὲ—ἦν γὰρ δὴ τὸ ὑπόλοιπον ποταμοῦ ῥεῦμα— ὠνόμασεν Εὐρώταν.", "st": "3.1"}, {"sp": "N", "t": "ἅτε δὲ οὐκ ὄντων αὐτῷ παίδων ἀρρένων βασιλεύειν καταλείπει Λακεδαίμονα, μητρὸς μὲν Ταϋγέτης ὄντα, ἀφ’ ἧς καὶ τὸ ὄρος ὠνομάσθη, ἐς Δία δὲ πατέρα ἀνήκοντα κατὰ τὴν φήμην· συνῴκει δὲ ὁ Λακεδαίμων Σπάρτῃ θυγατρὶ τοῦ Εὐρώτα. τότε δὲ ὡς ἔσχε τὴν ἀρχήν, πρῶτα μὲν τῇ χώρᾳ καὶ τοῖς ἀνθρώποις μετέθετο ἀφ’ αὑτοῦ τὰ ὀνόματα, μετὰ δὲ τοῦτο ᾤκισέ τε καὶ ὠνόμασεν ἀπὸ τῆς γυναικὸς πόλιν, ἣ Σπάρτη καλεῖται καὶ ἐς ἡμᾶς.", "st": "3.1"}, {"sp": "N", "t": "Ἀμύκλας δὲ ὁ Λακεδαίμονος, βουλόμενος ὑπολιπέσθαι τι καὶ αὐτὸς ἐς μνήμην, πόλισμα ἔκτισεν ἐν τῇ Λακωνικῇ. γενομένων δέ οἱ παίδων Ὑάκινθον μὲν νεώτατον ὄντα καὶ τὸ εἶδος κάλλιστον κατέλαβεν ἡ πεπρωμένη πρότερον τοῦ πατρός, καὶ Ὑακίνθου μνῆμά ἐστιν ἐν Ἀμύκλαις ὑπὸ τὸ ἄγαλμα τοῦ Ἀπόλλωνος. ἀποθανόντος δὲ Ἀμύκλα ἐς Ἄργαλον τὸν πρεσβύτατον τῶν Ἀμύκλα παίδων καὶ ὕστερον ἐς Κυνόρταν Ἀργάλου τελευτήσαντος ἀφίκετο ἡ ἀρχή.", "st": "3.1"}, {"sp": "N", "t": "Κυνόρτα δὲ ἐγένετο Οἴβαλος. οὗτος Γοργοφόνην τε τὴν Περσέως γυναῖκα ἔσχεν ἐξ Ἄργους καὶ παῖδα ἔσχε Τυνδάρεων, ᾧ περὶ τῆς βασιλείας Ἱπποκόων ἠμφισβήτει καὶ κατὰ πρεσβείαν ἔχειν ἠξίου τὴν ἀρχήν. προσλαβὼν δὲ Ἰκάριον καὶ τοὺς στασιώτας παρὰ πολύ τε ὑπερεβάλετο δυνάμει Τυνδάρεων καὶ ἠνάγκασεν ἀποχωρῆσαι δείσαντα, ὡς μὲν Λακεδαιμόνιοί φασιν, ἐς Πελλάναν, Μεσσηνίων δέ ἐστιν ἐς αὐτὸν λόγος Τυνδάρεων φεύγοντα ἐλθεῖν ὡς Ἀφαρέα ἐς τὴν Μεσσηνίαν εἶναί τε Ἀφαρέα τὸν Περιήρους ἀδελφὸν Τυνδάρεω πρὸς μητρός· καὶ οἰκῆσαί τε αὐτὸν τῆς Μεσσηνίας φασὶν ἐν Θαλάμαις καὶ τοὺς παῖδας ἐνταῦθα οἰκοῦντι αὐτῷ γενέσθαι.", "st": "3.1"}, {"sp": "N", "t": "χρόνῳ δὲ ὕστερον κατῆλθέ τε ὑπὸ Ἡρακλέους Τυνδάρεως καὶ ἀνενεώσατο τὴν ἀρχὴν· ἐβασίλευσαν δὲ καὶ οἱ Τυνδάρεω παῖδες καὶ Μενέλαος ὁ Ἀτρέως Τυνδάρεω γαμβρὸς ὢν Ὀρέστης τε Ἑρμιόνῃ τῇ Μενελάου συνοικῶν. κατελθόντων δὲ Ἡρακλειδῶν ἐπὶ Τισαμενοῦ τοῦ Ὀρέστου βασιλεύοντος, Μεσσήνη μὲν καὶ Ἄργος ἑκατέρα μοῖρα Τήμενον, ἡ δὲ Κρεσφόντην ἔσχεν ἄρχοντας· ἐν Λακεδαίμονι δὲ ὄντων διδύμων τῶν Ἀριστοδήμου παίδων οἰκίαι δύο βασίλειαι γίνονται·", "st": "3.1"}, {"sp": "N", "t": "συναρέσαι γὰρ τῇ Πυθίᾳ φασίν. Ἀριστοδήμῳ δὲ αὐτῷ πρότερον τὴν τελευτὴν συμβῆναι λέγουσιν ἐν Δελφοῖς πρὶν ἢ Δωριέας κατελθεῖν ἐς Πελοπόννησον. οἱ μὲν δὴ ἀποσεμνύνοντες τὰ ἐς αὐτὸν τοξευθῆναι λέγουσιν Ἀριστόδημον ὑπὸ Ἀπόλλωνος, ὅτι οὐκ ἀφίκοιτο ἐπὶ τὸ μαντεῖον, παρὰ δὲ Ἡρακλέους ἐντυχόντος οἱ πρότερον πύθοιτο ὡς ἐς Πελοπόννησον Δωριεῦσι γενήσεται ἥδε ἡ κάθοδος· ὁ δὲ ἀληθέστερος ἔχει λόγος Πυλάδου τοὺς παῖδας καὶ Ἠλέκτρας, ἀνεψιοὺς ὄντας Τισαμενῷ τῷ Ὀρέστου, φονεῦσαι τὸν Ἀριστόδημον.", "st": "3.1"}, {"sp": "N", "t": "ὀνόματα μὲν δὴ τοῖς παισὶν αὐτοῦ Προκλῆς καὶ Εὐρυσθένης ἐτέθη, δίδυμοι δὲ ὄντες διάφοροι τὰ μάλιστα ἦσαν. προεληλυθότες δὲ ἐπὶ μέγα ἀπεχθείας ὅμως ἐν κοινῷ Θήρᾳ τῷ Αὐτεσίωνος, ἀδελφῷ τῆς μητρὸς σφῶν ὄντι Ἀργείας, ἐπιτροπεύσαντι δὲ καὶ αὐτῶν, συνήραντο ἐς ἀποικίαν. τὴν δὲ ἀποικίαν ὁ Θήρας ἔστελλεν ἐς τὴν νῆσον τὴν τότε ὀνομαζομένην Καλλίστην, τοὺς ἀπογόνους οἱ τοῦ Μεμβλιάρου παραχωρήσεσθαι τῆς βασιλείας ἐλπίζων ἑκόντας, ὅπερ οὖν καὶ ἐποίησαν", "st": "3.1"}, {"sp": "N", "t": "λαβόντες λογισμὸν ὅτι Θήρᾳ μὲν ἐς αὐτὸν ἀνῄει Κάδμον τὸ γένος, οἱ δὲ ἦσαν ἀπόγονοι Μεμβλιάρου· Μεμβλίαρον δὲ ἄνδρα ὄντα τοῦ δήμου Κάδμος ἐν τῇ νήσῳ κατέλιπεν ἡγεμόνα εἶναι τῶν ἐποίκων. καὶ Θήρας μὲν τῇ τε νήσῳ μετέβαλεν ἀφ’ ἑαυτοῦ τὸ ὄνομα καί οἱ καὶ νῦν ἔτι οἱ Θηραῖοι κατὰ ἔτος ἐναγίζουσιν ὡς οἰκιστῇ· Προκλεῖ δὲ καὶ Εὐρυσθένει μέχρι μὲν τῆς προθυμίας τῆς ἐς τὸν Θήραν ἐς τὸ αὐτὸ συνῆλθον αἱ γνῶμαι, τὰ δὲ λοιπὰ διειστήκει σφίσιν ἐπὶ παντὶ τὰ βουλεύματα.", "st": "3.1"}, {"sp": "N", "t": "οὐ μὴν οὐδὲ ὁμονοησάντων τοὺς ἀπογόνους αὐτῶν ἐς κοινὸν κατάλογον ὑπάξειν ⟨ἂν⟩ ἔμελλον· οὐ γάρ τι τὰ πάντα ἐς τὸ αὐτὸ συνεληλύθασιν ἡλικίας, ὡς ἀνεψιόν τε ἀνεψιῷ καὶ ἀνεψιῶν παῖδας, ὡσαύτως δὲ καὶ τοὺς κατωτέρω κατὰ ἀριθμὸν τυχεῖν ἀλλήλοις γεγονότας τὸν ἴσον. ἑκατέραν οὖν τὴν οἰκίαν ἐπέξειμι αὐτῶν ἰδίως καὶ οὐκ ἀμφοτέρας ἅμα ἐς τὸ αὐτὸ ἀναμίξας.", "st": "3.1"}, {"sp": "N", "t": "Εὐρυσθένει πρεσβυτέρῳ τῶν Ἀριστοδήμου παίδων ὄντι ἡλικίαν γενέσθαι λέγουσιν υἱὸν Ἆγιν· ἀπὸ τούτου δὲ τὸ γένος τὸ Εὐρυσθένους καλοῦσιν Ἀγιάδας. ἐπὶ τούτου Πατρεῖ τῷ Πρευγένους κτίζοντι ἐν Ἀχαΐᾳ πόλιν, ἥντινα Πάτρας καὶ ἐς ἡμᾶς καλοῦσιν ἀπὸ τοῦ Πατρέως τούτου, συνεπελάβοντο Λακεδαιμόνιοι τοῦ οἰκισμοῦ. συνήραντο δὲ καὶ Γρᾷ τῷ Ἐχέλα τοῦ Πενθίλου τοῦ Ὀρέστου στελλομένῳ ναυσὶν ἐς ἀποικίαν. καὶ ὁ μὲν τὴν τῆς Ἰωνίας μεταξὺ καὶ Μυσῶν, καλουμένην δὲ Αἰολίδα ἐφ’ ἡμῶν, καθέξειν ἔμελλεν· ὁ δέ οἱ πρόγονος Πενθίλος Λέσβον τὴν ὑπὲρ τῆς ἠπείρου ταύτης νῆσον εἷλεν ἔτι πρότερον.", "st": "3.2"}, {"sp": "N", "t": "ἐπὶ δὲ Ἐχεστράτου τοῦ Ἄγιδος βασιλεύοντες ἐν Σπάρτῃ Κυνουρέας τοὺς ἐν [τῇ] ἡλικίᾳ Λακεδαιμόνιοι ποιοῦσιν ἀναστάτους, αἰτίαν ἐπενεγκόντες ὡς τὴν Ἀργολίδα συγγενῶν σφισιν ὄντων Ἀργείων λῃσταί τε ἐκ τῆς Κυνουριακῆς κακουργοῖεν καὶ αὐτοὶ καταδρομὰς ἐκ τοῦ φανεροῦ ποιοῖντο ἐς τὴν γῆν. λέγονται δὲ οἱ Κυνουρεῖς Ἀργεῖοι τὸ ἀνέκαθεν εἶναι, καὶ οἰκιστήν φασιν αὐτῶν Κύνουρον γενέσθαι τὸν Περσέως.", "st": "3.2"}, {"sp": "N", "t": "ἔτεσι δὲ ὕστερον οὐ πολλοῖς Λαβώτας ὁ Ἐχεστράτου τὴν ἀρχὴν ἔσχεν ἐν Σπάρτῃ. τοῦτον τὸν Λαβώταν Ἡρόδοτος ἐν τῷ λόγῳ τῷ ἐς Κροῖσον ὑπὸ Λυκούργου τοῦ θεμένου τοὺς νόμους φησὶν ἐπιτροπευθῆναι παῖδα ὄντα· Λεωβώτην δέ οἱ τίθεται τὸ ὄνομα καὶ οὐ Λαβώταν. Λακεδαιμονίοις δὲ πρῶτον τότε ἔδοξεν ἄρασθαι πρὸς Ἀργείους πόλεμον· ἐποιοῦντο δὲ ἐς αὐτοὺς ἐγκλήματα τήν τε Κυνουριακὴν ἑλόντων αὑτῶν ἀποτέμνεσθαι τοὺς Ἀργείους καὶ τοὺς περιοίκους σφῶν ὑπηκόους ὄντας ἀφιστάναι. τότε μὲν δὴ παρὰ οὐδετέρων πολεμησάντων ὅμως μνήμης ἄξιον πραχθῆναί φασιν οὐδέν·", "st": "3.2"}, {"sp": "N", "t": "τοὺς δὲ ἐφεξῆς βασιλεύσαντας τῆς οἰκίας ταύτης Δόρυσσον τὸν Λαβώτα καὶ Ἀγησίλαον Δορύσσου δι’ ὀλίγου σφᾶς τὸ χρεὼν ἐπέλαβεν ἀμφοτέρους. ἔθηκε δὲ καὶ Λυκοῦργος Λακεδαιμονίοις τοὺς νόμους ἐπὶ τῆς Ἀγησιλάου βασιλείας· θεῖναι δὲ αὐτὸν λέγουσιν οἱ μὲν παρὰ τῆς Πυθίας διδαχθέντα ὑπὲρ αὐτῶν, οἱ δὲ ὡς Κρητικὰ ὄντα νόμιμα ἐπαγάγοιτο. τούτους δὲ οἱ Κρῆτες τοὺς νόμους τεθῆναί σφισιν ὑπὸ Μίνω λέγουσι, βουλεύσασθαι δὲ ὑπὲρ τῶν νόμων οὐκ ἄνευ θεοῦ τὸν Μίνω. ᾐνίξατο δὲ καὶ Ὅμηρος ἐμοὶ δοκεῖν περὶ τοῦ Μίνω τῆς νομοθεσίας ἐν τοῖσδε τοῖς ἔπεσι·<br>τῇσι δ’ ἐνὶ Κνωσσός, μεγάλη πόλις, ἔνθα τε Μίνως<br>ἐννέωρος βασίλευε Διὸς μεγάλου ὀαριστής.", "st": "3.2"}, {"sp": "N", "t": "Λυκούργου μὲν οὖν καὶ ἐν τοῖς ἔπειτα τοῦ λόγου ποιήσομαι μνήμην· Ἀγησιλάου δὲ παῖς ἐγένετο Ἀρχέλαος. ἐπὶ τούτου Λακεδαιμόνιοι πολέμῳ κρατήσαντες πόλιν τῶν περιοικίδων ἠνδραποδίσαντο Αἴγυν, ὑποπτεύσαντες ὡς οἱ Αἰγῦται φρονοῦσι τὰ Ἀρκάδων. Χαρίλαος δὲ ὁ τῆς ἑτέρας οἰκίας βασιλεὺς συνεξεῖλε μὲν καὶ Ἀρχελάῳ τὴν Αἴγυν, ὁπόσα δὲ καὶ ἰδίᾳ Λακεδαιμονίων αὐτὸς ἔδρασεν ἡγούμενος, μνήμην καὶ τῶνδε ποιησόμεθα ὁμοῦ τῷ λόγῳ μεταβάντι ἐς τοὺς Εὐρυπωντίδας καλουμένους.", "st": "3.2"}, {"sp": "N", "t": "Ἀρχελάου δὲ ἦν Τήλεκλος· ἐπὶ τούτου πόλεις Λακεδαιμόνιοι τῶν περιοικίδων πολέμῳ κρατήσαντες ἐξεῖλον Ἀμύκλας καὶ Φᾶριν καὶ Γεράνθρας, ἐχόντων ἔτι Ἀχαιῶν. τούτων Φαρῖται καὶ Γερανθρᾶται τὴν ἔφοδον τῶν Δωριέων καταπλαγέντες ἀπελθεῖν ἐκ Πελοποννήσου συγχωροῦνται ὑπόσπονδοι· τοὺς δὲ Ἀμυκλαιεῖς οὐκ ἐξ ἐπιδρομῆς ἐκβάλλουσιν, ἀλλὰ ἀντισχόντας τε ἐπὶ πολὺ τῷ πολέμῳ καὶ ἔργα οὐκ ἄδοξα ἐπιδειξαμένους. δηλοῦσι δὲ καὶ οἱ Δωριεῖς τρόπαιον ἐπὶ τοῖς Ἀμυκλαιεῦσιν ἀναστήσαντες, ὡς ἐν τῷ τότε λόγου μάλιστα ἄξιον τοῦτο ὑπάρξαν σφίσιν. οὐ πολλῷ δὲ ὕστερον τούτων ἀπέθανεν ὑπὸ Μεσσηνίων Τήλεκλος ἐν Ἀρτέμιδος ἱερῷ· τὸ δὲ ἱερὸν τοῦτο ἐν μεθορίῳ τῆς τε Λακωνικῆς καὶ τῆς Μεσσηνίας ἐπεποίητο ἐν χωρίῳ καλουμένῳ Λίμναις.", "st": "3.2"}, {"sp": "N", "t": "Τηλέκλου δὲ ἀποθανόντος Ἀλκαμένης ἔσχεν ὁ Τηλέκλου τὴν ἀρχήν· καὶ Λακεδαιμόνιοι πέμπουσιν ἐς Κρήτην Χαρμίδαν τὸν Εὔθυος, ἄνδρα ἐν Σπάρτῃ τῶν δοκίμων, στάσεις τε καταπαύσοντα τοῖς Κρησὶ καὶ τὰ πολίσματα, ὁπόσα ἦν ἀπωτέρω θαλάσσης καὶ ἄλλως ἀσθενῆ, ταῦτα μὲν τοὺς Κρῆτας πείσοντα ἐκλιπεῖν, τὰ δὲ ἐν ἐπικαίρῳ τοῦ παράπλου συνοικιοῦντα ἀντ’ αὐτῶν. ἀνέστησαν δὲ καὶ Ἕλος ἐπὶ θαλάσσῃ πόλισμα Ἀχαιῶν ἐχόντων καὶ Ἀργείους τοῖς εἵλωσιν ἀμύναντας μάχῃ νικῶσιν.", "st": "3.2"}, {"sp": "N", "t": "τελευτήσαντος δὲ Ἀλκαμένους Πολύδωρος τὴν βασιλείαν παρέλαβεν ὁ Ἀλκαμένους, καὶ ἀποικίαν τε ἐς Ἰταλίαν Λακεδαιμόνιοι τὴν ἐς Κρότωνα ἔστειλαν καὶ [ἀποικίαν] ἐς Λοκροὺς τοὺς πρὸς ἄκρᾳ Ζεφυρίῳ, καὶ ὁ πόλεμος ὁ καλούμενος Μεσσηνιακὸς Πολυδώρου βασιλεύοντος μάλιστα ἐς ἀκμὴν προῆλθε. λέγουσι δὲ οὐ τὰς αὐτὰς Λακεδαιμόνιοί τε αἰτίας καὶ Μεσσήνιοι τοῦ πολέμου.", "st": "3.3"}, {"sp": "N", "t": "τὰ οὖν λεγόμενα ὑπ’ αὐτῶν, καὶ ὁποῖον ὁ πόλεμος ἔσχεν οὗτος πέρας, τοῦ λόγου μοι τὰ ἐφεξῆς δηλώσει· τοσοῦτον δὲ ἐν τῷ παρόντι μνησθησόμεθα αὐτῶν, τὰ πολλὰ ἡγήσασθαι Λακεδαιμονίοις ἐν τῷ προτέρῳ πρὸς Μεσσηνίους πολέμῳ Θεόπομπον τὸν Νικάνδρου, βασιλέα ὄντα τῆς ἑτέρας οἰκίας. διαπεπολεμημένου δὲ τοῦ πρὸς Μεσσήνην πολέμου καὶ ἤδη Λακεδαιμονίοις δορικτήτου τῆς Μεσσηνίας οὔσης, Πολύδωρον εὐδοκιμοῦντα ἐν Σπάρτῃ καὶ κατὰ γνώμην Λακεδαιμονίων μάλιστα ὄντα τῷ δήμῳ—οὔτε γὰρ ἔργον βίαιον οὔτε ὑβριστὴν λόγον παρείχετο ἐς οὐδένα, ἐν δὲ ταῖς κρίσεσι τὰ δίκαια ἐφύλασσεν οὐκ ἄνευ φιλανθρωπίας, ἔχοντος δὲ ἤδη Πολυδώρου λαμπρὸν", "st": "3.3"}, {"sp": "N", "t": "ἀνὰ πᾶσαν τὴν Ἑλλάδα ὄνομα, Πολέμαρχος οἰκίας ἐν Λακεδαίμονι ἀνὴρ οὐκ ἀδόξου, θρασύτερος δὲ ὡς ἐδήλωσε γνώμην, φονεύει τὸν Πολύδωρον· ἀποθανόντι δὲ αὐτῷ πολλά τε παρὰ Λακεδαιμονίων δέδοται καὶ ἀξιόλογα ἐς τιμήν. ἔστι μέντοι καὶ Πολεμάρχου μνῆμα ἐν Σπάρτῃ, εἴτε ἀγαθοῦ τὰ πρότερα ἀνδρὸς εἶναι νομισθέντος εἴτε καὶ κρύφα οἱ προσήκοντες θάπτουσιν αὐτόν.", "st": "3.3"}, {"sp": "N", "t": "ἐπὶ μὲν δὴ Εὐρυκράτους τοῦ Πολυδώρου βασιλεύοντος Μεσσήνιοί τε ἠνείχοντο ὑπήκοοι Λακεδαιμονίων ὄντες καὶ παρὰ τοῦ δήμου τοῦ Ἀργείων οὐδέν σφισιν ἀπήντησε νεώτερον· ἐπὶ δὲ Ἀναξάνδρου τοῦ Εὐρυκράτους—τὸ γὰρ χρεὼν ἤδη Μεσσηνίους ἤλαυνεν ἐκτὸς Πελοποννήσου πάσης—ἀφίστανται Λακεδαιμονίων οἱ Μεσσήνιοι. καὶ χρόνον μὲν ἀντέσχον πολεμοῦντες· ὑπόσπονδοι δὲ ὡς ἐκρατήθησαν ἀπῄεσαν ἐκ Πελοποννήσου, τὸ δὲ αὐτῶν ἐγκαταλειφθὲν τῇ γῇ Λακεδαιμονίων ἐγένοντο οἰκέται πλὴν οἱ τὰ ἐπὶ τῇ θαλάσσῃ πολίσματα ἔχοντες.", "st": "3.3"}, {"sp": "N", "t": "τὰ μὲν δὴ ἐπὶ τοῦ πολέμου συμβάντα, ὃν οἱ Μεσσήνιοι Λακεδαιμονίων ἀποστάντες ἐπολέμησαν, οὔ μοι κατὰ καιρὸν ἦν ἐν τῇ συγγραφῇ τῇ παρούσῃ δηλῶσαι· Ἀναξάνδρου δὲ υἱὸς Εὐρυκράτης γίνεται, Εὐρυκράτους δὲ τοῦ δευτέρου Λέων. ἐπὶ τούτων βασιλευόντων Λακεδαιμόνιοι προσέπταιον ἐν τῷ πρὸς Τεγεάτας πολέμῳ τὰ πλείονα. ἐπὶ δὲ Ἀναξανδρίδου τοῦ Λέοντος ἐπικρατέστεροι Τεγεατῶν γίνονται τῷ πολέμῳ· γίνονται δὲ οὕτως. ἀνὴρ Λακεδαιμόνιος Λίχας ὄνομα ἀφίκετο ἐς Τεγέαν·", "st": "3.3"}, {"sp": "N", "t": "τηνικαῦτα δὲ αἱ πόλεις ἄγουσαι σπονδὰς ἔτυχον. ἀφικομένου δὲ τοῦ Λίχα Ὀρέστου τὰ ὀστᾶ ἀνεζήτουν· ἀνεζήτουν δὲ αὐτὰ ἐκ θεοπροπίου Σπαρτιᾶται. συνῆκεν οὖν ὁ Λίχας ὡς ἔστι κατακείμενα ἐν οἰκίᾳ χαλκέως, συνῆκε δὲ οὕτως· ὁπόσα ἐν τῇ τοῦ χαλκέως ἑώρα, παρέβαλεν αὐτὰ πρὸς τὸ ἐκ Δελφῶν μάντευμα, ἀνέμοις μὲν τοῦ χαλκέως εἰκάζων τὰς φύσας, ὅτι καὶ αὐταὶ βίαιον πνεῦμα ἠφίεσαν, τύπον δὲ τὴν σφῦραν καὶ τὸν ἄκμονα ἀντίτυπον ταύτῃ, πῆμα δὲ εἰκότως ἀνθρώπῳ τὸν σίδηρον, ὅτι ἐχρῶντο ἐς τὰς μάχας ἤδη τῷ σιδήρῳ· τὰ δὲ ἐπὶ τῶν ἡρώων καλουμένων ἂν εἶπεν ὁ θεὸς ἀνθρώπῳ πῆμα εἶναι τὸν χαλκόν.", "st": "3.3"}, {"sp": "N", "t": "τῷ χρησμῷ δὲ τῷ γενομένῳ Λακεδαιμονίοις ἐς τοῦ Ὀρέστου τὰ ὀστᾶ καὶ Ἀθηναίοις ὕστερον ἐοικότα ἐχρήσθη κατάγουσιν ἐς Ἀθήνας ἐκ Σκύρου Θησέα, ἄλλως δὲ οὐκ εἶναί σφισιν ἑλεῖν Σκῦρον· ἀνεῦρε δὲ [δὴ] τὰ ὀστᾶ τοῦ Θησέως Κίμων ὁ Μιλτιάδου, σοφίᾳ χρησάμενος καὶ οὗτος, καὶ μετ’ οὐ πολὺ εἷλε τὴν Σκῦρον.", "st": "3.3"}, {"sp": "N", "t": "ὅτι δὲ ἐπὶ τῶν ἡρώων τὰ ὅπλα ὁμοίως χαλκᾶ ἦν πάντα, μαρτυρεῖ μοι καὶ Ὁμήρου τῶν ἐπῶν ⟨τὰ⟩ ἔς τε ἀξίνην ἔχοντα τὴν Πεισάνδρου καὶ ἐς τοῦ Μηριόνου τὸν ὀιστόν. βεβαιοῖ δὲ καὶ ἄλλως μοι τὸν λόγον ἐν Φασήλιδι ἀνακείμενον ἐν Ἀθηνᾶς ἱερῷ τὸ δόρυ Ἀχιλλέως καὶ Νικομηδεῦσιν ἐν Ἀσκληπιοῦ ναῷ μάχαιρα ὁ Μέμνονος· καὶ τοῦ μὲν ἥ τε αἰχμὴ καὶ ὁ σαυρωτήρ, ἡ μάχαιρα δὲ καὶ διὰ πάσης χαλκοῦ πεποίηται.", "st": "3.3"}, {"sp": "N", "t": "ταῦτα μὲν δὴ ἴσμεν ἔχοντα οὕτως· Ἀναξανδρίδης δὲ ὁ Λέοντος Λακεδαιμονίων μόνος γυναῖκάς τε δύο ἅμα ἔσχε καὶ οἰκίας δύο ἅμα ᾤκησε. τὴν γάρ οἱ πρότερον συνοικοῦσαν ἀρίστην τὰ ἄλλα οὖσαν συνέβαινεν οὐ τίκτειν· ἀποπέμψασθαι δὲ αὐτὴν κελευόντων τῶν ἐφόρων τοῦτο μὲν οὐδαμῶς ἐπαγγέλλεται, τοσοῦτον δέ σφισιν εἴκει γυναῖκα ἑτέραν λαβεῖν πρὸς ταύτῃ. καὶ ἥ τε ἐπεισελθοῦσα Κλεομένην παῖδα ἔσχε καὶ ἡ προτέρα τέως οὐ σχοῦσα ἐν γαστρὶ ἐπὶ γεγονότι ἤδη Κλεομένει τίκτει Δωριέα καὶ αὖθις Λεωνίδαν, ἐπὶ δὲ αὐτοῖς Κλεόμβροτον.", "st": "3.3"}, {"sp": "N", "t": "ἐπεὶ δὲ ἀπέθανεν Ἀναξανδρίδης, Λακεδαιμόνιοι Δωριέα καὶ γνώμην Κλεομένους καὶ τὰ ἐς πόλεμον ἀμείνονα εἶναι νομίζοντες τὸν μὲν ἀπώσαντο ἄκοντες, Κλεομένει δὲ διδόασιν ἐκ τῶν νόμων πρεσβεῖα τὴν ἀρχήν.", "st": "3.3"}, {"sp": "N", "t": "Δωριεὺς μὲν δὴ—οὐ γὰρ ἠνείχετο ὑπακούειν Κλεομένει μένων ἐν Λακεδαίμονι—ἐς ἀποικίαν στέλλεται· Κλεομένης δὲ ὡς ἐβασίλευσεν, αὐτίκα ἐσέβαλεν ἐς τὴν Ἀργολίδα, Λακεδαιμονίων τε αὐτῶν ἀθροίσας καὶ τῶν συμμάχων στρατιάν. ὡς δὲ ἐπεξῆλθον οἱ Ἀργεῖοι σὺν ὅπλοις, ὁ Κλεομένης ἐνίκα τῇ μάχῃ· καὶ —ἦν γὰρ πλησίον ἄλσος ἱερὸν Ἄργου τοῦ Νιόβης— καταφεύγουσιν ὡς ἐτράποντο ὅσον τε πεντακισχίλιοι τῶν Ἀργείων ἐς τὸ ἄλσος. Κλεομένης δὲ—ἐξώρμει γὰρ τὰ πολλὰ ἐκ τοῦ νοῦ—κελεύει καὶ τότε ἐνεῖναι πῦρ τοῖς εἵλωσιν ἐς τὸ ἄλσος, καὶ τό τε ἄλσος ἡ φλὸξ ἐπέλαβεν ἅπαν καὶ ὁμοῦ τῷ ἄλσει καιομένῳ συγκατεκαύθησαν [αὖθις] οἱ ἱκέται.", "st": "3.4"}, {"sp": "N", "t": "ἐστράτευσε δὲ καὶ ἐπὶ Ἀθήνας, τὸ μὲν πρότερον Ἀθηναίοις τε ἐλευθερίαν ἀπὸ τῶν Πεισιστράτου παίδων καὶ αὑτῷ καὶ Λακεδαιμονίοις δόξαν ἐν τοῖς Ἕλλησιν ἀγαθὴν κτώμενος, ὕστερον δὲ Ἀθηναίου χάριτι ἀνδρὸς Ἰσαγόρου τυραννίδα οἱ συγκατεργασόμενος Ἀθηνῶν. ὡς δὲ ἡμάρτανε τῆς ἐλπίδος καὶ οἱ Ἀθηναῖοι περὶ τῆς ἐλευθερίας ἐμαχέσαντο ἐρρωμένως, ἐνταῦθα ὁ Κλεομένης ἄλλα τε ἐδῄωσε τῆς χώρας καὶ τῆς καλουμένης Ὀργάδος θεῶν τε τῶν ἐν Ἐλευσῖνι ἱερᾶς, καὶ ταύτης τεμεῖν φασιν αὐτόν. ἀφίκετο δὲ καὶ ἐς Αἴγιναν, καὶ Αἰγινητῶν τοὺς δυνατοὺς συνελάμβανεν ὅσοι μηδισμοῦ τε αὐτῶν μετέσχον καὶ βασιλεῖ Δαρείῳ τῷ Ὑστάσπου γῆν δοῦναι καὶ ὕδωρ τοὺς πολίτας ἔπεισαν.", "st": "3.4"}, {"sp": "N", "t": "διατρίβοντος δὲ ἐν Αἰγίνῃ Κλεομένους Δημάρατος ὁ τῆς οἰκίας βασιλεὺς τῆς ἑτέρας διέβαλλεν αὐτὸν ἐς τῶν Λακεδαιμονίων τὸ πλῆθος· Κλεομένης δὲ ὡς ἀνέστρεψεν ἐξ Αἰγίνης, ἔπρασσεν ὅπως Δημάρατον παύσειε βασιλεύοντα, καὶ τήν τε ἐν Δελφοῖς πρόμαντιν ὠνήσατο, Λακεδαιμονίοις αὐτὴν ὁπόσα αὐτὸς ἐδίδασκεν ἐς Δημάρατον χρῆσαι, καὶ Λεωτυχίδην ἄνδρα τοῦ βασιλικοῦ γένους καὶ οἰκίας Δημαράτῳ τῆς αὐτῆς ἐπῆρεν ἀμφισβητεῖν ὑπὲρ τῆς ἀρχῆς.", "st": "3.4"}, {"sp": "N", "t": "εἴχετο δὲ Λεωτυχίδης λόγων οὓς Ἀρίστων ποτὲ ἐς Δημάρατον τεχθέντα ἐξέβαλεν ὑπὸ ἀμαθίας οὐχ αὑτοῦ παῖδα εἶναι φήσας. τότε δὲ οἱ μὲν ἐς τὸ χρηστήριον οἱ Λακεδαιμόνιοι τὸ ἐν Δελφοῖς, ὥσπερ καὶ τὰ ἄλλα εἰώθεσαν, ἀνάγουσι καὶ τὸ ἀμφισβήτημα τὸ ὑπὲρ Δημαράτου· ἡ δέ σφισιν ἔχρησεν ἡ πρόμαντις ὁπόσα ἦν Κλεομένει κατὰ γνώμην.", "st": "3.4"}, {"sp": "N", "t": "Δημάρατος μὲν δὴ κατὰ ἔχθος τὸ Κλεομένους καὶ οὐ σὺν τῷ δικαίῳ βασιλείας ἐπαύθη, Κλεομένην δὲ ὕστερον τούτων ἐπέλαβεν ἡ τελευτὴ μανέντα· ὡς γὰρ δὴ ἐλάβετο ξίφους, ἐτίτρωσκεν αὐτὸς αὑτὸν καὶ διεξῄει τὸ σῶμα ἅπαν κόπτων τε καὶ λυμαινόμενος. Ἀργεῖοι μὲν δὴ τοῖς ἱκέταις τοῦ Ἄργου διδόντα αὐτὸν δίκην τέλος τοῦ βίου φασὶν εὑρέσθαι τοιοῦτον, Ἀθηναῖοι δὲ ὅτι ἐδῄωσε τὴν Ὀργάδα, Δελφοὶ δὲ τῶν δώρων ἕνεκα ὧν τῇ προμάντιδι ἔδωκεν, ἀναπείσας ἐψευσμένα εἰπεῖν ἐς Δημάρατον.", "st": "3.4"}, {"sp": "N", "t": "εἴη δ’ ἂν καὶ τὰ μηνίματα ἔκ τε ἡρώων ὁμοῦ καὶ θεῶν ἐς τὸ αὐτὸ τῷ Κλεομένει συνεληλυθότα, ἐπεί τοι καὶ ἰδίᾳ Πρωτεσίλαος ἐν Ἐλαιοῦντι οὐδὲν ἥρως Ἄργου φανερώτερος ἄνδρα Πέρσην ἐτιμωρήσατο Ἀρταΰκτην καὶ Μεγαρεῦσιν οὔ ποτε θεῶν τῶν ἐν Ἐλευσῖνι ὄντων ἐξεγένετο ἱλάσασθαι τὸ μήνιμα γῆν ἐπεργασαμένοις τὴν ἱεράν. τὰ δὲ ἐς τοῦ μαντείου τὴν διάπειραν οὐδὲ τὸ παράπαν ἄλλον γε οὐδένα ὅτι μὴ μόνον Κλεομένην τολμήσαντα ἴσμεν.", "st": "3.4"}, {"sp": "N", "t": "Κλεομένει δὲ οὐκ ὄντων ἀρρένων παίδων ἐς Λεωνίδαν τὸν Ἀναξανδρίδου, Δωριέως δὲ ἀπ’ ἀμφοτέρων ἀδελφόν, κατέβαινεν ἡ ἀρχή. καὶ Ξέρξης τε τηνικαῦτα ἐπὶ τὴν Ἑλλάδα ἤγαγε τὸν λαὸν καὶ Λεωνίδας τριακοσίοις ὁμοῦ Λακεδαιμονίων ἀπήντησεν ἐς Θερμοπύλας. γεγόνασι μὲν δὴ πόλεμοι καὶ Ἑλλήνων πολλοὶ καὶ ἐς ἀλλήλους βαρβάρων, εὐαρίθμητοι δὲ ὁπόσους ἀνδρὸς ἑνὸς μάλιστα ἀρετὴ προήγαγεν ἐς πλέον δόξης, ὡς Ἀχιλλεύς τε τὸν πρὸς Ἰλίῳ πόλεμον καὶ Μιλτιάδης τὸ Μαραθῶνι ἔργον. ἀλλὰ γὰρ τὸ Λεωνίδου κατόρθωμα ὑπερεβάλετο ἐμοὶ δοκεῖν τά τε ἀνὰ χρόνον συμβάντα καὶ τὰ ἔτι πρότερον.", "st": "3.4"}, {"sp": "N", "t": "Ξέρξῃ γὰρ βασιλέων, ὁπόσοι Μήδοις καὶ Πέρσαις ἐγένοντο ὕστερον, παρασχομένῳ μέγιστον φρόνημα καὶ ἀποδειξαμένῳ λαμπρὰ οὕτω, κατὰ τὴν πορείαν Λεωνίδας σὺν ὀλίγοις, οὓς ἠγάγετο ἐς Θερμοπύλας, ἐγένετο ἂν ἐμποδὼν μηδὲ ἀρχὴν τὴν Ἑλλάδα ἰδεῖν αὐτὸν μηδὲ Ἀθηναίων ποτὲ ἐμπρῆσαι τὴν πόλιν, εἰ μὴ κατὰ τὴν ἀτραπὸν τὴν διὰ τῆς Οἴτης τείνουσαν περιαγαγὼν τὴν μετὰ Ὑδάρνου στρατιὰν ὁ Τραχίνιος κυκλώσασθαί σφισι τοὺς Ἕλληνας παρέσχε καὶ οὕτω κατεργασθέντος Λεωνίδου παρῆλθον ἐς τὴν Ἑλλάδα οἱ βάρβαροι.", "st": "3.4"}, {"sp": "N", "t": "Παυσανίας δὲ ὁ Κλεομβρότου βασιλεὺς μὲν οὐκ ἐγένετο· ἐπιτροπεύων γὰρ Πλείσταρχον τὸν Λεωνίδου καταλειφθέντα ἔτι παῖδα ἐς Πλάταιάν τε Λακεδαιμονίους ἤγαγε καὶ ὕστερον ναυσὶν ἐς τὸν Ἑλλήσποντον. Παυσανίου δὲ τὸ ἔργον τὸ ἐς τὴν Κῴαν γυναῖκα ἐν ἐπαίνῳ τίθεμαι μάλιστα, ἥντινα ἀνδρὸς οὐκ ἀδόξου παρὰ Κῴοις θυγατέρα οὖσαν Ἡγητορίδου τοῦ Ἀνταγόρου Φαρανδάτης ὁ Τεάσπιδος, ἀνὴρ Πέρσης, παλλακὴν εἶχεν ἄκουσαν·", "st": "3.4"}, {"sp": "N", "t": "ἐπεὶ δὲ Πλαταιᾶσι Μαρδόνιός τε ἔπεσεν ἐν τῇ μάχῃ καὶ ἀπώλοντο οἱ βάρβαροι, τὴν γυναῖκα ὁ Παυσανίας ἀπέστειλεν ἐς τὴν Κῶν κόσμον τε ὃν ἐποιήσατο ὁ Πέρσης αὐτῇ καὶ τὴν ἄλλην ἀγομένην κατασκευήν. Μαρδονίου τε οὐκ ἠθέλησεν ὁ Παυσανίας αἰσχῦναι τὸν νεκρὸν κατὰ τὴν παραίνεσιν τοῦ Αἰγινήτου Λάμπωνος.", "st": "3.4"}, {"sp": "N", "t": "Πλείσταρχος μὲν οὖν ὁ Λεωνίδου νεωστὶ τὴν βασιλείαν παρειληφὼς ἐτελεύτησε, Πλειστοάναξ δὲ ἔσχε τὴν ἀρχὴν ὁ Παυσανίου τοῦ Πλαταιᾶσιν ἡγησαμένου· Πλειστοάνακτος δὲ ἐγένετο Παυσανίας. οὗτος ἐς τὴν Ἀττικὴν ἀφίκετο ὁ Παυσανίας Θρασυβούλῳ καὶ Ἀθηναίοις πολέμιος τῷ λόγῳ, τοῖς δὲ ἄρχειν ἐπιτραπεῖσιν ὑπὸ Λυσάνδρου καταστησόμενος τὴν τυραννίδα ἐν βεβαίῳ. καὶ μάχῃ μὲν ἐνίκησεν Ἀθηναίων τοὺς ἔχοντας τὸν Πειραιᾶ, μετὰ δὲ τὴν μάχην αὐτίκα οἱ τὸν στρατὸν ἀπάγειν οἴκαδε ἤρεσε μηδὲ ἀνοσίων ἀνδρῶν τυραννίδα αὔξοντα ἐπισπάσασθαι τῇ Σπάρτῃ τὸ αἴσχιστον ⟨τῶν⟩ ὀνειδῶν.", "st": "3.5"}, {"sp": "N", "t": "ὡς δὲ ἐπανῆλθεν ἐξ Ἀθηνῶν μαχεσάμενος ἄπρακτον μάχην, ὑπάγουσιν αὐτὸν ἐς κρίσιν οἱ ἐχθροί. βασιλεῖ δὲ τῷ Λακεδαιμονίων δικαστήριον ἐκάθιζον οἵ τε ὀνομαζόμενοι γέροντες, ὀκτὼ καὶ εἴκοσιν ὄντες ἀριθμόν, καὶ ἡ τῶν ἐφόρων ἀρχή, σὺν δὲ αὐτοῖς καὶ ὁ τῆς οἰκίας βασιλεὺς τῆς ἑτέρας. τέσσαρες μὲν δὴ καὶ δέκα τῶν γερόντων, ἐπὶ δὲ αὐτοῖς Ἆγις ὁ τῆς ἑτέρας οἰκίας βασιλεύς, ἀδικεῖν τὸν Παυσανίαν κατέγνωσαν·", "st": "3.5"}, {"sp": "N", "t": "τὸ δὲ ἄλλο ἀπέγνω δικαστήριον. μετὰ δὲ οὐ πολὺν χρόνον Λακεδαιμονίων συλλεγόντων ἐπὶ Θήβας στρατιάν—αἰτία δὲ ἥτις ἐγένετο προσέσται τῷ ἐς Ἀγησίλαον λόγῳ—, τότε δὲ Λύσανδρος μὲν ἐς τὴν Φωκίδα ἀφικόμενος καὶ ἀναλαβὼν πανδημεὶ τοὺς Φωκέας οὐδένα ἔτι ἐπισχὼν χρόνον ἔς τε Βοιωτίαν ἐληλύθει καὶ προσβολὰς ἐποιεῖτο ἐς τὸ Ἁλιαρτίων τεῖχος οὐκ ἐθελόντων ἀπὸ Θηβαίων ἀφίστασθαι. ἐσεληλύθεσαν δὲ ἤδη καὶ Θηβαίων καὶ Ἀθηναίων τινὲς κρύφα ἐς τὴν πόλιν, ὧν ἐπεξελθόντων καὶ πρὸ τοῦ τείχους ταξαμένων ἄλλοι τε ἐνταῦθα Λακεδαιμονίων καὶ Λύσανδρος ἔπεσε.", "st": "3.5"}, {"sp": "N", "t": "Παυσανίας δὲ ὑστέρησε μὲν τοῦ ἀγῶνος παρὰ Τεγεατῶν καὶ ἐξ Ἀρκαδίας τῆς ἄλλης ἀθροίζων δύναμιν· ὡς δὲ ἐς τὴν Βοιωτίαν ἀφίκετο, ἐπυνθάνετό [τε] τήν τε ἧτταν τῶν ὁμοῦ Λυσάνδρῳ καὶ αὐτοῦ Λυσάνδρου τὴν τελευτήν, ἐπῆγε δὲ ὅμως ἐπὶ τὰς Θήβας τὸν στρατὸν καὶ διενοεῖτο ὡς μάχης ἄρξων. ἐνταῦθα οἵ τε Θηβαῖοι [τὰ] ἐναντία ἐτάσσοντο καὶ Θρασύβουλος ἀπέχειν οὐ πολὺ ἀπηγγέλλετο ἄγων τοὺς Ἀθηναίους· ἀνέμενε δὲ ἄρξαι Λακεδαιμονίους μάχης, ἄρξασι δὲ αὐτὸς ἤδη κατὰ νώτου σφίσιν ἔμελλεν ἐπικείσεσθαι.", "st": "3.5"}, {"sp": "N", "t": "ἔδεισεν οὖν ὁ Παυσανίας διπλοῦ στρατιωτικοῦ πολεμίων ἀνδρῶν μεταξὺ ἀποληφθῆναι, καὶ οὕτω σπονδάς τε πρὸς τοὺς Θηβαίους ἐποιήσατο καὶ τοὺς ὑπὸ τῷ Ἁλιαρτίων τείχει πεσόντας ἀνείλετο. τοῦτο Λακεδαιμονίοις μὲν ἐγένετο οὐ κατὰ γνώμην, ἐγὼ δὲ ἐπαινῶ τῶνδε ἕνεκα τὸ βούλευμα· ἅτε γὰρ εὖ εἰδὼς ὁ Παυσανίας ὡς τὰ σφάλματα ἀεὶ Λακεδαιμονίοις γίνονται ἐν μέσῳ πολεμίων ἀποληφθεῖσι, τό τε ἐν Θερμοπύλαις καὶ ἐν τῇ Σφακτηρίᾳ νήσῳ δεῖμα ἐποιήσατο μή σφισι καὶ αὐτὸς τρίτου γένηται κακοῦ πρόφασις.", "st": "3.5"}, {"sp": "N", "t": "τότε δὲ ἐν αἰτίᾳ ποιουμένων τῶν πολιτῶν τὴν βραδυτῆτα αὐτοῦ τὴν ἐς Βοιωτίαν οὐχ ὑπέμεινεν ἐσελθεῖν ἐς δικαστήριον, Τεγεᾶται δὲ αὐτὸν τῆς Ἀθηνᾶς ἱκέτην ἐδέξαντο τῆς Ἀλέας. ἦν δὲ ἄρα τὸ ἱερὸν τοῦτο ἐκ παλαιοῦ Πελοποννησίοις πᾶσιν αἰδέσιμον καὶ τοῖς αὐτόθι ἱκετεύουσιν ἀσφάλειαν μάλιστα παρείχετο· ἐδήλωσαν δὲ οἵ τε Λακεδαιμόνιοι τὸν Παυσανίαν καὶ ἔτι πρότερον τούτου Λεωτυχίδην καὶ Ἀργεῖοι Χρυσίδα, καθεζομένους ἐνταῦθα ἱκέτας, οὐδὲ ἀρχὴν ἐξαιτῆσαι θελήσαντες.", "st": "3.5"}, {"sp": "N", "t": "Παυσανίου δὲ φυγόντος οἱ μὲν παῖδες Ἀγησίπολις καὶ Κλεόμβροτος νέοι παντάπασιν ἔτι ἦσαν, Ἀριστόδημος δὲ ἐπετρόπευεν αὐτοὺς γένους ἐγγύτατα ὤν· καὶ τὸ ἐν Κορίνθῳ Λακεδαιμονίων κατόρθωμα Ἀριστοδήμου σφίσιν ἐγένετο ἡγουμένου.", "st": "3.5"}, {"sp": "N", "t": "Ἀγησίπολις δὲ ἐπεὶ τὴν βασιλείαν ἔσχεν αὐξηθείς, Πελοποννησίων πρώτοις ἐπολέμησεν Ἀργείοις. ὡς δὲ ἐκ τῆς Τεγεατῶν ἐς τὴν Ἀργολίδα ἤγαγε τὸν στρατόν, πέμπουσι κήρυκα οἱ Ἀργεῖοι σπεισόμενον πρὸς Ἀγησίπολίν σφισι πατρῴους δή τινας σπονδὰς ἐκ παλαιοῦ καθεστώσας τοῖς Δωριεῦσι πρὸς ἀλλήλους. ὁ δὲ οὔτε τῷ κήρυκι ἐσπείσατο καὶ προϊὼν ὁμοῦ τῇ στρατιᾷ τὴν γῆν ἔφθειρεν· ἔσεισέ τε δὴ ὁ θεὸς καὶ ὁ Ἀγησίπολις οὐδ’ οὕτω τὴν δύναμιν ἀπάξειν ἔμελλε, καίτοι Λακεδαιμονίοις μάλιστα Ἑλλήνων—ὡσαύτως δὲ καὶ Ἀθηναίοις—δεῖμα αἱ διοσημεῖαι παρείχοντο.", "st": "3.5"}, {"sp": "N", "t": "καὶ ὁ μὲν ὑπὸ τὸ τεῖχος κατεστρατοπεδεύετο ἤδη τὸ Ἀργείων καὶ οὐ παρίει σείων ὁ θεὸς καί τινες καὶ ἀπώλοντο τῶν στρατιωτῶν κεραυνωθέντες, τοὺς δὲ καὶ ἔκφρονας ἐποίησαν αἱ βρονταί. οὕτω μὲν δὴ ἐκ τῆς Ἀργολίδος ἀνέζευξεν ἄκων, ἐπὶ δὲ Ὀλυνθίους ἐποιεῖτο αὖθις στρατείαν. κρατοῦντα δὲ αὐτὸν τῷ πολέμῳ καὶ ᾑρηκότα τῶν τε ἄλλων πόλεων τῶν ἐν Χαλκιδεῦσι τὰς πολλὰς καὶ αὐτὴν ἐλπίζοντα αἱρήσειν τὴν Ὄλυνθον νόσος τε ἐξαίφνης καὶ θάνατος ἐπέλαβεν ἀπ’ αὐτῆς.", "st": "3.5"}, {"sp": "N", "t": "Ἀγησιπόλιδος δὲ ἄπαιδος τελευτήσαντος ἐς Κλεόμβροτον περιῆλθεν ἡ ἀρχή, καὶ ὑπὸ ἡγεμόνι τούτῳ Βοιωτοῖς ἐναντία ἠγωνίσαντο ἐν Λεύκτροις· Κλεόμβροτος δὲ αὐτὸς γενόμενος ἀνὴρ ἀγαθὸς ἀρχομένης ἔτι ἔπεσε τῆς μάχης. μάλιστα δέ πως ἐπὶ πταίσμασιν ἐθέλει μεγάλοις προαφαιρεῖσθαι τὸν ἡγεμόνα ὁ δαίμων, καθὰ δὴ καὶ Ἀθηναίων ἀπῆγεν Ἱπποκράτην τε τὸν Ἀρίφρονος στρατηγοῦντα ἐπὶ Δηλίῳ καὶ ὕστερον ἐν Θεσσαλίᾳ Λεωσθένην.", "st": "3.6"}, {"sp": "N", "t": "Κλεομβρότου δὲ ὁ μὲν πρεσβύτερος τῶν παίδων Ἀγησίπολις παρέσχετο μέγα οὐδὲν ἐς μνήμην, Κλεομένης δὲ ὁ νεώτερος μετὰ τὸν ἀδελφὸν τελευτήσαντα ἔσχε τὴν ἀρχήν. γενομένων δὲ αὐτῷ παίδων Ἀκροτάτου καὶ ἐπ’ αὐτῷ Κλεωνύμου κατήγαγε τὸ χρεὼν Ἀκρότατον ἔτι πρότερον ἢ αὐτὸν Κλεομένην, καὶ ὡς Κλεομένης ἀπέθανεν ὕστερον, ἐς ἀντιλογίαν ἀφίκοντο ὑπὲρ τῆς βασιλείας Κλεώνυμός τε ὁ Κλεομένους καὶ Ἀρεὺς ὁ Ἀκροτάτου. δικάζουσιν οὖν οἱ γέροντες Ἀρεῖ τῷ Ἀκροτάτου καὶ οὐχὶ Κλεωνύμῳ πατρῴαν εἶναι τὴν τιμήν.", "st": "3.6"}, {"sp": "N", "t": "Κλεωνύμῳ δὲ ἀπελαθέντι τῆς βασιλείας περισσῶς δή τι ὁ θυμὸς ᾤδει, καὶ αὐτὸν οἱ ἔφοροι καὶ ἄλλοις γέρασι ψυχαγωγοῦντες καὶ ἐπὶ ταῖς δυνάμεσιν ἐφιστάντες ἄρχοντα παρῆγον μή ποτε πολέμιον γενέσθαι τῇ Σπάρτῃ. τέλος δὲ ὁ μὲν πολλά τε καὶ ἐχθρὰ ἐς τὴν πατρίδα ἐτόλμησε καὶ Πύρρον τὸν Αἰακίδου σφίσιν ἐπηγάγετο ἐς τὴν χώραν·", "st": "3.6"}, {"sp": "N", "t": "Ἀρέως δὲ ἐν Σπάρτῃ τοῦ Ἀκροτάτου βασιλεύοντος Ἀντίγονος ὁ Δημητρίου πεζῷ τε καὶ ναυσὶν ἐπὶ Ἀθήνας στρατεύει. τοῖς δὲ Ἀθηναίοις ἀμυνοῦντες ἀφίκοντο μὲν ὁ Αἰγυπτίων ὁμοῦ Πατρόκλῳ στόλος, ἐξίασι δὲ καὶ οἱ Λακεδαιμόνιοι πανδημεί, τὸν βασιλέα ἡγεῖσθαί σφισιν Ἀρέα ἐπιτάξαντες.", "st": "3.6"}, {"sp": "N", "t": "περικαθημένου δὲ Ἀντιγόνου τὰς Ἀθήνας καὶ τῆς ἐσόδου τῆς ἐς τὴν πόλιν τὰ Ἀθηναίων συμμαχικὰ εἴργοντος, Πάτροκλος ἀποστέλλων ἀγγέλους προέτρεπε Λακεδαιμονίους καὶ Ἀρέα ἄρχειν πρὸς Ἀντίγονον μάχης, ἐκείνων δὲ ἀρξάντων οὕτω καὶ αὐτὸς κατὰ νώτου τοῖς Μακεδόσιν ἔφασκεν ἐπικείσεσθαι· πρότερον δὲ οὐκ εἰκὸς εἶναι σφᾶς Αἰγυπτίους τε ὄντας καὶ ναύτας Μακεδόσιν ἐπιέναι πεζῇ. Λακεδαιμόνιοι μὲν δὴ παρακινδυνεύειν ὥρμηντο Ἀθηναίων τε εὐνοίᾳ καί τι καὶ ἄξιον μνήμης ἐς τοὺς ἔπειτα ἐργάσασθαι προθυμούμενοι·", "st": "3.6"}, {"sp": "N", "t": "Ἀρεὺς δέ, ὥς σφισι τὰ ἐπιτήδεια ἐξανήλωτο, ἀπῆγεν ὀπίσω τὴν στρατιάν. ταμιεύεσθαι γὰρ τὴν ἀπόνοιαν ἐς τὰ οἰκεῖα ἠξίου καὶ μὴ ἀφειδῶς ἐπ’ ἀλλοτρίοις ἀναρρῖψαι. τοῖς δὲ Ἀθηναίοις ἀντισχοῦσιν ἐπὶ μακρότατον ἐποιήσατο Ἀντίγονος εἰρήνην, ἐφ’ ᾧ τέ σφισιν ἐπαγάγῃ φρουρὰν ἐς τὸ Μουσεῖον. καὶ τοῖς μὲν ἀνὰ χρόνον αὐτὸς ἐξήγαγεν ἑκουσίως τὴν φρουρὰν ὁ Ἀντίγονος, Ἀρέως δὲ ἐγένετο υἱὸς Ἀκρότατος, τοῦ δὲ Ἀρεύς, ὃς ὀκτὼ μάλιστα ἔτη γεγονὼς τελευτᾷ νόσῳ.", "st": "3.6"}, {"sp": "N", "t": "καὶ ἐλείπετο γὰρ τῆς Εὐρυσθένους οἰκίας γένος τὸ πρὸς ἀνδρῶν Λεωνίδας ὁ Κλεωνύμου, παντάπασιν ἤδη γέρων· τούτῳ δὴ διδόασιν οἱ Λακεδαιμόνιοι τὴν ἀρχὴν. τῷ δὲ Λεωνίδᾳ διάφορος ἐτύγχανεν ὢν ἐς τὰ μάλιστα Λύσανδρος, ἀπόγονος Λυσάνδρου τοῦ Ἀριστοκρίτου. οὗτος προσποιεῖται Κλεόμβροτον θυγατέρα ἔχοντα Λεωνίδου· τοῦτον δὲ οἰκειωσάμενος ἐπῆγε Λεωνίδᾳ καὶ ἄλλα ἐγκλήματα καὶ ὅρκους αὐτὸν Κλεωνύμῳ τῷ πατρὶ ὀμόσαι παῖδα ὄντα ἐπὶ ὀλέθρῳ τῆς Σπάρτης.", "st": "3.6"}, {"sp": "N", "t": "ἐπαύσθη τε δὴ Λεωνίδας βασιλείας καὶ ἀντ’ αὐτοῦ Κλεόμβροτος ἔσχε τὴν τιμήν. εἰ μὲν δὴ ὁ Λεωνίδας ἐπέτρεψε τῷ θυμῷ καὶ Δημαράτῳ τῷ Ἀρίστωνος κατὰ ταὐτὰ ἀπεχώρησεν ἤτοι παρὰ τὸν ἐν Μακεδονίᾳ βασιλεύοντα ἢ τὸν Αἰγύπτιον, ὁ δὲ καὶ μεταγνόντων ἂν Σπαρτιατῶν ὤνατο οὐδέν· νῦν δὲ ἐπιβαλόντων οἱ φυγὴν τῶν πολιτῶν ἀφίκετο ἐς Ἀρκαδίαν, ἐκεῖθεν δὲ ἔτεσιν ὕστερον οὐ πολλοῖς κατάγουσί τε αὐτὸν Λακεδαιμόνιοι καὶ αὖθις βασιλέα ἐποιήσαντο.", "st": "3.6"}, {"sp": "N", "t": "Κλεομένει δὲ τῷ Λεωνίδους τά τε ἄλλα ὁποῖα ἐς τόλμαν [ἐτόλμησαν] ὁμοῦ καὶ ἀνδρείαν ὑπῆρξε καὶ ὡς ἐπαύσαντο ἐξ ἐκείνου Σπαρτιᾶται βασιλευόμενοι, πρότερον ἔτι ἐδήλωσέ μοι τὰ ἐς τὸν Σικυώνιον Ἄρατον· προσεπελάβετο δὲ ὁ λόγος μοι καὶ τρόπον ὅντινα ἐν Αἰγύπτῳ Κλεομένης ἐτελεύτησεν.", "st": "3.6"}, {"sp": "N", "t": "γένους μὲν δὴ τοῦ Εὐρυσθένους, καλουμένων δὲ Ἀγιαδῶν, Κλεομένης ὁ Λεωνίδου βασιλεὺς ὕστατος ἐγένετο ἐν Σπάρτῃ· τὰ δὲ ἐς τὴν οἰκίαν τὴν ἑτέραν τοιάδε ἤκουσα εἶναι. Προκλῆς ὁ Ἀριστοδήμου τῷ παιδὶ ὄνομα τίθεται Σόον. Εὐρυπῶντα δὲ τὸν Σόου φασὶν ἐς τοσοῦτον ἀφικέσθαι δόξης ὡς καὶ τὴν οἰκίαν ταύτην Εὐρυπωντίδας ὄνομα ἀπ’ αὐτοῦ λαβεῖν, Προκλείδας ἐς ἐκεῖνον καλουμένους.", "st": "3.7"}, {"sp": "N", "t": "Εὐρυπῶντος δὲ υἱὸς γίνεται Πρύτανις. ἐπὶ μὲν δὴ Πρυτάνιδος τοῦ Εὐρυπῶντος τὸ ἔχθος τε Λακεδαιμονίοις ἤρξατο τὸ ἐς Ἀργείους καὶ ἔτι τοῦ ἐγκλήματος τούτου πρότερον Κυνουρεῦσιν ἐπολέμησαν· τὰς δὲ ἐφεξῆς ταύτῃ γενεάς, Εὐνόμου τε τοῦ Πρυτάνιδος καὶ Πολυδέκτου τοῦ Εὐνόμου βασιλευόντων, ἐν εἰρήνῃ διετέλεσεν οὖσα ἡ Σπάρτη.", "st": "3.7"}, {"sp": "N", "t": "Χάριλλος δὲ ὁ Πολυδέκτου τήν τε γῆν ἐδῄωσεν Ἀργείοις— οὗτος γὰρ καὶ ὁ ἐς τὴν Ἀργολίδα ἐσβαλών—καὶ ἔτεσιν οὐ πολλοῖς ὕστερον ὑπὸ ἡγεμόνι Χαρίλλῳ γίνεται καὶ ἡ Σπαρτιατῶν ἐπὶ Τεγεάτας ἔξοδος, ὅτε οἱ Λακεδαιμόνιοι Τεγεάτας αἱρήσειν ἤλπισαν καὶ ἀποτεμεῖσθαι τῆς Ἀρκαδίας τὸ Τεγεατῶν πεδίον, ὑπούλῳ μαντεύματι ἐπελθόντες.", "st": "3.7"}, {"sp": "N", "t": "μετὰ δὲ Χάριλλον τελευτήσαντα Νίκανδρος ὁ Χαρίλλου διαδέχεται τὴν ἀρχήν· καὶ τὰ Μεσσηνίων ἐς Τήλεκλον τὸν τῆς ἑτέρας βασιλέα οἰκίας ἐν τῷ ἱερῷ τῆς Λιμνάδος συμβάντα ἐπὶ Νικάνδρου γίνεται βασιλεύοντος. ἐσέβαλε δὲ καὶ ἐς τὴν Ἀργολίδα ὁ Νίκανδρος στρατιᾷ καὶ τὰ πολλὰ ἐκάκωσε τῆς χώρας· μετασχόντες δὲ Ἀσιναῖοι Λακεδαιμονίοις τοῦ ἔργου δίκην μετ’ οὐ πολὺ Ἀργείοις ἀπέδοσαν σὺν μεγάλῳ πατρίδος τε ὀλέθρῳ καὶ φυγῇ τῇ σφετέρᾳ.", "st": "3.7"}, {"sp": "N", "t": "Θεόπομπον δὲ τὸν Νικάνδρου βασιλεύσαντα μετὰ Νίκανδρον μέλλει καὶ αὖθις ὁ λόγος μοι προσθήσειν προελθόντι ἐς τὴν Μεσσηνίαν συγγραφήν. Θεοπόμπου δὲ ἔτι ἔχοντος τὴν ἀρχὴν ἐν Σπάρτῃ γίνεται καὶ ὁ περὶ τῆς Θυρεάτιδος καλουμένης χώρας Λακεδαιμονίοις ἀγὼν πρὸς Ἀργείους, Θεόπομπος δὲ αὐτὸς οὐ μετέσχε τοῦ ἔργου γήρᾳ καὶ ὑπὸ λύπης τὸ πλέον· Ἀρχίδαμον γὰρ Θεοπόμπου ζῶντος ἔτι ἐπιλαμβάνει τὸ χρεών.", "st": "3.7"}, {"sp": "N", "t": "οὐ μὴν ἄπαις ἐτελεύτησεν ὁ Ἀρχίδαμος, Ζευξίδαμον δὲ ἀπολιπὼν υἱόν. Ζευξιδάμου δὲ Ἀναξίδαμος ὁ παῖς ἐκδέχεται τὴν ἀρχήν· ἐπὶ τούτου Μεσσήνιοι φεύγουσιν ἐκ Πελοποννήσου, πολέμῳ τὸ δεύτερον κρατηθέντες ὑπὸ Σπαρτιατῶν. Ἀναξιδάμου δὲ υἱὸς ἐγένετο Ἀρχίδαμος, Ἀρχιδάμου δὲ Ἀγησικλῆς· καί σφισιν ὑπῆρξεν ἀμφοτέροις τὸν βίον διατελέσαι πάντα ἐν ἡσυχίᾳ καὶ πολέμων οὖσιν ἐκτός.", "st": "3.7"}, {"sp": "N", "t": "Ἀρίστωνι δὲ τῷ Ἀγησικλέους ἀγαγομένῳ γυναῖκα ἥντινα παρθένον μὲν τῶν ἐν Λακεδαίμονι εἶναί φασιν αἰσχίστην, γυναικῶν δὲ τὸ εἶδος καλλίστην ὑπὸ Ἑλένης γενέσθαι, ταύτην ἀγαγομένῳ τῷ Ἀρίστωνι ἐγένετο υἱὸς Δημάρατος ἐν μόνοις μησὶν ἑπτά· καὶ αὐτῷ μετὰ τῶν ἐφόρων καθημένῳ τηνικαῦτα ἐν βουλῇ ἦλθεν οἰκέτης ἀπαγγέλλων τετέχθαι οἱ παῖδα. Ἀρίστων δὲ ἐπῶν τῶν ἐν Ἰλιάδι ἐς τὴν Εὐρυσθέως γένεσιν πεποιημένος λήθην ἢ μηδὲ ἀρχὴν συνεὶς αὐτῶν οὐκ ἔφη τῶν μηνῶν ἕνεκα αὑτοῦ τὸν παῖδα εἶναι.", "st": "3.7"}, {"sp": "N", "t": "τοῦτον μὲν δὴ τῶν εἰρημένων μετάνοια ἔλαβεν ὕστερον· Δημάρατον δὲ βασιλεύοντα καὶ τά τε ἄλλα εὐδοκιμοῦντα ἐν Σπάρτῃ καὶ ἀπὸ τῶν Πεισιστρατιδῶν Κλεομένει συνελευθερώσαντα Ἀθηναίους ἥ τε Ἀρίστωνος ἀγνωμοσύνη καὶ τὸ ἔχθος τὸ Κλεομένους ἐποίησεν ἰδιώτην. καὶ τοῦ μὲν παρὰ βασιλέα Δαρεῖον ἐλθόντος ἐς Πέρσας ἐπὶ πολὺν ἐν τῇ Ἀσίᾳ χρόνον διαμεῖναι τοὺς ἀπογόνους φασί·", "st": "3.7"}, {"sp": "N", "t": "Λεωτυχίδης δὲ ἀντὶ Δημαράτου γενόμενος βασιλεὺς μετέσχε μὲν Ἀθηναίοις καὶ Ἀθηναίων τῷ στρατηγῷ Ξανθίππῳ τῷ Ἀρίφρονος τοῦ ἔργου τοῦ πρὸς Μυκάλῃ, ἐστράτευσε δὲ ὕστερον τούτων καὶ ἐπὶ τοὺς Ἀλευάδας ἐς Θεσσαλίαν· καί οἱ καταστρέψασθαι Θεσσαλίαν πᾶσαν ἐξὸν ἅτε ἀεὶ νικῶντι ἐν ταῖς μάχαις, δῶρα ἔλαβε παρὰ τῶν Ἀλευαδῶν.", "st": "3.7"}, {"sp": "N", "t": "ὑπαγόμενος δὲ ἐν Λακεδαίμονι ἐς δίκην ἔφυγεν ἐθελοντὴς ἐς Τεγέαν. καὶ ὁ μὲν αὐτόθι τὴν Ἀθηνᾶν τὴν Ἀλέαν ἱκέτευε, Λεωτυχίδου δὲ ὁ μὲν παῖς Ζευξίδαμος ζῶντος ἔτι Λεωτυχίδου καὶ οὐ πεφευγότος πω τελευτᾷ νόσῳ, Ἀρχίδαμος δὲ ὁ Ζευξιδάμου μετὰ Λεωτυχίδην ἀπελθόντα ἐς Τεγέαν ἔσχε τὴν ἀρχήν. οὗτος Ἀρχίδαμος Ἀθηναίοις μάλιστα ἐκάκωσε τὴν χώραν στρατῷ τε ἐσβάλλων ἐς γῆν τὴν Ἀττικὴν ἀνὰ πᾶν ἔτος καὶ ὁπότε ἐσβάλοι διὰ πάσης ἐπεξῄει φθείρων καὶ Πλαταιέων Ἀθηναίοις ὄντων εὔνων πολιορκίᾳ τὸ ἄστυ εἷλεν.", "st": "3.7"}, {"sp": "N", "t": "οὐ μὴν τὸν πόλεμόν γε τὸν Πελοποννησίων καὶ Ἀθηναίων γενέσθαι συνέσπευσεν. ἀλλὰ καὶ ἐς ὅσον δυνάμεως ἧκε, διαμεῖναί σφισιν ἔπρασσε τὰς σπονδάς. Σθενελαΐδας δὲ ἔς τε ἄλλα ὢν οὐκ ἀδύνατος ἐν Λακεδαίμονι καὶ ἐφορεύων ἐν τῷ τότε τοῦ πολέμου μάλιστα ἐγένετο αἴτιος· καὶ ὁ πόλεμος οὗτος εὖ τὴν Ἑλλάδα ἔτι βεβηκυῖαν διέσεισεν ἐκ βάθρων, καὶ ὕστερον Φίλιππος ὁ Ἀμύντου σαθρὰν ἤδη καὶ οὐ παντάπασιν ὑγιῆ προσκατήρειψεν αὐτήν.", "st": "3.7"}, {"sp": "N", "t": "Ἀρχιδάμου δὲ ὡς ἐτελεύτα καταλιπόντος παῖδας Ἆγίς τε πρεσβύτερος ἦν ἡλικίᾳ καὶ παρέλαβεν ἀντὶ Ἀγησιλάου τὴν ἀρχήν. ἐγένετο δὲ Ἀρχιδάμῳ καὶ θυγάτηρ, ὄνομα μὲν Κυνίσκα, φιλοτιμότατα δὲ ἐς τὸν ἀγῶνα ἔσχε τὸν Ὀλυμπικόν καὶ πρώτη τε ἱπποτρόφησε γυναικῶν καὶ νίκην ἀνείλετο Ὀλυμπικὴν πρώτη. Κυνίσκας δὲ ὕστερον γυναιξὶ καὶ ἄλλαις καὶ μάλιστα ταῖς ἐκ Λακεδαίμονος γεγόνασιν Ὀλυμπικαὶ νῖκαι, ὧν [ἡ] ἐπιφανεστέρα ἐς τὰς νίκας ⟨οὐδεμία⟩ ἐστὶν αὐτῆς.", "st": "3.8"}, {"sp": "N", "t": "δοκοῦσι δὲ οἱ Σπαρτιᾶταί μοι ποίησιν καὶ ἔπαινον τὸν ἀπ’ αὐτῆς ἥκιστα ἀνθρώπων θαυμάσαι· ὅτι γὰρ μὴ τῇ Κυνίσκᾳ τὸ ἐπίγραμμα ἐποίησεν ὅστις δή, καὶ ἔτι πρότερον Παυσανίᾳ τὸ ἐπὶ τῷ τρίποδι Σιμωνίδης τῷ ἀνατεθέντι ἐς Δελφούς, ἄλλο [δέ] γε παρὰ ἀνδρὸς ποιητοῦ Λακεδαιμονίων τοῖς βασιλεῦσιν οὐδέν ἐστιν ἐς μνήμην.", "st": "3.8"}, {"sp": "N", "t": "ἐπὶ δὲ Ἄγιδος τοῦ Ἀρχιδάμου βασιλεύοντος Λακεδαιμονίοις ἄλλα τε ἐγένετο ἐς Ἠλείους ἐγκλήματα καὶ τοῦ ἀγῶνος τοῦ Ὀλυμπικοῦ καὶ ἱεροῦ τοῦ Ὀλυμπίασιν ὑπ’ αὐτῶν εἰργόμενοι μάλιστα ἤχθοντο. ἀποστέλλουσιν οὖν κήρυκα ἐπίταγμα φέροντα Ἠλείοις Λεπρεάτας τε αὐτονόμους ἀφιέναι καὶ ὅσοι τῶν περιοίκων ἄλλοι σφίσιν ἦσαν ὑπήκοοι. ἀποκριναμένων δὲ Ἠλείων ὡς ἐπειδὰν τὰς περιοικίδας τῆς Σπάρτης πόλεις ἴδωσιν ἐλευθέρας, οὐδὲ αὐτοὶ μελλήσουσιν ἔτι ἀφιέναι τὰς ἑαυτῶν, οὕτω Λακεδαιμόνιοι καὶ ὁ βασιλεὺς Ἆγις ἐσβάλλουσιν ἐς τὴν Ἠλείαν.", "st": "3.8"}, {"sp": "N", "t": "τότε μὲν δὴ τοῦ θεοῦ σείσαντος ὀπίσω τὸ στράτευμα ἀπεχώρησεν ἄχρι Ὀλυμπίας καὶ τοῦ Ἀλφειοῦ προελθόντες· τῷ δὲ ἐφεξῆς ἔτει τήν τε χώραν ἐδῄωσεν ὁ Ἆγις καὶ ἤλασε τῆς λείας τὴν πολλήν. Ξενίας δὲ ἀνὴρ Ἠλεῖος Ἄγιδί τε ἰδίᾳ ξένος καὶ Λακεδαιμονίων τοῦ κοινοῦ πρόξενος ἐπανέστη τῷ δήμῳ σὺν τοῖς τὰ χρήματα ἔχουσι· πρὶν δὲ Ἆγιν καὶ τὸν στρατὸν ἀφῖχθαί σφισιν ἀμύνοντας, Θρασυδαῖος προεστηκὼς τότε τοῦ Ἠλείων δήμου μάχῃ Ξενίαν καὶ τοὺς σὺν αὐτῷ κρατήσας ἐξέβαλεν ἐκ τῆς πόλεως.", "st": "3.8"}, {"sp": "N", "t": "Ἆγις δὲ ὡς ἀπήγαγεν ὀπίσω τὴν στρατιάν, Λυσίστρατον Σπαρτιάτην καὶ μοῖράν τε τῆς δυνάμεως καὶ Ἠλείων καταλείπει τοὺς φυγάδας, κακουργεῖν σφᾶς ὁμοῦ Λεπρεάταις τὴν χώραν. τρίτῳ δὲ ἔτει τοῦ πολέμου Λακεδαιμόνιοι μὲν καὶ Ἆγις παρεσκευάζοντο ὡς ἐς τὴν Ἠλείαν καὶ τότε ἐσβαλοῦντες· οἱ δὲ Ἠλεῖοι καὶ Θρασυδαῖος—κεκακωμένοι γὰρ ἐς τὸ ἔσχατον ἦσαν— συγχωροῦσι μήτε τῶν περιοίκων ἔτι ἄρχειν καὶ τοῦ ἄστεως κατερεῖψαι τὸ τεῖχος, Λακεδαιμονίους τε ἐν Ὀλυμπίᾳ καὶ θύειν τῷ θεῷ καὶ τὸν ἀγῶνα ἐξεῖναί σφισιν ἀγωνίζεσθαι.", "st": "3.8"}, {"sp": "N", "t": "ἐνέβαλλε δὲ καὶ ἐς τὴν Ἀττικὴν συνεχῶς ὁ Ἆγις στρατιᾷ καὶ ἐπετείχισε φρούριον Ἀθηναίοις τὸ ἐν Δεκελείᾳ· καταλυθέντος δὲ ἐν Αἰγὸς ποταμοῖς τοῦ Ἀθηναίων ναυτικοῦ Λύσανδρος ὁ Ἀριστοκρίτου καὶ Ἆγις ὅρκους μὲν θεῶν ὑπερέβησαν, οὓς ὤμοσαν Ἀθηναίοις ἐν κοινῷ Λακεδαιμόνιοι, κατὰ σφᾶς δὲ αὐτοὶ καὶ οὐ μετὰ Σπαρτιατῶν τοῦ κοινοῦ τὸ βούλευμα ἐς τοὺς συμμάχους ἐξήνεγκαν ἐκκόψαι προρρίζους τὰς Ἀθήνας.", "st": "3.8"}, {"sp": "N", "t": "τὰ μὲν οὖν ἐς πόλεμον μάλιστα ἐπίσημα τοιαῦτα ὑπῆρχε τῷ Ἄγιδι· προπέτειαν δὲ τὴν Ἀρίστωνος ἐς Δημάρατον καὶ Ἆγις ἐς τὸν παῖδα ἔσχε Λεωτυχίδην, καί οἱ κατά τινα οὐκ ἀγαθὸν δαίμονα ἐσῆλθεν ἐς ἐπήκοον τῶν ἐφόρων εἰπεῖν ὡς οὐχ αὑτοῦ νομίζοι Λεωτυχίδην. ἐπέλαβε μέντοι καὶ Ἆγιν μετάνοια ὕστερον, καὶ—ἔφερον γὰρ τηνικαῦτα οἴκαδε ἐξ Ἀρκαδίας αὐτὸν νοσοῦντα—ὡς ἐγίνετο ἐν Ἡραίᾳ, καὶ τὸ πλῆθος μάρτυρας ἐποιεῖτο ἦ μὴν Λεωτυχίδην ἑαυτοῦ παῖδα ἡγεῖσθαι καί σφισι σὺν ἱκεσίᾳ τε καὶ δακρύοις ἐπέσκηπτε πρὸς Λακεδαιμονίους ταῦτα ἀπαγγέλλειν.", "st": "3.8"}, {"sp": "N", "t": "μετὰ δὲ Ἆγιν ἀποθανόντα ἀπήλαυνεν Ἀγησίλαος τῆς βασιλείας Λεωτυχίδην, ἐς μνήμην ἄγων Λακεδαιμονίοις τὰ ὑπὸ Ἄγιδός ποτε λεχθέντα ἐς τὸν Λεωτυχίδην. ἀφίκοντο δὲ καὶ οἱ ἐξ Ἡραίας Ἀρκάδες καὶ ἦσαν τῷ Λεωτυχίδῃ μάρτυρες ὁπόσα Ἄγιδος τελευτῶντος ἤκουσαν.", "st": "3.8"}, {"sp": "N", "t": "τῷ δὲ Ἀγησιλάῳ καὶ Λεωτυχίδῃ παρέσχεν ἐς πλέον τὸ μάντευμα ἀντιλογίαν τὸ ἐκ Δελφῶν, γεγονὸς μὲν ἐκεῖ, ἔχον δὲ οὕτω·<br>φράζεο δή, Σπάρτη, καίπερ μεγάλαυχος ἐοῦσα,<br>μὴ σέθεν ἀρτίποδος βλάστῃ χωλὴ βασιλεία.<br>δηρὸν γὰρ μόχθοι σε κατασχήσουσιν ἄελπτοι<br>φθερσιβρότου τ’ ἐπὶ κῦμα κυκωόμενον πολέμοιο.", "st": "3.8"}, {"sp": "N", "t": "τότε οὖν Λεωτυχίδης μὲν ἐς Ἀγησίλαον ταῦτα ἔφασκεν εἰρῆσθαι, τὸν γὰρ δὴ ἕτερον τῶν ποδῶν ἐπεπήρωτο ὁ Ἀγησίλαος· Ἀγησίλαος δὲ ἐς Λεωτυχίδην αὐτὰ ἔτρεπεν οὐ γνήσιον ὄντα Ἄγιδος. Λακεδαιμόνιοι δέ, καίπερ ἐπὶ σφίσιν ὄν, οὐκ ἐπανήγαγον τὸ ἀμφισβήτημα ἐς Δελφούς· αἴτιος δ’ ἐμοὶ δοκεῖν Λύσανδρος ἐγένετο ὁ Ἀριστοκρίτου ⟨Ἀγησιλάῳ⟩ συσπεύδων ἐξ ἅπαντος τὴν βασιλείαν γενέσθαι.", "st": "3.8"}, {"sp": "N", "t": "βασιλεύει τε δὴ Ἀγησίλαος ὁ Ἀρχιδάμου καὶ Λακεδαιμονίοις ἤρεσε διαβῆναι ναυσὶν ἐς τὴν Ἀσίαν, Ἀρταξέρξην τὸν Δαρείου αἱρήσοντας· ἐδιδάσκοντο γὰρ ὑπό τε ἄλλων τῶν ἐν τέλει καὶ μάλιστα ὑπὸ Λυσάνδρου μὴ τὸν Ἀρταξέρξην σφίσιν ἐν τῷ πρὸς Ἀθηναίους πολέμῳ, Κῦρον δὲ εἶναι τὸν τὰ χρήματα διδόντα ἐς τὰς ναῦς. Ἀγησίλαος δὲ—ἀπεδείχθη γὰρ διαβιβάσαι τε ἐς τὴν Ἀσίαν τὸν στρατὸν καὶ δυνάμεως ἡγεμὼν τῆς πεζῆς—περιέπεμπεν ἔς τε Πελοπόννησον πλὴν Ἄργους καὶ ἐς τοὺς Ἕλληνας τοὺς ἐκτὸς Ἰσθμοῦ, συμμαχεῖν σφισιν ἐπαγγέλλων.", "st": "3.9"}, {"sp": "N", "t": "Κορίνθιοι μὲν οὖν, καίπερ ἐς τὰ μάλιστα ἔχοντες προθύμως μετασχεῖν τοῦ ἐς τὴν Ἀσίαν στόλου, κατακαυθέντος σφίσιν ἐξαίφνης ναοῦ Διὸς ἐπίκλησιν Ὀλυμπίου, ποιησάμενοι πονηρὸν οἰωνὸν καταμένουσιν ἄκοντες. Ἀθηναίοις δὲ ἦν μὲν ἡ πρόφασις ἐκ τοῦ Πελοποννησίων πολέμου καὶ ἐκ νόσου τῆς λοιμώδους ἐπανήκειν τὴν πόλιν ἐς τὴν πρότερόν ποτε οὖσαν εὐδαιμονίαν· πυνθανόμενοι δὲ δι’ ἀγγέλων ὡς Κόνων ὁ Τιμοθέου παρὰ βασιλέα ἀναβεβηκὼς εἴη, κατὰ τοῦτο ἡσύχαζον μάλιστα.", "st": "3.9"}, {"sp": "N", "t": "ἀπεστάλη δὲ καὶ ἐς Θήβας πρεσβεύειν Ἀριστομηλίδας, μητρὸς μὲν τῆς Ἀγησιλάου πατήρ, Θηβαίοις δὲ εἶχεν ἐπιτηδείως καὶ ἐγεγόνει τῶν δικαστῶν, οἳ Πλαταιεῦσιν ἁλόντος τοῦ τείχους ἀποθανεῖν τοὺς ἐγκαταληφθέντας ἔγνωσαν. Θηβαῖοι μὲν οὖν κατὰ τὰ αὐτὰ Ἀθηναίοις ἀπείπαντο, οὐ φάμενοι βοηθήσειν· Ἀγησίλαος δέ, ὡς αὐτῷ τά τε οἴκοθεν καὶ παρὰ τῶν συμμάχων τὸ στράτευμα ἤθροιστο καὶ ἅμα αἱ νῆες εὐτρεπεῖς ἦσαν, ἀφίκετο ἐς Αὐλίδα τῇ Ἀρτέμιδι θύσων, ὅτι καὶ Ἀγαμέμνων ἐνταῦθα ἱλασάμενος τὴν θεὸν τὸν ἐς Τροίαν στόλον ἤγαγεν.", "st": "3.9"}, {"sp": "N", "t": "ἠξίου δὲ ἄρα ὁ Ἀγησίλαος πόλεώς τε εὐδαιμονεστέρας ἢ Ἀγαμέμνων βασιλεὺς εἶναι καὶ ἄρχειν τῆς Ἑλλάδος πάσης ὁμοίως ἐκείνῳ, τό τε κατόρθωμα ἐπιφανέστερον ἔσεσθαι βασιλέα κρατήσαντα Ἀρταξέρξην εὐδαιμονίαν κτήσασθαι τὴν Περσῶν ἢ ἀρχὴν καθελεῖν τὴν Πριάμου. θύοντος δὲ αὐτοῦ Θηβαῖοι σὺν ὅπλοις ἐπελθόντες τῶν τε ἱερείων καιόμενα ἤδη τὰ μηρία ἀπορρίπτουσιν ἀπὸ τοῦ βωμοῦ καὶ αὐτὸν ἐξελαύνουσιν ἐκ τοῦ ἱεροῦ.", "st": "3.9"}, {"sp": "N", "t": "Ἀγησίλαον δὲ ἐλύπει μὲν ἡ θυσία μὴ τελεσθεῖσα, διέβαινε δὲ ὅμως ἐς τὴν Ἀσίαν καὶ ἤλαυνεν ἐπὶ τὰς Σάρδεις· ἦν γὰρ δὴ τῆς Ἀσίας τῆς κάτω μέγιστον μέρος τηνικαῦτα ἡ Λυδία, καὶ αἱ Σάρδεις πλούτῳ καὶ παρασκευῇ προεῖχον, τῷ τε σατραπεύοντι ἐπὶ θαλάσσῃ τοῦτο οἰκητήριον ἀπεδέδεικτο καθάπερ γε αὐτῷ βασιλεῖ τὰ Σοῦσα.", "st": "3.9"}, {"sp": "N", "t": "γενομένης δὲ πρὸς Τισσαφέρνην σατράπην τῶν περὶ Ἰωνίαν μάχης ἐν Ἕρμου πεδίῳ τήν τε ἵππον τῶν Περσῶν ἐνίκησεν ὁ Ἀγησίλαος καὶ τὸ πεζὸν τότε πλεῖστον ἀθροισθὲν μετά γε τὸν Ξέρξου καὶ πρότερον ἔτι ἐπὶ Σκύθας Δαρείου καὶ ἐπὶ Ἀθήνας στρατόν. Λακεδαιμόνιοι δὲ ἀγασθέντες τὸ ἐς τὰ πράγματα τοῦ Ἀγησιλάου πρόθυμον διδόασιν ἄρχοντα εἶναι καὶ τῶν νεῶν αὐτῷ. ὁ δὲ ταῖς μὲν τριήρεσιν ἐπέστησεν ἡγεμόνα Πείσανδρον—τοῦ Πεισάνδρου δὲ ἐτύγχανε συνοικῶν ἀδελφῇ—, τῷ πολέμῳ δὲ αὐτὸς κατὰ γῆν προσεῖχεν ἐρρωμένως.", "st": "3.9"}, {"sp": "N", "t": "καί οἱ θεῶν τις ἐβάσκηνε μὴ ἀγαγεῖν τὰ βουλεύματα ἐς τέλος. ὡς γὰρ δὴ ἐπύθετο Ἀρταξέρξης μάχας τε ἃς ἐνίκησεν Ἀγησίλαος καὶ ὡς ⟨ἐς⟩ τὸ πρόσω χειρούμενος τὰ ἐν ποσὶ πρόεισιν ἀεὶ σὺν τῷ στρατῷ, Τισσαφέρνην μὲν καίπερ τὰ πρότερα εὐεργέτην ὄντα ζημιοῖ θανάτῳ, Τιθραύστην δὲ κατέπεμψεν ἐπὶ θάλασσαν, [καὶ] φρονῆσαί τε δεινὸν καί τι καὶ ἐς τοὺς Λακεδαιμονίους ἔχοντα δυσνοίας.", "st": "3.9"}, {"sp": "N", "t": "οὗτος ὡς ἀφίκετο ἐς Σάρδεις, αὐτίκα ἐπενόει τρόπον ᾧ τινι ἀναγκάσει Λακεδαιμονίους τὴν ἐκ τῆς Ἀσίας ἀνακαλέσασθαι στρατιάν. ἄνδρα οὖν Ῥόδιον Τιμοκράτην ἐς τὴν Ἑλλάδα πέμπει χρήματα ἄγοντα, ἐντειλάμενος πόλεμον ἐν τῇ Ἑλλάδι ἐργάσασθαι Λακεδαιμονίοις. οἱ δὲ τῶν χρημάτων μεταλαβόντες Ἀργείων μὲν Κύλων τε εἶναι λέγονται καὶ Σωδάμας, ἐν Θήβαις δὲ Ἀνδροκλείδης καὶ Ἰσμηνίας καὶ Ἀμφίθεμις· μετέσχε δὲ καὶ Ἀθηναῖος Κέφαλος καὶ Ἐπικράτης καὶ ὅσοι Κορινθίων ἐφρόνουν τὰ Ἀργείων Πολυάνθης τε καὶ Τιμόλαος.", "st": "3.9"}, {"sp": "N", "t": "οἱ δὲ ἐς τὸ φανερὸν τοῦ πολέμου παρασχόντες τὴν ἀρχὴν ἐγένοντο οἱ ἐξ Ἀμφίσσης Λοκροί. τοῖς γὰρ δὴ Λοκροῖς γῆ πρὸς τοὺς Φωκέας ἐτύγχανεν οὖσα ἀμφισβητήσιμος [γῆ]· ἐκ ταύτης ὑπὸ Θηβαίων ἐπαρθέντες τῶν περὶ Ἰσμηνίαν τόν τε σῖτον ἀκμάζοντα ἔτεμον καὶ ἤλασαν λείαν ἄγοντες· ἐνέβαλον δὲ πανδημεὶ καὶ οἱ Φωκεῖς ἐς τὴν Λοκρίδα καὶ ἐδῄωσαν τὴν χώραν.", "st": "3.9"}, {"sp": "N", "t": "ἐπηγάγοντο οὖν οἱ Λοκροὶ συμμάχους Θηβαίους καὶ τὴν Φωκίδα ἐπόρθησαν· ἐς δὲ τὴν Λακεδαίμονα ἐλθόντες οἱ Φωκεῖς τοῖς Θηβαίοις ἐπέκειντο καὶ ἐδίδασκον οἷα ἐπεπόνθεσαν ὑπ’ αὐτῶν. Λακεδαιμονίοις δὲ πόλεμον πρὸς Θηβαίους ἔδοξεν ἄρασθαι· ἐποιοῦντο δὲ ἐς αὐτοὺς καὶ ἄλλα ἐγκλήματα καὶ τὴν ἐν Αὐλίδι αὐτῶν ὕβριν ἐς τὴν Ἀγησιλάου θυσίαν.", "st": "3.9"}, {"sp": "N", "t": "Ἀθηναῖοι δὲ τὴν διάνοιαν τῶν Λακεδαιμονίων προπεπυσμένοι πέμπουσιν ἐς Σπάρτην, ὅπλα μὲν [ἐπὶ σφᾶς] ἐπὶ Θήβας δεόμενοι μὴ κινῆσαι, δίκῃ δὲ ὑπὲρ ὧν ἐγκαλοῦσι διακρίνεσθαι· Λακεδαιμόνιοι δὲ πρὸς ὀργὴν ἀποπέμπουσι τὴν πρεσβείαν. τὰ δὲ ἐπὶ τούτοις ἔς τε τὴν Λακεδαιμονίων ἔξοδον καὶ τὰ ἐς τὴν Λυσάνδρου τελευτὴν ἐδήλωσέ μοι τοῦ λόγου τὰ ἐς Παυσανίαν·", "st": "3.9"}, {"sp": "N", "t": "καὶ ὁ κληθεὶς Κορινθιακὸς πόλεμος ἐς πλέον ἀεὶ προῆλθεν ἀπὸ τῆς Λακεδαιμονίων ἀρξάμενος ἐς Βοιωτίαν ἐξόδου. κατὰ ταύτην μὲν δὴ τὴν ἀνάγκην ὀπίσω τὸ στράτευμα ἐκ τῆς Ἀσίας ἀπῆγεν Ἀγησίλαος· ἐπεὶ δὲ ἐξ Ἀβύδου περαιωθεὶς ναυσὶν ἐς Σηστὸν καὶ διεξελθὼν τὴν Θρᾴκην ἀφίκετο ἐς Θεσσαλίαν, ἐνταῦθα οἱ Θεσσαλοὶ χάριτι τῇ ἐς Θηβαίους τοῦ πρόσω τὸν Ἀγησίλαον ἐπειρῶντο εἴργειν· ἦν δέ τι εὐνοίας ἐκ παλαιοῦ καὶ ἐς τὴν πόλιν αὐτοῖς τὴν Ἀθηναίων.", "st": "3.9"}, {"sp": "N", "t": "Ἀγησίλαος δὲ Θεσσαλίαν τε διεξῆλθε τρεψάμενος αὐτῶν τὸ ἱππικὸν καὶ αὖθις διὰ Βοιωτῶν διώδευσε Θηβαίους ἐν Κορωνείᾳ καὶ τὸ ἄλλο νικήσας συμμαχικόν. ὡς δὲ ἐτράποντο οἱ Βοιωτοί, καταφεύγουσιν ἄνδρες ἐξ αὐτῶν ἐς ἱερὸν Ἀθηνᾶς ἐπίκλησιν Ἰτωνίας· Ἀγησίλαος δὲ εἶχε μὲν τραῦμα ἐκ τῆς μάχης, ἐς δὲ τοὺς ἱκέτας παρενόμησεν οὐδ’ οὕτως.", "st": "3.9"}, {"sp": "N", "t": "οὐ πολλῷ δὲ ὕστερον τὸν ἀγῶνα ἔθηκαν τῶν Ἰσθμίων οἱ ἐπὶ λακωνισμῷ φεύγοντες Κορίνθιοι⟨. οἱ⟩ δὲ ἐν τῇ πόλει τότε μὲν τῷ Ἀγησιλάου δείματι ἡσύχαζον· ἀναζεύξαντος δὲ ἐς τὴν Σπάρτην, οὕτω καὶ αὐτοὶ μετὰ Ἀργείων τὰ Ἴσθμια ἄγουσιν. ἀφίκετο δὲ καὶ αὖθις ἐπὶ Κόρινθον στρατιᾷ· καὶ—ἐπῄει γὰρ Ὑακίνθια—ἀφίησι τοὺς Ἀμυκλαιεῖς οἴκαδε ἀπελθόντας τὰ καθεστηκότα τῷ τε Ἀπόλλωνι καὶ Ὑακίνθῳ δρᾶσαι. ταύτην τὴν μοῖραν ἐπιθέμενοι καθ’ ὁδὸν Ἀθηναῖοι καὶ Ἰφικράτης διέφθειραν·", "st": "3.10"}, {"sp": "N", "t": "Ἀγησίλαος δὲ καὶ ἐς Αἰτωλίαν ἐπικουρήσων ἀφίκετο Αἰτωλοῖς ὑπὸ Ἀκαρνάνων πολέμῳ πιεζομένοις, καὶ Ἀκαρνᾶνας ἠνάγκασε καταλύσασθαι τὸν πόλεμον οὐ πολὺ ἀποδέοντας Καλυδῶνα καὶ τὰ ἄλλα Αἰτωλῶν πολίσματα ᾑρηκέναι. χρόνῳ δὲ ὕστερον ἔπλευσε καὶ ἐς Αἴγυπτον, ἀφεστηκότων ἀπὸ βασιλέως τῶν Αἰγυπτίων βοηθήσων· καὶ ἔστιν Ἀγησιλάῳ πολλά τε εἰργασμένα καὶ μνήμης ἄξια ἐν Αἰγύπτῳ. καὶ—ἦν γὰρ δὴ ἤδη γέρων—τὸν μὲν κατὰ τὴν πορείαν ἐπέλαβεν ἡ μοῖρα· Λακεδαιμόνιοι δέ, ὡς ἐκομίσθη σφίσιν ὁ νεκρός, θάπτουσιν αὐτὸν βασιλέων τιμήσαντες μάλιστα.", "st": "3.10"}, {"sp": "N", "t": "Ἀρχιδάμου δὲ τοῦ Ἀγησιλάου βασιλεύοντος κατέλαβον τὸ ἱερὸν Φωκεῖς τὸ ἐν Δελφοῖς. Θηβαίοις μὲν δὴ πολεμεῖν τοῖς Φωκεῦσιν ἀφίκετο μὲν καὶ ἰδίᾳ συμμαχικὰ ἐπὶ χρήμασιν, ἀπὸ δὲ κοινοῦ λόγου Λακεδαιμόνιοί τε καὶ Ἀθηναῖοί σφισιν ἤμυνον, οἱ μὲν ἀρχαίαν δή τινα ἐκ τῶν Φωκέων μνημονεύοντες εὐεργεσίαν, Λακεδαιμόνιοι δὲ προφάσει μὲν καὶ οὗτοι φιλίας, κατὰ ἔχθος δὲ ἐμοὶ δοκεῖν τὸ Θηβαίων. Θεόπομπος δὲ ὁ Δαμασιστράτου τόν τε Ἀρχίδαμον μετασχεῖν τῶν χρημάτων αὐτὸν καὶ ἔτι Δεινίχαν τὴν Ἀρχιδάμου γυναῖκα παρὰ τῶν δυναστευόντων ἐν Φωκεῦσιν ἔφη λαμβάνουσαν δωρεὰν ἑτοιμότερον ποιεῖν σφισιν ἐς τὴν συμμαχίαν Ἀρχίδαμον.", "st": "3.10"}, {"sp": "N", "t": "τὸ μὲν δὴ χρήματα ἱερὰ δέξασθαι καὶ ἀνδράσιν ἀμῦναι μαντείων πορθήσασι τὸ ἐπιφανέστατον οὐκ ἐς ἔπαινον τίθεμαι, τοσοῦτον δέ οἱ πρόσεστιν ἐς ἔπαινον· Δελφῶν γὰρ τούς τε ἡβῶντας ἀποκτεῖναι καὶ γυναῖκας καὶ τέκνα ἐξανδραποδίσασθαι, καταβαλεῖν δὲ καὶ αὐτὴν ἐς ἔδαφος τὴν πόλιν ἐτόλμων οἱ Φωκεῖς· ταῦτα οὖν μὴ παθεῖν ὑπὸ τῶν Φωκέων αὐτοὺς παρῃτήσατο Ἀρχίδαμος.", "st": "3.10"}, {"sp": "N", "t": "διέβη δὲ καὶ ἐς Ἰταλίαν ὕστερον Ταραντίνοις βαρβάρων πόλεμον συνδιοίσων σφίσιν ὁμόρων· καὶ ἀπέθανέ τε αὐτόθι ὑπὸ τῶν βαρβάρων καὶ αὐτοῦ τὸν νεκρὸν ἁμαρτεῖν τάφου τὸ μήνιμα ἐγένετο ἐμποδὼν τὸ ἐκ τοῦ Ἀπόλλωνος. τοῦ δὲ Ἀρχιδάμου τούτου τὸν μὲν πρεσβύτερον παῖδα Ἆγιν κατέλαβεν ἀποθανεῖν Μακεδόσιν ἐναντία καὶ Ἀντιπάτρῳ μαχεσάμενον, Εὐδαμίδας δὲ ὁ νεώτερος Λακεδαιμονίοις ἐβασίλευσεν ἄγουσιν εἰρήνην. τὰ δὲ ἐς Ἆγιν τὸν Εὐδαμίδου καὶ ἐς Εὐρυδαμίδαν τὸν Ἄγιδος ὡς ἔσχεν, ἤδη μοι καὶ τάδε ἡ Σικυωνία ⟨συγ⟩γραφὴ διεξῄει.", "st": "3.10"}, {"sp": "N", "t": "ἰοῦσι δὲ ἀπὸ τῶν Ἑρμῶν ἐστιν ὁ τόπος οὗτος ἅπας δρυῶν πλήρης· τὸ δὲ ὄνομα τῷ χωρίῳ Σκοτίταν [τὸ δὲ σκότος] οὐ τὸ συνεχὲς τῶν δένδρων ἐποίησεν, ἀλλὰ Ζεὺς ἐπίκλησιν ἔσχε Σκοτίτας, καὶ ἔστιν ἐν ἀριστερᾷ τῆς ὁδοῦ δέκα μάλιστά που στάδια ἐκτραπομένοις ἱερὸν Σκοτίτα Διός. ἐπανελθόντων δὲ ἐντεῦθεν προελθοῦσιν ὀλίγον καὶ τραπεῖσιν αὖθις ἐς ἀριστερὰν ἄγαλμά ἐστιν Ἡρακλέους καὶ τρόπαιον· ἀναστῆσαι δὲ ἐλέγετο Ἡρακλῆς ἀποκτείνας Ἱπποκόωντα καὶ τοὺς παῖδας.", "st": "3.10"}, {"sp": "N", "t": "τρίτη δὲ ἐκ τῆς ὁδοῦ τῆς εὐθείας ἐκβολὴ κατὰ τὰ δεξιὰ ἐς Καρύας ἄγει καὶ ἐς τὸ ἱερὸν τῆς Ἀρτέμιδος. τὸ γὰρ χωρίον Ἀρτέμιδος καὶ Νυμφῶν ἐστιν αἱ Κάρυαι καὶ ἄγαλμα ἕστηκεν Ἀρτέμιδος ἐν ὑπαίθρῳ Καρυάτιδος· χοροὺς δὲ ἐνταῦθα αἱ Λακεδαιμονίων παρθένοι κατὰ ἔτος ἱστᾶσι καὶ ἐπιχώριος αὐταῖς καθέστηκεν ὄρχησις. ἀναστρέψαντι δὲ καὶ κατὰ τὴν λεωφόρον ἰόντι ἐρείπια Σελλασίας ἐστί· ταύτην, καθὰ καὶ πρότερον ἔγραψα, ἠνδραποδίσαντο Ἀχαιοὶ Λακεδαιμονίους καὶ τὸν βασιλέα Κλεομένην τὸν Λεωνίδου μάχῃ νικήσαντες.", "st": "3.10"}, {"sp": "N", "t": "ἐν δὲ Θόρνακι—ἐς γὰρ τοῦτον ἀφίξῃ προϊών—ἄγαλμά ἐστι Πυθαέως Ἀπόλλωνος κατὰ τὰ αὐτὰ τῷ ἐν Ἀμύκλαις πεποιημένον· τὸ δὲ σχῆμα ὁποῖόν ἐστιν, ἐπ’ ἐκείνῳ γράψω. Λακεδαιμονίοις γὰρ ἐπιφανέστερά ἐστι τὰ ἐς τὸν Ἀμυκλαῖον, ὥστε καὶ τὸν χρυσόν, ὃν Κροῖσος ὁ Λυδὸς τῷ Ἀπόλλωνι ἔπεμψε τῷ Πυθαεῖ, τούτῳ ἐς κόσμον τοῦ ἐν Ἀμύκλαις κατεχρήσαντο ἀγάλματος.", "st": "3.10"}, {"sp": "N", "t": "ἀπὸ δὲ Θόρνακος προελθόντι ἔστιν ἡ πόλις, Σπάρτη μὲν ὀνομασθεῖσα ἐξ ἀρχῆς, προσλαβοῦσα δὲ ἀνὰ χρόνον καὶ Λακεδαίμων ἡ αὐτὴ καλεῖσθαι· τέως δὲ τὸ ὄνομα τοῦτο ἔκειτο τῇ γῇ. ὃ δὲ ἐν τῇ συγγραφῇ μοι τῇ Ἀτθίδι ἐπανόρθωμα ἐγένετο, μὴ τὰ πάντα με ἐφεξῆς, ⟨τὰ δὲ⟩ μάλιστα ἄξια μνήμης ἐπιλεξάμενον ἀπ’ αὐτῶν εἰρηκέναι, δηλώσω δὴ πρὸ τοῦ λόγου τοῦ ἐς Σπαρτιάτας· ἐμοὶ γὰρ ἐξ ἀρχῆς ἠθέλησεν ὁ λόγος ἀπὸ πολλῶν καὶ οὐκ ἀξίων ἀφηγήσεως, ὧν [ἃ] ἕκαστοι παρὰ σφίσι λέγουσιν, ἀποκρῖναι τὰ ἀξιολογώτατα. ὡς οὖν εὖ βεβουλευμένος οὐκ ἔστιν ὅπου παραβήσομαι.", "st": "3.11"}, {"sp": "N", "t": "Λακεδαιμονίων τοῖς Σπάρτην ἔχουσίν ἐστιν ἀγορὰ θέας ἀξία, καὶ τῆς τε γερουσίας βουλευτήριον καὶ τῶν ἐφόρων καὶ νομοφυλάκων καὶ καλουμένων Βιδιαίων ἀρχεῖά ἐστιν ἐπὶ τῆς ἀγορᾶς. ἡ μὲν δὴ γερουσία συνέδριον Λακεδαιμονίοις κυριώτατον τῆς πολιτείας, οἱ λοιποὶ δέ εἰσιν ἄρχοντες· τοῖς δὲ ἐφόροις καὶ Βιδιαίοις πέντε ἀριθμὸν ἑκατέροις οὖσι, τοῖς μὲν ⟨τοὺς⟩ ἐπὶ τῷ Πλατανιστᾷ καλουμένῳ καὶ ἄλλους τῶν ἐφήβων ἀγῶνας τιθέναι καθέστηκεν, ἔφοροι δὲ τά τε ἄλλα διοικοῦσι τὰ σπουδῆς μάλιστα ἄξια καὶ παρέχονται τὸν ἐπώνυμον, καθὰ δὴ καὶ Ἀθηναίοις τῶν καλουμένων ἐννέα ἐπώνυμός ἐστιν εἷς ἄρχων.", "st": "3.11"}, {"sp": "N", "t": "ἐπιφανέστατον δὲ τῆς ἀγορᾶς ἐστιν ἣν στοὰν Περσικὴν ὀνομάζουσιν ἀπὸ λαφύρων ποιηθεῖσαν τῶν Μηδικῶν· ἀνὰ χρόνον δὲ αὐτὴν ἐς μέγεθος τὸ νῦν καὶ ἐς κόσμον τὸν παρόντα μεταβεβλήκασιν. εἰσὶ δὲ ἐπὶ τῶν κιόνων Πέρσαι λίθου λευκοῦ καὶ ἄλλοι καὶ Μαρδόνιος ὁ Γωβρύου. πεποίηται δὲ καὶ Ἀρτεμισία, θυγάτηρ μὲν Λυγδάμιδος, ἐβασίλευσε δὲ Ἁλικαρνασσοῦ· ταύτην φασὶν ἑκουσίως ἐπὶ τὴν Ἑλλάδα συστρατεῦσαι Ξέρξῃ καὶ ἔργα ἐν τῇ ναυμαχίᾳ περὶ Σαλαμῖνα ἀποδείξασθαι.", "st": "3.11"}, {"sp": "N", "t": "ναοὶ δέ εἰσιν ἐπὶ τῆς ἀγορᾶς Καίσαρος, ὃς μοναρχίας πρῶτος ἐν Ῥωμαίοις ἐπεθύμησεν καὶ ἀρχὴν τὴν καθεστηκυῖαν πρῶτος ἐκτήσατο, ὁ δὲ Αὐγούστῳ πεποίηται παιδὶ ἐκείνου τήν τε βασιλείαν βεβαιωσαμένῳ μᾶλλον καὶ ἀξιώματος καὶ δυνάμεως ἐς πλέον ἢ ⟨ὁ⟩ πατήρ οἱ προελθόντι· τὸ δὲ ὄνομα ἦν τούτῳ Αὔγουστος, ὃ κατὰ γλῶσσαν δύναται τὴν Ἑλλήνων σεβαστός.", "st": "3.11"}, {"sp": "N", "t": "τοῦ δὲ Αὐγούστου δεικνύουσι πρὸς τῷ βωμῷ χαλκῆν εἰκόνα Ἀγίου. τοῦτον τὸν Ἀγίαν μαντευσάμενόν φασι Λυσάνδρῳ τὸ Ἀθηναίων ἑλεῖν ναυτικὸν περὶ Αἰγὸς ποταμοὺς πλὴν τριήρων δέκα· αὗται δὲ ἀποφεύγουσιν ἐς Κύπρον, τὰς δὲ ἄλλας οἱ Λακεδαιμόνιοι καὶ αὐτὰς καὶ τοὺς ἄνδρας αἱροῦσιν. ὁ δὲ Ἀγίας Ἀγελόχου παῖς ἦν τοῦ Τισαμενοῦ·", "st": "3.11"}, {"sp": "N", "t": "Τισαμενῷ δὲ ὄντι Ἠλείῳ τῶν Ἰαμιδῶν λόγιον ἐγένετο ἀγῶνας ἀναιρήσεσθαι πέντε ἐπιφανεστάτους αὐτόν. οὕτω πένταθλον Ὀλυμπίασιν ἀσκήσας ἀπῆλθεν ἡττηθείς, καίτοι τὰ δύο γε ἦν πρῶτος· καὶ γὰρ δρόμῳ τε ἐκράτει καὶ πηδήματι Ἱερώνυμον τὸν Ἄνδριον. καταπαλαισθεὶς δὲ ὑπ’ αὐτοῦ καὶ ἁμαρτὼν τῆς νίκης συνίησι τοῦ χρησμοῦ, διδόναι οἱ τὸν θεὸν μαντευομένῳ πέντε ἀγῶνας πολέμῳ κρατῆσαι.", "st": "3.11"}, {"sp": "N", "t": "Λακεδαιμόνιοι δὲ—οὐ γὰρ εἶχον ἀνηκόως ὧν Τισαμενῷ προεῖπεν ἡ Πυθία—πείθουσι μετοικήσαντα ἐξ Ἤλιδος μαντεύεσθαι Σπαρτιατῶν τῷ κοινῷ· καί σφισιν ὁ Τισαμενὸς ἀγῶνας πολέμου πέντε ἐνίκησε, πρῶτον μὲν Πλαταιᾶσιν ἐναντία Περσῶν, δεύτερον δὲ ἐν Τεγέᾳ πρὸς Τεγεάτας καὶ Ἀργείους μάχης Λακεδαιμονίοις συνεστώσης, ἐπὶ τούτοις δὲ ἐν Διπαιεῦσιν Ἀρκάδων πάντων πλὴν Μαντινέων ἀντιτεταγμένων· οἱ δὲ Διπαιεῖς ἐν τῇ Μαιναλίᾳ πόλισμα Ἀρκάδων ἦσαν.", "st": "3.11"}, {"sp": "N", "t": "τέταρτον δὲ ἠγωνίσατο πρὸς τοὺς ἐξ ἰσθμοῦ ⟨ἐς⟩ Ἰθώμην ἀποστάντας [ἀπὸ] τῶν εἱλώτων· ἀπέστησαν δὲ οὐχ ἅπαντες οἱ εἵλωτες, ἀλλὰ τὸ Μεσσηνιακὸν ἀπὸ τῶν ἀρχαίων εἱλώτων ἀποσχισθέντες· καί μοι καὶ τάδε ὁ λόγος αὐτίκα ἐπέξεισι. τότε δὲ οἱ Λακεδαιμόνιοι τοὺς ἀποστάντας ἀπελθεῖν ὑποσπόνδους εἴασαν Τισαμενῷ καὶ τῷ ἐν Δελφοῖς χρηστηρίῳ πειθόμενοι· τελευταῖον δὲ ὁ Τισαμενὸς ἐμαντεύσατο ἐν Τανάγρᾳ σφίσι πρὸς Ἀργείους καὶ Ἀθηναίους γινομένης συμβολῆς.", "st": "3.11"}, {"sp": "N", "t": "τὰ μὲν Τισαμενοῦ τοιαῦτα ἐπυνθανόμην ὄντα· Σπαρτιάταις δὲ ἐπὶ τῆς ἀγορᾶς Πυθαέως τέ ἐστιν [καὶ] Ἀπόλλωνος καὶ Ἀρτέμιδος καὶ Λητοῦς ἀγάλματα. Χορὸς δὲ οὗτος ὁ τόπος καλεῖται πᾶς, ὅτι ἐν ταῖς γυμνοπαιδίαις—ἑορτὴ δὲ εἴ τις ἄλλη καὶ αἱ γυμνοπαιδίαι διὰ σπουδῆς Λακεδαιμονίοις εἰσίν—ἐν ταύταις οὖν οἱ ἔφηβοι χοροὺς ἱστᾶσι τῷ Ἀπόλλωνι. τούτων δὲ οὐ πόρρω Γῆς ἱερὸν καὶ Διός ἐστιν Ἀγοραίου, τὸ δὲ Ἀθηνᾶς Ἀγοραίας καὶ Ποσειδῶνος ὃν ἐπονομάζουσιν Ἀσφάλιον, καὶ Ἀπόλλωνος αὖθις καὶ Ἥρας·", "st": "3.11"}, {"sp": "N", "t": "ἀνάκειται δὲ καὶ Δήμου τοῦ Σπαρτιατῶν ἀνδριὰς μεγέθει μέγας. καὶ Μοιρῶν Λακεδαιμονίοις ἐστὶν ἱερόν, Ὀρέστου δὲ τοῦ Ἀγαμέμνονος πρὸς αὐτῷ τάφος· κομισθέντα γὰρ ἐκ Τεγέας τοῦ Ὀρέστου τὰ ὀστᾶ κατὰ μαντείαν θάπτουσιν ἐνταῦθα. παρὰ δὲ τοῦ Ὀρέστου τὸν τάφον ἐστὶν εἰκὼν Πολυδώρου τοῦ Ἀλκαμένους, ὃν βασιλέων ἐς τοσοῦτο τιμῆς προήχασιν ὥστε οἱ τὰς ἀρχὰς ἔχοντες, ὁπόσα δεῖ σημαίνεσθαι, τοῦ Πολυδώρου σημαίνονται τῇ εἰκόνι.", "st": "3.11"}, {"sp": "N", "t": "ἔστι δὲ καὶ Ἑρμῆς Ἀγοραῖος Διόνυσον φέρων παῖδα, καὶ τὰ ἀρχαῖα καλούμενα Ἐφορεῖα, ἐν δὲ αὐτοῖς Ἐπιμενίδου τοῦ Κρητὸς μνῆμα καὶ Ἀφαρέως τοῦ Περιήρους· καὶ τά γε ἐς Ἐπιμενίδην Λακεδαιμονίους δοξάζω μᾶλλον Ἀργείων λέγειν εἰκότα. ἐνταῦθα, ἔνθα αἱ Μοῖραι, καὶ Ἑστία τοῖς Λακεδαιμονίοις ἐστὶ καὶ Ζεὺς Ξένιος καὶ Ἀθηνᾶ Ξενία.", "st": "3.11"}, {"sp": "N", "t": "ἰόντι δὲ ἐκ τῆς ἀγορᾶς κατὰ τὴν ὁδὸν ἣν Ἀφεταΐδα ὀνομάζουσι, τὰ καλούμενα Βοώνητά ἐστι· καί με ὁ λόγος ἀπαιτεῖ πρότερα εἰπεῖν τὰ ἐς τὴν ἐπίκλησιν τῆς ὁδοῦ. τοῖς μνηστῆρσιν Ἰκάριον τῆς Πηνελόπης φασὶν ἀγῶνα προθεῖναι δρόμου· καὶ ὅτι μὲν Ὀδυσσεὺς ἐκράτει, δῆλά ἐστιν, ἀφεθῆναι δὲ αὐτοὺς λέγουσιν ἐς τὸν δρόμον διὰ τῆς ὁδοῦ τῆς Ἀφεταΐδος.", "st": "3.12"}, {"sp": "N", "t": "δοκεῖν δ’ ἐμοὶ δρόμου Ἰκάριος τὸ ἀγώνισμα ἐποίησε μιμούμενος Δαναόν. Δαναῷ γὰρ τοῦτο ἐπὶ ταῖς θυγατράσιν εὑρέθη, καὶ ὡς γυναῖκα οὐδεὶς ἤθελεν ἐξ αὐτῶν διὰ τὸ μίασμα ἀγαγέσθαι, διέπεμπε δὴ ὁ Δαναὸς ἕδνων ἄνευ δώσειν ᾗ ἂν ἕκαστος κατὰ κάλλος ἀρέσκηται· ἀφικομένοις δὲ ἀνδράσιν οὐ πολλοῖς ἀγῶνα δρόμου κατέστησε, καὶ πρώτῳ τε ἐλθόντι ἐγένετο ἑλέσθαι πρώτῳ τῶν ἄλλων καὶ μετ’ ἐκεῖνον τῷ δευτέρῳ καὶ ἤδη κατὰ τὰ αὐτὰ ἄχρι τοῦ τελευταίου· τὰς δὲ ὑπολειφθείσας μένειν ἔφοδον ἄλλην μνηστήρων ἔδει καὶ ἀγῶνα ἄλλον δρόμου.", "st": "3.12"}, {"sp": "N", "t": "Λακεδαιμονίοις δὲ κατὰ τὴν ὁδὸν ταύτην ἐστίν, ὡς ἤδη λέλεκταί μοι, τὰ ὀνομαζόμενα Βοώνητα, Πολυδώρου ποτὲ οἰκία τοῦ βασιλέως· ἀποθανόντος δὲ παρὰ τοῦ Πολυδώρου τῆς γυναικὸς ἐπρίαντο ἀντιδόντες βοῦς. ἀργύρου γὰρ οὐκ ἦν πω τότε οὐδὲ χρυσοῦ νόμισμα, κατὰ τρόπον δὲ ἔτι τὸν ἀρχαῖον ἀντεδίδοσαν βοῦς καὶ ἀνδράποδα καὶ ἀργὸν τὸν ἄργυρον καὶ χρυσόν·", "st": "3.12"}, {"sp": "N", "t": "οἱ δὲ ἐς τὴν Ἰνδικὴν ἐσπλέοντες φορτίων φασὶν Ἑλληνικῶν τοὺς Ἰνδοὺς ἀγώγιμα ἄλλα ἀνταλλάσσεσθαι, νόμισμα δὲ οὐκ ἐπίστασθαι, καὶ ταῦτα χρυσοῦ τε ἀφθόνου καὶ χαλκοῦ παρόντος σφίσι. τοῦ δὲ τῶν Βιδιαίων ἀρχείου πέραν ἐστὶν Ἀθηνᾶς ἱερόν· Ὀδυσσεὺς δὲ ἱδρύσασθαι τὸ ἄγαλμα λέγεται καὶ ὀνομάσαι Κελεύθειαν, τοὺς Πηνελόπης μνηστῆρας τῷ δρόμῳ νικήσας. ἱδρύσατο δὲ τῆς Κελευθείας ἱερὰ ἀριθμῷ τρία διεστηκότα ἀπ’ ἀλλήλων.", "st": "3.12"}, {"sp": "N", "t": "προϊόντων δὲ κατὰ τὴν Ἀφεταΐδα ἡρῷά ἐστιν Ἴοπός τε κατὰ Λέλεγα ἢ Μύλητα γενέσθαι δοκοῦντος καὶ Ἀμφιαράου τοῦ Ὀικλέους· τοῦτο δὲ ⟨τοὺς⟩ Τυνδάρεω παῖδας νομίζουσιν ἅτε ἀνεψιῷ τῷ Ἀμφιαράῳ ποιῆσαι· καὶ αὐτοῦ Λέλεγός ἐστιν ἡρῷον, τούτων δὲ οὐ πόρρω τέμενος Ποσειδῶνος [Ταιναρίου]—Ταινάριον δὲ ἐπονομάζουσιν—", "st": "3.12"}, {"sp": "N", "t": "οὐ μακρὰν δὲ Ἀθηνᾶς ἄγαλμα, ὃ τοὺς ἐς Ἰταλίαν τε καὶ Τάραντα ἀποικισθέντας ἀναθεῖναι λέγουσι. τὸ δὲ χωρίον, ὃ καλοῦσιν Ἑλλήνιον, ἐστὶν εἰρημένον ὡς οἱ τῶν Ἑλλήνων Ξέρξην διαβαίνοντα ἐς τὴν Εὐρώπην παρεσκευάζοντο ἀμυνούμενοι, κατὰ τοῦτο τὸ χωρίον βουλευσάμενοι τρόπον ὅντινα ἀνθέξουσιν. ὁ δὲ ἕτερος τῶν λόγων τοὺς Μενελάου χάριτι στρατεύσαντας ἐπὶ Ἴλιον βουλεύσασθαί φησιν ἐνταῦθα ὅπως ἀναπλεῦσαί τε ἐς Τροίαν καὶ δίκας δυνήσονται παρὰ Ἀλεξάνδρου λαβεῖν τῆς Ἑλένης ἁρπαγῆς.", "st": "3.12"}, {"sp": "N", "t": "τοῦ δὲ Ἑλληνίου πλησίον Ταλθυβίου μνῆμα ἀποφαίνουσι· δεικνύουσι δὲ καὶ Ἀχαιῶν Αἰγιεῖς ἐπὶ τῆς ἀγορᾶς, Ταλθυβίου καὶ οὗτοι φάμενοι μνῆμα εἶναι. Ταλθυβίου δὲ τούτου μήνιμα ἐπὶ τῷ φόνῳ τῶν κηρύκων, οἳ παρὰ βασιλέως Δαρείου γῆν τε καὶ ὕδωρ αἰτήσοντες ἐς τὴν Ἑλλάδα ἐπέμφθησαν, Λακεδαιμονίοις μὲν ἐπεσήμαινεν ἐς τὸ δημόσιον, ἐν Ἀθήναις δὲ ἰδίᾳ τε καὶ ἐς ἑνὸς οἶκον ἀνδρὸς κατέσκηψε Μιλτιάδου τοῦ Κίμωνος· ἐγεγόνει δὲ καὶ τῶν κηρύκων τοῖς ἐλθοῦσιν ἐς τὴν Ἀττικὴν ὁ Μιλτιάδης ἀποθανεῖν αἴτιος ὑπὸ Ἀθηναίων.", "st": "3.12"}, {"sp": "N", "t": "Λακεδαιμονίοις δὲ ἔστι μὲν Ἀπόλλωνος Ἀκρίτα βωμός, ἔστι δ’ ἐπονομαζόμενον Γάσηπτον ἱερὸν Γῆς· Ἀπόλλων δὲ ὑπὲρ αὐτὸ ἵδρυται Μαλεάτης. ἐπὶ δὲ τῷ πέρατι ⟨τῆς⟩ Ἀφεταΐδος, ἐγγύτατα ἤδη τοῦ τείχους, Δικτύννης ἐστὶν ἱερὸν καὶ βασίλειοι τάφοι τῶν καλουμένων Εὐρυπωντιδῶν· παρὰ δὲ τὸ Ἑλλήνιον Ἀρσινόης ἱερόν, Λευκίππου τε θυγατρὸς καὶ γυναικῶν τῶν Πολυδεύκους καὶ Κάστορος ἀδελφῆς. πρὸς δὲ τοῖς Φρουρίοις καλουμένοις ναός ἐστιν Ἀρτέμιδος, καὶ προελθοῦσιν ὀλίγον πεποίηται μνῆμα τοῖς ἐξ Ἤλιδος μάντεσι, καλουμένοις δὲ Ἰαμίδαις.", "st": "3.12"}, {"sp": "N", "t": "καὶ Μάρωνός ἐστιν ἱερὸν καὶ Ἀλφειοῦ· Λακεδαιμονίων δὲ τῶν ἐς Θερμοπύλας στρατευσαμένων λόγου μάλιστα ἀξίως μαχέσασθαι μετά γε αὐτὸν δοκοῦσι Λεωνίδαν. τοῦ δὲ Τροπαίου Διὸς τὸ ἱερὸν ἐποίησαν οἱ Δωριεῖς πολέμῳ τούς τε ἄλλους Ἀχαιούς, οἳ γῆν τὴν Λακωνικὴν τηνικαῦτα εἶχον, καὶ τοὺς Ἀμυκλαιεῖς κρατήσαντες. τὸ δὲ ἱερὸν τῆς Μεγάλης μητρὸς τιμᾶται περισσῶς δή τι. μετὰ δὲ αὐτὸ ἡρῷα Ἱππολύτου τέ ἐστι τοῦ Θησέως καὶ Αὐλῶνος Ἀρκάδος, υἱοῦ δὲ Τλησιμένους· Τλησιμένη⟨ν⟩ δὲ Παρθενοπαίου τοῦ Μελανίωνος ἀδελφόν, οἱ δὲ παῖδα εἶναι λέγουσιν.", "st": "3.12"}, {"sp": "N", "t": "ἑτέρα δὲ ἐκ τῆς ἀγορᾶς ἐστιν ἔξοδος, καθ’ ἣν πεποίηταί σφισιν ἡ καλουμένη Σκιάς, ἔνθα καὶ νῦν ἔτι ἐκκλησιάζουσι. ταύτην τὴν Σκιάδα Θεοδώρου τοῦ Σαμίου φασὶν εἶναι ποίημα, ὃς πρῶτος διαχέαι σίδηρον εὗρε καὶ ἀγάλματα ἀπ’ αὐτοῦ πλάσαι. ἐνταῦθα ἐκρέμασαν οἱ Λακεδαιμόνιοι τὴν Τιμοθέου τοῦ Μιλησίου κιθάραν, καταγνόντες ὅτι χορδαῖς ἑπτὰ ταῖς ἀρχαίαις ἐφεῦρεν ἐν τῇ κιθαρῳδίᾳ τέσσαρας χορδάς.", "st": "3.12"}, {"sp": "N", "t": "πρὸς δὲ τῇ Σκιάδι οἰκοδόμημά ἐστι περιφερές, ἐν δὲ αὐτῷ Διὸς καὶ Ἀφροδίτης ἀγάλματα ἐπίκλησιν Ὀλυμπίων· τοῦτο Ἐπιμενίδην κατασκευάσαι λέγουσιν, οὐχ ὁμολογοῦντες τὰ ἐς αὐτὸν Ἀργείοις, ὅπου μηδὲ πολεμῆσαί φασι πρὸς Κνωσσίους.", "st": "3.12"}, {"sp": "N", "t": "πλησίον δὲ ἔστι μὲν Κυνόρτου τοῦ Ἀμύκλα τάφος, ἔστι δὲ καὶ Κάστορος μνῆμα, ἐπὶ δὲ αὐτῷ καὶ ἱερὸν πεποίηται· τεσσαρακοστῷ γὰρ ὕστερον ἔτει τῆς μάχης τῆς πρὸς Ἴδαν καὶ Λυγκέα θεοὺς τοὺς Τυνδάρεω παῖδας καὶ οὐ πρότερον νομισθῆναί φασι. δείκνυται δὲ πρὸς τῇ Σκιάδι καὶ Ἴδα καὶ Λυγκέως τάφος. κατὰ μὲν δὴ τοῦ λόγου τὸ εἰκὸς ἐτάφησαν ἐν τῇ Μεσσηνίᾳ καὶ οὐ ταύτῃ·", "st": "3.13"}, {"sp": "N", "t": "Μεσσηνίων δὲ αἱ συμφοραὶ καὶ ὁ χρόνος, ὅσον ἔφυγον ἐκ Πελοποννήσου, πολλὰ τῶν ἀρχαίων καὶ κατελθοῦσιν ἐποίησεν ἄγνωστα, ἅτε δὲ ἐκείνων οὐκ εἰδότων ἔστιν ἤδη τοῖς ἐθέλουσιν ἀμφισβητεῖν. Λακεδαιμονίοις δὲ ἀπαντικρὺ τῆς Ὀλυμπίας Ἀφροδίτης ἐστὶ ναὸς Κόρης Σωτείρας· ποιῆσαι δὲ τὸν Θρᾷκα Ὀρφέα λέγουσιν, οἱ δὲ Ἄβαριν ἀφικόμενον ἐξ Ὑπερβορέων.", "st": "3.13"}, {"sp": "N", "t": "ὁ δὲ Καρνειός, ὃν Οἰκέταν ἐπονομάζουσι, τιμὰς εἶχεν ἐν Σπάρτῃ καὶ πρὶν Ἡρακλείδας κατελθεῖν, ἵδρυτο δὲ ἐν οἰκίᾳ Κριοῦ τοῦ Θεοκλέους, ἀνδρὸς μάντεως· τούτου δὲ τοῦ Κριοῦ γεμιζούσῃ τῇ θυγατρὶ ὕδωρ συντυχόντες κατάσκοποι τῶν Δωριέων αὐτῇ τε ἀφίκοντο ἐς λόγους καὶ παρὰ τὸν Κριὸν ἐλθόντες διδάσκονται τὴν ἅλωσιν τῆς Σπάρτης.", "st": "3.13"}, {"sp": "N", "t": "Κάρνειον δὲ Ἀπόλλωνα Δωριεῦσι μὲν τοῖς πᾶσι σέβεσθαι καθέστηκεν ἀπὸ Κάρνου γένος ἐξ Ἀκαρνανίας, μαντευομένου δὲ ἐξ Ἀπόλλωνος· τοῦτον γὰρ τὸν Κάρνον ἀποκτείναντος Ἱππότου τοῦ Φύλαντος ἐνέπεσεν ἐς τὸ στρατόπεδον τοῖς Δωριεῦσι μήνιμα Ἀπόλλωνος, καὶ Ἱππότης τε ἔφυγεν ἐπὶ τῷ φόνῳ καὶ Δωριεῦσιν ἀπὸ τούτου τὸν Ἀκαρνᾶνα μάντιν καθέστηκεν ἱλάσκεσθαι. ἀλλὰ γὰρ Λακεδαιμονίοις οὐχ οὗτος ὁ Οἰκέτας ἐστὶ Καρνειός, ὁ δὲ ἐν τοῦ μάντεως Κριοῦ τιμώμενος Ἀχαιῶν ἔτι ἐχόντων τὴν Σπάρτην.", "st": "3.13"}, {"sp": "N", "t": "Πραξίλλῃ μὲν δὴ πεποιημένα ἐστὶν ὡς Εὐρώπης εἴη καὶ ⟨Διὸς ὁ⟩ Κάρνειος καὶ αὐτὸν ἀνεθρέψατο Ἀπόλλων καὶ Λητώ· λέγεται δὲ καὶ ἄλλος ἐπ’ αὐτῷ λόγος, ἐν τῇ Ἴδῃ τῇ Τρωικῇ κρανείας ἐν Ἀπόλλωνος ἄλσει πεφυκυίας τοὺς Ἕλληνας ἐκτεμεῖν ἐς τοῦ ἵππου τοῦ δουρείου τὴν ποίησιν· μαθόντες δὲ ὀργήν σφισιν ἔχειν τὸν θεὸν θυσίαις ἱλάσκονται καὶ Ἀπόλλωνα ὀνομάζουσι Κάρνειον ἀπὸ τῶν κρανειῶν, ὑπερθέντες τὸ ῥῶ κατὰ δή τι ἀρχαῖον.", "st": "3.13"}, {"sp": "N", "t": "τοῦ Καρνείου δὲ οὐ πόρρω καλούμενόν ἐστιν ἄγαλμα Ἀφεταίου· τοῖς δὲ Πηνελόπης μνηστῆρσί φασιν ἐντεῦθεν γενέσθαι τοῦ δρόμου τὴν ἀρχήν. ἔστι δέ τι χωρίον ἔχον στοὰς ἐν τετραγώνῳ τῷ σχήματι, ἔνθα σφίσιν ἐπιπράσκετο ὁ ῥῶπος τὸ ἀρχαῖον· πρὸς τούτῳ Διὸς Ἀμβουλίου καὶ Ἀθηνᾶς ἐστιν Ἀμβουλίας βωμὸς καὶ Διοσκούρων καὶ τούτων Ἀμβουλίων.", "st": "3.13"}, {"sp": "N", "t": "ἀπαντικρὺ δὲ ἥ τε ὀνομαζομένη Κολώνα καὶ Διονύσου Κολωνάτα ναός, πρὸς αὐτῷ δὲ τέμενός ἐστιν ἥρωος, ὃν τῆς ὁδοῦ τῆς ἐς Σπάρτην Διονύσῳ φασὶ γενέσθαι ἡγεμόνα· τῷ δὲ ἥρωι τούτῳ πρὶν ἢ τῷ θεῷ θύουσιν αἱ Διονυσιάδες καὶ αἱ Λευκιππίδες. τὰς δὲ ἄλλας ἕνδεκα ἃς καὶ αὐτὰς Διονυσιάδας ὀνομάζουσι, ταύταις δρόμου προτιθέασιν ἀγῶνα·", "st": "3.13"}, {"sp": "N", "t": "δρᾶν δὲ οὕτω σφίσιν ἦλθεν ἐκ Δελφῶν. τοῦ Διονύσου δὲ οὐ μακρὰν Διὸς ἱερόν ἐστιν Εὐανέμου, τούτου δὲ ἐν δεξιᾷ Πλευρῶνος ἡρῷον. γεγόνασι δὲ οἱ Τυνδάρεω παῖδες τὰ πρὸς μητρὸς ἀπὸ τοῦ Πλευρῶνος· Θέστιον γὰρ τὸν Λήδας πατέρα Ἄσιός φησιν ἐν τοῖς ἔπεσιν Ἀγήνορος παῖδα εἶναι τοῦ Πλευρῶνος. τοῦ δὲ ἡρῴου λόφος ἐστὶν οὐ πόρρω καὶ Ἥρας ἐπὶ τῷ λόφῳ ναὸς Ἀργείας· ἱδρύσασθαι δὲ Εὐρυδίκην φασὶ Λακεδαίμονος θυγατέρα, γυναῖκα δὲ Ἀκρισίου τοῦ Ἄβαντος. Ἥρας δὲ ἱερὸν Ὑπερχειρίας κατὰ μαντείαν ἐποιήθη, τοῦ Εὐρώτα πολὺ τῆς γῆς σφισιν ἐπικλύζοντος.", "st": "3.13"}, {"sp": "N", "t": "ξόανον δὲ ἀρχαῖον καλοῦσιν Ἀφροδίτης Ἥρας· ἐπὶ δὲ θυγατρὶ γαμουμένῃ νενομίκασι τὰς μητέρας τῇ θεῷ θύειν. τοῦ λόφου δὲ κατὰ τὴν ἐς δεξιὰν ὁδὸν Ἑτοιμοκλέους ἐστὶν εἰκών· τῷ δὲ Ἑτοιμοκλεῖ καὶ αὐτῷ ⟨καὶ⟩ Ἱπποσθένει τῷ πατρὶ πάλης εἰσὶν Ὀλυμπικαὶ νῖκαι, [καὶ] συναμφοτέροις μὲν μία τε καὶ δέκα, τῷ δὲ Ἱπποσθένει μιᾷ νίκῃ τὸν υἱὸν παρελθεῖν ὑπῆρξεν.", "st": "3.13"}, {"sp": "N", "t": "ἐκ δὲ τῆς ἀγορᾶς πρὸς ἥλιον ἰόντι δυόμενον τάφος κενὸς Βρασίδᾳ τῷ Τέλλιδος πεποίηται· ἀπέχει δὲ οὐ πολὺ τοῦ τάφου τὸ θέατρον, λίθου λευκοῦ, θέας ἄξιον. τοῦ θεάτρου δὲ ἀπαντικρὺ Παυσανίου τοῦ Πλαταιᾶσιν ἡγησαμένου μνῆμά ἐστι, τὸ δὲ ἕτερον Λεωνίδου— καὶ λόγους κατὰ ἔτος ἕκαστον ἐπ’ αὐτοῖς λέγουσι καὶ τιθέασιν ἀγῶνα, ἐν ᾧ πλὴν Σπαρτιατῶν ἄλλῳ γε οὐκ ἔστιν ἀγωνίζεσθαι—, τὰ [δὲ] ὀστᾶ τοῦ Λεωνίδου τεσσαράκοντα ἔτεσιν ὕστερον ἀνελομένου ἐκ Θερμοπυλῶν τοῦ Παυσανίου. κεῖται δὲ καὶ στήλη πατρόθεν τὰ ὀνόματα ἔχουσα οἳ πρὸς Μήδους τὸν ἐν Θερμοπύλαις ἀγῶνα ὑπέμειναν.", "st": "3.14"}, {"sp": "N", "t": "καλεῖται δὲ ἐν τῇ Σπάρτῃ Θεομηλίδα χωρίον· κατὰ τοῦτο τῆς πόλεως τάφοι τῶν Ἀγιαδῶν βασιλέων εἰσὶ καὶ πλησίον ὀνομαζομένη λέσχη Κροτανῶν· εἰσὶ δὲ οἱ Κροτανοὶ Πιτανατῶν μοῖρα. Ἀσκληπιοῦ δὲ οὐ πόρρω τῆς λέσχης ἐστὶν ἱερὸν, ἐν Ἀγιαδῶν καλούμενον. προελθοῦσι δὲ Ταινάρου μνῆμά ἐστι, καὶ τὴν ἄκραν τὴν ἐς θάλασσαν ἐσέχουσαν ἀπὸ τούτου φασὶν ὀνομασθῆναι· θεῶν δὲ ἱερὰ Ποσειδῶνός ἐστιν Ἱπποκουρίου καὶ Ἀρτέμιδος Αἰγιναίας. ἐπανελθοῦσι δὲ ὀπίσω πρὸς τὴν λέσχην ἐστὶν Ἀρτέμιδος Ἰσσωρίας ἱερόν· ἐπονομάζουσι δὲ αὐτὴν καὶ Λιμναίαν, οὖσαν οὐκ Ἄρτεμιν, Βριτόμαρτιν δὲ τὴν Κρητῶν· τὰ δὲ ἐς αὐτὴν ὁ Αἰγιναῖος ἔχει μοι λόγος.", "st": "3.14"}, {"sp": "N", "t": "ἐγγυτάτω δὲ τῶν μνημάτων ἃ τοῖς Ἀγιάδαις πεποίηται στήλην ὄψει, γεγραμμέναι δέ εἰσιν ἃς Χίονις ἀνὴρ Λακεδαιμόνιος δρόμου νίκας ἀνείλετο ἄλλας τε καὶ Ὀλυμπίασιν· ἐνταῦθα δὲ ἑπτὰ ἐγένοντό ⟨οἱ⟩ νῖκαι, τέσσαρες μὲν σταδίου, διαύλου δὲ αἱ λοιπαί· τὸν δὲ σὺν τῇ ἀσπίδι δρόμον ἐπὶ ἀγῶνι λήγοντι οὐ συνέβαινεν εἶναί πω. Χίονιν δὲ καὶ τοῦ στόλου μετασχεῖν τῷ Θηραίῳ Βάττῳ καὶ Κυρήνην οἰκίσαι σὺν ἐκείνῳ καὶ Λιβύων καταστρέψασθαι τοὺς προσχώρους λέγουσιν.", "st": "3.14"}, {"sp": "N", "t": "τὸ δὲ ἱερὸν τῆς Θέτιδος κατασκευασθῆναί φασιν ἐπ’ αἰτίᾳ τοιαύτῃ· πολεμεῖν μὲν πρὸς Μεσσηνίους ἀφεστηκότας, τὸν δὲ βασιλέα σφῶν Ἀνάξανδρον ἐσβαλόντα ἐς τὴν Μεσσηνίαν λαβεῖν αἰχμαλώτους γυναῖκας, ἐν δὲ αὐταῖς εἶναι Κλεώ, Θέτιδος δὲ αὐτὴν ἱέρειαν εἶναι. ταύτην ἡ τοῦ Ἀναξάνδρου γυνὴ τὴν Κλεὼ παρὰ τοῦ Ἀναξάνδρου αἰτεῖ, καὶ τό τε ξόανον τῆς Θέτιδος ἀνεῦρεν ἔχουσαν καὶ ναὸν μετ’ αὐτῆς ἱδρύσατο τῇ θεῷ· ἐποίει δὲ ταῦτα ἡ Λεανδρὶς κατὰ ὄψιν ὀνείρατος.", "st": "3.14"}, {"sp": "N", "t": "τὸ μὲν δὴ ξόανον τῆς Θέτιδος ἐν ἀπορρήτῳ φυλάσσουσι· Δήμητρα δὲ Χθονίαν Λακεδαιμόνιοι μὲν σέβειν φασὶ παραδόντος σφίσιν Ὀρφέως, δόξῃ δὲ ἐμῇ διὰ τὸ ἱερὸν τὸ ἐν Ἑρμιόνῃ κατέστη καὶ τούτοις Χθονίαν νομίζειν Δήμητρα. ἔστι δὲ καὶ Σαράπιδος νεώτατον τοῦτο Σπαρτιάταις ἱερὸν καὶ Διὸς ἐπίκλησιν Ὀλυμπίου.", "st": "3.14"}, {"sp": "N", "t": "καλοῦσι δὲ Λακεδαιμόνιοι Δρόμον, ἔνθα τοῖς νέοις καὶ ἐφ’ ἡμῶν ἔτι δρόμου μελέτη καθέστηκεν. ἐς τοῦτον τὸν Δρόμον ἰόντι ἀπὸ τοῦ τάφου τῶν Ἀγιαδῶν ἔστιν ἐν ἀριστερᾷ μνῆμα Εὐμήδους, Ἱπποκόωντος δὲ καὶ οὗτος ἦν ὁ Εὐμήδης· ἔστι δὲ ἄγαλμα ἀρχαῖον Ἡρακλέους, ᾧ θύουσιν οἱ Σφαιρεῖς· οἱ δέ εἰσιν ⟨οἱ⟩ ἐκ τῶν ἐφήβων ἐς ἄνδρας ἀρχόμενοι συντελεῖν. πεποίηται δὲ καὶ γυμνάσια ἐν τῷ Δρόμῳ, τὸ ἕτερον Εὐρυκλέους ἀνάθημα ἀνδρὸς Σπαρτιάτου· τοῦ Δρόμου δὲ ἐκτὸς κατὰ τοῦ Ἡρακλέους τὸ ἄγαλμα ἔστιν οἰκία τὰ ἐφ’ ἡμῶν ἰδιώτου, Μενελάου τὸ ἀρχαῖον. προελθόντι δὲ ἀπὸ τοῦ Δρόμου Διοσκούρων ἱερὸν καὶ Χαρίτων, τὸ δὲ Εἰλειθυίας ἐστὶν Ἀπόλλωνός τε Καρνείου καὶ Ἀρτέμιδος Ἡγεμόνης·", "st": "3.14"}, {"sp": "N", "t": "τὸ δὲ τοῦ Ἀγνίτα πεποίηται μὲν ἐν δεξιᾷ τοῦ Δρόμου, Ἀσκληπιοῦ δέ ἐστιν ἐπίκλησις ὁ Ἀγνίτας, ὅτι ἦν ἄγνου τῷ θεῷ ξόανον· ἡ δὲ ἄγνος λύγος καὶ αὐτὴ κατὰ ταὐτά ἐστι τῇ ῥάμνῳ. τοῦ Ἀσκληπιοῦ δὲ οὐ πόρρω τρόπαιον ἕστηκε, Πολυδεύκην δὲ ἀναστῆσαί φασιν ἐπὶ Λυγκεῖ· καί μοι [κἀμοὶ] καὶ τοῦτο ἀποφαίνει τὸν λόγον εἰκότα, οὐ ταφῆναι τοὺς Ἀφαρέως παῖδας ἐν Σπάρτῃ. πρὸς δὲ τοῦ Δρόμου τῇ ἀρχῇ Διόσκουροί τέ εἰσιν Ἀφετήριοι καὶ ὀλίγον προελθόντι ἡρῷον Ἄλκωνος· τὸν δὲ Ἄλκωνα λέγουσιν Ἱπποκόωντας παῖδα εἶναι. παρὰ δὲ τοῦ Ἄλκωνος τὸ ἡρῷον Ποσειδῶνός ἐστιν ἱερόν, Δωματίτην δὲ ἐπονομάζουσιν.", "st": "3.14"}, {"sp": "N", "t": "καὶ χωρίον Πλατανιστᾶς ἐστιν ἀπὸ τῶν δένδρων, αἳ δὴ ὑψηλαὶ καὶ συνεχεῖς περὶ αὐτὸ αἱ πλάτανοι πεφύκασιν. αὐτὸ δὲ τὸ χωρίον, ἔνθα τοῖς ἐφήβοις μάχεσθαι καθέστηκε, κύκλῳ μὲν εὔριπος περιέχει κατὰ ταὐτὰ καὶ εἰ νῆσον θάλασσα, ἔφοδοι δὲ ἐπὶ γεφυρῶν εἰσι. γεφυρῶν δὲ ἐφ’ ἑκατέρᾳ τῇ μέν ἐστιν ἄγαλμα Ἡρακλέους, τῇ δὲ εἰκὼν Λυκούργου· νόμους δὲ ἔς τε τὴν ἄλλην πολιτείαν καὶ ἐς τὴν μάχην τῶν ἐφήβων ἔθηκεν ὁ Λυκοῦργος.", "st": "3.14"}, {"sp": "N", "t": "καὶ τάδε ἄλλα τοῖς ἐφήβοις δρώμενά ἐστι· θύουσι πρὸ τῆς μάχης ἐν τῷ Φοιβαίῳ· τὸ δὲ Φοιβαῖόν ἐστιν ἐκτὸς τῆς πόλεως, Θεράπνης οὐ πολὺ ἀφεστηκός. ἐνταῦθα ἑκατέρα μοῖρα τῶν ἐφήβων σκύλακα κυνὸς τῷ Ἐνυαλίῳ θύουσι, θεῶν τῷ ἀλκιμωτάτῳ κρίνοντες ἱερεῖον κατὰ γνώμην εἶναι τὸ ἀλκιμώτατον ζῷον τῶν ἡμέρων. κυνὸς δὲ σκύλακας οὐδένας ἄλλους οἶδα Ἑλλήνων νομίζοντας θύειν ὅτι μὴ Κολοφωνίους· θύουσι γὰρ καὶ Κολοφώνιοι μέλαιναν τῇ Ἐνοδίῳ σκύλακα. νυκτεριναὶ δὲ ἥ τε Κολοφωνίων θυσία καὶ τῶν ἐν Λακεδαίμονι ἐφήβων καθεστήκασιν.", "st": "3.14"}, {"sp": "N", "t": "ἐπὶ δὲ τῇ θυσίᾳ κάπρους ἠθάδας οἱ ἔφηβοι συμβάλλουσι μαχουμένους· ὁποτέρων δ’ ἂν ὁ κάπρος τύχῃ νικῶν, [ἐστιν] ἐν τῷ Πλατανιστᾷ κρατῆσαι τούτους ὡς τὰ πλείω συμβαίνει. τοσάδε μὲν δρῶσιν ἐν τῷ Φοιβαίῳ· ἐς δὲ τὴν ἐπιοῦσαν ὀλίγον πρὸ μεσούσης ἡμέρας ἐσίασι κατὰ τὰς γεφύρας ἐς τὸ εἰρημένον χωρίον. τὴν μὲν δὴ ἔσοδον, καθ’ ἣν ἐσελθεῖν δεῦρο ἔστιν ἑκατέραν τάξιν, προεδήλωσε κλῆρός σφισιν ἐν τῇ νυκτί· μάχονται δὲ καὶ ἐν χερσὶ καὶ ἐμπηδῶντες λάξ, δάκνουσί τε καὶ τοὺς ὀφθαλμοὺς ἀντορύσσουσιν. ἀνὴρ μὲν δὴ πρὸς ἄνδρα τὸν εἰρημένον τρόπον μάχεται· ἀθρόοι δέ ἐμπίπτουσι βιαίως καὶ ἐς τὸ ὕδωρ ὠθοῦσιν ἀλλήλους.", "st": "3.14"}, {"sp": "N", "t": "πρὸς δὲ τῷ Πλατανιστᾷ καὶ Κυνίσκας ἐστὶν ἡρῷον, θυγατρὸς Ἀρχιδάμου βασιλεύοντος Σπαρτιατῶν· πρώτη δὲ ἱπποτρόφησε γυναικῶν καὶ Ὀλυμπίασι πρώτη νίκην ἀνείλετο ἅρματι. ἔστι δὲ τῆς στοᾶς, ἣ παρὰ τὸν Πλατανιστᾶν πεποίηται, ταύτης ὄπισθεν ἡρῷα, τὸ μὲν Ἀλκίμου, τὸ δὲ Ἐναρσφόρου καὶ ἀφεστηκὸς οὐ πολὺ Δορκέως, τὸ δὲ ἐπὶ τούτῳ Σεβροῦ· παῖδας δὲ Ἱπποκόωντος εἶναι λέγουσιν.", "st": "3.15"}, {"sp": "N", "t": "ἀπὸ δὲ τοῦ Δορκέως κρήνην τὴν πλησίον τοῦ ἡρῴου Δορκείαν, τὸ δὲ χωρίον τὸ Σέβριον καλοῦσιν ἀπὸ τοῦ Σεβροῦ. τοῦ Σεβρίου δέ ἐστιν ἐν δεξιᾷ μνῆμα Ἀλκμᾶνος, ᾧ ποιήσαντι ᾄσματα οὐδὲν ἐς ἡδονὴν αὐτῶν ἐλυμήνατο τῶν Λακώνων ἡ γλῶσσα, ἥκιστα παρεχομένη τὸ εὔφωνον.", "st": "3.15"}, {"sp": "N", "t": "Ἑλένης δὲ ἱερὰ καὶ Ἡρακλέους, τῆς μὲν πλησίον τοῦ τάφου τοῦ Ἀλκμᾶνος, τῷ δὲ ἐγγυτάτω τοῦ τείχους, ἐν αὐτῷ δὲ ἄγαλμα Ἡρακλέους ἐστὶν ὡπλισμένον· τὸ δὲ σχῆμα τοῦ ἀγάλματος διὰ τὴν πρὸς Ἱπποκόωντα καὶ τοὺς παῖδας μάχην γενέσθαι λέγουσι. τὸ δὲ ἔχθος Ἡρακλεῖ φασιν ἐς οἶκον ὑπάρξαι τὸν Ἱπποκόωντος, ὅτι μετὰ τὸν Ἰφίτου θάνατον καθαρσίων ἕνεκα ἐλθόντα αὐτὸν ἐν Σπάρτῃ ἀπηξίωσαν καθῆραι·", "st": "3.15"}, {"sp": "N", "t": "προσεγένετο δὲ ἐς τοῦ πολέμου τὴν ἀρχὴν καὶ ἄλλο τοιόνδε. Οἰωνὸς ἡλικίαν μὲν μειράκιον, ἀνεψιὸς δὲ Ἡρακλεῖ—Λικυμνίου γὰρ παῖς ἦν τοῦ ἀδελφοῦ τοῦ Ἀλκμήνης—ἀφίκετο ἐς Σπάρτην ἅμα Ἡρακλεῖ· περιιόντι δὲ καὶ θεωμένῳ τὴν πόλιν, ὡς ἐγίνετο κατὰ τοῦ Ἱπποκόωντος τὴν οἰκίαν, ἐνταῦθά οἱ κύων ἐπεφέρετο οἰκουρός. ὁ δὲ τυγχάνει τε ἀφεὶς λίθον ὁ Οἰωνὸς καὶ καταβάλλει τὴν κύνα· ἐπεκθέουσιν οὖν τοῦ Ἱπποκόωντος οἱ παῖδες καὶ ῥοπάλοις τύπτοντες κατεργάζονται τὸν Οἰωνόν.", "st": "3.15"}, {"sp": "N", "t": "τοῦτο Ἡρακλέα μάλιστα ἐξηγρίωσεν ἐς Ἱπποκόωντα καὶ τοὺς παῖδας· αὐτίκα δὲ ὡς ὀργῆς εἶχε χωρεῖ σφισιν ἐς μάχην. τότε μὲν δὴ τιτρώσκεται καὶ λαθὼν ἀπεχώρησεν· ὕστερον δὲ ἐξεγένετό οἱ στρατεύσαντι ἐς Σπάρτην τιμωρήσασθαι μὲν Ἱπποκόωντα, τιμωρήσασθαι δὲ καὶ τοὺς παῖδας τοῦ Οἰωνοῦ φόνου. τὸ δὲ μνῆμα τῷ Οἰωνῷ πεποίηται παρὰ τὸ Ἡρακλεῖον.", "st": "3.15"}, {"sp": "N", "t": "ἰόντι δὲ ἐκ τοῦ Δρόμου πρὸς ἀνίσχοντα ἥλιον ἀτραπός ἐστιν ἐν δεξιᾷ καὶ Ἀθηνᾶς Ἀξιοποίνου καλουμένης ἱερόν. ὡς γὰρ δὴ ἀμυνόμενος Ἡρακλῆς Ἱπποκόωντα καὶ τοὺς παῖδας μετῆλθε κατ’ ἀξίαν ὧν προυπῆρξεν, ἱερὸν Ἀθηνᾶς ἱδρύεται, Ἀξιοποίνου δὲ ἐπίκλησιν, ὅτι τὰς τιμωρίας οἱ παλαιοὶ τῶν ἀνθρώπων ὠνόμαζον ποινάς. ἔστι δὲ καὶ ἄλλο ἱερὸν Ἀθηνᾶς ἰόντι ἑτέραν ὁδὸν ἀπὸ τοῦ Δρόμου· Θήραν δὲ ἀναθεῖναι τὸν Αὐτεσίωνος τοῦ Τισαμενοῦ τοῦ Θερσάνδρου φασίν, ἡνίκα ἀποικίαν ἔστελλεν ἐπὶ τὴν νῆσον ἣ νῦν ἀπὸ Θήρα τούτου τὸ ὄνομα ἔσχηκε, τὸ δὲ ἀρχαῖον ἐκαλεῖτο Καλλίστη.", "st": "3.15"}, {"sp": "N", "t": "πλησίον δέ ἐστιν Ἱπποσθένους ναός, ᾧ γεγόνασιν αἱ πολλαὶ νῖκαι πάλης· σέβουσι δὲ ἐκ μαντεύματος τὸν Ἱπποσθένην ἅτε Ποσειδῶνι τιμὰς νέμοντες. τοῦ ναοῦ δὲ ἀπαντικρὺ πέδας ἐστὶν ἔχων Ἐνυάλιος, ἄγαλμα ἀρχαῖον. γνώμη δὲ Λακεδαιμονίων τε ἐς τοῦτό ἐστιν ἄγαλμα καὶ Ἀθηναίων ἐς τὴν Ἄπτερον καλουμένην Νίκην, τῶν μὲν οὔποτε τὸν Ἐνυάλιον φεύγοντα οἰχήσεσθαί σφισιν ἐνεχόμενον ταῖς πέδαις, Ἀθηναίων δὲ τὴν Νίκην αὐτόθι ἀεὶ μενεῖν οὐκ ὄντων πτερῶν. τόνδε μέν εἰσιν αἱ πόλεις αὗται τὰ ξόανα τὸν τρόπον ἱδρυμέναι καὶ ἐπὶ δόξῃ τοιαύτῃ·", "st": "3.15"}, {"sp": "N", "t": "ἐν Σπάρτῃ δὲ λέσχη τέ ἐστι καλουμένη Ποικίλη καὶ ἡρῷα πρὸς αὐτῇ Κάδμου τοῦ Ἀγήνορος τῶν τε ἀπογόνων, Οἰολύκου τοῦ Θήρα καὶ Αἰγέως τοῦ Οἰολύκου. ποιῆσαι δὲ τὰ ἡρῷα λέγουσι Μαῖσιν καὶ Λαίαν τε καὶ Εὐρώπαν, εἶναι δὲ αὐτοὺς Ὑραίου παῖδας τοῦ Αἰγέως. ἐποίησαν δὲ καὶ τῷ Ἀμφιλόχῳ τὸ ἡρῷον, ὅτι σφίσιν ὁ πρόγονος Τισαμενὸς μητρὸς ἦν Δημωνάσσης, ἀδελφῆς Ἀμφιλόχου.", "st": "3.15"}, {"sp": "N", "t": "μόνοις δὲ Ἑλλήνων Λακεδαιμονίοις καθέστηκεν Ἥραν ἐπονομάζειν Αἰγοφάγον καὶ αἶγας τῇ θεῷ θύειν. Ἡρακλέα δὲ λέγουσιν ἱδρύσασθαι τὸ ἱερὸν καὶ αἶγας θῦσαι πρῶτον, ὅτι μαχομένῳ οἱ πρὸς Ἱπποκόωντα καὶ τοὺς παῖδας οὐδὲν ἐκ τῆς Ἥρας ἀπήντησεν ἐμπόδιον, ὥσπερ γε ἐπὶ τῶν ἄλλων ἐδόξαζεν ἐναντιοῦσθαί οἱ τὴν θεόν· αἶγας δὲ αὐτὸν θῦσαί φασιν ἱερείων ἀπορήσαντα ἀλλοίων.", "st": "3.15"}, {"sp": "N", "t": "τοῦ θεάτρου δὲ οὐ πόρρω Ποσειδῶνός τε ἱερόν ἐστι Γενεθλίου καὶ ἡρῷα Κλεοδαίου τοῦ Ὕλλου καὶ Οἰβάλου. τῶν δὲ Ἀσκληπιείων τὸ ἐπιφανέστατον πεποίηταί σφισι πρὸς τοῖς Βοωνήτοις, ἐν ἀριστερᾷ δὲ ἡρῷον Τηλέκλου· τούτου δὲ καὶ ὕστερον ποιήσομαι μνήμην ἐν τῇ Μεσσηνίᾳ συγγραφῇ. προελθοῦσι δὲ οὐ πολὺ λόφος ἐστὶν οὐ μέγας, ἐπὶ δὲ αὐτῷ ναὸς ἀρχαῖος καὶ Ἀφροδίτης ξόανον ὡπλισμένης. ναῶν δὲ ὧν οἶδα μόνῳ τούτῳ καὶ ὑπερῷον ἄλλο ἐπῳκοδόμηται Μορφοῦς ἱερόν.", "st": "3.15"}, {"sp": "N", "t": "ἐπίκλησις μὲν δὴ τῆς Ἀφροδίτης ἐστὶν ἡ Μορφώ, κάθηται δὲ καλύπτραν τε ἔχουσα καὶ πέδας περὶ τοῖς ποσί· περιθεῖναι δέ οἱ Τυνδάρεων τὰς πέδας φασὶν ἀφομοιοῦντα τοῖς δεσμοῖς τὸ ἐς τοὺς συνοικοῦντας τῶν γυναικῶν βέβαιον. τὸν γὰρ δὴ ἕτερον λόγον, ὡς τὴν θεὸν πέδαις ἐτιμωρεῖτο ὁ Τυνδάρεως, γενέσθαι ταῖς θυγατράσιν ἐξ Ἀφροδίτης ἡγούμενος τὰ ὀνείδη, τοῦτον οὐδὲ ἀρχὴν προσίεμαι· ἦν γὰρ δὴ παντάπασιν εὔηθες κέδρου ποιησάμενον ζῴδιον καὶ ὄνομα Ἀφροδίτην θέμενον ἐλπίζειν ἀμύνεσθαι τὴν θεόν.", "st": "3.15"}, {"sp": "N", "t": "πλησίον δὲ Ἱλαείρας καὶ Φοίβης ἐστὶν ἱερόν· ὁ δὲ ποιήσας τὰ ἔπη τὰ Κύπρια θυγατέρας αὐτὰς Ἀπόλλωνός φησιν εἶναι. κόραι δὲ ἱερῶνταί σφισι παρθένοι, καλούμεναι κατὰ ταὐτὰ ταῖς θεαῖς καὶ αὗται Λευκιππίδες. τὸ μὲν δὴ ἕτερον τῶν ἀγαλμάτων ἱερασαμένη τις ταῖς θεαῖς Λευκιππὶς ἐπεκόσμησε, πρόσωπον ἀντὶ τοῦ ἀρχαίου ποιησαμένη τῆς ἐφ’ ἡμῶν τέχνης τὸ δὲ ἕτερον μὴ καὶ τοῦτο ἐπικοσμεῖν αὐτὴν ἀπεῖπεν ὄνειρον. ἐνταῦθα ἀπήρτηται ᾠὸν τοῦ ὀρόφου κατειλημένον ταινίαις· εἶναι δέ φασιν ᾠὸν ἐκεῖνο ὃ τεκεῖν Λήδαν ἔχει λόγος.", "st": "3.16"}, {"sp": "N", "t": "ὑφαίνουσι δὲ κατὰ ἔτος αἱ γυναῖκες τῷ Ἀπόλλωνι χιτῶνα τῷ ἐν Ἀμύκλαις, καὶ τὸ οἴκημα ἔνθα ὑφαίνουσι Χιτῶνα ὀνομάζουσιν. οἰκία δὲ αὐτοῦ πεποίηται πλησίον· τὸ δὲ ἐξ ἀρχῆς φασιν αὐτὴν οἰκῆσαι τοὺς Τυνδάρεω παῖδας, χρόνῳ δὲ ὕστερον ἐκτήσατο Φορμίων Σπαρτιάτης. παρὰ τοῦτον ἀφίκοντο οἱ Διόσκουροι ξένοις ἀνδράσιν ἐοικότες· ἥκειν δὲ ἐκ Κυρήνης φήσαντες καταχθῆναί τε ἠξίουν παρ’ αὐτῷ καὶ οἴκημα ᾐτοῦντο ᾧ μάλιστα ἔχαιρον, ἡνίκα μετὰ ἀνθρώπων ἦσαν.", "st": "3.16"}, {"sp": "N", "t": "ὁ δὲ οἰκίας μὲν τῆς ἄλλης ἐκέλευεν αὐτοὺς ἔνθα ἂν ἐθέλωσιν οἰκῆσαι, τὸ δὲ οἴκημα οὐκ ἔφη δώσειν· θυγάτηρ γὰρ ἔτυχέν οἱ παρθένος ἔχουσα ἐν αὐτῷ δίαιταν. ἐς δὲ τὴν ὑστεραίαν παρθένος μὲν ἐκείνη καὶ θεραπεία πᾶσα ἡ περὶ τὴν παῖδα ἠφάνιστο, Διοσκούρων δὲ ἀγάλματα ἐν τῷ οἰκήματι εὑρέθη καὶ τράπεζά τε καὶ σίλφιον ἐπ’ αὐτῇ.", "st": "3.16"}, {"sp": "N", "t": "τάδε μὲν οὕτω γενέσθαι λέγουσιν· ἰόντι δὲ ὡς ἐπὶ τὰς πύλας ἀπὸ τοῦ Χιτῶνος Χίλωνός ἐστιν ἡρῷον τοῦ σοφοῦ νομιζομένου καὶ Ἀθηνοδώρου τῶν ὁμοῦ Δωριεῖ τῷ Ἀναξανδρίδου σταλέντων ἐς Σικελίαν· ἐστάλησαν δὲ τὴν Ἐρυκίνην χώραν νομίζοντες τῶν ἀπογόνων τῶν Ἡρακλέους εἶναι καὶ οὐ βαρβάρων τῶν ἐχόντων. Ἡρακλέα γὰρ ἔχει λόγος παλαῖσαι πρὸς Ἔρυκα ἐπὶ τοῖσδε εἰρημένοις, ἢν μὲν Ἡρακλῆς νικήσῃ, γῆν τὴν Ἔρυκος Ἡρακλέους εἶναι, κρατηθέντος δὲ τῇ πάλῃ βοῦς τὰς Γηρυόνου—", "st": "3.16"}, {"sp": "N", "t": "ταύτας γὰρ τότε ἤλαυνεν Ἡρακλῆς, διανηξαμένας δὲ ἐπὶ Σικελίαν κατὰ τὸν ἔλαιον τὸν κυφὸν ἀνευρήσων ἐπιδιέβη—τὰς οὖν βοῦς ἔδει κρατηθέντος Ἡρακλέους τὸν Ἔρυκα ἄγοντα οἴχεσθαι. τὸ δὲ εὐμενὲς ἐκ τῶν θεῶν οὐ κατὰ ταὐτὰ Ἡρακλεῖ καὶ ὕστερον Δωριεῖ τῷ Ἀναξανδρίδου παρεγένετο, ἀλλὰ Ἡρακλῆς μὲν ἀποκτίννυσιν Ἔρυκα, Δωριέα δὲ αὐτόν τε καὶ τῆς στρατιᾶς διέφθειραν τὸ πολὺ Ἐγεσταῖοι.", "st": "3.16"}, {"sp": "N", "t": "Λακεδαιμόνιοι δὲ καὶ Λυκούργῳ τῷ θεμένῳ τοὺς νόμους οἷα δὴ θεῷ πεποιήκασι καὶ τούτῳ ἱερόν. τάφος δέ ἐστιν ὄπισθε μὲν τοῦ ναοῦ τῷ Λυκούργου παιδὶ Εὐκόσμῳ, πρὸς δὲ τῷ βωμῷ Λαθρίας καὶ Ἀναξάνδρας· αἱ δὲ αὐταί τε ἦσαν δίδυμοι καὶ ἐπὶ τούτῳ σφᾶς οἱ [τ’] Ἀριστοδήμου παῖδες ἅτε ὄντες καὶ αὐτοὶ δίδυμοι λαμβάνουσι, θυγατέρες δὲ ἦσαν Θερσάνδρου τοῦ Ἀγαμηδίδα, βασιλεύοντος μὲν Κλεωναίων, τετάρτου δὲ ἀπογόνου Κτησίππου τοῦ Ἡρακλέους. τοῦ ναοῦ δὲ ἀπαντικρὺ μνῆμα Θεοπόμπου τοῦ Νικάνδρου, τὸ δὲ Εὐρυβιάδου Λακεδαιμονίων τριήρεσιν ἐπ’ Ἀρτεμισίῳ καὶ Σαλαμῖνι ναυμαχήσαντος πρὸς Μήδους, πλησίον δὲ Ἀστραβάκου καλούμενόν ἐστιν ἡρῷον.", "st": "3.16"}, {"sp": "N", "t": "τὸ δὲ χωρίον τὸ ἐπονομαζόμενον Λιμναῖον Ὀρθίας ἱερόν ἐστιν Ἀρτέμιδος. τὸ ξόανον δὲ ἐκεῖνο εἶναι λέγουσιν ὅ ποτε [καὶ] Ὀρέστης καὶ Ἰφιγένεια ἐκ τῆς Ταυρικῆς ἐκκλέπτουσιν· ἐς δὲ τὴν σφετέραν Λακεδαιμόνιοι κομισθῆναί φασιν Ὀρέστου καὶ ἐνταῦθα βασιλεύοντος. καί μοι εἰκότα λέγειν μᾶλλόν τι δοκοῦσιν ἢ Ἀθηναῖοι. ποίῳ γὰρ δὴ λόγῳ κατέλιπεν ἂν ἐν Βραυρῶνι Ἰφιγένεια τὸ ἄγαλμα; ἢ πῶς, ἡνίκα Ἀθηναῖοι τὴν χώραν ἐκλιπεῖν παρεσκευάζοντο, οὐκ ἐσέθεντο καὶ τοῦτο ἐς τὰς ναῦς;", "st": "3.16"}, {"sp": "N", "t": "καίτοι διαμεμένηκεν ἔτι καὶ νῦν τηλικοῦτο ὄνομα τῇ Ταυρικῇ θεῷ, ὥστε ἀμφισβητοῦσι μὲν Καππάδοκες καὶ οἱ τὸν Εὔξεινον οἰκοῦντες τὸ ἄγαλμα εἶναι παρὰ σφίσιν, ἀμφισβητοῦσι δὲ καὶ Λυδῶν οἷς ἐστιν Ἀρτέμιδος ἱερὸν Ἀναιίτιδος. Ἀθηναίοις δὲ ἄρα παρώφθη γενόμενον λάφυρον τῷ Μήδῳ· τὸ γὰρ ἐκ Βραυρῶνος ἐκομίσθη τε ἐς Σοῦσα καὶ ὕστερον Σελεύκου δόντος Σύροι Λαοδικεῖς ἐφ’ ἡμῶν ἔχουσι.", "st": "3.16"}, {"sp": "N", "t": "μαρτύρια δέ μοι καὶ τάδε, τὴν ἐν Λακεδαίμονι Ὀρθίαν τὸ ἐκ τῶν βαρβάρων εἶναι ξόανον· τοῦτο μὲν γὰρ Ἀστράβακος καὶ Ἀλώπεκος οἱ Ἴρβου τοῦ Ἀμφισθένους τοῦ Ἀμφικλέους τοῦ Ἄγιδος τὸ ἄγαλμα εὑρόντες αὐτίκα παρεφρόνησαν· τοῦτο δὲ οἱ Λιμνᾶται Σπαρτιατῶν καὶ Κυνοσουρεῖς καὶ ⟨οἱ⟩ ἐκ Μεσόας τε καὶ Πιτάνης θύοντες τῇ Ἀρτέμιδι ἐς διαφοράν, ἀπὸ δὲ αὐτῆς καὶ ἐς φόνους προήχθησαν, ἀποθανόντων δὲ ἐπὶ τῷ βωμῷ πολλῶν νόσος ἔφθειρε τοὺς λοιπούς.", "st": "3.16"}, {"sp": "N", "t": "καί σφισιν ἐπὶ τούτῳ γίνεται λόγιον αἵματι ἀνθρώπων τὸν βωμὸν αἱμάσσειν· θυομένου δὲ ὅντινα ὁ κλῆρος ἐπελάμβανε, Λυκοῦργος μετέβαλεν ἐς τὰς ἐπὶ τοῖς ἐφήβοις μάστιγας, ἐμπίπλαταί τε οὕτως ἀνθρώπων αἵματι ὁ βωμός. ἡ δὲ ἱέρεια τὸ ξόανον ἔχουσά σφισιν ἐφέστηκε· τὸ δέ ἐστιν ἄλλως μὲν κοῦφον ὑπὸ σμικρότητος, ἢν δὲ οἱ", "st": "3.16"}, {"sp": "N", "t": "μαστιγοῦντές ποτε ὑποφειδόμενοι παίωσι κατὰ ἐφήβου κάλλος ἢ ἀξίωμα, τότε ἤδη τῇ γυναικὶ τὸ ξόανον γίνεται βαρὺ καὶ οὐκέτι εὔφορον, ἡ δὲ ἐν αἰτίᾳ τοὺς μαστιγοῦντας ποιεῖται καὶ πιέζεσθαι δι’ αὐτούς φησιν. οὕτω τῷ ἀγάλματι ἀπὸ τῶν ἐν τῇ Ταυρικῇ θυσιῶν ἐμμεμένηκεν ἀνθρώπων αἵματι ἥδεσθαι· καλοῦσι δὲ οὐκ Ὀρθίαν μόνον ἀλλὰ καὶ Λυγοδέσμαν τὴν αὐτήν, ὅτι ἐν θάμνῳ λύγων εὑρέθη, περιειληθεῖσα δὲ ἡ λύγος ἐποίησε τὸ ἄγαλμα ὀρθόν.", "st": "3.16"}, {"sp": "N", "t": "οὐ πόρρω δὲ τῆς Ὀρθίας ἐστὶν Εἰλειθυίας ἱερόν· οἰκοδομῆσαι δέ φασιν αὐτὸ καὶ Εἰλείθυιαν νομίσαι θεὸν γενομένου σφίσιν ἐκ Δελφῶν μαντεύματος. Λακεδαιμονίοις δὲ [ἡ] ἀκρόπολις μὲν ἐς ὕψος περιφανὲς ἐξίσχουσα οὐκ ἔστι, καθὰ δὴ Θηβαίοις τε ἡ Καδμεία καὶ ἡ Λάρισα Ἀργείοις· ὄντων δὲ ἐν τῇ πόλει λόφων καὶ ἄλλων, τὸ μάλιστα ἐς μετέωρον ἀνῆκον ὀνομάζουσιν ἀκρόπολιν.", "st": "3.17"}, {"sp": "N", "t": "ἐνταῦθα Ἀθηνᾶς ἱερὸν πεποίηται Πολιούχου καλουμένης καὶ Χαλκιοίκου τῆς αὐτῆς. τοῦ δὲ ἱεροῦ τῆς κατασκευῆς Τυνδάρεως καθὰ λέγουσιν ἤρξατο· ἀποθανόντος δὲ ἐκείνου δεύτερα οἱ παῖδες ἐξεργάσασθαι τὸ οἰκοδόμημα ἤθελον, ἀφορμὴ δέ σφισιν ἔμελλε τὰ ἐξ Ἀφιδναίων ἔσεσθαι λάφυρα. προαπολιπόντων δὲ καὶ τούτων, Λακεδαιμόνιοι πολλοῖς ἔτεσιν ὕστερον τόν τε ναὸν ὁμοίως καὶ ⟨τὸ⟩ ἄγαλμα ἐποιήσαντο Ἀθηνᾶς χαλκοῦν· Γιτιάδας δὲ εἰργάσατο ἀνὴρ ἐπιχώριος. ἐποίησε δὲ καὶ ᾄσματα Δώρια ὁ Γιτιάδας ἄλλα τε καὶ ὕμνον ἐς τὴν θεόν.", "st": "3.17"}, {"sp": "N", "t": "ἐπείργασται δὲ τῷ χαλκῷ πολλὰ μὲν τῶν ἄθλων Ἡρακλέους, πολλὰ δὲ καὶ ὧν ἐθελοντὴς κατώρθωσε, Τυνδάρεω δὲ τῶν παίδων ἄλλα τε καὶ ἡ τῶν Λευκίππου θυγατέρων ἁρπαγή· καὶ Ἥφαιστος τὴν μητέρα ἐστὶν ἀπολύων τῶν δεσμῶν. ἐδήλωσα δὲ καὶ ταῦτα, ὁποῖα λέγεται, πρότερον ἔτι ἐν τῇ Ἀτθίδι συγγραφῇ. Περσεῖ δ’ ἐς Λιβύην καὶ ἐπὶ Μέδουσαν ὡρμημένῳ διδοῦσαι νύμφαι δῶρά εἰσι κυνῆν καὶ τὰ ὑποδήματα, ὑφ’ ὧν οἰσθήσεσθαι διὰ τοῦ ἀέρος ἔμελλεν. ἐπείργασται δὲ καὶ τὰ ἐς τὴν Ἀθηνᾶς γένεσιν καὶ Ἀμφιτρίτη καὶ Ποσειδῶν, ἃ δὴ μέγιστα καὶ μάλιστα ἦν ἐμοὶ δοκεῖν θέας ἄξια.", "st": "3.17"}, {"sp": "N", "t": "ἔστι δὲ καὶ ἕτερον αὐτόθι Ἀθηνᾶς Ἐργάνης ἱερόν. ἐς δὲ τὴν πρὸς μεσημβρίαν ⟨ἰόντι⟩ στοὰν Κοσμητᾶ τε ἐπίκλησιν Διὸς ναὸς καὶ Τυνδάρεω πρὸ αὐτοῦ μνῆμά ἐστιν· ἡ δὲ πρὸς δυσμὰς ἔχει τῶν στοῶν ἀετούς τε δύο τοὺς ὄρνιθας καὶ ἴσας ἐπ’ αὐτοῖς Νίκας, Λυσάνδρου μὲν ἀνάθημα, τῶν δὲ ἔργων ὑπόμνημα [τῶν] ἀμφοτέρων, τοῦ τε περὶ Ἔφεσον, ὅτε Ἀντίοχον τὸν Ἀλκιβιάδου κυβερνήτην καὶ Ἀθηναίων τριήρεις ἐνίκησε, καὶ ὕστερον ἐν Αἰγὸς ποταμοῖς καθεῖλεν Ἀθηναίων τὸ ναυτικόν.", "st": "3.17"}, {"sp": "N", "t": "ἐν ἀριστερᾷ δὲ τῆς Χαλκιοίκου Μουσῶν ἱδρύσαντο ἱερόν, ὅτι οἱ Λακεδαιμόνιοι τὰς ἐξόδους ἐπὶ τὰς μάχας οὐ μετὰ σαλπίγγων ἐποιοῦντο ἀλλὰ πρός τε αὐλῶν μέλη καὶ ὑπὸ λύρας καὶ κιθάρας κρούσμασιν. ὄπισθεν δὲ τῆς Χαλκιοίκου ναός ἐστιν Ἀφροδίτης Ἀρείας· τὰ δὲ ξόανα ἀρχαῖα εἴπερ τι ἄλλο ἐν Ἕλλησιν.", "st": "3.17"}, {"sp": "N", "t": "τῆς Χαλκιοίκου δὲ ἐν δεξιᾷ Διὸς ἄγαλμα Ὑπάτου πεποίηται, παλαιότατον πάντων ὁπόσα ἐστὶ χαλκοῦ· δι’ ὅλου γὰρ οὐκ ἔστιν εἰργασμένον, ἐληλασμένου δὲ ἰδίᾳ τῶν μερῶν καθ’ αὑτὸ ἑκάστου συνήρμοσταί τε πρὸς ἄλληλα καὶ ἧλοι συνέχουσιν αὐτὰ μὴ διαλυθῆναι. [καὶ] Κλέαρχον δὲ ἄνδρα Ῥηγῖνον τὸ ἄγαλμα ποιῆσαι λέγουσιν, ὃν Διποίνου καὶ Σκύλλιδος, οἱ δὲ αὐτοῦ Δαιδάλου φασὶν εἶναι μαθητήν. πρὸς δὲ τῷ Σκηνώματι ὀνομαζομένῳ γυναικός ἐστιν εἰκών, Λακεδαιμόνιοι δὲ Εὐρυλεωνίδα λέγουσιν εἶναι· νίκην δὲ ἵππων συνωρίδι ἀνείλετο Ὀλυμπικήν.", "st": "3.17"}, {"sp": "N", "t": "παρὰ δὲ τῆς Χαλκιοίκου τὸν βωμὸν ἑστήκασι δύο εἰκόνες Παυσανίου τοῦ περὶ Πλάταιαν ἡγησαμένου. τὰ δὲ ἐς αὐτὸν ὁποῖα ἐγένετο εἰδόσιν οὐ διηγήσομαι· τὰ γὰρ τοῖς πρότερον συγγραφέντα ἐπ’ ἀκριβὲς ἀποχρῶντα ἦν· ἐπεξελθεῖν ⟨δέ⟩ σφισιν ἀρκέσομαι. ἤκουσα δὲ ἀνδρὸς Βυζαντίου Παυσανίαν φωραθῆναί τε ἐφ’ οἷς ἐβουλεύετο καὶ μόνον τῶν ἱκετευσάντων τὴν Χαλκίοικον ἁμαρτεῖν ἀδείας κατ’ ἄλλο μὲν οὐδέν, φόνου δὲ ἄγος ἐκνίψασθαι μὴ δυνηθέντα.", "st": "3.17"}, {"sp": "N", "t": "ὡς γὰρ δὴ διέτριβε περὶ Ἑλλήσποντον ναυσὶ τῶν τε ἄλλων Ἑλλήνων καὶ αὐτῶν Λακεδαιμονίων, παρθένου Βυζαντίας ἐπεθύμησε· καὶ αὐτίκα νυκτὸς ἀρχομένης τὴν Κλεονίκην—τοῦτο γὰρ ὄνομα ἦν τῇ κόρῃ—κομίζουσιν οἷς ἐπετέτακτο. ἐν τούτῳ δὲ ὑπνωμένον τὸν Παυσανίαν ἐπήγειρεν ὁ ψόφος· ἰοῦσα γὰρ παρ’ αὐτὸν τὸν καιόμενον λύχνον κατέβαλεν ἄκουσα. ἅτε δὲ ὁ Παυσανίας συνειδὼς αὑτῷ προδιδόντι τὴν Ἑλλάδα καὶ δι’ αὐτὸ ἐχόμενος ταραχῇ τε ἀεὶ καὶ δείματι, ἐξέστη καὶ τότε καὶ τὴν παῖδα τῷ ἀκινάκῃ παίει.", "st": "3.17"}, {"sp": "N", "t": "τοῦτο τὸ ἄγος οὐκ ἐξεγένετο ἀποφυγεῖν Παυσανίᾳ, καθάρσια παντοῖα καὶ ἱκεσίας δεξαμένῳ Διὸς Φυξίου καὶ δὴ ἐς Φιγαλίαν ἐλθόντι τὴν Ἀρκάδων παρὰ τοὺς ψυχαγωγούς· δίκην δὲ ἣν εἰκὸς ἦν Κλεονίκῃ τε ἀπέδωκε καὶ τῷ θεῷ. Λακεδαιμόνιοι δὲ ἐκτελοῦντες πρόσταγμα ἐκ Δελφῶν τάς τε εἰκόνας ἐποιήσαντο τὰς χαλκᾶς καὶ δαίμονα τιμῶσιν Ἐπιδώτην, τὸ ἐπὶ Παυσανίᾳ τοῦ Ἱκεσίου μήνιμα ἀποτρέπειν τὸν Ἐπιδώτην λέγοντες τοῦτον.", "st": "3.17"}, {"sp": "N", "t": "τῶν δὲ ἀνδριάντων τοῦ Παυσανίου πλησίον ἐστὶν Ἀμβολογήρας Ἀφροδίτης ἄγαλμα ἱδρυμένον κατὰ μαντείαν, ἄλλα δὲ Ὕπνου καὶ Θανάτου· καὶ σφᾶς ἀδελφοὺς εἶναι κατὰ τὰ ἔπη τὰ ἐν Ἰλιάδι ἥγηνται.", "st": "3.18"}, {"sp": "N", "t": "ἰόντι δὲ ὡς ἐπὶ τὸ Ἀλπίον καλούμενον ναός ἐστιν Ἀθηνᾶς Ὀφθαλμίτιδος· ἀναθεῖναι δὲ Λυκοῦργον λέγουσιν ἐκκοπέντα τῶν ὀφθαλμῶν τὸν ἕτερον ὑπὸ Ἀλκάνδρου, διότι οὓς ἔθηκε νόμους οὐκ ἀρεστοὺς συνέβαινεν εἶναι τῷ Ἀλκάνδρῳ. διαφυγὼν δὲ ἐς τοῦτο τὸ χωρίον Λακεδαιμονίων ἀμυνάντων μὴ προσαπολέσθαι οἱ καὶ τὸν λειπόμενον ὀφθαλμόν, οὕτω ναὸν Ὀφθαλμίτιδος Ἀθηνᾶς ἐποίησε.", "st": "3.18"}, {"sp": "N", "t": "προελθόντι δὲ ἐντεῦθεν ἱερόν ἐστιν Ἄμμωνος· φαίνονται δὲ ἀπ’ ἀρχῆς Λακεδαιμόνιοι μάλιστα Ἑλλήνων χρώμενοι τῷ ἐν Λιβύῃ μαντείῳ. λέγεται δὲ καὶ Λυσάνδρῳ πολιορκοῦντι Ἄφυτιν τὴν ἐν τῇ Παλλήνῃ νύκτωρ ἐπιφανέντα Ἄμμωνα προαγορεύειν ὡς ἄμεινον ἐκείνῳ τε ἔσοιτο καὶ τῇ Λακεδαίμονι πολέμου πρὸς Ἀφυταίους παυσαμένοις· καὶ οὕτω τὴν πολιορκίαν διέλυσεν ὁ Λύσανδρος καὶ Λακεδαιμονίους τὸν θεὸν σέβειν προήγαγεν ἐς πλέον, Ἀφυταῖοι δὲ τιμῶσιν Ἄμμωνα οὐδὲν ἧσσον ἢ οἱ Ἀμμώνιοι Λιβύων.", "st": "3.18"}, {"sp": "N", "t": "τὰ δὲ ἐς τὴν Κναγίαν Ἄρτεμίν ἐστιν οὕτω λεγόμενα· Κναγέα ἄνδρα ἐπιχώριον στρατεῦσαί φασιν ἐς Ἄφιδναν ὁμοῦ τοῖς Διοσκούροις, ληφθέντα δὲ αἰχμάλωτον ἐν τῇ μάχῃ καὶ πραθέντα ἐς Κρήτην δουλεύειν ἔνθα ἦν Ἀρτέμιδος τοῖς Κρησὶν ἱερόν, ἀνὰ χρόνον δὲ αὐτόν τε ἀποδρᾶναι καὶ παρθένον τὴν ἱερωμένην ἔχοντα οἴχεσθαι τὸ ἄγαλμα ἀγομένην. ἐπὶ τούτῳ δὲ λέγουσιν ὀνομάζειν Κναγίαν Ἄρτεμιν·", "st": "3.18"}, {"sp": "N", "t": "ἐμοὶ δὲ οὗτος ὁ Κναγεὺς ἄλλως ἀφικέσθαι πως ἐς Κρήτην φαίνεται καὶ οὐχ ὡς οἱ Λακεδαιμόνιοί φασιν, ἐπεὶ μηδὲ γενέσθαι δοκῶ πρὸς Ἀφίδνῃ μάχην Θησέως τε ἐν Θεσπρώτοις ἐχομένου καὶ Ἀθηναίων οὐχ ὁμονοούντων ἀλλὰ ἐς Μενεσθέα ῥεπόντων μᾶλλον ταῖς εὐνοίαις. οὐ μὴν οὐδὲ ἀγῶνος συμβάντος πείθοιτο ἄν τις αἰχμαλώτους ληφθῆναι παρὰ τῶν κρατησάντων, ἄλλως τε καὶ παρὰ πολὺ γενομένης τῆς νίκης, ὥστε ἁλῶναι καὶ αὐτὴν Ἄφιδναν.", "st": "3.18"}, {"sp": "N", "t": "τάδε μὲν ἐς τοσοῦτον ἐξητάσθω· ἐς Ἀμύκλας δὲ κατιοῦσιν ἐκ Σπάρτης ποταμός ἐστι Τίασα· θυγατέρα δὲ νομίζουσιν εἶναι τοῦ Εὐρώτα τὴν Τίασαν, καὶ πρὸς αὐτῇ Χαρίτων ἐστὶν ἱερὸν Φαέννας καὶ Κλητᾶς, καθὰ δὴ καὶ Ἀλκμὰν ἐποίησεν. ἱδρύσασθαι δὲ Λακεδαίμονα Χάρισιν ἐνταῦθα ⟨τὸ⟩ ἱερὸν καὶ θέσθαι τὰ ὀνόματα ἥγηνται.", "st": "3.18"}, {"sp": "N", "t": "τὰ δὲ ἐν Ἀμύκλαις θέας ἄξια ἀνὴρ [γὰρ] πένταθλός ἐστιν ἐπὶ στήλης ὄνομα Αἴνητος· τούτῳ νικήσαντι Ὀλυμπίασι καὶ ἔτι στεφανουμένῳ γενέσθαι τοῦ βίου τὴν τελευτὴν λέγουσι. τούτου τε οὖν ἐστιν εἰκὼν καὶ τρίποδες χαλκοῖ· τοὺς δὲ ἀρχαιοτέρους δεκάτην τοῦ πρὸς Μεσσηνίους πολέμου φασὶν εἶναι.", "st": "3.18"}, {"sp": "N", "t": "ὑπὸ μὲν δὴ τῷ πρώτῳ τρίποδι Ἀφροδίτης ἄγαλμα ἑστήκει, Ἄρτεμις δὲ ὑπὸ τῷ δευτέρῳ, Γιτιάδα καὶ αὐτοὶ τέχνη καὶ τὰ ἐπειργασμένα, ὁ τρίτος δέ ἐστιν Αἰγινήτου Κάλλωνος· ὑπὸ τούτῳ δὲ ἄγαλμα Κόρης τῆς Δήμητρος ἕστηκεν. Ἀρίστανδρος δὲ Πάριος καὶ Πολύκλειτος Ἀργεῖος ὁ μὲν γυναῖκα ἐποίησεν ἔχουσαν λύραν, Σπάρτην δῆθεν, Πολύκλειτος δὲ Ἀφροδίτην παρὰ Ἀμυκλαίῳ καλουμένην. οὗτοι δὲ οἱ τρίποδες μεγέθει τε ὑπὲρ τοὺς ἄλλους εἰσὶ καὶ ἀπὸ τῆς νίκης τῆς ἐν Αἰγὸς ποταμοῖς ἀνετέθησαν.", "st": "3.18"}, {"sp": "N", "t": "Βαθυκλέους δὲ Μάγνητος, ὃς τὸν θρόνον ἐποίησε τοῦ Ἀμυκλαίου, ἀναθήματα ἐπ’ ἐξειργασμένῳ τῷ θρόνῳ Χάριτες καὶ ἄγαλμα δὲ Λευκοφρυήνης ἐστὶν Ἀρτέμιδος. ὅτου δὲ οὗτος ὁ Βαθυκλῆς μαθητὴς ἐγεγόνει καὶ τὸν θρόνον ἐφ’ ὅτου βασιλεύοντος Λακεδαιμονίων ἐποίησε, τάδε μὲν παρίημι, τὸν θρόνον δὲ εἶδόν τε καὶ τὰ ἐς αὐτὸν ὁποῖα ἦν γράψω.", "st": "3.18"}, {"sp": "N", "t": "ἀνέχουσιν ἔμπροσθεν αὐτόν, κατὰ ταὐτὰ δὲ καὶ ὀπίσω, Χάριτές τε δύο καὶ Ὧραι δύο· ἐν ἀριστερᾷ δὲ Ἔχιδνα ἕστηκε καὶ Τυφώς, ἐν δεξιᾷ δὲ Τρίτωνες. τὰ δὲ ἐπειργασμένα καθ’ ἕκαστον ἐπ’ ἀκριβὲς διελθεῖν ὄχλον τοῖς ἐπιλεξομένοις παρέξειν ἔμελλεν· ὡς δὲ δηλῶσαι συλλαβόντι, ἐπεὶ μηδὲ ἄγνωστα τὰ πολλὰ ἦν, Ταϋγέτην θυγατέρα Ἄτλαντος καὶ ἀδελφὴν αὐτῆς Ἀλκυόνην φέρουσι Ποσειδῶν καὶ Ζεύς. ἐπείργασται δὲ καὶ Ἄτλας καὶ Ἡρακλέους μονομαχία πρὸς Κύκνον καὶ ἡ παρὰ Φόλῳ τῶν Κενταύρων μάχη.", "st": "3.18"}, {"sp": "N", "t": "τὸν δὲ Μίνω καλούμενον Ταῦρον οὐκ οἶδα ἀνθ’ ὅτου πεποίηκε Βαθυκλῆς δεδεμένον τε καὶ ἀγόμενον ὑπὸ Θησέως ζῶντα· καὶ Φαιάκων χορός ἐστιν ἐπὶ τῷ θρόνῳ καὶ ᾄδων ὁ Δημόδοκος· Περσέως τε τὸ ἔργον πεποίηται τὸ ἐς Μέδουσαν. παρέντι δὲ Ἡρακλέους μάχην πρὸς Θούριον τῶν γιγάντων καὶ Τυνδάρεω πρὸς Εὔρυτον, ἔστιν ἁρπαγὴ τῶν Λευκίππου θυγατέρων· Διόνυσον δὲ καὶ Ἡρακλέα, τὸν μὲν παῖδα ἔτι ὄντα ἐς οὐρανόν ἐστιν Ἑρμῆς φέρων, Ἀθηνᾶ δὲ ἄγουσα Ἡρακλέα συνοικήσοντα ἀπὸ τούτου θεοῖς.", "st": "3.18"}, {"sp": "N", "t": "παραδίδωσι δὲ καὶ Πηλεὺς Ἀχιλλέα τραφησόμενον παρὰ Χίρωνι, ὃς καὶ διδάξαι λέγεται· Κέφαλος δὲ τοῦ κάλλους ἕνεκα ὑπὸ Ἡμέρας ἐστὶν ἡρπασμένος, καὶ ἐς τὸν γάμον τὸν Ἁρμονίας δῶρα κομίζουσιν οἱ θεοί. καὶ Ἀχιλλέως μονομαχία πρὸς Μέμνονα ἐπείργασται, Διομήδην τε Ἡρακλῆς τὸν Θρᾷκα καὶ ἐπ’ Εὐήνῳ τῷ ποταμῷ Νέσσον τιμωρούμενος. Ἑρμῆς δὲ παρ’ Ἀλέξανδρον κριθησομένας ἄγει τὰς θεάς, Ἄδραστος δὲ καὶ Τυδεὺς Ἀμφιάραον καὶ Λυκοῦργον τὸν Πρώνακτος μάχης καταπαύουσιν.", "st": "3.18"}, {"sp": "N", "t": "Ἥρα δὲ ἀφορᾷ πρὸς Ἰὼ τὴν Ἰνάχου βοῦν οὖσαν ἤδη, καὶ Ἀθηνᾶ διώκοντα ἀποφεύγουσά ἐστιν Ἥφαιστον. ἐπὶ δὲ τούτοις Ἡρακλέους πεποίηται [τάξις] τῶν ἔργων [τῶν] ⟨τὸ⟩ ἐς τὴν ὕδραν καὶ ὡς ἀνήγαγε τοῦ Ἅιδου τὸν κύνα. Ἀναξίας δὲ καὶ Μνασίνους, τούτων μὲν ἐφ’ ἵππου καθήμενός ἐστιν ἑκάτερος, Μεγαπένθην δὲ τὸν Μενελάου καὶ Νικόστρατον ἵππος εἷς φέρων ἐστίν. ἀναιρεῖ δὲ καὶ Βελλεροφόντης τὸ ἐν Λυκίᾳ θηρίον, καὶ Ἡρακλῆς τὰς Γηρυόνου βοῦς ἐλαύνει.", "st": "3.18"}, {"sp": "N", "t": "τοῦ θρόνου δὲ πρὸς τοῖς ἄνω πέρασιν ἐφ’ ἵππων ἑκατέρωθέν εἰσιν οἱ Τυνδάρεω παῖδες· καὶ σφίγγες τέ εἰσιν ὑπὸ τοῖς ἵπποις καὶ θηρία ἄνω θέοντα, τῇ μὲν πάρδαλις, κατὰ δὲ τὸν Πολυδεύκην λέαινα. ἀνωτάτω δὲ χορὸς ἐπὶ τῷ θρόνῳ πεποίηται, Μάγνητες οἱ συνειργασμένοι Βαθυκλεῖ τὸν θρόνον.", "st": "3.18"}, {"sp": "N", "t": "ὑπελθόντι δὲ ὑπὸ τὸν θρόνον τὰ ἔνδον ἀπὸ τῶν Τριτώνων ὑός ἐστι θήρα τοῦ Καλυδωνίου καὶ Ἡρακλῆς ἀποκτείνων τοὺς παῖδας τοὺς Ἄκτορος, Κάλαϊς δὲ καὶ Ζήτης τὰς Ἁρπυίας Φινέως ἀπελαύνουσιν· Πειρίθους τε καὶ Θησεὺς ἡρπακότες εἰσὶν Ἑλένην καὶ ἄγχων Ἡρακλῆς τὸν λέοντα, Τιτυὸν δὲ Ἀπόλλων τοξεύει καὶ Ἄρτεμις·", "st": "3.18"}, {"sp": "N", "t": "Ἡρακλέους τε πρὸς Ὄρειον Κένταυρον μάχη πεποίηται καὶ Θησέως πρὸς Ταῦρον τὸν Μίνω. πεποίηται δὲ καὶ ἡ πρὸς Ἀχελῷον Ἡρακλέους πάλη καὶ τὰ λεγόμενα ἐς Ἥραν, ὡς ὑπὸ Ἡφαίστου δεθείη, καὶ ὃν Ἄκαστος ἔθηκεν ἀγῶνα ἐπὶ πατρὶ καὶ τὰ ἐς Μενέλαον καὶ τὸν Αἰγύπτιον Πρωτέα ἐν Ὀδυσσείᾳ. τελευταῖα Ἄδμητός τε ζευγνύων ἐστὶν ὑπὸ τὸ ἅρμα κάπρον καὶ λέοντα καὶ οἱ Τρῶες ἐπιφέροντες χοὰς Ἕκτορι.", "st": "3.18"}, {"sp": "N", "t": "τοῦ θρόνου δὲ ᾗ καθίζοιτο ἂν ὁ θεός, οὐ διὰ παντὸς κατὰ τοῦτο συνεχοῦς ὄντος ἀλλὰ καθέδρας παρεχομένου πλείονας, παρὰ δὲ καθέδραν ἑκάστην ὑπολειπομένης καὶ εὐρυχωρίας, τὸ μέσον ἐστὶν εὐρυχωρὲς μάλιστα καὶ τὸ ἄγαλμα ἐνταῦθα ἐνέστηκε.", "st": "3.19"}, {"sp": "N", "t": "μέγεθος δὲ αὐτοῦ μέτρῳ μὲν οὐδένα ἀνευρόντα οἶδα, εἰκάζοντι δὲ καὶ τριάκοντα εἶναι φαίνοιντο ἂν πήχεις. ἔργον δὲ οὐ Βαθυκλέους ἐστίν, ἀλλὰ ἀρχαῖον καὶ οὐ σὺν τέχνῃ πεποιημένον· ὅτι γὰρ μὴ πρόσωπον αὐτῷ καὶ πόδες εἰσὶν ἄκροι καὶ χεῖρες, τὸ λοιπὸν χαλκῷ κίονί ἐστιν εἰκασμένον. ἔχει δὲ ἐπὶ τῇ κεφαλῇ κράνος, λόγχην δὲ ἐν ταῖς χερσὶ καὶ τόξον.", "st": "3.19"}, {"sp": "N", "t": "τοῦ δὲ ἀγάλματος τὸ βάθρον παρέχεται μὲν βωμοῦ σχῆμα, τεθάφθαι δὲ τὸν Ὑάκινθον λέγουσιν ἐν αὐτῷ, καὶ Ὑακινθίοις πρὸ τῆς τοῦ Ἀπόλλωνος θυσίας ἐς τοῦτον Ὑακίνθῳ τὸν βωμὸν διὰ θύρας χαλκῆς ἐναγίζουσιν· ἐν ἀριστερᾷ δέ ἐστιν ἡ θύρα τοῦ βωμοῦ. ἐπείργασται δὲ τῷ βωμῷ τοῦτο μὲν ἄγαλμα Βίριδος, τοῦτο δὲ Ἀμφιτρίτης καὶ Ποσειδῶνος· Διὸς δὲ καὶ Ἑρμοῦ διαλεγομένων ἀλλήλοις πλησίον Διόνυσος ἑστήκασι καὶ Σεμέλη, παρὰ δὲ αὐτὴν Ἰνώ.", "st": "3.19"}, {"sp": "N", "t": "πεποίηται δὲ ἐπὶ τοῦ βωμοῦ καὶ ἡ Δημήτηρ καὶ Κόρη καὶ Πλούτων, ἐπὶ δὲ αὐτοῖς Μοῖραί τε καὶ Ὧραι, σὺν δέ σφισιν Ἀφροδίτη καὶ Ἀθηνᾶ τε καὶ Ἄρτεμις· κομίζουσι δ’ ἐς οὐρανὸν Ὑάκινθον καὶ Πολύβοιαν, Ὑακίνθου καθὰ λέγουσιν ἀδελφὴν ἀποθανοῦσαν ἔτι παρθένον. τοῦτο μὲν οὖν τοῦ Ὑακίνθου τὸ ἄγαλμα ἔχον ἐστὶν ἤδη γένεια, Νικίας δὲ ὁ Νικομήδους περισσῶς δή τι ἔγραψεν αὐτὸν ὡραῖον, τὸν ἐπὶ Ὑακίνθῳ λεγόμενον Ἀπόλλωνος ἔρωτα ὑποσημαίνων.", "st": "3.19"}, {"sp": "N", "t": "πεποίηται δὲ ἐπὶ τοῦ βωμοῦ καὶ Ἡρακλῆς ὑπὸ Ἀθηνᾶς καὶ θεῶν τῶν ἄλλων καὶ οὗτος ἀγόμενος ἐς οὐρανόν. εἰσὶ δὲ καὶ αἱ Θεστίου θυγατέρες ἐπὶ τῷ βωμῷ, καὶ Μοῦσαί τε καὶ Ὧραι. περὶ δὲ ἀνέμου Ζεφύρου, καὶ ὡς ὑπὸ τοῦ Ἀπόλλωνος Ὑάκινθος ἀπέθανεν ἄκοντος, καὶ τὰ ἐς τὸ ἄνθος εἰρημένα τάχα μὲν ἂν ἔχοι καὶ ἄλλως, δοκείτω δὲ ᾗ λέγεται.", "st": "3.19"}, {"sp": "N", "t": "Ἀμύκλαι δὲ ἀνάστατος ὑπὸ Δωριέων γενομένη καὶ ἀπ’ ἐκείνου κώμη διαμένουσα θέας παρείχετο ἄξιον ἱερὸν Ἀλεξάνδρας καὶ ἄγαλμα· τὴν δὲ Ἀλεξάνδραν οἱ Ἀμυκλαιεῖς Κασσάνδραν τὴν Πριάμου φασὶν εἶναι. καὶ Κλυταιμνήστρας ἐστὶν ἐνταῦθα εἰκὼν καὶ [ἄγαλμα] Ἀγαμέμνονος νομιζόμενον μνῆμα. θεῶν δὲ σέβουσιν οἱ ταύτῃ τόν τε Ἀμυκλαῖον καὶ Διόνυσον, ὀρθότατα ἐμοὶ δοκεῖν Ψίλακα ἐπονομάζοντες· ψίλα γὰρ καλοῦσιν οἱ Δωριεῖς τὰ πτερά, ἀνθρώπους δὲ οἶνος ἐπαίρει τε καὶ ἀνακουφίζει γνώμην οὐδέν τι ἧσσον ἢ ὄρνιθας πτερά. καὶ Ἀμύκλαι μὲν παρείχοντο τοσαῦτα ἐς μνήμην, ἑτέρα δὲ ἐκ τῆς πόλεως ὁδὸς ἐς Θεράπνην ἄγει·", "st": "3.19"}, {"sp": "N", "t": "κατὰ δὲ τὴν ὁδὸν Ἀθηνᾶς ξόανόν ἐστιν Ἀλέας. πρὶν δὲ ἢ διαβῆναι τὸν Εὐρώταν, ὀλίγον ὑπὲρ τῆς ὄχθης ἱερὸν δείκνυται Διὸς Πλουσίου. διαβᾶσι δὲ Κοτυλέως ἐστὶν Ἀσκληπιοῦ ναός, ὃν ἐποίησεν Ἡρακλῆς· καὶ Ἀσκληπιὸν Κοτυλέα ὠνόμασεν ἀκεσθεὶς τὸ τραῦμα τὸ ἐς τὴν κοτύλην οἱ γενόμενον ἐν τῇ πρὸς Ἱπποκόωντα καὶ τοὺς παῖδας προτέρᾳ μάχῃ. ὁπόσα δὲ πεποίηται κατὰ τὴν ὁδὸν ταύτην, ἐστὶν ἀρχαιότατον αὐτῶν Ἄρεως ἱερόν. τοῦτό ἐστιν ἐν ἀριστερᾷ τῆς ὁδοῦ, ⟨καὶ⟩ τὸ ἄγαλμα [καὶ] τοὺς Διοσκούρους φασὶ κομίσαι ἐκ Κόλχων·", "st": "3.19"}, {"sp": "N", "t": "Θηρίταν δὲ ἐπονομάζουσιν ἀπὸ Θηροῦς, ταύτην γὰρ τροφὸν εἶναι τοῦ Ἄρεως λέγουσι. τάχα δ’ ἂν ἀκηκοότες παρὰ Κόλχων Θηρίταν λέγοιεν, ἐπεὶ Ἔλληνές γε οὐκ ἴσασιν Ἄρεως τροφὸν Θηρώ· δοκεῖν δέ μοι Θηρίτας οὐ διὰ τὴν τροφὸν ἡ ἐπωνυμία τῷ Ἄρει γέγονεν, ὅτι δὲ ἀνδρὶ χρὴ πολεμίῳ καταστάντα ἐς μάχην οὐδὲν ἔτι ἔχειν ἤπιον, καθὰ δὴ καὶ Ὁμήρῳ περὶ Ἀχιλλέως πεποίηται<br>λέων δ’ ὣς ἄγρια οἶδεν.", "st": "3.19"}, {"sp": "N", "t": "Θεράπνη δὲ ὄνομα μὲν τῷ χωρίῳ γέγονεν ἀπὸ τῆς Λέλεγος θυγατρός, Μενελάου δέ ἐστιν ἐν αὐτῇ ναός, καὶ Μενέλαον καὶ Ἑλένην ἐνταῦθα ταφῆναι λέγουσιν. Ῥόδιοι δὲ οὐχ ὁμολογοῦντες Λακεδαιμονίοις φασὶν Ἑλένην Μενελάου τελευτήσαντος, Ὀρέστου δὲ ἔτι πλανωμένου, τηνικαῦτα ὑπὸ Νικοστράτου καὶ Μεγαπένθους διωχθεῖσαν ἐς Ῥόδον ἀφικέσθαι Πολυξοῖ τῇ Τληπολέμου γυναικὶ ἔχουσαν ἐπιτηδείως·", "st": "3.19"}, {"sp": "N", "t": "εἶναι γὰρ καὶ Πολυξὼ τὸ γένος Ἀργείαν, Τληπολέμῳ δὲ ἔτι πρότερον συνοικοῦσαν φυγῆς μετασχεῖν τῆς ἐς Ῥόδον καὶ τῆς νήσου τηνικαῦτα ἄρχειν ὑπολειπομένην ἐπὶ ὀρφανῷ παιδί. ταύτην τὴν Πολυξώ φασιν ἐπιθυμοῦσαν Ἑλένην τιμωρήσασθαι τελευτῆς τῆς Τληπολέμου τότε, ὡς ἔλαβεν αὐτὴν ὑποχείριον, ἐπιπέμψαι οἱ λουμένῃ θεραπαίνας Ἐρινύσιν ⟨ἴσα⟩ ἐσκευασμένας· καὶ αὗται διαλαβοῦσαι δὴ τὴν Ἑλένην αἱ γυναῖκες ἀπάγχουσιν ἐπὶ δένδρου, καὶ ἐπὶ τούτῳ Ῥοδίοις Ἑλένης ἱερόν ἐστι Δενδρίτιδος.", "st": "3.19"}, {"sp": "N", "t": "ὃν δὲ οἶδα λέγοντας Κροτωνιάτας περὶ Ἑλένης λόγον, ὁμολογοῦντας δέ σφισι καὶ Ἱμεραίους, ἐπιμνησθήσομαι καὶ τοῦδε. ἔστιν ἐν τῷ Εὐξείνῳ νῆσος κατὰ τοῦ Ἴστρου τὰς ἐκβολὰς Ἀχιλλέως ἱερά· ὄνομα μὲν τῇ νήσῳ Λευκή, περίπλους δὲ αὐτῇ σταδίων εἴκοσι, δασεῖα δὲ ὕλῃ πᾶσα καὶ πλήρης ζῴων ἀγρίων καὶ ἡμέρων, καὶ ναὸς Ἀχιλλέως καὶ ἄγαλμα ἐν αὐτῇ.", "st": "3.19"}, {"sp": "N", "t": "ἐς ταύτην πρῶτος ἐσπλεῦσαι λέγεται Κροτωνιάτης Λεώνυμος. πολέμου γὰρ Κροτωνιάταις συνεστηκότος πρὸς τοὺς ἐν Ἰταλίᾳ Λοκρούς, τῶν Λοκρῶν κατὰ οἰκειότητα πρὸς Ὀπουντίους Αἴαντα τὸν Ὀιλέως ἐς τὰς μάχας ἐπικαλουμένων, ὁ Λεώνυμος Κροτωνιάταις στρατηγῶν ἐπῄει τοῖς ἐναντίοις κατὰ τοῦτο ᾗ προτετάχθαι σφίσι τὸν Αἴαντα ἤκουε. τιτρώσκεται δὴ τὸ στέρνον καὶ— ἔκαμνε γὰρ ὑπὸ τοῦ τραύματος—ἀφίκετο ἐς Δελφούς. ἐλθόντα δὲ ἡ Πυθία Λεώνυμον ἀπέστελλεν ἐς νῆσον τὴν Λευκήν, ἐνταῦθα εἰποῦσα αὐτῷ φανήσεσθαι τὸν Αἴαντα καὶ ἀκέσεσθαι τὸ τραῦμα.", "st": "3.19"}, {"sp": "N", "t": "χρόνῳ δὲ ὡς ὑγιάνας ἐπανῆλθεν ἐκ τῆς Λευκῆς, ἰδεῖν μὲν ἔφασκεν Ἀχιλλέα, ἰδεῖν δὲ τὸν Ὀιλέως καὶ τὸν Τελαμῶνος Αἴαντα, συνεῖναι δὲ καὶ Πάτροκλόν σφισι καὶ Ἀντίλοχον· Ἑλένην δὲ Ἀχιλλεῖ μὲν συνοικεῖν, προστάξαι δέ οἱ πλεύσαντι ἐς Ἱμέραν πρὸς Στησίχορον ἀγγέλλειν ὡς ἡ διαφθορὰ τῶν ὀφθαλμῶν ἐξ Ἑλένης γένοιτο αὐτῷ μηνίματος. Στησίχορος μὲν ἐπὶ τούτῳ τὴν παλινῳδίαν ἐποίησεν·", "st": "3.19"}, {"sp": "N", "t": "ἐν Θεράπνῃ δὲ κρήνην τὴν Μεσσηίδα ἰδὼν οἶδα. Λακεδαιμονίων δὲ ἑτέροις ἐστὶν εἰρημένον τὴν Πολυδεύκειαν ὀνομαζομένην ἐφ’ ἡμῶν, οὐ τὴν ἐν Θεράπνῃ Μεσσηίδα καλεῖσθαι τὸ ἀρχαῖον· ἡ δὲ Πολυδεύκειά ἐστιν αὐτή τε ἡ κρήνη καὶ Πολυδεύκους ἱερὸν ἐν δεξιᾷ τῆς ἐς Θεράπνην ὁδοῦ.", "st": "3.20"}, {"sp": "N", "t": "Θεράπνης δὲ οὐ πόρρω Φοιβαῖον καλούμενόν ἐστιν, ἐν δὲ αὐτῷ Διοσκούρων ναός· καὶ οἱ ἔφηβοι τῷ Ἐνυαλίῳ θύουσιν ἐνταῦθα. τούτου δὲ οὐ πολὺ Ποσειδῶνος ἀφέστηκεν ἱερὸν ἐπίκλησιν Γαιαόχου. καὶ ἀπ’ αὐτοῦ προελθόντι ὡς ἐπὶ τὸ Ταΰγετον ὀνομάζουσιν Ἀλεσίας χωρίον, Μύλητα τὸν Λέλεγος πρῶτον ἀνθρώπων μύλην τε εὑρεῖν λέγοντες καὶ ἐν ταῖς Ἀλεσίαις ταύταις ἀλέσαι. καί σφισι Λακεδαίμονος τοῦ Ταϋγέτης ἐνταῦθά ἐστιν ἡρῷον.", "st": "3.20"}, {"sp": "N", "t": "διαβᾶσι δὲ αὐτόθεν ποταμὸν Φελλίαν, παρὰ Ἀμύκλας ἰοῦσιν εὐθεῖαν ὡς ἐπὶ θάλασσαν Φᾶρις πόλις ἐν τῇ Λακωνικῇ ποτε ᾠκεῖτο· ἀποτρεπομένῳ δὲ ἀπὸ τῆς Φελλίας ἐς δεξιὰν ἡ πρὸς τὸ ὄρος τὸ Ταΰγετόν ἐστιν ὁδός. ἔστι δὲ ἐν τῷ πεδίῳ Διὸς Μεσσαπέως τέμενος· γενέσθαι δέ οἱ τὴν ἐπίκλησιν ἀπὸ ἀνδρὸς λέγουσιν ἱερασαμένου τῷ θεῷ. ἐντεῦθέν ἐστιν ἀπιοῦσιν ἐκ τοῦ Ταϋγέτου χωρίον ἔνθα πόλις ποτὲ ᾠκεῖτο Βρυσίαι· καὶ Διονύσου ναὸς ἐνταῦθα ἔτι λείπεται καὶ ἄγαλμα ἐν ὑπαίθρῳ. τὸ δὲ ἐν τῷ ναῷ μόναις γυναιξὶν ἔστιν ὁρᾶν· γυναῖκες γὰρ δὴ μόναι καὶ τὰ ἐς τὰς θυσίας δρῶσιν ἐν ἀπορρήτῳ.", "st": "3.20"}, {"sp": "N", "t": "ἄκρα δὲ τοῦ Ταϋγέτου Ταλετὸν ὑπὲρ Βρυσεῶν ἀνέχει. ταύτην Ἡλίου καλοῦσιν ἱερὰν καὶ ἄλλα τε αὐτόθι Ἡλίῳ θύουσι καὶ ἵππους· τὸ δὲ αὐτὸ καὶ Πέρσας οἶδα θύειν νομίζοντας. Ταλετοῦ δὲ οὐ πόρρω καλούμενός ἐστιν Εὐόρας, θηρία καὶ ἄλλα τρέφων καὶ αἶγας μάλιστα ἀγρίας. παρέχεται δὲ καὶ δι’ ὅλου τὸ Ταΰγετον τῶν αἰγῶν τούτων ἄγραν καὶ ὑῶν, πλείστην δὲ καὶ ἐλάφων καὶ ἄρκτων.", "st": "3.20"}, {"sp": "N", "t": "Ταλετοῦ δὲ τὸ μεταξὺ καὶ Εὐόρα Θήρας ὀνομάζοντες Λητώ φασιν ἀπὸ τῶν ἄκρων τοῦ Ταϋγέτου … Δήμητρος ἐπίκλησιν Ἐλευσινίας ἐστὶν ἱερόν· ἐνταῦθα Ἡρακλέα Λακεδαιμόνιοι κρυφθῆναί φασιν ὑπὸ Ἀσκληπιοῦ τὸ τραῦμα ἰώμενον· καὶ Ὀρφέως ἐστὶν ἐν αὐτῷ ξόανον, Πελασγῶν ὥς φασιν ἔργον. καὶ τόδε δὲ ἄλλο δρώμενον ἐνταῦθα οἶδα·", "st": "3.20"}, {"sp": "N", "t": "ἐπὶ θαλάσσῃ πόλισμα Ἕλος ἦν, οὗ δὴ καὶ Ὅμηρος ἐμνημόνευκεν ἐν καταλόγῳ Λακεδαιμονίων·<br>οἵ τ’ ἄρ’ Ἀμύκλας εἶχον Ἕλος τ’ ἔφαλον πτολίεθρον.<br>τοῦτο ᾤκισε μὲν Ἕλιος νεώτατος τῶν Περσέως παίδων, Δωριεῖς δὲ παρεστήσαντο ὕστερον πολιορκίᾳ, καὶ πρῶτοί τε ἐγένοντο οὗτοι Λακεδαιμονίων δοῦλοι τοῦ κοινοῦ καὶ εἵλωτες ἐκλήθησαν πρῶτοι, καθάπερ γε καὶ ἦσαν· τὸ δὲ οἰκετικὸν τὸ ἐπικτηθὲν ὕστερον, Δωριεῖς Μεσσηνίους ὄντας, ὀνομασθῆναι καὶ τούτους ἐξενίκησεν εἵλωτας, καθότι καὶ Ἕλληνας τὸ σύμπαν γένος ἀπὸ τῆς ἐν Θεσσαλίᾳ ποτὲ καλουμένης Ἑλλάδος.", "st": "3.20"}, {"sp": "N", "t": "ἐκ τούτου δὴ τοῦ Ἕλους ξόανον Κόρης τῆς Δήμητρος ἐν ἡμέραις ῥηταῖς ἀνάγουσιν ἐς τὸ Ἐλευσίνιον. πεντεκαίδεκα δὲ τοῦ Ἐλευσινίου σταδίους ἀφέστηκε Λαπίθαιον καλούμενον ἀπὸ ἀνδρὸς ἐγχωρίου Λαπίθου· τοῦτό τε οὖν τὸ Λαπίθαιόν ἐστιν ἐν τῷ Ταϋγέτῳ καὶ οὐ πόρρω Δέρειον, ἔνθα Ἀρτέμιδος ἄγαλμα ἐν ὑπαίθρῳ Δερεάτιδος, καὶ πηγὴ παρ’ αὐτῷ ἣν Ἄνονον ὀνομάζουσι. μετὰ δὲ τὸ Δέρειον σταδίους προελθόντι ὡς εἴκοσιν ἔστιν Ἅρπλεια καθήκοντα ἄχρι τοῦ πεδίου.", "st": "3.20"}, {"sp": "N", "t": "τὴν δὲ ἐπ’ Ἀρκαδίας ἰοῦσιν ἐκ Σπάρτης Ἀθηνᾶς ἕστηκεν ἐπίκλησιν Παρείας ἄγαλμα ἐν ὑπαίθρῳ, μετὰ δὲ αὐτὸ ἱερόν ἐστιν Ἀχιλλέως· ἀνοίγειν δὲ αὐτὸ οὐ νομίζουσιν· ὁπόσοι δ’ ἂν τῶν ἐφήβων ἀγωνιεῖσθαι μέλλωσιν ἐν τῷ Πλατανιστᾷ, καθέστηκεν αὐτοῖς τῷ Ἀχιλλεῖ πρὸ τῆς μάχης θύειν. ποιῆσαι δέ σφισι τὸ ἱερὸν Σπαρτιᾶται λέγουσι Πράκα ἀπόγονον τρίτον Περγάμου τοῦ Νεοπτολέμου.", "st": "3.20"}, {"sp": "N", "t": "προϊοῦσι δὲ Ἵππου καλούμενον μνῆμά ἐστι. Τυνδάρεως γὰρ θύσας ἐνταῦθα ἵππον τοὺς Ἑλένης ἐξώρκου μνηστῆρας ἱστὰς ἐπὶ τοῦ ἵππου τῶν τομίων· ὁ δὲ ὅρκος ἦν Ἑλένῃ καὶ τῷ γῆμαι προκριθέντι Ἑλένην ἀμυνεῖν ἀδικουμένοις· ἐξορκώσας δὲ τὸν ἵππον κατώρυξεν ἐνταῦθα. κίονες δὲ ἑπτὰ [οἳ] τοῦ μνήματος τούτου διέχουσιν οὐ πολύ, κατὰ τρόπον οἶμαι τὸν ἀρχαῖον, οὓς ἀστέρων τῶν πλανητῶν φασιν ἀγάλματα. καὶ Κρανίου τέμενος κατὰ τὴν ὁδὸν ἐπίκλησιν Στεμματίου καὶ Μυσίας ἐστὶν ἱερὸν Ἀρτέμιδος.", "st": "3.20"}, {"sp": "N", "t": "τὸ δὲ ἄγαλμα τῆς Αἰδοῦς τριάκοντά που στάδια ἀπέχον τῆς πόλεως Ἰκαρίου μὲν ἀνάθημα εἶναι, ποιηθῆναι δὲ ἐπὶ λόγῳ φασὶ τοιῷδε. ὅτ’ ἔδωκεν Ὀδυσσεῖ Πηνελόπην γυναῖκα Ἰκάριος, ἐπειρᾶτο μὲν κατοικίσαι καὶ αὐτὸν Ὀδυσσέα ἐν Λακεδαίμονι, διαμαρτάνων δὲ ἐκείνου δεύτερα τὴν θυγατέρα ἱκέτευε καταμεῖναι καὶ ἐξορμωμένης ἐς Ἰθάκην ἐπακολουθῶν τῷ ἅρματι ἐδεῖτο.", "st": "3.20"}, {"sp": "N", "t": "Ὀδυσσεὺς δὲ τέως μὲν ἠνείχετο, τέλος δὲ ἐκέλευε Πηνελόπην συνακολουθεῖν ἑκοῦσαν ἢ τὸν πατέρα ἑλομένην ἀναχωρεῖν ἐς Λακεδαίμονα. καὶ τὴν ἀποκρίνασθαί φασιν οὐδέν· ἐγκαλυψαμένης δὲ πρὸς τὸ ἐρώτημα, Ἰκάριος τὴν μὲν ἅτε δὴ συνιεὶς ὡς βούλεται ἀπιέναι μετὰ Ὀδυσσέως ἀφίησιν, ἄγαλμα δὲ ἀνέθηκεν Αἰδοῦς· ἐνταῦθα γὰρ τῆς ὁδοῦ προήκουσαν ἤδη τὴν Πηνελόπην λέγουσιν ἐγκαλύψασθαι.", "st": "3.20"}, {"sp": "N", "t": "προελθόντι δὲ αὐτόθεν σταδίους εἴκοσι τοῦ Εὐρώτα τὸ ῥεῦμα ἐγγυτάτω τῆς ὁδοῦ γίνεται, καὶ Λάδα μνῆμά ἐστιν ὠκύτητι ὑπερβαλομένου ποδῶν τοὺς ἐπ’ αὐτοῦ· καὶ δὴ καὶ Ὀλυμπίασιν ἐστεφανοῦτο δολίχῳ κρατῶν, δοκεῖν δέ μοι κάμνων αὐτίκα μετὰ τὴν νίκην ἐκομίζετο, καὶ συμβάσης ἐνταῦθά οἱ τελευτῆς ὁ τάφος ἐστὶν ὑπὲρ τὴν λεωφόρον. τὸν δὲ ὁμώνυμον τούτῳ, νίκην καὶ αὐτὸν Ὀλυμπίασι, πλὴν οὐ δολίχου, σταδίου δὲ ἀνελόμενον, Ἀχαιὸν ἐξ Αἰγίου φησὶν εἶναι [καὶ] τὰ ἐς τοὺς Ὀλυμπιονίκας Ἠλείων γράμματα.", "st": "3.21"}, {"sp": "N", "t": "προϊόντι δὲ ὡς ἐπὶ τὴν Πελλάναν Χαράκωμά ἐστιν ὀνομαζόμενον καὶ μετὰ τοῦτο Πελλάνα πόλις τὸ ἀρχαῖον. Τυνδάρεων δὲ οἰκῆσαί φασιν ἐνταῦθα, ὅτε Ἱπποκόωντα καὶ τοὺς παῖδας ἔφευγεν ἐκ Σπάρτης. θέας δὲ ἄξια αὐτόθι ἰδὼν Ἀσκληπιοῦ τε οἶδα ἱερὸν καὶ τὴν πηγὴν Πελλανίδα. ἐς ταύτην λέγουσιν ὑδρευομένην ἐσπεσεῖν παρθένον, ἀφανισθείσης δὲ τὸ κάλυμμα ἀναφανῆναι τὸ ἐπὶ τῆς κεφαλῆς ἐν ἑτέρᾳ πηγῇ Λαγκίᾳ.", "st": "3.21"}, {"sp": "N", "t": "Πελλάνας δὲ ἑκατὸν στάδια ἀπέχει Βελεμίνα καλουμένη· τῆς δὲ χώρας τῆς Λακωνικῆς ἡ Βελεμίνα μάλιστα ἄρδεσθαι πέφυκεν, ἥντινα διοδεύει μὲν τοῦ Εὐρώτα τὸ ὕδωρ, παρέχεται δὲ ἀφθόνους καὶ αὐτὴ πηγάς.", "st": "3.21"}, {"sp": "N", "t": "ἐπὶ θάλασσαν δὲ ἐς Γύθιον καταβαίνοντί ἐστι Λακεδαιμονίοις [ἡ] κώμη καλουμένη Κροκέαι καὶ λιθοτομία· μία μὲν πέτρα συνεχὴς οὐ διήκουσα, λίθοι δὲ ὀρύσσονται σχῆμα τοῖς ποταμίοις ἐοικότες, ἄλλως μὲν δυσεργεῖς, ἢν δὲ ἐπεργασθῶσιν, ἐπικοσμήσαιεν ἂν καὶ θεῶν ἱερά, κολυμβήθραις δὲ καὶ ὕδασι συντελοῦσι μάλιστα ἐς κάλλος. θεῶν δὲ αὐτόθι πρὸ μὲν τῆς κώμης Διὸς Κροκεάτα λίθου πεποιημένον ἄγαλμα ἕστηκε, Διόσκουροι δὲ ἐπὶ τῇ λιθοτομίᾳ χαλκοῖ.", "st": "3.21"}, {"sp": "N", "t": "μετὰ δὲ Κροκέας ἀποτραπεῖσιν ἐς δεξιὰν ἀπὸ τῆς ἐς Γύθιον εὐθείας ἐπὶ πόλισμα ἥξεις Αἰγίας· Ὅμηρον δὲ ἐν τοῖς ἔπεσι τὸ πόλισμα τοῦτο ὀνομάζειν λέγουσιν Αὐγειάς. ἐνταῦθα ἔστι μὲν λίμνη καλουμένη Ποσειδῶνος, ἔστι δὲ ἐπὶ τῇ λίμνῃ ναὸς καὶ ἄγαλμα τοῦ θεοῦ. τοὺς δὲ ἰχθῦς δεδοίκασιν ἐξαιρεῖν, τὸν θηρεύσαντα ἁλιέα γενέσθαι λέγοντες ἐξ ἀνθρώπου.", "st": "3.21"}, {"sp": "N", "t": "Γύθιον δὲ ἀπέχει μὲν σταδίους τριάκοντα Αἰγιῶν, ἐπὶ θαλάσσῃ δὲ ᾠκισμένον ἔστιν ἤδη τῶν Ἐλευθερολακώνων, οὓς βασιλεὺς Αὔγουστος δουλείας ἀφῆκε Λακεδαιμονίων τῶν ἐν Σπάρτῃ κατηκόους ὄντας. θαλάσσῃ μὲν δὴ πλὴν τοῦ Κορινθίων ἰσθμοῦ περιέχεται πᾶσα ἡ Πελοπόννησος· κόχλους δὲ ἐς βαφὴν πορφύρας παρέχεται τὰ ἐπιθαλάσσια τῆς Λακωνικῆς ἐπιτηδειοτάτας μετά γε τὴν Φοινίκων θάλασσαν.", "st": "3.21"}, {"sp": "N", "t": "ἀριθμὸς δὲ τῶν Ἐλευθερολακώνων ὀκτὼ πόλεις καὶ δέκα εἰσί, πρώτη μὲν καταβᾶσιν ἐξ Αἰγιῶν ἐπὶ θάλασσαν Γύθιον, μετὰ δὲ αὐτὴν Τευθρώνη τε καὶ Λᾶς καὶ Πύρριχος, ἐπὶ Ταινάρῳ δὲ Καινήπολις Οἴτυλός τε καὶ Λεῦκτρα καὶ Θαλάμαι, πρὸς δὲ Ἀλαγονία τε καὶ Γερηνία· τὰ δὲ ἐπέκεινα Γυθίου πρὸς θαλάσσῃ Ἀσωπὸς Ἀκριαὶ Βοιαὶ Ζάραξ Ἐπίδαυρος ἡ Λιμηρὰ Βρασιαὶ Γερόνθραι Μαριός. αὗται μὲν οὖν εἰσιν αἱ λοιπαὶ τῶν Ἐλευθερολακώνων ἀπὸ τεσσάρων ποτὲ καὶ εἴκοσι πόλεων· τὰς δὲ ἄλλας, ἐφ’ ἃς ἂν καὶ αὐτὰς ὁ λόγος ἐπέλθῃ δή μοι, συντελούσας ἴστω τις ἐς Σπάρτην καὶ οὐχ ὁμοίως τοῖς προλεχθεῖσιν αὐτονόμους.", "st": "3.21"}, {"sp": "N", "t": "Γυθεᾶται δὲ τῆς πόλεως ἀνθρώπων μὲν οὐδένα οἰκιστὴν γενέσθαι λέγουσιν, Ἡρακλέα δὲ καὶ Ἀπόλλωνα ὑπὲρ τοῦ τρίποδος ἐς ἀγῶνα ἐλθόντας, ὡς διηλλάγησαν, μετὰ τὴν ἔριν οἰκίσαι κοινῇ τὴν πόλιν· καὶ ἐν τῇ ἀγορᾷ σφισιν Ἀπόλλωνος καὶ Ἡρακλέους ἐστὶν ἀγάλματα, πλησίον δὲ αὐτῶν Διόνυσος. ἑτέρωθι δὲ Ἀπόλλων Κάρνειος καὶ ἱερὸν Ἄμμωνος καὶ Ἀσκληπιοῦ χαλκοῦν ἄγαλμά ἐστιν, οὐκ ἐπόντος ὀρόφου τῷ ναῷ, καὶ πηγὴ τοῦ θεοῦ καὶ Δήμητρος ἱερὸν ἅγιον καὶ Ποσειδῶνος ἄγαλμα Γαιαόχου.", "st": "3.21"}, {"sp": "N", "t": "ὃν δὲ ὀνομάζουσι Γυθεᾶται Γέροντα, οἰκεῖν ἐν θαλάσσῃ φάμενοι, Νηρέα ὄντα εὕρισκον· καί σφισι τοῦ ὀνόματος τούτου παρέσχεν ἀρχὴν Ὅμηρος ἐν Ἰλιάδι ἐν Θέτιδος λόγοις·<br>ὑμεῖς μὲν νῦν δῦτε θαλάσσης εὐρέα κόλπον,<br>ὀψόμεναί τε γέρονθ’ ἅλιον καὶ δώματα πατρός.<br>καλοῦνται δὲ ἐνταῦθα καὶ πύλαι Καστορίδες, καὶ ἐν τῇ ἀκροπόλει ναὸς καὶ ἄγαλμα Ἀθηνᾶς πεποίηται.", "st": "3.21"}, {"sp": "N", "t": "Γυθίου δὲ τρεῖς μάλιστα ἀπέχει σταδίους ἀργὸς λίθος· Ὀρέστην λέγουσι καθεσθέντα ἐπ’ αὐτοῦ παύσασθαι τῆς μανίας· διὰ τοῦτο ὁ λίθος ὠνομάσθη Ζεὺς Καππώτας κατὰ γλῶσσαν τὴν Δωρίδα. ἡ δὲ νῆσος ἡ Κρανάη πρόκειται Γυθίου, καὶ Ὅμηρος Ἀλέξανδρον ἁρπάσαντα Ἑλένην ἐνταῦθα ἔφη συγγενέσθαι οἱ πρῶτον. κατὰ δὲ τὴν νῆσον ἱερόν ἐστιν Ἀφροδίτης ἐν τῇ ἠπείρῳ Μιγωνίτιδος, καὶ ὁ τόπος οὗτος ἅπας καλεῖται Μιγώνιον.", "st": "3.22"}, {"sp": "N", "t": "τοῦτο μὲν δὴ τὸ ἱερὸν ποιῆσαι λέγουσιν Ἀλέξανδρον· Μενέλαος δὲ Ἴλιον ἑλὼν καὶ ἔτεσιν ὕστερον ὀκτὼ μετὰ Τροίας πόρθησιν οἴκαδε ἀνασωθεὶς ἄγαλμα Θέτιδος καὶ θεὰς Πραξιδίκας ἱδρύσατο ἐγγὺς τῆς Μιγωνίτιδος. Διονύσου δὲ ὄρος ἱερὸν Λαρύσιον καλούμενόν ἐστιν ὑπὲρ τοῦ Μιγωνίου· καὶ ἦρος ἀρχομένου Διονύσῳ τὴν ἑορτὴν ἄγουσιν ἄλλα τε ἐς τὰ δρώμενα λέγοντες καὶ ὡς βότρυν ἐνταῦθα ἀνευρίσκουσιν ὡραῖον.", "st": "3.22"}, {"sp": "N", "t": "ἐν ἀριστερᾷ δὲ Γυθίου στάδια προελθόντι ὡς τριάκοντα ἔστιν ἐν τῇ ἠπείρῳ Τρινασοῦ καλουμένης τείχη, φρουρίου ποτὲ ἐμοὶ δοκεῖν καὶ οὐ πόλεως. γενέσθαι δέ οἱ δοκῶ τὸ ὄνομα ἀπὸ τῶν νησίδων, αἳ ταύτῃ πρόκεινται τῆς ἠπείρου τρεῖς ἀριθμόν. προελθόντι δὲ ἀπὸ Τρινασοῦ στάδια ὡς ὀγδοήκοντα τοῦ Ἕλους τὰ ἐρείπια ὑπόλοιπα ἦν, καὶ μετὰ ταῦτα τριάκοντα", "st": "3.22"}, {"sp": "N", "t": "προελθόντι που σταδίους ἐπὶ θαλάσσης πόλις ἐστὶν Ἀκρίαι· θέας δὲ αὐτόθι ἄξια Μητρὸς θεῶν ναὸς καὶ ἄγαλμα λίθου. παλαιότατον δὲ τοῦτο εἶναί φασιν οἱ τὰς Ἀκρίας ἔχοντες, ὁπόσα τῆς θεοῦ ταύτης Πελοποννησίοις ἱερά ἐστιν, ἐπεὶ Μαγνησί γε, οἳ τὰ πρὸς Βορρᾶν νέμονται τοῦ Σιπύλου, τούτοις ἐπὶ Κοδδίνου πέτρᾳ Μητρός ἐστι θεῶν ἀρχαιότατον ἁπάντων ἄγαλμα· ποιῆσαι δὲ οἱ Μάγνητες αὐτὸ Βροτέαν λέγουσι τὸν Ταντάλου.", "st": "3.22"}, {"sp": "N", "t": "Ἀκριᾶται δὲ καὶ ἄνδρα ποτὲ Ὀλυμπιονίκην παρέσχοντο Νικοκλέα, Ὀλυμπιάσι δύο ἀνελόμενον δρόμου νίκας πέντε· πεποίηται δὲ καὶ μνῆμα τῷ Νικοκλεῖ τοῦ τε γυμνασίου μεταξὺ καὶ τοῦ τείχους τοῦ πρὸς τῷ λιμένι.", "st": "3.22"}, {"sp": "N", "t": "ἀπὸ θαλάσσης δὲ ἄνω Γερόνθραι σταδίους ἀπέχουσιν εἴκοσι καὶ ἑκατὸν Ἀκριῶν. ταύτας οἰκουμένας πρὶν Ἡρακλείδας ἐλθεῖν ἐς Πελοπόννησον, ἐποίησαν ἀναστάτους Δωριεῖς οἱ Λακεδαίμονα ἔχοντες, ἀναστήσαντες δὲ Γερονθρῶν τοὺς Ἀχαιοὺς παρὰ σφῶν ἐποίκους ἀπέστειλαν· ἐπ’ ἐμοῦ δὲ Ἐλευθερολακώνων καὶ οὗτοι μοῖρα ἦσαν. κατὰ μὲν δὴ τὴν ἐξ Ἀκριῶν ἐς Γερόνθρας ὁδὸν ἔστι Παλαιὰ καλουμένη κώμη, ἐν δὲ αὐταῖς Γερόνθραις Ἄρεως ναὸς καὶ ἄλσος·", "st": "3.22"}, {"sp": "N", "t": "ἑορτὴν δὲ ἄγουσι τῷ θεῷ κατὰ ἔτος, ἐν ᾗ γυναιξίν ἐστιν ἀπηγορευμένον ἐσελθεῖν ἐς τὸ ἄλσος. περὶ δὲ τὴν ἀγοράν σφισιν αἱ πηγαὶ τῶν ποτίμων εἰσὶν ὑδάτων. ἐν δὲ τῇ ἀκροπόλει ναός ἐστιν Ἀπόλλωνος καὶ ἀγάλματος ἐλέφαντος πεποιημένου κεφαλή· τὰ δὲ λοιπὰ τοῦ ἀγάλματος πῦρ ἠφάνισεν ὁμοῦ τῷ προτέρῳ ναῷ.", "st": "3.22"}, {"sp": "N", "t": "Μαριὸς δὲ ἄλλο Ἐλευθερολακώνων πόλισμα, ὃ ἀπὸ Γερονθρῶν στάδια ἑκατὸν ἀφέστηκεν. ἱερόν ἐστιν αὐτόθι ἀρχαῖον κοινὸν θεῶν ἁπάντων καὶ περὶ αὐτὸ ἄλσος παρεχόμενον πηγάς, εἰσὶ δὲ καὶ ἐν Ἀρτέμιδος ἱερῷ πηγαί· ὕδωρ δὲ ἄφθονον εἴπερ ἄλλο τι χωρίον παρέχεται καὶ Μαριός. κώμη δὲ ὑπὲρ τὸ πόλισμά ἐστιν ἐν μεσογαίᾳ καὶ αὐτή, Γλυππία· καὶ ἐς κώμην ἑτέραν Σελινοῦντα ἐκ Γερονθρῶν ἐστιν ὁδὸς σταδίων εἴκοσι.", "st": "3.22"}, {"sp": "N", "t": "τάδε μὲν ἀπὸ Ἀκριῶν ἄνω πρὸς ἤπειρον· τὰ δὲ πρὸς θαλάσσῃ, πόλις Ἀσωπὸς Ἀκριῶν ἀπέχει σταδίους ἑξήκοντα. ἐν αὐτῇ δὲ ναός τε Ῥωμαίων βασιλέων καὶ ἀνωτέρω τῆς πόλεως ὅσον τε σταδίους δώδεκα [καὶ] ἱερόν ἐστιν Ἀσκληπιοῦ· Φιλόλαον τὸν θεὸν ὀνομάζουσι. τὰ δὲ ὀστᾶ ἐν τῷ γυμνασίῳ τὰ τιμώμενα μεγέθει μὲν ὑπερβάλλοντα, ἀνθρώπου δὲ ὅμως ἐστί. καὶ Ἀθηνᾶς ἱερόν ἐστιν ἐν τῇ ἀκροπόλει Κυπαρισσίας ἐπίκλησιν. τῆς δὲ ἀκροπόλεως πρὸς τοῖς ποσὶ πόλεως ἐρείπια καλουμένης Ἀχαιῶν τῶν Παρακυπαρισσίων.", "st": "3.22"}, {"sp": "N", "t": "ἔστι δὲ ἐν τῇ γῇ ταύτῃ καὶ ἱερὸν Ἀσκληπιοῦ στάδια ἀπέχον ὡς πεντήκοντα Ἀσωποῦ· τὸ δὲ χωρίον, ἔνθα τὸ Ἀσκληπιεῖον, Ὑπερτελέατον ὀνομάζουσιν. ἄκρα δὲ ἀνέχουσα ἐς θάλασσαν ἀφέστηκεν Ἀσωποῦ διακόσια στάδια· καλοῦσι δὲ Ὄνου γνάθον τὴν ἄκραν. ἐνταῦθά ἐστιν Ἀθηνᾶς ἱερὸν ἄγαλμα οὐκ ἔχον, οὐδὲ ὄροφος ἔπεστιν ἐπ’ αὐτῷ· λέγεται δὲ ὡς ὑπὸ Ἀγαμέμνονος ἐποιήθη. ἔστι δὲ καὶ μνῆμα Κινάδου· νεὼς τῆς Μενελάου καὶ οὗτος κυβερνήτης ἦν.", "st": "3.22"}, {"sp": "N", "t": "ἐσέχει δὲ μετὰ τὴν ἄκραν Βοιατικὸς καλούμενος κόλπος, καὶ Βοιαὶ πόλις πρὸς τῷ πέρατί ἐστι τοῦ κόλπου. ταύτην ᾤκισε μὲν Βοιὸς τῶν Ἡρακλειδῶν, συναγαγεῖν δὲ ἄνδρας ἀπὸ τριῶν ἐς αὐτὴν λέγεται πόλεων, Ἤτιδος καὶ Ἀφροδισιάδος καὶ Σίδης. τῶν δὲ πόλεων τῶν ἀρχαίων τὰς μὲν δύο ἐς Ἰταλίαν φεύγοντα Αἰνείαν καὶ ὑπὸ πνευμάτων ἀπενεχθέντα ἐς τοῦτον τὸν κόλπον οἰκίσαι φασί, τὴν Ἠτιάδα Αἰνείου θυγατέρα λέγοντες εἶναι· τὴν τρίτην δὲ κληθῆναι τῶν πόλεων λέγουσιν ἀπὸ τῆς Δαναοῦ Σίδης.", "st": "3.22"}, {"sp": "N", "t": "ἀπὸ δὴ τούτων τῶν πόλεων ἀναστάντες ἐζήτουν ἔνθα οἰκῆσαι σφᾶς χρεὼν εἴη· καί τι καὶ μάντευμα ἦν αὐτοῖς Ἄρτεμιν ἔνθα οἰκήσουσιν ἐπιδείξειν. ὡς οὖν ἐκβᾶσιν ἐς τὴν γῆν λαγὼς ἐπιφαίνεται, τὸν λαγὼν ἐποιήσαντο ἡγεμόνα τῆς ὁδοῦ· καταδύντος δὲ ἐς μυρσίνην πόλιν τε οἰκίζουσιν ἐνταῦθα, οὗπερ ἡ μυρσίνη ἦν, καὶ τὸ δένδρον ἔτι ἐκείνην σέβουσι τὴν μυρσίνην καὶ Ἄρτεμιν ὀνομάζουσι Σώτειραν.", "st": "3.22"}, {"sp": "N", "t": "καὶ Ἀπόλλωνος ναὸς ἐν τῇ Βοιατῶν ἀγορᾷ ἐστι καὶ ἑτέρωθι Ἀσκληπιοῦ καὶ Σαράπιδός τε καὶ Ἴσιδος. ⟨Ἤτιδος δ’⟩ ἐρείπια ἀπέχει μὲν Βοιῶν οὐ πλέον ἢ σταδίους ἑπτά· ἰόντι δὲ ἐς αὐτὰ ἄγαλμα Ἑρμοῦ λίθινον ἕστηκεν ἐν ἀριστερᾷ, καὶ ἐν τοῖς ἐρειπίοις ἱερὸν Ἀσκληπιοῦ καὶ Ὑγείας ἐστὶν οὐκ ἀφανές.", "st": "3.22"}, {"sp": "N", "t": "Κύθηρα δὲ κεῖται μὲν ἀπαντικρὺ Βοιῶν, ἐς δὲ Πλατανιστοῦντα—ἐλάχιστον γὰρ τῆς ἠπείρου ταύτῃ διέστηκεν ἡ νῆσος—ἐς ταύτην τὴν ἄκραν τὸν Πλατανιστοῦντα ἀπὸ ἄκρας τῆς ἠπείρου, καλουμένης δὲ Ὄνου γνάθου, σταδίων πλοῦς τεσσαράκοντά ἐστιν. ἐν Κυθήροις δὲ ἐπὶ θαλάσσης Σκάνδειά ἐστιν ἐπίνειον, Κύθηρα δὲ ἡ πόλις ἀναβάντι ἀπὸ Σκανδείας στάδια ὡς δέκα. τὸ δὲ ἱερὸν τῆς Οὐρανίας ἁγιώτατον καὶ ἱερῶν ὁπόσα Ἀφροδίτης παρ’ Ἕλλησίν ἐστιν ἀρχαιότατον· αὐτὴ δὲ ἡ θεὸς ξόανον ὡπλισμένον.", "st": "3.23"}, {"sp": "N", "t": "πλέοντι δὲ ἐκ Βοιῶν τὴν ὑπὸ τὴν ἄκραν τῆς Μαλέας λιμήν ἐστιν ὀνομαζόμενον Νύμφαιον καὶ Ποσειδῶνος ἄγαλμα ὀρθὸν καὶ σπήλαιον θαλάσσης ἐγγύτατα, ἐν δὲ αὐτῷ γλυκέος ὕδατος πηγή· καὶ ἄνθρωποι περιοικοῦσι πολλοί. περιπλεύσαντι δὲ τὴν ἄκραν τῆς Μαλέας καὶ ἑκατὸν στάδια ἀποσχόντι, ἐπὶ θαλάσσῃ χωρίον ἐν ὅροις Βοιατῶν Ἀπόλλωνος μὲν ἱερόν ἐστιν, Ἐπιδήλιον δὲ ὀνομαζόμενον·", "st": "3.23"}, {"sp": "N", "t": "τὸ γὰρ τοῦ Ἀπόλλωνος ξόανον, ὃ νῦν ἐστιν ἐνταῦθα, ἐν Δήλῳ ποτὲ ἵδρυτο. τῆς γὰρ Δήλου τότε ἐμπορίου τοῖς Ἕλλησιν οὔσης καὶ ἄδειαν τοῖς ἐργαζομένοις διὰ τὸν θεὸν δοκούσης παρέχειν, Μηνοφάνης Μιθριδάτου στρατηγὸς εἴτε αὐτὸς ὑπερφρονήσας εἴτε καὶ ὑπὸ Μιθριδάτου προστεταγμένον —ἀνθρώπῳ γὰρ ἀφορῶντι ἐς κέρδος τὰ θεῖα ὕστερα λημμάτων—, οὗτος οὖν ὁ Μηνοφάνης, ἅτε οὔσης", "st": "3.23"}, {"sp": "N", "t": "ἀτειχίστου τῆς Δήλου καὶ ὅπλα οὐ κεκτημένων ⟨τῶν⟩ ἀνδρῶν, τριήρεσιν ἐσπλεύσας ἐφόνευσε μὲν τοὺς ἐπιδημοῦντας τῶν ξένων, ἐφόνευσε δὲ αὐτοὺς τοὺς Δηλίους· κατασύρας δὲ πολλὰ μὲν ἐμπόρων χρήματα, πάντα δὲ ⟨τὰ⟩ ἀναθήματα, προσεξανδραποδισάμενος δὲ καὶ γυναῖκας καὶ τέκνα, καὶ αὐτὴν ἐς ἔδαφος κατέβαλε τὴν Δῆλον. ἅτε δὲ πορθουμένης τε καὶ ἁρπαζομένης, τῶν τις βαρβάρων ὑπὸ ὕβρεως τὸ ξόανον τοῦτο ἀπέρριψεν ἐς τὴν θάλασσαν· ὑπολαβὼν δὲ ὁ κλύδων ἐνταῦθα τῆς Βοιατῶν ἀπήνεγκε, καὶ τὸ χωρίον διὰ τοῦτο Ἐπιδήλιον ὀνομάζουσι.", "st": "3.23"}, {"sp": "N", "t": "τὸ μέντοι μήνιμα ⟨τὸ⟩ ἐκ τοῦ θεοῦ διέφυγεν οὔτε Μηνοφάνης οὔτε αὐτὸς Μιθριδάτης· ἀλλὰ Μηνοφάνην μὲν παραυτίκα, ὡς ἀνήγετο ἐρημώσας τὴν Δῆλον, λοχήσαντες ναυσὶν οἱ διαπεφευγότες τῶν ἐμπόρων καταδύουσι, Μιθριδάτην δὲ ὕστερον τούτων ἠνάγκασεν ὁ θεὸς αὐτόχειρα αὑτοῦ καταστῆναι, τῆς τε ἀρχῆς οἱ καθῃρημένης καὶ ἐλαυνόμενον πανταχόθεν ὑπὸ Ῥωμαίων· εἰσὶ δὲ οἵ φασιν αὐτὸν παρά του τῶν μισθοφόρων θάνατον βίαιον ἐν μέρει χάριτος εὕρασθαι.", "st": "3.23"}, {"sp": "N", "t": "τούτοις μὲν τοιαῦτα ἀπήντησεν ἀσεβήσασι· τῇ δὲ Βοιαῶν ὅμορος Ἐπίδαυρός ἐστιν ἡ Λιμηρά, σταδίους ὡς διακοσίους ἀπέχουσα Ἐπιδηλίου. φασὶ δὲ οὐ Λακεδαιμονίων, τῶν δὲ ἐν τῇ Ἀργολίδι Ἐπιδαυρίων εἶναι, πλέοντες δὲ ἐς Κῶν παρὰ τὸν Ἀσκληπιὸν ἀπὸ τοῦ κοινοῦ προσσχεῖν τῆς Λακωνικῆς ἐνταῦθα καὶ ἐξ ἐνυπνίων γενομένων σφίσι καταμείναντες οἰκῆσαι.", "st": "3.23"}, {"sp": "N", "t": "λέγουσι δὲ καὶ ὡς οἴκοθεν ἐκ τῆς Ἐπιδαύρου δράκοντα ἐπαγομένοις αὐτοῖς ἐξέφυγεν ἐκ τῆς νεὼς ὁ δράκων, ἐκφυγὼν δὲ οὐ πόρρω κατέδυ θαλάσσης, καί σφισιν ὁμοῦ τῶν ὀνειράτων τῇ ὄψει καὶ ἀπὸ τοῦ σημείου τοῦ κατὰ τὸν δράκοντα ἔδοξεν αὐτόθι καταμείναντας οἰκῆσαι. καὶ ἔνθα ὁ δράκων κατέδυ, βωμοί τέ εἰσιν Ἀσκληπιοῦ καὶ ἐλαῖαι περὶ αὐτοὺς πεφύκασιν.", "st": "3.23"}, {"sp": "N", "t": "προελθόντι δὲ ἐν δεξιᾷ δύο που σταδίους, ἔστιν Ἰνοῦς καλούμενον ὕδωρ, μέγεθος μὲν κατὰ λίμνην μικράν, τῆς γῆς δὲ ἐν βάθει μᾶλλον· ἐς τοῦτο τὸ ὕδωρ ἐν τῇ ἑορτῇ τῆς Ἰνοῦς ἐμβάλλουσιν ἀλφίτων μάζας. ταύτας ἐπὶ μὲν αἰσίῳ τοῦ ἐμβαλόντος καταδεξάμενον ἔχει τὸ ὕδωρ· εἰ δὲ ἀναπέμψαιτο σφᾶς, πονηρὸν κέκριται σημεῖον.", "st": "3.23"}, {"sp": "N", "t": "τὸ δὲ αὐτὸ καὶ ἐν Αἴτνῃ δηλοῦσιν οἱ κρατῆρες· καὶ γὰρ χρυσοῦ ἐς αὐτοὺς καὶ ἀργύρου ποιήματα, ἔτι δὲ καὶ ἱερεῖα τὰ πάντα ἀφιᾶσι· ταῦτα δὲ ἢν μὲν ὑπολαβὸν ἀπενέγκῃ τὸ πῦρ, οἱ δὲ χαίρουσιν ὡς ἐπὶ πεφηνότι ἀγαθῷ, ἀπωσαμένου δὲ τὰ ἐμβληθέντα συμφορὰν ἔσεσθαι τούτῳ τῷ ἀνδρὶ νομίζουσι.", "st": "3.23"}, {"sp": "N", "t": "κατὰ δὲ τὴν ὁδὸν τὴν ἐκ Βοιῶν ἐς Ἐπίδαυρον τὴν Λιμηρὰν ἄγουσαν Ἀρτέμιδος ἱερόν ἐστιν ἐν τῇ Ἐπιδαυρίων Λιμνάτιδος. ἡ πόλις δὲ ἀπέχουσα οὐ πολὺ ἀπὸ θαλάσσης ἐπὶ μετεώρῳ μὲν ᾤκισται, θέας δὲ αὐτόθι ἄξια τὸ μὲν Ἀφροδίτης ἐστὶν ἱερόν, τὸ δὲ Ἀσκληπιοῦ καὶ ἄγαλμα ὀρθὸν λίθου, καὶ Ἀθηνᾶς ἐν τῇ ἀκροπόλει ναός, πρὸ δὲ τοῦ λιμένος Διὸς ἐπίκλησιν Σωτῆρος.", "st": "3.23"}, {"sp": "N", "t": "ἄκρα δὲ ἐς τὸ πέλαγος κατὰ τὴν πόλιν ἀνέχει καλουμένη Μινῴα· καὶ ὁ μὲν κόλπος οὐδέν τι ἔχει διάφορον ἢ ὅσαι κατὰ τὴν Λακωνικὴν ἄλλαι θαλάσσης εἰσὶν ἐσβολαί, αἰγιαλὸς δὲ ὁ ταύτῃ παρέχεται ψηφῖδας σχῆμα εὐπρεπεστέρας καὶ χρόας παντοδαπῆς.", "st": "3.23"}, {"sp": "N", "t": "Ἐπιδαύρου δὲ σταδίους ἑκατὸν ἀπέχει Ζάραξ, ἄλλως μὲν εὐλίμενον χωρίον, τῶν δὲ Ἐλευθερολακώνων μάλιστα τοῦτο ἐκτετρύχωται, ἐπεὶ καὶ Κλεώνυμος ὁ Κλεομένους τοῦ Ἀγησιπόλιδος μόνον τοῦτο τῶν Λακωνικῶν πολισμάτων ἐποίησεν ἀνάστατον· καί μοι τὰ ἐς τὸν Κλεώνυμον ἑτέρωθί ἐστιν εἰρημένα. ἐν Ζάρακι δὲ ἄλλο μὲν οὐδέν, πρὸς δὲ τοῦ λιμένος τῷ πέρατι Ἀπόλλωνος ναός ἐστι καὶ ἄγαλμα κιθάραν ἔχον.", "st": "3.24"}, {"sp": "N", "t": "προελθόντι δὲ ἀπὸ Ζάρακος παρὰ τὴν θάλασσαν ἑκατόν που στάδια καὶ ἐπιστρέψαντι αὐτόθεν ἐς μεσόγαιαν καὶ ἐπαναβάντι σταδίους ὡς δέκα, Κυφάντων καλουμένων ἐρείπιά ἐστιν, ἐν δὲ αὐτοῖς σπήλαιον ἱερὸν Ἀσκληπιοῦ, λίθου δὲ τὸ ἄγαλμα. ἔστι δὲ καὶ ὕδατος ψυχροῦ κρουνὸς ἐκβάλλων ἐκ πέτρας· Ἀταλάντην θηρεύουσαν ἐνταῦθά φασιν, ὡς ἠνιᾶτο ὑπὸ δίψης, παῖσαι τῇ λόγχῃ τὴν πέτραν καὶ οὕτω ῥυῆναι τὸ ὕδωρ.", "st": "3.24"}, {"sp": "N", "t": "Βρασιαὶ δὲ ἐσχάτη μὲν ταύτῃ τῶν Ἐλευθερολακώνων πρὸς θαλάσσῃ ἐστί, Κυφάντων δὲ ἀπέχουσι πλοῦν σταδίων διακοσίων. οἱ δὲ ἄνθρωποι λέγουσιν ⟨οἱ⟩ ἐνταῦθα, οὐδέσιν ὁμολογοῦντες Ἑλλήνων, ὡς Σεμέλη τέκοι τὸν παῖδα ἐκ Διὸς καὶ ὑπὸ τοῦ Κάδμου φωραθεῖσα ἐς λάρνακα αὐτὴ καὶ Διόνυσος ἐμβληθείη· καὶ τὴν λάρνακα ὑπὸ τοῦ κλύδωνος ἐκπεσεῖν φασιν ἐς τὴν σφετέραν, καὶ Σεμέλην μὲν—οὐ γὰρ αὐτὴν περιοῦσαν ἔτι εὑρεῖν—ἐπιφανῶς θάψαι, Διόνυσον δὲ ἀναθρέψαι λέγουσιν.", "st": "3.24"}, {"sp": "N", "t": "ἐπὶ τούτῳ δὲ αὐτοῖς καὶ τὴν πόλιν, Ὀρειάτας ἐς ἐκεῖνο ὀνομαζομένην, μετονομασθῆναι Βρασιὰς ἐπὶ τῇ ἐκβολῇ τῇ ἐς τὴν γῆν τῆς λάρνακος· ὡσαύτως δὲ καὶ ἐφ’ ἡμῶν τὰ ὑπὸ τοῦ κλύδωνος ἀπωθούμενα ἐς τὴν γῆν ἐκβεβράσθαι καλοῦσιν οἱ πολλοί. Βρασιᾶται δὲ καὶ τάδε ἐπιλέγουσιν, Ἰνώ σφισιν ἐς τὴν χώραν ἀφικέσθαι πλανωμένην, ἐλθοῦσαν δὲ ἐθελῆσαι τοῦ Διονύσου γενέσθαι τροφόν· καὶ ἀποφαίνουσι μὲν τὸ ἄντρον ἔνθα τὸν Διόνυσον ἔθρεψεν Ἰνώ, καλοῦσι δὲ καὶ τὸ πεδίον Διονύσου κῆπον.", "st": "3.24"}, {"sp": "N", "t": "ἱερὰ δὲ αὐτόθι τὸ μέν ἐστιν Ἀσκληπιοῦ, τὸ δὲ Ἀχιλλέως, καὶ ἑορτὴν κατὰ ἔτος ἄγουσιν Ἀχιλλεῖ. ἄκρα δέ ἐστιν ἐν ταῖς Βρασιαῖς μικρά, προέχουσα ἠρέμα ἐς τὴν θάλασσαν, καὶ ἐπ’ αὐτῇ χαλκοῖ ποδιαίων ἑστήκασιν οὐ μείζονες, πίλους ἐπὶ ταῖς κεφαλαῖς ἔχοντες, οὐκ οἶδα εἰ Διοσκούρους σφᾶς ἢ Κορύβαντας νομίζουσι· τρεῖς δ’ οὖν εἰσί, τέταρτον δὲ Ἀθηνᾶς ἄγαλμα.", "st": "3.24"}, {"sp": "N", "t": "τὰ δὲ ἐν δεξιᾷ Γυθίου Λᾶς ἐστι, θαλάσσης μὲν δέκα στάδια, Γυθίου δὲ τεσσαράκοντα ἀπέχουσα. ᾤκισται δὲ νῦν μὲν Ἰλίου καλουμένου καὶ Ἀσίας καὶ Κνακαδίου, τῶν ὀρῶν τούτων τὸ μεταξὺ ἐπέχουσα, πρότερον δὲ τῆς Ἀσίας τοῦ ὄρους ἔκειτο ἐπὶ τῇ κορυφῇ· καὶ νῦν ἔτι τῆς πόλεώς ἐστι τῆς ἀρχαίας ἐρείπια καὶ πρὸ τῶν τειχῶν ἄγαλμα Ἡρακλέους καὶ ἀπὸ τῶν Μακεδόνων τρόπαιον, οἳ μοῖρα τῆς Φιλίππου στρατιᾶς ἦσαν, ἡνίκα ἐς τὴν Λακωνικὴν ἐσέβαλεν, ἀποτραπόμενοι δὲ ἀπὸ τῶν ἄλλων τὰ παραθαλάσσια ἐλεηλάτουν τῆς χώρας.", "st": "3.24"}, {"sp": "N", "t": "ἔστι δὲ ἐν τοῖς ἐρειπίοις ναὸς Ἀθηνᾶς ἐπίκλησιν Ἀσίας, ποιῆσαι δὲ Πολυδεύκην καὶ Κάστορά φασιν ἀνασωθέντας ἐκ Κόλχων· εἶναι γὰρ καὶ Κόλχοις Ἀθηνᾶς Ἀσίας ἱερόν. μετασχόντας μὲν οὖν οἶδα Ἰάσονι τοῦ στόλου τοὺς Τυνδάρεω παῖδας· ὅτι δὲ Ἀθηνᾶν Ἀσίαν τιμῶσιν οἱ Κόλχοι, παρὰ Λακεδαιμονίων ἀκούσας γράφω. τῆς δὲ ἐφ’ ἡμῶν οἰκουμένης πόλεως κρήνη τέ ἐστι πλησίον διὰ τὴν χρόαν τοῦ ὕδατος καλουμένη Γαλακὼ καὶ πρὸς τῇ κρήνῃ γυμνάσιον· Ἑρμοῦ δὲ ἕστηκεν ἄγαλμα ἀρχαῖον.", "st": "3.24"}, {"sp": "N", "t": "τῶν δὲ ὀρῶν ἐπὶ μὲν τοῦ Ἰλίου Διονύσου τέ ἐστι καὶ ἐπ’ ἄκρας τῆς κορυφῆς Ἀσκληπιοῦ ναός, πρὸς δὲ τῷ Κνακαδίῳ Κάρνειος καλούμενος Ἀπόλλων. ἀπὸ δὲ τοῦ Καρνείου σταδίους προελθόντι ὡς τριάκοντα, ἔστιν ἐν χωρίῳ Ὕψοις ἐν ὅροις ἤδη Σπαρτιατῶν ἱερὸν Ἀσκληπιοῦ καὶ Ἀρτέμιδος ἐπίκλησιν Δαφναίας.", "st": "3.24"}, {"sp": "N", "t": "πρὸς θαλάσσῃ δὲ ἐπὶ ἄκρας ναός ἐστι Δικτύννης Ἀρτέμιδος, καί οἱ κατὰ ἔτος ἕκαστον ἑορτὴν ἄγουσι. ταύτης δὲ ἐν ἀριστερᾷ τῆς ἄκρας ποταμὸς ἐκδίδωσιν ἐς θάλασσαν Σμῆνος, ὕδωρ πιεῖν ἡδὺ εἴπερ ἄλλος τις παρασχόμενος ποταμός· ἔχει δὲ ἐν τῷ ὄρει τῷ Ταϋγέτῳ τὰς πηγάς, ἀπέχει δὲ τῆς πόλεως σταδίους οὐ πλέον πέντε.", "st": "3.24"}, {"sp": "N", "t": "ἐν δὲ Ἀραΐνῳ καλουμένῳ χωρίῳ τάφος Λᾶ καὶ ἀνδριὰς ἐπὶ τῷ μνήματι ἔπεστι. τοῦτον τὸν Λᾶν οἰκιστὴν εἶναι λέγουσιν οἱ ταύτῃ, καὶ ἀποθανεῖν φασιν ὑπὸ Ἀχιλλέως, Ἀχιλλέα δὲ κατᾶραί σφισιν ἐς τὴν χώραν Ἑλένην παρὰ Τυνδάρεω γυναῖκα αἰτοῦντα. λέγοντι δὲ ἐπ’ ἀληθείᾳ Πάτροκλός ἐστιν ὁ τὸν Λᾶν ἀποκτείνας· οὗτος γὰρ καὶ ὁ μνηστευσάμενός ἐστιν Ἑλένην. καὶ ὅτι μὲν τῶν Ἑλένης μνηστήρων Ἀχιλλεὺς οὐκ ἔστιν ἐν Καταλόγῳ γυναικῶν, μηδὲν τοῦτο ἔστω τεκμήριον οὐκ αἰτῆσαι Ἑλένην αὐτόν·", "st": "3.24"}, {"sp": "N", "t": "Ὅμηρος δὲ ἔγραψε μὲν τῆς ποιήσεως ἀρχόμενος ὡς Ἀχιλλεὺς χαριζόμενος τοῖς Ἀτρέως παισὶ καὶ οὐκ ἐνεχόμενος τοῖς ὅρκοις τοῖς Τυνδάρεω παραγένοιτο ἐς Τροίαν, ἐποίησε δὲ ἐν ἄθλοις λέγοντα Ἀντίλοχον ὡς Ὀδυσσεὺς πρεσβύτερός ἐστιν αὐτοῦ γενεᾷ, τὸν δὲ Ὀδυσσέα πρὸς Ἀλκίνουν περὶ τῶν ἐν Ἅιδου καὶ ἄλλα διηγούμενον καὶ ὅτι Θησέα ἰδεῖν ἐθελήσαι καὶ Πειρίθουν προτέρους ἄνδρας ἢ καθ’ ἡλικίαν τὴν αὑτοῦ· Θησέα δὲ ἴσμεν ἁρπάσαντα Ἑλένην. οὕτως οὐδὲ ἐγχωροῦν ἐστιν ἀρχὴν Ἑλένης μνηστῆρα Ἀχιλλέα γενέσθαι.", "st": "3.24"}, {"sp": "N", "t": "προελθόντι δὲ ἀπὸ τοῦ μνήματος ἐκδίδωσιν ἐς θάλασσαν ποταμός, ὄνομα δέ οἱ Σκύρας, ὅτι κατὰ τοῦτον ἀνώνυμον τέως ὄντα Πύρρος ὁ Ἀχιλλέως ἔσχε ταῖς ναυσίν, ἡνίκα ἐπὶ τὸν Ἑρμιόνης γάμον ἔπλευσεν ἐκ Σκύρου. διαβάντων δὲ τὸν ποταμὸν ἔστιν ἱερὸν ἀρχαῖον … ἀπωτέρω Διὸς βωμοῦ. τοῦ ποταμοῦ δὲ σταδίους τεσσαράκοντα ἀπέχει Πύρριχος ἐν μεσογαίᾳ. τὸ δὲ ὄνομα τῇ πόλει γενέσθαι φασὶν ἀπὸ Πύρρου τοῦ Ἀχιλλέως, οἱ δὲ εἶναι θεὸν Πύρριχον τῶν καλουμένων", "st": "3.25"}, {"sp": "N", "t": "Κουρήτων· εἰσὶ δὲ οἳ Σιληνὸν ἐκ Μαλέας ἐλθόντα ἐνταῦθα λέγουσιν οἰκῆσαι. τραφῆναι μὲν δὴ τὸν Σιληνὸν ἐν τῇ Μαλέᾳ δηλοῖ καὶ τάδε ἐξ ᾄσματος Πινδάρου<br>ὁ ζαμενὴς δὲ ὁ χοροιτύπος, ὃν Μαλέας ὄρος<br>ἔθρεψε, Ναΐδος ἀκοίτας, Σιληνός·<br>ὡς δὲ καὶ Πύρριχος ὄνομα ἦν αὐτῷ, Πινδάρῳ μὲν οὐκ ἔστιν εἰρημένον, λέγουσι δὲ οἱ περὶ τὴν Μαλέαν οἰκοῦντες.", "st": "3.25"}, {"sp": "N", "t": "ἔστι δὲ ἐν τῇ Πυρρίχῳ φρέαρ ἐν τῇ ἀγορᾷ, δοῦναι δέ σφισι τὸν Σιληνὸν νομίζουσι· σπανίζοιέν τ’ ἂν ὕδατος, εἰ τὸ φρέαρ τοῦτο ἐπιλείποι. θεῶν δὲ ἐν τῇ γῇ σφισιν ἱερά ἐστιν Ἀρτέμιδός τε ἐπίκλησιν Ἀστρατείας, ὅτι τῆς ἐς τὸ πρόσω στρατείας ἐνταῦθα ἐπαύσαντο Ἀμαζόνες, καὶ Ἀπόλλων Ἀμαζόνιος· ξόανα μὲν ἀμφότερα, ἀναθεῖναι δὲ λέγουσιν αὐτὰ τὰς ἀπὸ Θερμώδοντος γυναῖκας.", "st": "3.25"}, {"sp": "N", "t": "ἀπὸ δὲ Πυρρίχου καταβάντι ἐς θάλασσαν ἔστι Τευθρώνη· τὸν δὲ οἰκιστὴν οἱ ταύτῃ Τεύθραντα Ἀθηναῖον ὄντα ἀποφαίνουσι, τιμῶσι δὲ θεῶν μάλιστα Ἰσσωρίαν Ἄρτεμιν, καὶ πηγή σφισίν ἐστι Ναΐα. Τευθρώνης δὲ ἀπέχει πεντήκοντα καὶ ἑκατὸν σταδίους ἐς θάλασσαν ἀνέχουσα ἄκρα Ταίναρον, καὶ λιμένες ὅ τε Ἀχίλλειός ἐστι καὶ Ψαμαθοῦς, ἐπὶ δὲ τῇ ἄκρᾳ ναὸς εἰκασμένος σπηλαίῳ καὶ πρὸ αὐτοῦ Ποσειδῶνος ἄγαλμα.", "st": "3.25"}, {"sp": "N", "t": "ἐποίησαν δὲ Ἑλλήνων τινὲς ὡς Ἡρακλῆς ἀναγάγοι ταύτῃ τοῦ Ἅιδου τὸν κύνα, οὔτε ὑπὸ γῆν ὁδοῦ διὰ τοῦ σπηλαίου φερούσης οὔτε ἕτοιμον ὂν πεισθῆναι θεῶν ὑπόγαιον εἶναί τινα οἴκησιν ἐς ἣν ἀθροίζεσθαι τὰς ψυχάς. ἀλλὰ Ἑκαταῖος μὲν ὁ Μιλήσιος λόγον εὗρεν εἰκότα, ὄφιν φήσας ἐπὶ Ταινάρῳ τραφῆναι δεινόν, κληθῆναι δὲ Ἅιδου κύνα, ὅτι ἔδει τὸν δηχθέντα τεθνάναι παραυτίκα ὑπὸ τοῦ ἰοῦ, καὶ τοῦτον ἔφη τὸν ὄφιν ὑπὸ Ἡρακλέους ἀχθῆναι παρ’ Εὐρυσθέα·", "st": "3.25"}, {"sp": "N", "t": "Ὅμηρος δὲ— πρῶτος γὰρ ἐκάλεσεν Ἅιδου κύνα ὅντινα Ἡρακλῆς ἦγεν —οὔτε ὄνομα ἔθετο οὐδὲν οὔτε συνέπλασεν ἐς τὸ εἶδος ὥσπερ ἐπὶ τῇ Χιμαίρᾳ· οἱ δὲ ὕστερον Κέρβερον ὄνομα ἐποίησαν καὶ κυνὶ τἄλλα εἰκάζοντες κεφαλὰς τρεῖς φασιν ἔχειν αὐτὸν, οὐδέν τι μᾶλλον Ὁμήρου κύνα τὸν ἀνθρώπῳ σύντροφον εἰρηκότος ἢ εἰ δράκοντα ὄντα ἐκάλεσεν Ἅιδου κύνα.", "st": "3.25"}, {"sp": "N", "t": "ἀναθήματα δὲ ἄλλα τέ ἐστιν ἐπὶ Ταινάρῳ καὶ Ἀρίων ὁ κιθαρῳδὸς χαλκοῦς ἐπὶ δελφῖνος. τὰ μὲν οὖν ἐς αὐτὸν Ἀρίονα καὶ τὰ ἐπὶ τῷ δελφῖνι Ἡρόδοτος εἶπεν ἀκοὴν ἐν τῇ Λυδίᾳ συγγραφῇ· τὸν δὲ ἐν Ποροσελήνῃ δελφῖνα τῷ παιδὶ σῶστρα ἀποδιδόντα, ὅτι συγκοπέντα ὑπὸ ἁλιέων αὐτὸν ἰάσατο, τοῦτον τὸν δελφῖνα εἶδον καὶ καλοῦντι τῷ παιδὶ ὑπακούοντα καὶ φέροντα, ὁπότε ἐποχεῖσθαί οἱ βούλοιτο.", "st": "3.25"}, {"sp": "N", "t": "ἔστι δὲ ἐπὶ Ταινάρῳ καὶ πηγή, νῦν μὲν οὐδὲν ὥστε καὶ θαῦμα εἶναι παρεχομένη, πρότερον δὲ τοῖς ἐνιδοῦσιν ἐς τὸ ὕδωρ τοὺς λιμένας—φασὶ— καὶ τὰς ναῦς θεάσασθαι παρεῖχε. τοῦτο ἔπαυσε γυνὴ τὸ ὕδωρ μὴ καὶ τοῦ λοιποῦ τοιαῦτα ἐπιδείκνυσθαι, μεμιασμένην ἐναποπλύνασα ἐσθῆτα.", "st": "3.25"}, {"sp": "N", "t": "Ταινάρου δὲ τῆς ἄκρας πλοῦν ὅσον τεσσαράκοντα σταδίων ἀφέστηκε Καινήπολις· ὄνομα δὲ ἦν πάλαι καὶ ταύτῃ Ταίναρον. ἐν αὐτῇ δὲ μέγαρον Δήμητρος καὶ ἐπὶ θαλάσσῃ ναός ἐστιν Ἀφροδίτης καὶ ἄγαλμα ὀρθὸν λίθου. ἐντεῦθεν ἀποσχόντι τριάκοντα σταδίους Θυρίδες ἄκρα Ταινάρου καὶ πόλεως ἐρείπια Ἱππόλας ἐστίν, ἐν δὲ αὐτοῖς Ἀθηνᾶς ἱερὸν Ἱππολαΐτιδος· ὀλίγον δὲ ἀπωτέρω Μέσσα πόλις καὶ λιμήν.", "st": "3.25"}, {"sp": "N", "t": "ἀπὸ τούτου στάδια τοῦ λιμένος πεντήκοντά ἐστι καὶ ἑκατὸν ἐπὶ Οἴτυλον· ὁ δὲ ἥρως ἀφ’ οὗ τῇ πόλει τὸ ὄνομα ἐγένετο, Ἀργεῖος τὸ ἀνέκαθεν, Ἀμφιάνακτος υἱὸς ὢν τοῦ Ἀντιμάχου. θέας δὲ ἄξια ἐν Οἰτύλῳ Σαράπιδός ἐστιν ἱερὸν καὶ ἐν τῇ ἀγορᾷ Καρνείου ξόανον Ἀπόλλωνος.", "st": "3.25"}, {"sp": "N", "t": "ἐς Θαλάμας δὲ ἐξ Οἰτύλου μῆκος τῆς ὁδοῦ στάδιοι περὶ τοὺς ὀγδοήκοντά εἰσι, κατὰ δὲ τὴν ὁδὸν ἱερόν ἐστιν Ἰνοῦς καὶ μαντεῖον. μαντεύονται μὲν οὖν καθεύδοντες, ὁπόσα δ’ ἂν πυθέσθαι δεηθῶσιν, ὀνείρατα δείκνυσί σφισιν ἡ θεός. χαλκᾶ δὲ ἕστηκεν ἀγάλματα ἐν ὑπαίθρῳ τοῦ ἱεροῦ, τῆς τε Πασιφάης καὶ Ἡλίου τὸ ἕτερον· αὐτὸ δὲ τὸ ἐν τῷ ναῷ σαφῶς μὲν οὐκ ἦν ἰδεῖν ὑπὸ στεφανωμάτων, χαλκοῦν δὲ καὶ τοῦτο εἶναι λέγουσι. ῥεῖ δὲ καὶ ὕδωρ ἐκ πηγῆς ἱερᾶς πιεῖν ἡδύ· Σελήνης δὲ ἐπίκλησις καὶ οὐ Θαλαμάταις ἐπιχώριος δαίμων ἐστὶν ἡ Πασιφάη.", "st": "3.26"}, {"sp": "N", "t": "Θαλαμῶν δὲ ἀπέχει σταδίους εἴκοσιν ὀνομαζομένη Πέφνος ἐπὶ θαλάσσῃ. πρόκειται δὲ νησὶς πέτρας τῶν μεγάλων οὐ μείζων, Πέφνος καὶ ταύτῃ τὸ ὄνομα· τεχθῆναι δὲ ἐνταῦθα τοὺς Διοσκούρους φασὶν οἱ Θαλαμᾶται. τοῦτο μὲν δὴ καὶ Ἀλκμᾶνα ἐν ᾄσματι οἶδα εἰπόντα· τραφῆναι δὲ οὐκέτι ἐν τῇ Πέφνῳ φασὶν αὐτούς, ἀλλὰ Ἑρμῆν τὸν ἐς Πελλάναν κομίσαντα εἶναι.", "st": "3.26"}, {"sp": "N", "t": "ἐν ταύτῃ τῇ νησῖδι ἀγάλματα Διοσκούρων χαλκᾶ μέγεθος ποδιαῖα ἐν ὑπαίθρῳ τῆς νησῖδός ἐστιν· ταῦτα ἡ θάλασσα ἀποκινεῖν οὐκ ἐθέλει κατακλύζουσα ὥρᾳ χειμῶνος τὴν πέτραν. τοῦτό τε δὴ θαῦμά ἐστι καὶ οἱ μύρμηκες αὐτόθι λευκότερον ἢ ὡς μυρμήκων τὸ χρῶμα φαίνουσι. τὴν δὲ χώραν οἱ Μεσσήνιοι ταύτην αὑτῶν φασιν εἶναι τὸ ἀρχαῖον, ὥστε καὶ τοὺς Διοσκούρους μᾶλλόν τι αὑτοῖς καὶ οὐ Λακεδαιμονίοις προσήκειν νομίζουσιν.", "st": "3.26"}, {"sp": "N", "t": "Πέφνου δὲ στάδια εἴκοσιν ἀπέχει Λεῦκτρα. ἐφ’ ὅτῳ μὲν δή ἐστιν ὄνομα τῇ πόλει Λεῦκτρα, οὐκ οἶδα· εἰ δ’ ἄρα ἀπὸ Λευκίππου τοῦ Περιήρους, ὡς οἱ Μεσσήνιοί φασι, τούτου μοι δοκοῦσιν ἕνεκα οἱ ταύτῃ θεῶν μάλιστα Ἀσκληπιὸν τιμᾶν, ἅτε Ἀρσινόης παῖδα εἶναι τῆς Λευκίππου νομίζοντες. λίθου δέ ἐστιν Ἀσκληπιοῦ τε ἄγαλμα καὶ Ἰνοῦς ἑτέρωθι.", "st": "3.26"}, {"sp": "N", "t": "πεποίηται δὲ καὶ Κασσάνδρας τῆς Πριάμου ναὸς καὶ ἄγαλμα, Ἀλεξάνδρας ὑπὸ τῶν ἐγχωρίων καλουμένης· καὶ Ἀπόλλωνος Καρνείου ξόανά ἐστι κατὰ ταὐτὰ καθὰ δὴ καὶ Λακεδαιμονίων νομίζουσιν οἱ Σπάρτην ἔχοντες. ἐπὶ δὲ τῆς ἀκροπόλεώς ἐστιν ἱερὸν καὶ ἄγαλμα Ἀθηνᾶς, καὶ Ἔρωτός ἐστιν ἐν Λεύκτροις ναὸς καὶ ἄλσος· ὕδωρ δὲ ὥρᾳ χειμῶνος διαρρεῖ τὸ ἄλσος, τὰ δὲ φύλλα τῷ ἦρι ἀπὸ τῶν δένδρων πίπτοντα οὐκ ἂν ὑπὸ τοῦ ὕδατος οὐδὲ πλεονάσαντος παρενεχθείη.", "st": "3.26"}, {"sp": "N", "t": "ὃ δὲ οἶδα ἐν τῇ πρὸς θαλάσσῃ χώρᾳ τῆς Λευκτρικῆς ἐπ’ ἐμοῦ συμβάν, γράφω. ἄνεμος πῦρ ἐς ὕλην ἐνεγκὼν τὰ πολλὰ ἠφάνισε τῶν δένδρων· ὡς δὲ ἀνεφάνη τὸ χωρίον ψιλόν, ἄγαλμα ἐνταῦθα ἱδρυμένον εὑρέθη Διὸς Ἰθωμάτα. τοῦτο οἱ Μεσσήνιοί φασι μαρτύριον εἶναί σφισι τὰ Λεῦκτρα τὸ ἀρχαῖον τῆς Μεσσηνίας εἶναι· δύναιτο δ’ ἂν καὶ Λακεδαιμονίων τὰ Λεῦκτρα ἐξ ἀρχῆς οἰκούντων ὁ Ἰθωμάτας Ζεὺς παρ’ αὐτοῖς ἔχειν τιμάς.", "st": "3.26"}, {"sp": "N", "t": "Καρδαμύλη δέ, ἧς καὶ Ὅμηρος μνήμην ἐποιήσατο ἐν Ἀγαμέμνονος ὑποσχέσεσι δώρων, Λακεδαιμονίων ἐστὶν ὑπήκοος τῶν ἐν Σπάρτῃ, βασιλέως Αὐγούστου τῆς Μεσσηνίας ἀποτεμομένου. ἀπέχει δὲ Καρδαμύλη θαλάσσης μὲν ὀκτὼ σταδίους, Λεύκτρων δὲ καὶ ἑξήκοντα. ἐνταῦθα οὐ πόρρω τοῦ αἰγιαλοῦ τέμενος ἱερὸν τῶν Νηρέως θυγατέρων ἐστίν· ἐς γὰρ τοῦτο ἀναβῆναι τὸ χωρίον φασὶν ἐκ τῆς θαλάσσης αὐτὰς Πύρρον ὀψομένας τὸν Ἀχιλλέως, ὅτε ἐς Σπάρτην ἐπὶ τὸν Ἑρμιόνης ἀπῄει γάμον. ἐν δὲ τῷ πολίσματι Ἀθηνᾶς τε ἱερὸν καὶ Ἀπόλλων ἐστὶ Κάρνειος, καθὰ Δωριεῦσιν ἐπιχώριον.", "st": "3.26"}, {"sp": "N", "t": "πόλιν δὲ ὀνομαζομένην ἐν τοῖς ἔπεσιν Ἐνόπην τοῖς Ὁμήρου, Μεσσηνίους ὄντας, ἐς δὲ τὸ συνέδριον συντελοῦντας τὸ Ἐλευθερολακώνων, καλοῦσιν ἐφ’ ἡμῶν Γερηνίαν. ἐν ταύτῃ τῇ πόλει Νέστορα οἱ μὲν τραφῆναι λέγουσιν, οἱ δὲ ἐς τοῦτο ἐλθεῖν φεύγοντα τὸ χωρίον, ἡνίκα Πύλος ἡλίσκετο ὑπὸ Ἡρακλέους.", "st": "3.26"}, {"sp": "N", "t": "ἐνταῦθα ἐν τῇ Γερηνίᾳ Μαχάονος τοῦ Ἀσκληπιοῦ μνῆμα καὶ ἱερόν ἐστιν ἅγιον, καὶ ἀνθρώποις νόσων ἰάματα παρὰ τῷ Μαχάονι ἔστιν εὑρέσθαι. καὶ Ῥόδον μὲν τὸ χωρίον τὸ ἱερὸν ὀνομάζουσιν, ἄγαλμα δὲ τοῦ Μαχάονος χαλκοῦν ἐστιν ὀρθόν· ἐπίκειται δέ οἱ τῇ κεφαλῇ στέφανος, ὃν οἱ Μεσσήνιοι κίφος καλοῦσι τῇ ἐπιχωρίῳ φωνῇ. Μαχάονα δὲ ὑπὸ Εὐρυπύλου τοῦ Τηλέφου τελευτῆσαί φησιν ὁ τὰ ἔπη ποιήσας τὴν μικρὰν Ἰλιάδα.", "st": "3.26"}, {"sp": "N", "t": "διὸ καὶ τάδε αὐτὸς οἶδα περὶ τὸ Ἀσκληπιεῖον τὸ ἐν Περγάμῳ γινόμενα· ἄρχονται μὲν ἀπὸ Τηλέφου τῶν ὕμνων, προσᾴδουσι δὲ οὐδὲν ἐς τὸν Εὐρύπυλον, οὐδὲ ἀρχὴν ἐν τῷ ναῷ θέλουσιν ὀνομάζειν αὐτόν, οἷα ἐπιστάμενοι φονέα ὄντα Μαχάονος. ἀνασώσασθαι δὲ Νέστορα λέγεται τοῦ Μαχάονος τὰ ὀστᾶ· Ποδαλείριον δέ, ὡς ὀπίσω πορθήσαντες Ἴλιον ἐκομίζοντο, ἁμαρτεῖν τοῦ πλοῦ καὶ ἐς Σύρνον τῆς Καρικῆς ἠπείρου φασὶν ἀποσωθέντα οἰκῆσαι.", "st": "3.26"}, {"sp": "N", "t": "τῆς δὲ χώρας τῆς Γερηνίας ὄρος Καλάθιόν ἐστιν· ἐν αὐτῷ Κλαίας ἱερὸν καὶ σπήλαιον παρ’ αὐτὸ τὸ ἱερόν, ἔσοδον μὲν στενήν, τὰ δὲ ἔνδον παρεχόμενον θέας ἄξια. Γερηνίας δὲ ὡς ἐς μεσόγαιαν ἄνω τριάκοντα ἀπέχει σταδίους Ἀλαγονία, καὶ τὸ πόλισμα κατηρίθμησα ἤδη καὶ τοῦτο ἐν Ἐλευθερολάκωσι· θέας δὲ αὐτόθι ἄξια Διονύσου καὶ Ἀρτέμιδός ἐστιν ἱερά.", "st": "3.26"}, {"sp": "HDR", "t": "Βιβλίον Δʹ — Μεσσηνιακά", "st": "4"}, {"sp": "N", "t": "Μεσσηνίοις δὲ πρὸς τὴν σφετέραν τὴν ἀπονεμηθεῖσαν ὑπὸ τοῦ βασιλέως ἐς τὸ Λακωνικὸν ὅροι κατὰ τὴν Γερηνίαν εἰσὶν ἐφ’ ἡμῶν ⟨ἡ⟩ ὀνομαζομένη Χοίριος νάπη. ταύτην τὴν χώραν ἔρημον οὖσαν οὕτω σχεῖν τοὺς πρώτους λέγουσιν οἰκήτορας· ἀποθανόντος Λέλεγος, ὃς ἐβασίλευεν ἐν τῇ νῦν Λακωνικῇ, τότε δὲ ἀπ’ ἐκείνου Λελεγίᾳ καλουμένῃ, Μύλης μὲν πρεσβύτερος ὢν τῶν παίδων ἔσχε τὴν ἀρχήν, Πολυκάων δὲ νεώτερός τε ἦν ἡλικίᾳ καὶ δι’ αὐτὸ ἰδιώτης, ἐς ὃ Μεσσήνην τὴν Τριόπα τοῦ Φόρβαντος ἔλαβε γυναῖκα ἐξ Ἄργους.", "st": "4.1"}, {"sp": "N", "t": "φρονοῦσα δὲ ἡ Μεσσήνη διὰ τὸν πατέρα, ἀξιώματι καὶ δυνάμει τῶν τότε προέχοντα Ἑλλήνων, οὐκ ἠξίου τὸν ἄνδρα ἰδιωτεύειν. ἀθροίσαντες δὲ ἔκ τε Ἄργους δύναμιν καὶ ἐκ Λακεδαίμονος ἀφίκοντο ἐς ταύτην τὴν χώραν, καὶ συμπάσῃ μὲν ἐτέθη τῇ γῇ Μεσσήνη τὸ ὄνομα ἀπὸ τῆς Πολυκάονος γυναικός, πόλεις δὲ ἄλλαι τε ἐκτίσθησαν καὶ—ἔνθα τὰ βασίλεια κατεσκευάσθη σφίσιν—Ἀνδανία.", "st": "4.1"}, {"sp": "N", "t": "πρὸ δὲ τῆς μάχης, ἣν Θηβαῖοι πρὸς Λακεδαιμονίους ἐμαχέσαντο ἐν Λεύκτροις, καὶ τοῦ οἰκισμοῦ Μεσσήνης τῆς ἐφ’ ἡμῶν ὑπὸ τῇ Ἰθώμῃ, πόλιν οὐδεμίαν πω κληθῆναι πρότερον δοκῶ Μεσσήνην· εἰκάζω δὲ οὐχ ἥκιστα Ὁμήρου τοῖς ἔπεσιν. ἐν μὲν γὰρ καταλόγῳ τῶν ἐς Ἴλιον ἀφικομένων Πύλον καὶ Ἀρήνην καὶ ἄλλας καταλέγων οὐδεμίαν πόλιν Μεσσήνην ἐκάλεσεν· ἐν Ὀδυσσείᾳ δὲ δηλοῖ μὲν καὶ ἐν τῷδε ἔθνος καὶ οὐ πόλιν τοὺς Μεσσηνίους ὄντας,<br>μῆλα γὰρ ἐξ Ἰθάκης Μεσσήνιοι ἄνδρες ἄειραν,", "st": "4.1"}, {"sp": "N", "t": "σαφέστερον δὲ ἔτι περὶ τοῦ τόξου λέγων τοῦ Ἰφίτου<br>τὼ δ’ ἐν Μεσσήνῃ ξυμβλήτην ἀλλήλοιιν<br>οἴκῳ ἐν Ὀρτιλόχοιο.<br>τοῦ γὰρ Ὀρτιλόχου τὸν οἶκον ἐν τῇ Μεσσήνῃ πόλισμα εἴρηκε τὰς Φηράς, καὶ τόδε ἐξηγήσατο αὐτὸς ἐν Πεισιστράτου παρὰ Μενέλαον ἀποδημίᾳ·<br>ἐς Φηρὰς δ’ ἵκοντο Διοκλῆος ποτὶ δῶμα,<br>υἱέος Ὀρτιλόχοιο.", "st": "4.1"}, {"sp": "N", "t": "πρῶτοι δ’ οὖν βασιλεύουσιν ἐν τῇ χώρᾳ ταύτῃ Πολυκάων τε ὁ Λέλεγος καὶ Μεσσήνη γυνὴ τοῦ Πολυκάονος. παρὰ ταύτην τὴν Μεσσήνην τὰ ὄργια κομίζων τῶν Μεγάλων θεῶν Καύκων ἦλθεν ἐξ Ἐλευσῖνος ὁ Κελαινοῦ τοῦ Φλύου. Φλῦον δὲ αὐτὸν Ἀθηναῖοι λέγουσι παῖδα εἶναι Γῆς· ὁμολογεῖ δέ σφισι καὶ ὕμνος Μουσαίου Λυκομίδαις ποιηθεὶς ἐς Δήμητρα.", "st": "4.1"}, {"sp": "N", "t": "τὴν δὲ τελετὴν τῶν Μεγάλων θεῶν Λύκος ὁ Πανδίονος πολλοῖς ἔτεσιν ὕστερον Καύκωνος προήγαγεν ἐς πλέον τιμῆς· καὶ Λύκου δρυμὸν ἔτι ὀνομάζουσιν ἔνθα ἐκάθηρε τοὺς μύστας. καὶ ὅτι μὲν δρυμός ἐστιν ἐν τῇ γῇ ταύτῃ Λύκου καλούμενος, Ῥιανῷ τῷ Κρητί ἐστι πεποιημένον<br>πάρ τε τρηχὺν Ἐλαιὸν ὑπὲρ δρυμόν τε Λύκοιο·", "st": "4.1"}, {"sp": "N", "t": "ὡς δὲ ὁ Πανδίονος οὗτος ἦν Λύκος, δηλοῖ τὰ ἐπὶ τῇ εἰκόνι ἔπη τῇ Μεθάπου. μετεκόσμησε γὰρ καὶ Μέθαπος τῆς τελετῆς ἔστιν ἅ· ὁ δὲ Μέθαπος γένος μὲν ἦν Ἀθηναῖος, τελεστὴς δὲ καὶ ὀργίων [καὶ] παντοίων συνθέτης. οὗτος καὶ Θηβαίοις τῶν Καβείρων τὴν τελετὴν κατεστήσατο, ἀνέθηκε δὲ καὶ ἐς τὸ κλίσιον τὸ Λυκομιδῶν εἰκόνα ἔχουσαν ἐπίγραμμα ἄλλα τε λέγον καὶ ὅσα ἡμῖν ἐς πίστιν συντελεῖ τοῦ λόγου·", "st": "4.1"}, {"sp": "N", "t": "ἥγνισα δ’ Ἑρμείαο δόμους ⟨σεμνῆς⟩ τε κέλευθα<br>Δάματρος καὶ πρωτογόνου Κούρας, ὅθι φασὶ<br>Μεσσήνην θεῖναι Μεγάλαισι θεαῖσιν ἀγῶνα<br>Φλυάδεω κλεινοῖο γόνου Καυκωνιάδαο.<br>θαύμασα δ’ ὡς σύμπαντα Λύκος Πανδιόνιος φὼς<br>Ἀτθίδος ἱερὰ ἔργα παρ’ Ἀνδανίῃ θέτο κεδνῇ.", "st": "4.1"}, {"sp": "N", "t": "τοῦτο τὸ ἐπίγραμμα δηλοῖ μὲν ὡς παρὰ τὴν Μεσσήνην ἀφίκοιτο ὁ Καύκων ἀπόγονος ὢν Φλύου, δηλοῖ δὲ καὶ τὰ ἐς τὸν Λύκον ⟨τά⟩ τε ἄλλα καὶ ὡς ἡ τελετὴ τὸ ἀρχαῖον ἦν ἐν Ἀνδανίᾳ. καί μοι καὶ τοῦτο εἰκὸς ἐφαίνετο, τὴν Μεσσήνην μὴ ἑτέρωθι, ἀλλὰ ἔνθα αὐτή τε καὶ Πολυκάων ᾤκουν, καταστήσασθαι τὴν τελετήν.", "st": "4.1"}, {"sp": "N", "t": "πυθέσθαι δὲ σπουδῇ πάνυ ἐθελήσας, οἵ τινες παῖδες Πολυκάονι ἐγένοντο ἐκ Μεσσήνης, ἐπελεξάμην τάς τε Ἠοίας καλουμένας καὶ τὰ ἔπη τὰ Ναυπάκτια, πρὸς δὲ αὐτοῖς ὁπόσα Κιναίθων καὶ Ἄσιος ἐγενεαλόγησαν. οὐ μὴν ἔς γε ταῦτα ἦν σφισιν οὐδὲν πεποιημένον, ἀλλὰ Ὕλλου μὲν τοῦ Ἡρακλέους θυγατρὶ Εὐαίχμῃ συνοικῆσαι Πολυκάονα υἱὸν Βούτου λεγούσας τὰς μεγάλας οἶδα Ἠοίας, τὰ δὲ ἐς τὸν Μεσσήνης ἄνδρα καὶ τὰ ἐς αὐτὴν Μεσσήνην παρεῖταί σφισι.", "st": "4.2"}, {"sp": "N", "t": "χρόνῳ δὲ ὕστερον, ὡς ἦν τῶν Πολυκάονος οὐδεὶς ἔτι ἀπογόνων, ἐς γενεὰς πέντε ἐμοὶ δοκεῖν προελθόντων καὶ οὐ πλέονας, Περιήρην τὸν Αἰόλου βασιλέα ἐπάγονται. παρὰ τοῦτον ἀφίκετο, ὡς οἱ Μεσσήνιοί φασι, Μελανεύς, τοξεύειν ἀνὴρ ἀγαθὸς καὶ διὰ τοῦτο Ἀπόλλωνος εἶναι νομιζόμενος· καί οἱ τῆς χώρας τὸ Καρνάσιον, τότε δὲ Οἰχαλίαν κληθεῖσαν, ἀπένειμεν ὁ Περιήρης ἐνοικῆσαι· γενέσθαι δὲ ὄνομα Οἰχαλίαν τῇ πόλει φασὶν ἀπὸ τοῦ Μελανέως τῆς γυναικός.", "st": "4.2"}, {"sp": "N", "t": "Θεσσαλοὶ δὲ καὶ Εὐβοεῖς, ἥκει γὰρ δὴ ἐς ἀμφισβήτησιν τῶν ἐν τῇ Ἑλλάδι ⟨τὰ⟩ πλείω, λέγουσιν οἱ μὲν ὡς τὸ Εὐρύτιον—χωρίον δὲ ἔρημον ἐφ’ ἡμῶν ἐστι τὸ Εὐρύτιον—πόλις τὸ ἀρχαῖον ἦν καὶ ἐκαλεῖτο Οἰχαλία, τῷ δὲ Εὐβοέων λόγῳ Κρεώφυλος ἐν Ἡρακλείᾳ πεποίηκεν ὁμολογοῦντα· Ἑκαταῖος δὲ ὁ Μιλήσιος ἐν Σκίῳ μοίρᾳ τῆς Ἐρετρικῆς ἔγραψεν εἶναι Οἰχαλίαν. ἀλλὰ γὰρ οἱ Μεσσήνιοι τά τε ἄλλα δοκοῦσί μοι μᾶλλον εἰκότα ἐκείνων λέγειν καὶ οὐχ ἥκιστα τῶν ὀστῶν ἕνεκα τῶν Εὐρύτου, ἃ δὴ καὶ ἐν τοῖς ἔπειτά που ⟨ὁ⟩ λόγος ἐπέξεισί μοι.", "st": "4.2"}, {"sp": "N", "t": "Περιήρει δὲ ἐγεγόνεσαν ἐκ Γοργοφόνης τῆς Περσέως Ἀφαρεὺς καὶ Λεύκιππος, καὶ ὡς ἀπέθανε Περιήρης, ἔσχον οὗτοι τὴν Μεσσηνίων ἀρχήν· κυριώτερος δὲ ἔτι Ἀφαρεὺς ἦν. οὗτος βασιλεύσας πόλιν ᾤκισεν Ἀρήνην ἀπὸ τῆς Οἰβάλου θυγατρός, αὑτοῦ δὲ γυναικὸς τῆς αὐτῆς καὶ ἀδελφῆς ὁμομητρίας· καὶ γὰρ Οἰβάλῳ συνῴκησε Γοργοφόνη, καί μοι δὶς ἤδη τὰ ἐς αὐτὴν ὁ λόγος ἔν τε τῇ Ἀργολίδι ἐδήλωσε καὶ ἐν τῇ Λακωνικῇ συγγραφῇ.", "st": "4.2"}, {"sp": "N", "t": "ὁ δ’ οὖν Ἀφαρεὺς πόλιν τε ἔκτισεν ἐν τῇ Μεσσηνίᾳ τὴν Ἀρήνην καὶ Νηλέα τὸν Κρηθέως τοῦ Αἰόλου, Ποσειδῶνος δὲ ἐπίκλησιν, ἀνεψιὸν ὄντα αὐτῷ, φεύγοντα ἐξ Ἰωλκοῦ Πελίαν ἐδέξατο οἴκῳ καὶ τῆς γῆς οἱ ἔδωκε τὰ ἐπὶ θαλάσσῃ, ἐν οἷς ἄλλαι τε ἦσαν πόλεις καὶ ἡ Πύλος, ἔνθα καὶ ᾤκησε καὶ τὸ βασίλειον κατεστήσατο ὁ Νηλεύς.", "st": "4.2"}, {"sp": "N", "t": "ἀφίκετο δὲ ἐς τὴν Ἀρήνην καὶ Λύκος ὁ Πανδίονος, ὅτε καὶ αὐτὸς τὸν ἀδελφὸν Αἰγέα ἐξ Ἀθηνῶν ἔφευγε· καὶ τὰ ὄργια ἐπέδειξε τῶν Μεγάλων θεῶν Ἀφαρεῖ καὶ τοῖς παισὶ καὶ τῇ γυναικὶ Ἀρήνῃ· ταῦτα δέ σφισιν ἐπεδείκνυτο ἀγαγὼν ἐς τὴν Ἀνδανίαν, ὅτι καὶ τὴν Μεσσήνην ὁ Καύκων ἐμύησεν ἐνταῦθα.", "st": "4.2"}, {"sp": "N", "t": "Ἀφαρεῖ δὲ τῶν παίδων πρεσβύτερος μὲν καὶ ἀνδρειότερος Ἴδας, νεώτερος δὲ ἦν Λυγκεύς, ὃν ἔφη Πίνδαρος—ὅτῳ πιστὰ—οὕτως ὀξὺ ὁρᾶν ὡς καὶ διὰ στελέχους θεᾶσθαι δρυός. Λυγκέως μὲν δὴ παῖδα οὐκ ἴσμεν γενόμενον, Ἴδα δὲ Κλεοπάτραν θυγατέρα ἐκ Μαρπήσσης, ἣ Μελεάγρῳ συνῴκησεν. ὁ δὲ τὰ ἔπη ποιήσας τὰ Κύπρια Πρωτεσιλάου φησίν, ὃς ὅτε κατὰ τὴν Τρῳάδα ἔσχον Ἕλληνες ἀποβῆναι πρῶτος ἐτόλμησε, Πρωτεσιλάου τούτου τὴν γυναῖκα Πολυδώραν μὲν τὸ ὄνομα, θυγατέρα δὲ Μελεάγρου φησὶν εἶναι τοῦ Οἰνέως. εἰ τοίνυν ἐστὶν ἀληθές, αἱ γυναῖκες αὗται τρεῖς οὖσαι τὸν ἀριθμὸν ἀπὸ Μαρπήσσης ἀρξάμεναι προαποθανοῦσι πᾶσαι τοῖς ἀνδράσιν ἑαυτὰς ἐπικατέσφαξαν.", "st": "4.2"}, {"sp": "N", "t": "ἐπεὶ δὲ τοῖς Ἀφαρέως παισὶ πρὸς τοὺς Διοσκούρους ἐγένετο ἀνεψιοὺς ὄντας μάχη περὶ τῶν βοῶν καὶ τὸν μὲν Πολυδεύκης ἀπέκτεινεν, Ἴδαν δὲ ἐπέλαβε τὸ χρεὼν κεραυνωθέντα, ὁ μὲν Ἀφαρέως οἶκος γένους παντὸς ἠρήμωτο τοῦ ἄρρενος, ἐς δὲ Νέστορα τὸν [τοῦ] Νηλέως περιῆλθε Μεσσηνίων ἡ ἀρχὴ τῶν τε ἄλλων καὶ ὅσων πρότερον ἐβασίλευεν Ἴδας, πλὴν ὅσοι τοῖς Ἀσκληπιοῦ παισὶν αὐτῶν ὑπήκουον.", "st": "4.3"}, {"sp": "N", "t": "καὶ γὰρ τοὺς Ἀσκληπιοῦ παῖδας στρατεῦσαί φασιν ἐπ’ Ἴλιον Μεσσηνίους ὄντας, Ἀρσινόης γὰρ Ἀσκληπιὸν τῆς Λευκίππου καὶ οὐ Κορωνίδος παῖδα εἶναι· καὶ Τρίκκαν τε καλοῦσιν ἔρημον ἐν τῇ Μεσσηνίᾳ χωρίον καὶ ἔπη τῶν Ὁμήρου καταλέγουσιν, ἐν οἷς τὸν Μαχάονα ὁ Νέστωρ τῷ ὀιστῷ βεβλημένον περιέπων ἐστὶν εὐνοϊκῶς· οὐκ ἂν οὖν αὐτὸν ⟨εἰ⟩ μὴ ἐς γείτονα καὶ ἀνθρώπων βασιλέα ὁμοφύλων προθυμίαν τοσήνδε γε ἐπιδείξασθαι. οἳ δὲ καὶ μάλιστα ἤδη βεβαιοῦνται τὸν ἐς τοὺς Ἀσκληπιάδας λόγον, ἀποφαίνοντες ἐν Γερηνίᾳ Μαχάονος μνῆμα καὶ τὸ ἐν Φαραῖς τῶν Μαχάονος παίδων ἱερόν.", "st": "4.3"}, {"sp": "N", "t": "διαπολεμηθέντος δὲ τοῦ πρὸς Ἴλιον πολέμου καὶ Νέστορος ὡς ἐπανῆλθεν οἴκαδε τελευτήσαντος, Δωριέων στόλος καὶ ἡ κάθοδος Ἡρακλειδῶν γενομένη δύο γενεαῖς ὕστερον ἐξέβαλε τοὺς Νηλέως ἀπογόνους ἐκ τῆς Μεσσηνίας. καί μοι ταῦτα ἐγένετο ἤδη τῷ λόγῳ προσθήκη τῷ ἐς Τισαμενόν· πλὴν τοσόνδε ἔτι δηλώσω. Τημένῳ τῶν Δωριέων Ἄργος ἐφέντων ἔχειν, Κρεσφόντης γῆν σφᾶς ᾔτει τὴν Μεσσηνίαν ἅτε καὶ αὐτὸς Ἀριστοδήμου πρεσβύτερος.", "st": "4.3"}, {"sp": "N", "t": "Ἀριστόδημος μὲν οὖν ἐτύγχανεν ἤδη τεθνεώς, Θήρας δὲ ὁ Αὐτεσίωνος τῷ Κρεσφόντῃ μάλιστα ἠναντιοῦτο, τὸ μὲν ἀνέκαθεν Θηβαῖός τε καὶ ἀπόγονος πέμπτος Πολυνείκους τοῦ Οἰδίποδος, τότε δὲ ἐπετρόπευεν Ἀριστοδήμου τοὺς παῖδας θεῖος ὢν πρὸς μητρός· Αὐτεσίωνος γὰρ θυγατέρα Ἀριστόδημος ἔγημεν ὄνομα Ἀργείαν. Κρεσφόντης δὲ— γενέσθαι γάρ οἱ ἤθελε τὴν Μεσσηνίαν πάντως μοῖραν— Τημένου δεῖται, παρεσκευασμένος ⟨δὲ⟩ τοῦτον τῷ κλήρῳ δῆθεν ἐφίησι.", "st": "4.3"}, {"sp": "N", "t": "Τήμενος δὲ ἐς ὑδρίαν, ἐνόντος ἐν αὐτῇ καὶ ὕδατος, καθίησι τῶν Ἀριστοδήμου παίδων καὶ Κρεσφόντου τοὺς πάλους ἐπὶ διῃρημένοις, μοῖραν ἀναιρεῖσθαι τῆς χώρας προτέρους ὁποτέρων ἂν πάλος ἀνέλθῃ πρότερον. τοὺς μὲν δὴ πάλους ⟨γῆς⟩ ὁ Τήμενος ἐπεποίητο ἀμφοτέρους, ἀλλὰ τοῖς μὲν Ἀριστοδήμου παισὶ ξηρᾶς ὑπὸ ἡλίου, Κρεσφόντῃ δὲ ὀπτῆς πυρί· ὅ τε δὴ τῶν Ἀριστοδήμου παίδων πάλος κατετέτηκτο καὶ ὁ Κρεσφόντης οὕτω λαχὼν γῆν αἱρεῖται τὴν Μεσσηνίαν.", "st": "4.3"}, {"sp": "N", "t": "Μεσσηνίων δὲ τῶν ἀρχαίων οὐκ ἐγένετο ὑπὸ τῶν Δωριέων ὁ δῆμος ἀνάστατος, ἀλλὰ βασιλεύεσθαί τε συγχωροῦσιν ὑπὸ Κρεσφόντου καὶ ἀναδάσασθαι πρὸς τοὺς Δωριέας τὴν γῆν· ταῦτα δέ σφισιν εἴκειν παρίστατο ὑποψίᾳ πρὸς τοὺς βασιλεύοντας, ὅτι ἦσαν ἐξ Ἰωλκοῦ τὸ ἀνέκαθεν οἱ Νηλεῖδαι. γυναῖκα δὲ ἔσχε Κρεσφόντης Μερόπην τὴν Κυψέλου, βασιλεύοντος τότε Ἀρκάδων, ἀφ’ ἧς ἄλλοι τε δὴ παῖδες ἐγένοντο αὐτῷ καὶ νεώτατος Αἴπυτος·", "st": "4.3"}, {"sp": "N", "t": "τὰ δὲ βασίλεια, ἔνθα αὐτὸς καὶ οἱ παῖδες ἔμελλον οἰκήσειν, ᾠκοδομήσατο ἐν Στενυκλήρῳ. τὸ μὲν γὰρ ἀρχαῖον οἱ βασιλεῖς οἵ τε ἄλλοι καὶ ὁ Περιήρης ᾤκουν ἐν Ἀνδανίᾳ, κτίσαντος δὲ Ἀφαρέως Ἀρήνην αὖθις Ἀφαρεὺς καὶ οἱ παῖδες ἐνταῦθα ᾤκησαν· ἐπὶ δὲ Νέστορος καὶ τῶν ἀπογόνων ἐν Πύλῳ τὰ βασίλεια ἦν· Κρεσφόντης δὲ ἐν Στενυκλήρῳ τὸν βασιλέα οἰκεῖν κατεστήσατο. διοικούμενον δὲ αὐτὸν τὰ πολλὰ ἐς χάριν τοῦ δήμου μᾶλλον οἱ τὰ χρήματα ἔχοντες αὐτόν τε Κρεσφόντην ἐπαναστάντες καὶ τοὺς υἱοὺς ἀποκτείνουσι τοὺς λοιπούς, ὁ δὲ Αἴπυτος—παῖδα", "st": "4.3"}, {"sp": "N", "t": "γὰρ ἔτι ὄντα ἔτρεφεν αὐτὸν ὁ Κύψελος— περιγίνεται μόνος τοῦ οἴκου, καὶ ὡς ἀνὴρ ἐγένετο, οἱ Ἀρκάδες κατάγουσιν αὐτὸν ἐς Μεσσήνην· συγκατήγαγον δὲ καὶ οἱ λοιποὶ βασιλεῖς τῶν Δωριέων, οἵ τε Ἀριστοδήμου παῖδες καὶ Ἴσθμιος ὁ Τημένου. Αἴπυτος δὲ ὡς ἐβασίλευσεν, ἐτιμωρήσατο μὲν τοῦ πατρὸς τοὺς φονέας, ἐτιμωρήσατο δὲ καὶ ὅσοι τοῦ φόνου παραίτιοι καθεστήκεσαν· προσαγόμενος δὲ τοὺς μὲν ἐν τέλει τῶν Μεσσηνίων θεραπείαις, ὅσοι δὲ ἦσαν τοῦ δήμου, δωρεαῖς, ἐς τοσοῦτο προέβη τιμῆς ὡς καὶ τοὺς ἀπογόνους Αἰπυτίδας ἀντὶ Ἡρακλειδῶν κληθῆναι.", "st": "4.3"}, {"sp": "N", "t": "Γλαύκῳ δὲ τῷ Αἰπύτου βασιλεύσαντι μετὰ Αἴπυτον τὰ μὲν ἄλλα ἐξήρκεσε μιμήσασθαι τὸν πατέρα ἔν τε τοῖς κοινοῖς καὶ πρὸς τοὺς ἰδιώτας, εὐσεβείας δὲ ἐς πλέον προέβη. καὶ γὰρ τοῦ Διὸς τὸ ἐπὶ τῇ κορυφῇ τῆς Ἰθώμης τέμενος, ἀνέντων Πολυκάονος καὶ Μεσσήνης, οὐκ ἔχον παρὰ τοῖς Δωριεῦσι πω τιμάς, Γλαῦκος ἦν ὁ καὶ τούτοις σέβειν καταστησάμενος· καὶ Μαχάονι τῷ Ἀσκληπιοῦ πρῶτος ἔθυσεν ἐν Γερηνίᾳ, γέρα δὲ ἀπένειμε Μεσσήνῃ τῇ Τριόπα τὰ νομιζόμενα ἥρωσιν.", "st": "4.3"}, {"sp": "N", "t": "Ἴσθμιος δὲ ὁ Γλαύκου καὶ ἱερὸν τῷ Γοργάσῳ καὶ Νικομάχῳ τὸ ἐν Φαραῖς ἐποίησεν· Ἰσθμίου δὲ γίνεται Δωτάδας, ὃς ἐπίνεια καὶ ἄλλα τῆς Μεσσηνίας παρεχομένης τὸ ἐν Μοθώνῃ κατεσκευάσατο. Συβότας δὲ ὁ Δωτάδα τῷ τε ποταμῷ κατεστήσατο τῷ Παμίσῳ κατὰ ἔτος ἕκαστον θύειν τὸν βασιλεύοντα καὶ Εὐρύτῳ τῷ Μελανέως ἐναγίζειν ἐν Οἰχαλίᾳ πρὸ τῆς τελετῆς τῶν Μεγάλων θεῶν ἀγομένης ἔτι ἐν Ἀνδανίᾳ.", "st": "4.3"}, {"sp": "N", "t": "ἐπὶ δὲ Φίντα τοῦ Συβότα πρῶτον Μεσσήνιοι τότε τῷ Ἀπόλλωνι ἐς Δῆλον θυσίαν καὶ ἀνδρῶν χορὸν ἀποστέλλουσι· τὸ δέ σφισιν ᾆσμα προσόδιον ἐς τὸν θεὸν ἐδίδαξεν Εὔμηλος, εἶναί τε ὡς ἀληθῶς Εὐμήλου νομίζεται μόνα τὰ ἔπη ταῦτα. ἐγένετο δὲ καὶ πρὸς Λακεδαιμονίους ἐπὶ τῆς Φίντα βασιλείας διαφορὰ πρῶτον, ἀπὸ αἰτίας ἀμφισβητουμένης μὲν καὶ ταύτης, γενέσθαι δὲ οὕτω λεγομένης.", "st": "4.4"}, {"sp": "N", "t": "ἔστιν ἐπὶ τοῖς ὅροις τῆς Μεσσηνίας ἱερὸν Ἀρτέμιδος καλουμένης Λιμνάτιδος, μετεῖχον δὲ αὐτοῦ μόνοι Δωριέων οἵ τε Μεσσήνιοι καὶ οἱ Λακεδαιμόνιοι. Λακεδαιμόνιοι μὲν δή φασιν ὡς παρθένους αὑτῶν παραγενομένας ἐς τὴν ἑορτὴν αὐτάς τε βιάσαιντο ἄνδρες τῶν Μεσσηνίων καὶ τὸν βασιλέα σφῶν ἀποκτείναιεν πειρώμενον κωλύειν, Τήλεκλον Ἀρχελάου τοῦ Ἀγησιλάου τοῦ Δορύσσου τοῦ Λαβώτα τοῦ Ἐχεστράτου τοῦ Ἄγιδος, πρός τε δὴ τούτοις τὰς βιασθείσας τῶν παρθένων διεργάσασθαι λέγουσιν αὑτὰς ὑπὸ αἰσχύνης·", "st": "4.4"}, {"sp": "N", "t": "Μεσσήνιοι δὲ τοῖς ἐλθοῦσι σφῶν ἐς τὸ ἱερὸν πρωτεύουσιν ἐν Μεσσήνῃ κατὰ ἀξίωμα, τούτοις φασὶν ἐπιβουλεῦσαι Τήλεκλον, αἴτιον δὲ εἶναι τῆς χώρας τῆς Μεσσηνίας τὴν ἀρετήν, ἐπιβουλεύοντα δὲ ἐπιλέξαι Σπαρτιατῶν ὁπόσοι πω γένεια οὐκ εἶχον, τούτους δὲ ἐσθῆτι καὶ κόσμῳ τῷ λοιπῷ σκευάσαντα ὡς παρθένους ἀναπαυομένοις τοῖς Μεσσηνίοις ἐπεισαγαγεῖν, δόντα ἐγχειρίδια· καὶ τοὺς Μεσσηνίους ἀμυνομένους τούς τε ἀγενείους νεανίσκους καὶ αὐτὸν ἀποκτεῖναι Τήλεκλον, Λακεδαιμονίους δὲ—οὐ γὰρ ἄνευ τοῦ κοινοῦ ταῦτα βουλεῦσαι σφῶν τὸν βασιλέα—συνειδότας ὡς ἄρξαιεν ἀδικίας, τοῦ φόνου σφᾶς τοῦ Τηλέκλου δίκας οὐκ ἀπαιτῆσαι. ταῦτα μὲν ἑκάτεροι λέγουσι, πειθέσθω δὲ ὡς ἔχει τις ἐς τοὺς ἑτέρους σπουδῆς.", "st": "4.4"}, {"sp": "N", "t": "γενεᾷ δὲ ὕστερον βασιλεύοντος ἐν Λακεδαίμονι Ἀλκαμένους τοῦ Τηλέκλου, τῆς δὲ οἰκίας τῆς ἑτέρας Θεοπόμπου τοῦ Νικάνδρου τοῦ Χαρίλλου τοῦ Πολυδέκτου τοῦ Εὐνόμου τοῦ Πρυτάνιδος τοῦ Εὐρυπῶντος, Μεσσηνίων δὲ Ἀντιόχου καὶ Ἀνδροκλέους τῶν Φίντα, Λακεδαιμονίων καὶ Μεσσηνίων ἐξήρθη τὸ ἐς ἀλλήλους μῖσος· καὶ ἦρξαν οἱ Λακεδαιμόνιοι πολέμου, ἐπιγενομένης ἀφορμῆς σφισιν ἐθελέχθρως μὲν ἔχουσι καὶ πολεμῆσαι πάντως ἐγνωκόσιν οὐ μόνον ἀποχρώσης ἀλλὰ καὶ τὰ μάλιστα εὐπροσώπου, μετὰ δὲ εἰρηνικωτέρας γνώμης κἂν διελύθη δικαστηρίου γνώσει. τὰ δὲ συμβάντα ἔσχεν οὕτω.", "st": "4.4"}, {"sp": "N", "t": "Πολυχάρης Μεσσήνιος τά τε ἄλλα οὐκ ἀφανὴς καὶ νίκην Ὀλυμπίασιν ἀνῃρημένος —τετάρτην Ὀλυμπιάδα ἦγον Ἠλεῖοι καὶ ἀγώνισμα ἦν σταδίου μόνον, ὅτε ὁ Πολυχάρης ἐνίκησεν—, τούτῳ τῷ ἀνδρὶ ἐγένοντο βοῦς· καὶ—οὐ γὰρ ἐκέκτητο ἰδίαν γῆν ὡς νομὰς ταῖς βουσὶν ἱκανὰς εἶναι—Σπαρτιάτῃ σφᾶς δίδωσιν Εὐαίφνῳ βόσκεσθαί τε ἐν ἐκείνου καὶ μοῖραν εἶναι καὶ Εὐαίφνῳ τοῦ καρποῦ τῶν βοῶν.", "st": "4.4"}, {"sp": "N", "t": "ἦν δὲ ἄρα τοιόσδε τις ὁ Εὔαιφνος, κέρδη τε ἄδικα ἐπίπροσθεν ἢ πιστὸς εἶναι ποιούμενος καὶ ἄλλως αἱμύλος· ὃς καὶ τότε καταπλεύσασιν ἐς τὴν Λακωνικὴν ἐμπόροις ἀποδόμενος βοῦς τὰς Πολυχάρους ἦλθεν αὐτὸς ὡς Πολυχάρην ἄγγελος, ἐλθὼν δὲ ἀποβάντας ἔλεγεν ἐς τὴν χώραν λῃστὰς καὶ βιασαμένους αὐτὸν λείαν βοῦς τε ἄγεσθαι καὶ βουκόλους. ἕως δὲ οὗτος παρέπειθεν, ἐν τούτῳ τῶν τις βουκόλων ἀποδιδράσκει τοὺς ἐμπόρους, ἐπανήκων δὲ καταλαμβάνει τε αὐτοῦ παρὰ τῷ δεσπότῃ τὸν Εὔαιφνον καὶ Πολυχάρους ἐναντίον ἤλεγχεν.", "st": "4.4"}, {"sp": "N", "t": "ἁλισκόμενος δὲ καὶ οὐκ ἔχων ἀπαρνήσασθαι πολλὰ μὲν αὐτὸν Πολυχάρην, πολλὰ δὲ καὶ τοῦ Πολυχάρους τὸν παῖδα ἱκέτευε νεῖμαί οἱ συγγνώμην· ἐν γὰρ τῇ ἀνθρωπίνῃ φύσει καὶ ἄλλων ἐνόντων, ἐφ’ οἷς βιαζόμεθα ἄδικοι γίνεσθαι, τὰ κέρδη μεγίστην ἀνάγκην ἔχειν· τιμὴν δὲ ἥντινα εἰλήφει τῶν βοῶν, λόγῳ τε ἀπέφαινε καὶ τὸν παῖδα ἠξίου τὸν Πολυχάρους ἕπεσθαί οἱ κομιούμενον. ὡς δὲ προϊόντες ἐγίνοντο ἐν τῇ Λακωνικῇ, ἔργον ἐτόλμησεν Εὔαιφνος ἀνοσιώτερον τοῦ προτέρου·", "st": "4.4"}, {"sp": "N", "t": "φονεύει τοῦ Πολυχάρους τὸν υἱόν. ὁ δὲ ὡς καὶ ταῦτα ἔγνω πεπονθώς, φοιτῶν ἐς τὴν Λακεδαίμονα τοῖς βασιλεῦσιν ἦν καὶ τοῖς ἐφόροις δι’ ὄχλου, πολλὰ μὲν τὸν παῖδα ἀνακλαίων, καταριθμούμενος δὲ οἷα ὑπὸ Εὐαίφνου πεπονθὼς ἦν, ὃν αὐτὸς ξένον ἐποιήσατο καὶ πρὸ πάντων Λακεδαιμονίων ἐπίστευσεν. ὡς δέ οἱ συνεχῶς ἰόντι ἐπὶ τὰς ἀρχὰς οὐδεμία ἐγίνετο τιμωρία, ἐνταῦθα παρετράπη τε ὁ Πολυχάρης ἐκ τοῦ νοῦ καὶ τῷ θυμῷ χρώμενος, ἅτε ἔχων ἀφειδῶς ἤδη καὶ αὑτοῦ, πάντα τινὰ ὃν λάβοι Λακεδαιμονίων ἐτόλμα φονεύειν.", "st": "4.4"}, {"sp": "N", "t": "Λακεδαιμόνιοι μὲν δὴ Πολυχάρους τε ἕνεκα οὐκ ἐκδοθέντος σφίσι καὶ διὰ τὸν Τηλέκλου φόνον, καὶ πρότερον ἔτι ὑπόπτως ἔχοντες διὰ τὸ Κρεσφόντου κακούργημα ἐς τὸν κλῆρον, πολεμῆσαι λέγουσι· Μεσσήνιοι δὲ περὶ Τηλέκλου ἀντιλέγουσι τὰ εἰρημένα ἤδη μοι καὶ Αἴπυτον τὸν Κρεσφόντου συγκαταχθέντα ἀποφαίνουσιν ὑπὸ Ἀριστοδήμου τῶν παίδων, ὃ μήποτ’ ἂν ποιῆσαι σφᾶς Κρεσφόντῃ γε ὄντας διαφόρους.", "st": "4.5"}, {"sp": "N", "t": "Πολυχάρην δὲ ἐκδοῦναι μὲν ἐπὶ τιμωρίᾳ Λακεδαιμονίοις οὔ φασιν, ὅτι μηδὲ ἐκεῖνοι σφίσιν Εὔαιφνον, ἐθέλειν μέντοι παρὰ Ἀργείοις συγγενέσιν οὖσιν ἀμφοτέρων ἐν Ἀμφικτυονίᾳ διδόναι δίκας, ἐπιτρέπειν δὲ καὶ τῷ Ἀθήνῃσι δικαστηρίῳ, καλουμένῳ δὲ Ἀρείῳ πάγῳ, ὅτι δίκας τὰς φονικὰς τὸ δικαστήριον τοῦτο ἐδόκει δικάζειν ἐκ παλαιοῦ.", "st": "4.5"}, {"sp": "N", "t": "Λακεδαιμονίους δὲ οὐ διὰ ταῦτα πολεμῆσαί φασιν, ὑπὸ πλεονεξίας δὲ τῇ σφετέρᾳ τε ἐπιβουλεῦσαι καὶ ἄλλα ἐργάσασθαι, προφέροντες μέν σφισι τὰ Ἀρκάδων, προφέροντες δὲ καὶ τὰ Ἀργείων, ὡς οὔποτε ἐσχήκασι κόρον ἀποτεμνόμενοι τῆς χώρας αἰεί τι ἑκατέρων· Κροίσῳ τε αὐτοῖς δῶρα ἀποστείλαντι γενέσθαι φίλους βαρβάρῳ πρώτους, ἀφ’ οὗ γε τούς τε ἄλλους τοὺς ἐν τῇ Ἀσίᾳ κατεδουλώσατο Ἕλληνας καὶ ὅσοι Δωριεῖς ἐν τῇ Καρικῇ κατοικοῦσιν ἠπείρῳ.", "st": "4.5"}, {"sp": "N", "t": "ἀποφαίνουσι δὲ καὶ ἡνίκα οἱ Φωκέων δυνάσται τὸ ἱερὸν τὸ ἐν Δελφοῖς κατειλήφασιν, ἰδίᾳ τε κατὰ ἄνδρα τοὺς βασιλεύοντας ἐν Σπάρτῃ καὶ τῶν ἄλλων τοὺς ἐπ’ ἀξιώματος καὶ κοινῇ τῶν τε ἐφόρων τὴν ἀρχὴν καὶ τὴν γερουσίαν μετασχόντας τῶν τοῦ θεοῦ. πρό τε δὴ πάντων, ὡς οὐδὲν ἂν τοὺς Λακεδαιμονίους κέρδους ἕνεκα ὀκνήσαντας, τὴν συμμαχίαν ὀνειδίζουσί σφισι ⟨τὴν⟩ πρὸς Ἀπολλόδωρον τὸν ἐν Κασσανδρείᾳ τυραννήσαντα.", "st": "4.5"}, {"sp": "N", "t": "ἀνθ’ ὅτου δὲ Μεσσήνιοι τὸ ὄνειδος ἥγηνται τοῦτο οὕτω πικρόν, οὔ μοι τῷ λόγῳ τῷ παρόντι ἦν ἐπεισάγεσθαι· ὅτι γὰρ μὴ τῶν Μεσσηνίων τὸ εὔψυχον καὶ χρόνου μῆκος ὃν ἐπολέμησαν διάφορα ἐγένετο τῆς Ἀπολλοδώρου τυραννίδος, ἔς γε τὰς συμφορὰς οὐ πολλῷ τινι ἀποδέοι ⟨ἂν⟩ ἃ οἱ Κασσανδρεῖς πεπόνθασι.", "st": "4.5"}, {"sp": "N", "t": "ταῦτα μὲν δὴ αἴτια ἑκάτεροι τοῦ πολέμου γενέσθαι λέγουσι· τότε δὲ πρεσβεία Λακεδαιμονίων ἥκουσα ἐξῄτει Πολυχάρην. οἱ δὲ τῶν Μεσσηνίων βασιλεῖς τοῖς μὲν πρέσβεσιν ἀπεκρίναντο ὅτι βουλευσάμενοι μετὰ τοῦ δήμου τὰ δόξαντα ἐπιστελοῦσιν ἐς Σπάρτην, αὐτοὶ δὲ ἐκείνων ἀπελθόντων ἐς ἐκκλησίαν τοὺς πολίτας συνῆγον. αἱ δὲ γνῶμαι διάφοροι παρὰ πολὺ ἐγίνοντο, Ἀνδροκλέους μὲν ἐκδιδόναι Πολυχάρην ὡς ἀνόσιά τε καὶ πέρα δεινῶν εἰργασμένον· Ἀντίοχος δὲ ἄλλα τε ἀντέλεγε καὶ τὸ ἁπάντων οἴκτιστον, εἰ Πολυχάρης ἐν ὀφθαλμοῖς πείσεται τοῖς Εὐαίφνου, καταριθμούμενος ὅσα καὶ οἷα ἦν ἀνάγκη παθεῖν.", "st": "4.5"}, {"sp": "N", "t": "τέλος δὲ ἐς τοσοῦτο προήχθησαν οἵ τε Ἀνδροκλεῖ καὶ οἱ τῷ Ἀντιόχῳ συσπεύδοντες ὥστε καὶ τὰ ὅπλα ἔλαβον. οὐ μὴν ἐς μακράν γε προῆλθέ σφισιν ἡ μάχη· περιόντες γὰρ ἀριθμῷ καὶ πολὺ οἱ σὺν Ἀντιόχῳ τόν τε Ἀνδροκλέα καὶ τῶν περὶ αὐτὸν τοὺς λόγου μάλιστα ἀξίους ἀποκτείνουσιν. Ἀντίοχος δὲ βασιλεύων ἤδη μόνος ἔπεμπεν ἐς Σπάρτην ὡς ἐπιτρέπειν ἐθέλοι τοῖς δικαστηρίοις ἃ ἤδη λέλεκταί μοι· Λακεδαιμόνιοι δὲ οὐ λέγονται τοῖς κομίσασι τὰ γράμματα ἀποκρίνασθαι.", "st": "4.5"}, {"sp": "N", "t": "μησὶ δὲ οὐ πολλοῖς ὕστερον Ἀντιόχου τελευτήσαντος Εὐφαὴς ὁ Ἀντιόχου παρέλαβε τὴν ἀρχήν. Λακεδαιμόνιοι δὲ οὔτε κήρυκα ἀποστέλλουσι προεροῦντα Μεσσηνίοις πόλεμον οὔτε προαπειπάμενοι τὴν φιλίαν, κρύφα δὲ καὶ μάλιστα ὡς ἐδύναντο ἐν ἀπορρήτῳ παρασκευασάμενοι, προομνύουσιν ὅρκον μήτε τοῦ πολέμου μῆκος, ἢν μὴ δι’ ὀλίγου κριθῇ, μήτε τὰς συμφοράς, εἰ μεγάλαι πολεμοῦσι γένοιντο, ἀποστρέψειν σφᾶς πρὶν ἢ κτήσαιντο χώραν τὴν Μεσσηνίαν δοριάλωτον.", "st": "4.5"}, {"sp": "N", "t": "ταῦτα προομόσαντες ἔξοδον νύκτωρ ἐποιοῦντο ἐπὶ Ἄμφειαν, Ἀλκαμένην τὸν Τηλέκλου τῆς στρατιᾶς ἡγεμόνα ἀποδείξαντες. ἡ δὲ Ἄμφεια πρὸς τῇ Λακωνικῇ πόλισμα ἦν ἐν τῇ Μεσσηνίᾳ, μεγέθει μὲν οὐ μέγα, ἐπὶ λόφου δὲ ὑψηλοῦ κείμενον, καὶ ὑδάτων πηγὰς εἶχεν ἀφθόνους· ἐδόκει δὲ καὶ ἄλλως ἐς τὸν πάντα πόλεμον ὁρμητήριόν σφισιν ἐπιτήδειον ἡ Ἄμφεια εἶναι. καὶ τό τε πόλισμα αἱροῦσι πυλῶν ἀνεῳγμένων καὶ φυλακῆς οὐκ ἐνούσης καὶ τῶν Μεσσηνίων τοὺς ἐγκαταληφθέντας φονεύουσι, τοὺς μὲν ἔτι ἐν ταῖς εὐναῖς, τοὺς δὲ ὡς ᾔσθοντο πρός τε ἱερὰ θεῶν καὶ βωμοὺς καθημένους ἱκέτας· ὀλίγοι δὲ καὶ οἱ διαφυγόντες ἐγένοντο.", "st": "4.5"}, {"sp": "N", "t": "ταύτην Λακεδαιμόνιοι πρώτην ἐπὶ Μεσσηνίους ἔξοδον ἐποιήσαντο ἔτει δευτέρῳ τῆς ἐνάτης Ὀλυμπιάδος, ἣν Ξενοδόκος Μεσσήνιος ἐνίκα στάδιον· Ἀθήνῃσι δὲ οὐκ ἦσάν πω τότε οἱ τῷ κλήρῳ κατ’ ἐνιαυτὸν ἄρχοντες· τοὺς γὰρ ἀπὸ Μελάνθου, καλουμένους δὲ Μεδοντίδας, κατ’ ἀρχὰς μὲν ἀφείλοντο ὁ δῆμος τῆς ἐξουσίας τὸ πολὺ καὶ ἀντὶ βασιλείας μετέστησαν ἐς ἀρχὴν ὑπεύθυνον, ὕστερον δὲ καὶ προθεσμίαν ἐτῶν δέκα ἐποίησαν αὐτοῖς τῆς ἀρχῆς. τότε δὲ ὑπὸ τὴν κατάληψιν τῆς Ἀμφείας Αἰσιμίδης Ἀθηναίοις ἦρχεν ὁ Αἰσχύλου πέμπτον ἔτος.", "st": "4.5"}, {"sp": "N", "t": "πρὶν δὲ ἢ συγγράφειν με τὸν πόλεμον καὶ ὁπόσα πολεμοῦσιν ἑκατέροις ὁ δαίμων παθεῖν ἢ δρᾶσαι παρεσκεύασε, διακρῖναί τι καὶ ἡλικίας [ἔργα] πέρι ἠθέλησα ἀνδρὸς Μεσσηνίου. τὸν γὰρ πόλεμον τοῦτον γενόμενον μὲν Λακεδαιμονίων καὶ τῶν συμμάχων πρὸς Μεσσηνίους καὶ τοὺς ἐπικούρους, ὀνομασθέντα δὲ οὐκ ἀπὸ τῶν ἐπιστρατευσάντων ὥσπερ γε ὁ Μηδικὸς καὶ ὁ Πελοποννήσιος, Μεσσήνιον δὲ ἀπὸ τῶν συμφορῶν, καθὰ δὴ καὶ τὸν ἐπὶ Ἰλίῳ κληθῆναι Τρωικὸν καὶ οὐχ Ἑλληνικὸν ἐξενίκησεν, τοῦτον [γὰρ] τῶν Μεσσηνίων τὸν πόλεμον Ῥιανός τε ἐν τοῖς ἔπεσιν ἐποίησεν ὁ Βηναῖος καὶ ὁ Πριηνεὺς Μύρων· λόγοι δὲ πεζοὶ Μύρωνός ἐστιν ἡ συγγραφή.", "st": "4.6"}, {"sp": "N", "t": "συνεχῶς μὲν δὴ τὰ πάντα ἐξ ἀρχῆς ἐς τοῦ πολέμου τὴν τελευτὴν οὐδετέρῳ διήνυσται· μέρος δὲ ᾧ ἑκάτερος ἠρέσκετο, ὁ μὲν τῆς τε Ἀμφείας τὴν ἅλωσιν καὶ τὰ ἐφεξῆς συνέθηκεν οὐ πρόσω τῆς Ἀριστοδήμου τελευτῆς, Ῥιανὸς δὲ τοῦδε μὲν τοῦ πρώτου τῶν πολέμων οὐδὲ ἥψατο ἀρχήν· ὁπόσα δὲ χρόνῳ συνέβη τοῖς Μεσσηνίοις ἀποστᾶσιν ἀπὸ Λακεδαιμονίων, ὁ δὲ καὶ ταῦτα μὲν οὐ τὰ πάντα ἔγραψε, τῆς μάχης δὲ τὰ ὕστερα ἣν ἐμαχέσαντο ἐπὶ τῇ τάφρῳ τῇ καλουμένῃ Μεγάλῃ.", "st": "4.6"}, {"sp": "N", "t": "ἄνδρα οὖν Μεσσήνιον—τούτου γὰρ δὴ ἕνεκα τὸν πάντα ἐποιησάμην Ῥιανοῦ καὶ Μύρωνος λόγον—Ἀριστομένην, ὃς καὶ πρῶτος καὶ μάλιστα τὸ Μεσσήνης ὄνομα ἐς ἀξίωμα προήγαγε, τοῦτον τὸν ἄνδρα ἐπεισήγαγε μὲν ὁ Πριηνεὺς ἐς τὴν συγγραφήν, Ῥιανῷ δὲ ἐν τοῖς ἔπεσιν οὐδὲν Ἀριστομένης ἐστὶν ἀφανέστερος ἢ Ἀχιλλεὺς ἐν Ἰλιάδι Ὁμήρῳ. διάφορα οὖν ἐπὶ τοσοῦτον εἰρηκότων, προσέσθαι μὲν τὸν ἕτερόν μοι τῶν λόγων καὶ οὐχ ἅμα ἀμφοτέρους ὑπελείπετο, Ῥιανὸς δέ μοι ποιῆσαι μᾶλλον ἐφαίνετο εἰκότα ἐς τὴν Ἀριστομένους ἡλικίαν·", "st": "4.6"}, {"sp": "N", "t": "Μύρωνα δὲ ἐπί τε ἄλλοις καταμαθεῖν ἔστιν οὐ προορώμενον εἰ ψευδῆ τε καὶ οὐ πιθανὰ δόξει λέγειν καὶ οὐχ ἥκιστα ἐν τῇδε τῇ Μεσσηνίᾳ συγγραφῇ. πεποίηκε γὰρ ὡς ἀποκτείνειε Θεόπομπον τῶν Λακεδαιμονίων τὸν βασιλέα Ἀριστομένης ὀλίγον πρὸ τῆς Ἀριστοδήμου τελευτῆς· Θεόπομπον δὲ οὔτε μάχης γινομένης οὔτε ἄλλως προαποθανόντα ἴσμεν πρὶν ἢ διαπολεμηθῆναι τὸν πόλεμον.", "st": "4.6"}, {"sp": "N", "t": "οὗτος δὲ ὁ Θεόπομπος· ἦν καὶ ὁ πέρας ἐπιθεὶς τῷ πολέμῳ· μαρτυρεῖ δέ μοι καὶ τὰ ἐλεγεῖα τῶν Τυρταίου λέγοντα<br>ἡμετέρῳ βασιλῆι θεοῖσι φίλῳ Θεοπόμπῳ,<br>ὃν διὰ Μεσσήνην εἵλομεν εὐρύχορον.<br>ὁ τοίνυν Ἀριστομένης δόξῃ γε ἐμῇ γέγονεν ἐπὶ τοῦ πολέμου τοῦ ὑστέρου· καὶ τὰ ἐς αὐτόν, ἐπειδὰν ἐς τοῦτο ὁ λόγος ἀφίκηται, τηνικαῦτα ἐπέξειμι.", "st": "4.6"}, {"sp": "N", "t": "οἱ δὲ Μεσσήνιοι τότε, ὡς τὰ περὶ τὴν Ἄμφειαν ἤκουον παρ’ αὐτῶν τῶν ἀποσωθέντων ἐκ τῆς ἁλώσεως, συνελέγοντο ἐς Στενύκληρον ἀπὸ τῶν πόλεων. ἀθροισθέντος δὲ ἐς ἐκκλησίαν τοῦ δήμου καὶ ἄλλοι τῶν ἐν τέλει καὶ τελευταῖος ὁ βασιλεὺς παρεκελεύετο μήτε τῆς Ἀμφείας καταπεπλῆχθαι τὴν πόρθησιν, ὡς τὸν πάντα ἤδη κεκριμένον δι’ αὐτῆς πόλεμον, μήτε ὡς τῆς σφετέρας κρείσσονα τῶν Λακεδαιμονίων δεδοικέναι τὴν παρασκευήν· μελέτην μὲν γὰρ ἐκείνοις τῶν πολεμικῶν ἐκ χρόνου πλείονος, σφίσι δὲ εἶναι τήν τε ἀνάγκην ἰσχυροτέραν ἀνδράσιν ἀγαθοῖς γίνεσθαι καὶ τὸ εὐμενέστερον ἔσεσθαι παρὰ τῶν θεῶν ἀμύνουσι τῇ οἰκείᾳ καὶ οὐκ ἀδικίας ἄρχουσιν.", "st": "4.6"}, {"sp": "N", "t": "τοιαῦτα ὁ Εὐφαὴς εἰπὼν διέλυσε τὸν σύλλογον, τὸ δὲ ἀπὸ τούτου πάντας ἔσχεν ἤδη τοὺς Μεσσηνίους ἐν ὅπλοις, τούς τε οὐκ εἰδότας ἐπαναγκάζων διδάσκεσθαι τὰ πολεμικὰ καὶ τοῖς ἐπισταμένοις ἐπιμελεστέραν ἢ πρότερον τὴν ἄσκησιν εἶναι. Λακεδαιμόνιοι δὲ καταδρομὰς ἐποιοῦντο ἐς τὴν Μεσσηνίαν, καὶ τὴν μὲν χώραν οὐκ ἐλυμαίνοντο ἅτε δὴ νομίζοντες οἰκείαν οὐδὲ δένδρα ἔκοπτον οὐδὲ οἰκήματα κατέβαλλον· οἱ δὲ λείαν εἰ περιτύχοιεν ἤλαυνον καὶ σῖτον καὶ τὸν ἄλλον καρπὸν ἀφῃροῦντο.", "st": "4.7"}, {"sp": "N", "t": "πρὸς δὲ τὰς πόλεις ποιούμενοι προσβολὰς εἷλον μὲν οὐδεμίαν ἅτε καὶ τείχεσιν ὠχυρωμένας καὶ δι’ ἀκριβείας φρουρουμένας, λαμβάνοντες δὲ τραύματα ἀπεχώρουν ἄπρακτοι καὶ τελευτῶντες οὐκέτι ἀπεπειρῶντο τῶν πόλεων. ἐλῄστευον δὲ καὶ οἱ Μεσσήνιοι τά τε ἐπιθαλάσσια τῆς Λακωνικῆς καὶ ὅσαι γεωργίαι περὶ τὸ Ταΰγετον ἦσαν.", "st": "4.7"}, {"sp": "N", "t": "τετάρτῳ δὲ ἔτει μετὰ τῆς Ἀμφείας τὴν ἅλωσιν Εὐφαὴς τῷ θυμῷ χρήσασθαι τῷ Μεσσηνίων προθυμούμενος ἀκμαζόντων ἐς τοὺς Λακεδαιμονίους ταῖς ὀργαῖς καὶ ἅμα τὴν ἄσκησιν ἤδη σφίσιν αὐτάρκη νομίζων εἶναι, προεῖπεν ἔξοδον· συνακολουθεῖν δὲ καὶ τοὺς οἰκέτας προσέτασσε φέροντας ξύλα καὶ ἄλλα ὅσα πρόσφορα ἐς ποίησιν χαρακώματος. ἐπυνθάνοντο δὲ καὶ οἱ Λακεδαιμόνιοι παρὰ τῶν ἐν Ἀμφείᾳ φρουρῶν τοὺς Μεσσηνίους ἐξιόντας· ἐξεστρατεύοντο οὖν καὶ οὗτοι.", "st": "4.7"}, {"sp": "N", "t": "καὶ ἦν γὰρ ἐν τῇ Μεσσηνίᾳ χωρίον ἄλλως μὲν ἐς ἀγῶνα ἐπιτήδειον, χαράδρα δὲ προεβέβλητο αὐτοῦ βαθεῖα· ἐνταῦθα τοὺς Μεσσηνίους παρέτασσεν ὁ Εὐφαής, ἀποδείξας στρατηγὸν Κλέοννιν· τῆς δὲ ἵππου καὶ τῶν ψιλῶν, οἳ συναμφότεροι ἐλάσσους πεντακοσίων ἦσαν, τούτων Πυθάρατος καὶ Ἄντανδρος ἡγοῦντο.", "st": "4.7"}, {"sp": "N", "t": "ὡς δὲ συνῄει τὰ στρατόπεδα, τοῖς μὲν ὁπλίταις καὶ ἀφειδῶς ὅμως καὶ ἀκρατέστερον ὑπὸ τοῦ μίσους φερομένοις ἐπὶ ἀλλήλους οὐ παρέσχεν ἐλθεῖν ἐς χεῖρας ἡ χαράδρα διείργουσα· τὸ δ’ ἱππικὸν καὶ οἱ ψιλοὶ συμμίσγουσι μὲν κατὰ τὸ ὑπὲρ τὴν χαράδραν, ἦσαν δὲ οὔτε πλῆθος οὔτε ἐμπειρίᾳ διαφέροντες οὐδέτεροι, καὶ διὰ τοῦτο ἰσόρροπος ἡ μάχη σφίσιν ἐγένετο.", "st": "4.7"}, {"sp": "N", "t": "⟨ἐν⟩ ὅσῳ δὲ οὗτοι συνεστήκασιν, ἐν τοσούτῳ τοὺς οἰκέτας ἐκέλευεν ὁ Εὐφαὴς πρῶτα μὲν τὰ κατὰ νῶτον τοῦ στρατοπέδου φράξασθαι τοῖς σταυροῖς, μετὰ δὲ τὰ πλευρὰ ἀμφότερα. ἐπεὶ δὲ ἥ τε νύξ ἐπέλαβε καὶ ἡ μάχη διελέλυτο, τότε ἤδη καὶ τὰ πρὸ τοῦ στρατοπέδου κατὰ τὴν χαράδραν ἐφράξαντο, ὥστε ἐπισχούσης ἡμέρας τῆς τε προνοίας τοῦ Εὐφαοῦς τοῖς Λακεδαιμονίοις ἐπιπίπτει λογισμὸς εἶχόν τε οὔτε ὅπως μάχεσθαι χρὴ πρὸς τοὺς Μεσσηνίους μὴ προϊόντας ἐκ τοῦ χάρακος προσκαθῆσθαί τε ἀπεγίνωσκον ἀπαράσκευοι τοῖς πᾶσιν ὁμοίως ὄντες.", "st": "4.7"}, {"sp": "N", "t": "καὶ τότε μὲν ἀποχωροῦσιν οἴκαδε, ἐνιαυτῷ δὲ ὕστερον κακιζόντων σφᾶς τῶν γεγηρακότων καὶ δειλίαν τε ὁμοῦ προφερόντων καὶ τοῦ ὅρκου τὴν ὑπεροψίαν, οὕτω δευτέραν ἐκ τοῦ προφανοῦς ἐπὶ Μεσσηνίους στρατείαν ἐποιοῦντο. ἡγοῦντο δὲ οἱ βασιλεῖς ἀμφότεροι, Θεόπομπός τε ὁ Νικάνδρου καὶ Πολύδωρος ὁ Ἀλκαμένους· Ἀλκαμένης δὲ οὐκέτι περιῆν. ἀντεστρατοπεδεύοντο δὲ καὶ οἱ Μεσσήνιοι καὶ πειρωμένων μάχης τῶν Σπαρτιατῶν ἄρχειν ἀντεπεξῄεσαν.", "st": "4.7"}, {"sp": "N", "t": "Λακεδαιμονίοις δὲ ἡγεῖτο Πολύδωρος μὲν κατὰ τὸ κέρας τὸ ἀριστερόν, Θεόπομπος δὲ ἐπὶ τῷ δεξιῷ, τὸ μέσον δὲ εἶχεν Εὐρυλέων, τὰ μὲν παρόντα Λακεδαιμόνιος, τὰ ἐξ ἀρχῆς δὲ ἀπὸ Κάδμου καὶ ἐκ Θηβῶν, Αἰγέως τοῦ Οἰολύκου τοῦ Θήρα τοῦ Αὐτεσίωνος ἀπόγονος πέμπτος. τοῖς δὲ Μεσσηνίοις κατὰ μὲν τὸ δεξιὸν τῶν Λακεδαιμονίων ἀντετάσσοντο Ἄντανδρός τε καὶ Εὐφαής, τὸ δὲ ἕτερον κέρας τὸ κατὰ τὸν Πολύδωρον Πυθάρατος εἶχε, Κλέοννις δὲ τὸ μέσον.", "st": "4.7"}, {"sp": "N", "t": "συνιέναι δὲ ἤδη μελλόντων, ἐπεὶ παριόντες οἱ βασιλεῖς προέτρεπον τοὺς αὑτῶν, πρὸς μὲν δὴ τοὺς Λακεδαιμονίους βραχεῖαν κατὰ τὸ ἐπιχώριον τὴν παράκλησιν ἐποιεῖτο ὁ Θεόπομπος, τοῦ τε ὅρκου τοῦ κατὰ τῶν Μεσσηνίων ἀναμιμνήσκων καὶ ὡς καλόν σφισι τὸ φιλοτίμημα, τῶν πατέρων οἳ τοὺς περιοίκους κατεδουλώσαντο φανῆναι λαμπρότερα εἰργασμένους καὶ χώραν εὐδαιμονεστέραν προσκεκτημένους· Εὐφαὴς δὲ μακρότερα μὲν εἶπεν ἢ ὁ Σπαρτιάτης, οὐ πλείω δὲ οὐδ’ οὗτος ἢ ἐφιέντα ἑώρα τὸν καιρόν.", "st": "4.7"}, {"sp": "N", "t": "οὐ γὰρ περὶ γῆς μόνον οὐδὲ κτημάτων τὸν ἀγῶνα ἀπέφαινε γενησόμενον, εἰδέναι δὲ ἔφη σαφῶς ἃ νικωμένους ἐπιλήψεται· γυναῖκας μὲν γὰρ ἀχθήσεσθαι καὶ τέκνα ἐν ἀνδραπόδων μέρει, τοῖς δὲ ἐν ἡλικίᾳ τὸ ἐλαφρότατον ἔσεσθαι. θάνατον, ἢν μετ’ αἰκίας μὴ γένηται, συλήσεσθαι δέ σφισι καὶ τὰ ἱερὰ καὶ τὰς πατρίδας ἐμπρήσεσθαι· λέγειν δὲ οὐκ εἰκάζων, μάρτυρα δὲ ἐναργῆ πᾶσιν εἶναι τῶν ἐγκαταληφθέντων ἐν Ἀμφείᾳ τὰ πάθη.", "st": "4.7"}, {"sp": "N", "t": "πρό τε δὴ τηλικούτων κακῶν κέρδος εἶναι καλῶς τινα ἀποθανεῖν, πολὺ δὲ εἶναι ῥᾷον ἀηττήτοις οὖσιν ἔτι καὶ τὰς τόλμας καθεστηκόσιν ἐξ ἴσου προθυμίᾳ τοὺς ἀντιτεταγμένους ὑπερβαλεῖν ἢ προαποβαλόντας τὸ φρόνημα ἐπανορθοῦσθαι τὰ ἐπταισμένα.", "st": "4.7"}, {"sp": "N", "t": "τοιαῦτα μὲν ὁ Εὐφαὴς εἶπεν· ἐπεὶ δὲ ἑκατέροις ἐσήμηναν οἱ ἡγεμόνες, Μεσσήνιοι μὲν δρόμῳ τε ἐς τοὺς Λακεδαιμονίους ἐχρῶντο καὶ ἀφειδῶς αὑτῶν εἶχον ἅτε ἄνθρωποι θανατῶντες ὑπὸ τοῦ θυμοῦ, καὶ αὐτὸς ἕκαστος πρῶτος ἔσπευδεν ἄρξαι μάχης· ἀντεπῄεσαν δὲ καὶ οἱ Λακεδαιμόνιοι σπουδῇ καὶ οὗτοι, πρόνοιαν δὲ ὅμως ἐποιοῦντο μὴ διαλυθῆναί σφισι τὴν τάξιν.", "st": "4.8"}, {"sp": "N", "t": "ὡς δὲ πλησίον ἐγίνοντο, ἀπειλαῖς ἐχρῶντο τῶν τε ὅπλων τῇ κινήσει καὶ ἐνορῶντες ἐς ἀλλήλους δεινόν· ἔς τε λοιδορίας προήγοντο οἱ μὲν οἰκέτας αὑτῶν ἤδη τοὺς Μεσσηνίους καὶ οὐδὲν ἐλευθερωτέρους ἀποκαλοῦντες τῶν εἱλώτων, οἱ δὲ ἐκείνους τῷ τε ἐγχειρήματι ἀνοσίους, ἐπεὶ πλεονεξίας ἕνεκα ἐπὶ ἄνδρας συγγενεῖς ἐπίασι, καὶ θεῶν ἀσεβεῖς ὅσοι Δωριεῦσι πατρῷοι, τῶν τε ἄλλων καὶ μάλιστα Ἡρακλέους. ἤδη τε ὁμοῦ τοῖς ὀνείδεσι καὶ ἔργων ἥπτοντο, ἀθρόοι τε πρὸς ἀθρόους ὠθισμῷ χρώμενοι μάλιστα οἱ Λακεδαιμόνιοι καὶ ἀνὴρ ἀνδρὶ ἐπιόντες.", "st": "4.8"}, {"sp": "N", "t": "τέχνῃ μὲν οὖν ἐς τὰ πολεμικὰ ὁμοῦ καὶ μελέτῃ πολὺ οἱ Λακεδαιμόνιοι προέσχον, πρὸς δὲ καὶ τῷ πλήθει· τούς τε γὰρ περιοίκους ὑπηκόους ἤδη καὶ συνακολουθοῦντας εἶχον Ἀσιναῖοί τε [καὶ] οἱ Δρύοπες γενεᾷ πρότερον ὑπὸ Ἀργείων ἐκ τῆς σφετέρας ἀνεστηκότες καὶ ἥκοντες ἐς τὴν Λακεδαίμονα ἱκέται κατ’ ἀνάγκην συνεστρατεύοντο· πρὸς δὲ τοὺς ψιλοὺς τῶν Μεσσηνίων τοξότας Κρῆτας ἐπήγοντο μισθωτούς.", "st": "4.8"}, {"sp": "N", "t": "Μεσσηνίοις δὲ †ἐς ἅπαντα ἐς τὸ ἴσον ἥ τε ἀπόνοια καὶ τὸ ἐς τὸν θάνατον εὔθυμον· καὶ ὁπόσα μὲν πάσχοιεν, ἀναγκαῖα μᾶλλον τοῖς πατρίδα σεμνύνουσιν ἢ δεινὰ ἐνόμιζον, ἃ δὲ ἔδρων, αὐτοί τε ἡγοῦντο εἰργάσθαι μειζόνως καὶ τοῖς Λακεδαιμονίοις συμβαίνειν χαλεπώτερα. καὶ οἱ μὲν αὐτῶν προεκπηδῶντες τῆς τάξεως τολμήματα λαμπρὰ ἀπεδείκνυντο, τοῖς δὲ καὶ ἐπικαίρως τετρωμένοις καὶ ἐμπνέουσιν ὀλίγον ὅμως ἡ ἀπόνοια ἤκμαζε.", "st": "4.8"}, {"sp": "N", "t": "παρακλήσεις τε ἐγίνοντο, καὶ οἱ μὲν ζῶντες καὶ ἔτι ἄτρωτοι τοὺς τραυματίας παρώξυνον, πρὶν ἢ τὴν ἐσχάτην τινὶ ἐφεστηκέναι μοῖραν, ἀντιδράσαντα ὅ τι καὶ δύναιτο σὺν ἡδονῇ δέχεσθαι τὸ πεπρωμένον· οἱ δὲ ὁπότε αἴσθοιντο οἱ τραυματίαι τὴν ἰσχὺν σφᾶς ὑπολείπουσαν καὶ τὸ πνεῦμα οὐ παραμένον, διεκελεύοντο τοῖς ἀτρῶσι μὴ χείρονας ἢ αὐτοὶ γίνεσθαι μηδὲ ἐς ἀνωφελὲς τῇ πατρίδι καὶ τὴν ἐκείνων τελευτὴν καταστῆσαι.", "st": "4.8"}, {"sp": "N", "t": "Λακεδαιμόνιοι δὲ προτροπῇ μὲν ἐς ἀλλήλους [τῇ δεήσει] οὐκ ἐχρῶντο καὶ ἐς τὰ παράδοξα τῶν τολμημάτων οὐ κατὰ ταὐτὰ ἑτοίμως τοῖς Μεσσηνίοις εἶχον· ἅτε δὲ εὐθὺς ἐκ παίδων τὰ πολεμικὰ ἐπιστάμενοι, βαθυτέρᾳ τε τῇ φάλαγγι ἐχρῶντο καὶ τοὺς Μεσσηνίους ἤλπιζον οὔτε χρόνον τὸν ἴσον καρτερήσειν ἀντιτεταγμένους οὔτε πρὸς τὸν ἐν τοῖς ὅπλοις κάματον ἢ τὰ τραύματα ἀνθέξειν.", "st": "4.8"}, {"sp": "N", "t": "ἴδια μὲν τοιαῦτα ἐν ἑκατέρῳ τῷ στρατεύματι ἔς τε τὰ ἔργα ἦν καὶ ἐς τὰς γνώμας τῶν μαχομένων, κοινὰ δὲ ἀπ’ ἀμφοτέρων· οὔτε γὰρ ἱκεσίαις οἱ φονευόμενοι καὶ χρημάτων ὑποσχέσεσιν ἐχρῶντο, τάχα μέν που μὴ πείσειν διὰ τὸ ἔχθος ἀπεγνωκότες, τὸ δὲ πλεῖστον ἀπαξιοῦντες ὡς οὐ τὰ πρότερά γε κακιοῦσιν· οἵ τε ἀποκτείνοντες ἀπείχοντο καὶ αὐχήματος ὁμοίως καὶ ὀνειδῶν, οὐκ ἔχοντές πω βεβαίαν οὐδέτεροι τὴν ἐλπίδα εἰ κρατήσουσι. παραδοξότατα δὲ ἀπέθνησκον οἱ τῶν κειμένων σκυλεύειν τινὰ ἐπιχειροῦντες· ἢ γὰρ τοῦ σώματος γυμνόν τι ὑποφήναντες ἠκοντίζοντο καὶ ἐτύπτοντο οὐ προορώμενοι διὰ τὴν ἐν τῷ παρόντι ἀσχολίαν, ἢ καὶ ὑπὸ τῶν σκυλευομένων ἔτι ἐμπνεόντων διεφθείροντο.", "st": "4.8"}, {"sp": "N", "t": "ἐμάχοντο δὲ καὶ οἱ βασιλεῖς ἀξίως λόγου, Θεόπομπος δὲ καὶ ἀκρατέστερον ὥρμητο ὡς αὐτὸν ἀποκτενῶν Εὐφαῆ. Εὐφαὴς δὲ ὁρῶν ἐπιόντα εἶπεν ἄρα πρὸς τὸν Ἄντανδρον οὐδὲν εἶναι τὰ Θεοπόμπου διάφορα ἢ ⟨ὅσα⟩ ὁ πρόγονος αὐτοῦ Πολυνείκης ἐτόλμησε· Πολυνείκην τε γὰρ στρατιὰν ἐπὶ τὴν πατρίδα ἀγαγόντα ἐξ Ἄργους ἀποκτεῖναι τὸν ἀδελφὸν αὐτοχειρὶ καὶ ἀποθανεῖν ὑπὸ ἐκείνου, Θεόπομπόν τε ἐθέλειν ἐς τὸ ἴσον καταστῆσαι μιάσματος τοῖς ἀπὸ Λαΐου καὶ Οἰδίποδος τὸ Ἡρακλειδῶν γένος· οὐ μέντοι χαίροντά γε ἀπὸ τῆς μάχης διακριθήσεσθαι. τοιαῦτα ἐπιλέγων ἀντεπῄει καὶ οὗτος.", "st": "4.8"}, {"sp": "N", "t": "ἐνταῦθα ἥ τε πᾶσα μάχη κεκμηκότων ὅμως ἐς τὸ ἀκμαιότατον αὖθις ἤρθη, καὶ τοῖς τε σώμασιν ἀνερρώννυντο καὶ τὸ ἀφειδὲς ἐς τὸν θάνατον παρ’ ἀμφοτέρων ηὐξάνετο, ὥστε εἰκάσαι ἄν τις τοῦ ἔργου τότε σφᾶς πρῶτον ἅπτεσθαι. τέλος δὲ οἱ περὶ τὸν Εὐφαῆ τῆς τε ἀπονοίας τῷ ὑπερβάλλοντι μανίας ὄντες ἐγγύτατα καὶ ὑπ’ ἀνδραγαθίας—πᾶν γὰρ δὴ τὸ περὶ τὸν βασιλέα οἱ λογάδες τῶν Μεσσηνίων ἦσαν—βιάζονται τοὺς ἀντιτεταγμένους· καὶ αὐτόν τε Θεόπομπον ἀπώσαντο καὶ Λακεδαιμονίων τοὺς καθ’ αὑτοὺς ἐτρέψαντο.", "st": "4.8"}, {"sp": "N", "t": "τὸ δὲ ἕτερον κέρας τοῖς Μεσσηνίοις ἐταλαιπώρει. Πυθάρατός τε γὰρ ὁ στρατηγὸς ἐτεθνήκει καὶ αὐτοὶ διὰ τὴν ἀναρχίαν ἀτακτότερον καὶ ⟨θορυβωδέστερον ἐμάχοντο, οὐ μέντοι⟩ ἀθύμως εἶχον οὐδ’ οὗτοι. φεύγουσι δὲ οὔτε τοῖς Μεσσηνίοις ὁ Πολύδωρος οὔτε οἱ περὶ τὸν Εὐφαῆ τοῖς Λακεδαιμονίοις ἠκολούθησαν· Εὐφαεῖ γὰρ καὶ τοῖς περὶ αὐτὸν αἱρετώτερα ἐφαίνετο ἀμύνειν τοῖς ἡττωμένοις—οὐ μέντοι Πολυδώρῳ γὲ οὐδὲ τοῖς περὶ αὐτὸν συμμίσγουσιν, ἐν σκότῳ γὰρ ἤδη τὰ γινόμενα ἦν—", "st": "4.8"}, {"sp": "N", "t": "καὶ τοὺς Λακεδαιμονίους ἅμα εἶργε μὴ πρόσω τοῖς ἀποχωροῦσιν ἐπακολουθεῖν οὐχ ἥκιστα καὶ ἡ ἀπειρία τῶν τόπων. ἦν δὲ αὐτοῖς καὶ ἄλλως πάτριον σχολαιοτέρας τὰς διώξεις ποιεῖσθαι, μὴ διαλῦσαι τὴν τάξιν πλείονα ἔχοντας πρόνοιαν ἤ τινα ἀποκτεῖναι φεύγοντα. τὰ δὲ μέσα ἀμφοτέροις, ᾗ Λακεδαιμονίων ὁ Εὐρυλέων, Μεσσηνίοις δὲ Κλέοννις ἡγεῖτο, ἰσοπαλῶς μὲν ἠγωνίζοντο, διέλυσε δὲ ἀπ’ ἀλλήλων καὶ τούτους ἐπελθοῦσα ἡ νύξ.", "st": "4.8"}, {"sp": "N", "t": "ταύτην τὴν μάχην παρὰ ἀμφοτέρων ἢ μόνα ἢ μάλιστα ἐμαχέσαντο τὰ ὁπλιτικά. οἱ δὲ ἐπὶ τῶν ἵππων ὀλίγοι τε ἦσαν καὶ οὐδὲν ὥστε καὶ μνημονευθῆναι διεπράξαντο· οὐ γάρ τοι ἀγαθοὶ τότε ἱππεύειν ἦσαν οἱ Πελοποννήσιοι. τῶν δὲ Μεσσηνίων οἱ ψιλοὶ καὶ οἱ παρὰ Λακεδαιμονίοις Κρῆτες οὐδὲ συνέμιξαν ἀρχήν· τῷ γὰρ πεζῷ τῷ σφετέρῳ κατὰ τρόπον ἔτι ἑκάτεροι τὸν ἀρχαῖον ἐπετάχθησαν.", "st": "4.8"}, {"sp": "N", "t": "ἐς δὲ τὴν ἐπιοῦσαν μάχης μὲν οὐδέτεροι διενοοῦντο ἄρχειν οὐδὲ ἱστάναι πρότεροι τρόπαιον, προϊούσης δὲ τῆς ἡμέρας ὑπὲρ ἀναιρέσεως τῶν νεκρῶν ἐπεκηρυκεύοντο, καὶ ἐπειδὴ παρὰ ἀμφοτέρων συνεχωρήθη, θάψειν ἔμελλον ἤδη τὸ ἐντεῦθεν.", "st": "4.8"}, {"sp": "N", "t": "τοῖς δὲ Μεσσηνίοις μετὰ τὴν μάχην πονηρὰ γίνεσθαι τὰ πράγματα ἤρχετο· δαπάνῃ τε γὰρ χρημάτων ἀπειρήκεσαν, ἃ τῶν πόλεων ἀνήλισκον ἐς τὰς φρουράς, καὶ οἱ δοῦλοι παρὰ τοὺς Λακεδαιμονίους ηὐτομόλουν, τοῖς δὲ καὶ νόσος ἐνέπεσε καὶ ταραχὰς μὲν παρέσχεν ὡς εἴη λοιμώδης, οὐ μὴν ἐς ἅπαντάς γε ἐχώρησεν. βουλευομένοις δὲ πρὸς τὰ παρόντα ἐδόκει τὰ μὲν πολλὰ πολίσματα τὰ ἐς μεσόγαιαν πάντα ἐκλείπειν, ἐς δὲ τὸ ὄρος ἀνοικίζεσθαι τὴν Ἰθώμην.", "st": "4.9"}, {"sp": "N", "t": "ἦν δὲ καὶ πόλισμα αὐτόθι οὐ μέγα, ὃ καὶ Ὅμηρόν φασιν ἔχειν ἐν καταλόγῳ·<br>καὶ Ἰθώμην κλιμακόεσσαν.<br>ἐς τοῦτο τὸ πόλισμα ἀνῳκίζοντο, ἐπεκτείνοντες τὸν ἀρχαῖον περίβολον ἔρυμα εἶναι πᾶσιν αὔταρκες. ἦν δὲ τὸ χωρίον καὶ ἄλλως ἐχυρόν· ἡ γὰρ Ἰθώμη μεγέθει τε οὐδενὸς ἀποδεῖ τῶν ὀρῶν ὁπόσα ἐντός ἐστιν ἰσθμοῦ καὶ δύσβατος κατὰ τοῦτο μάλιστα ἦν.", "st": "4.9"}, {"sp": "N", "t": "ἐδόκει δὲ καὶ θεωρὸν πέμψαι σφίσιν ἐς Δελφούς. ἀποστέλλουσιν οὖν Τῖσιν τὸν Ἄλκιδος, καὶ ἀξιώματι οὐδενὸς ὕστερον καὶ ὅτι προσκεῖσθαι μαντικῇ μάλιστα ἐνομίζετο. τοῦτον τὸν Τῖσιν ἐπανιόντα ἐκ Δελφῶν λοχῶσιν ἄνδρες Λακεδαιμονίων ἀπὸ τῆς ἐν Ἀμφείᾳ φρουρᾶς· λοχήσαντες δὲ—οὐ γὰρ ὑπεῖκεν αἰχμάλωτος γενέσθαι— περιμένοντα οὖν ἀμύνεσθαι καὶ ἀνθεστηκότα ἐτίτρωσκον, ἐς ὃ γίνεται βοή σφισιν ἐξ ἀφανοῦς “τὸν χρησμοφόρον μέθες.”", "st": "4.9"}, {"sp": "N", "t": "καὶ Τῖσις μὲν ὡς ἀπεσώθη τάχιστα ἐς Ἰθώμην καὶ τὴν μαντείαν παρὰ τὸν βασιλέα ἀνήνεγκε, μετ’ οὐ πολὺ ὑπὸ τῶν τραυμάτων τελευτᾷ· τοὺς δὲ Μεσσηνίους συναθροίσας ὁ Εὐφαὴς ἐπεδείκνυ τὸν χρησμόν·<br>κόρην ἄχραντον νερτέροισι δαίμοσι,<br>κλήρῳ λαχοῦσαν Αἰπυτιδῶν ἀφ’ αἵματος,<br>θυηπολεῖτε νυκτέροισιν ἐν σφαγαῖς.<br>ἢν δὲ σφαλῆτε, καὶ παρ’ ἀλλοίου τότε<br>θύειν, διδόντος ἐς σφαγὴν ἑκουσίως.", "st": "4.9"}, {"sp": "N", "t": "ταῦτα τοῦ θεοῦ δηλώσαντος αὐτίκα ἐκληροῦντο ὅσαι παρθένοι τοῦ Αἰπυτιδῶν γένους ἦσαν· καὶ ἐπελάμβανε γὰρ Λυκίσκου θυγατέρα ὁ κλῆρος, ταύτην Ἐπήβολος ὁ μάντις ἀπηγόρευεν ὡς οὐ δέοι θύειν, οὐ γὰρ εἶναι Λυκίσκου· τὴν δὲ γυναῖκα ἣ Λυκίσκῳ συνῴκησεν, ὡς τεκεῖν οὔκουν οἵα τε ἦν, [ἐν τούτῳ] τὴν παῖδα ὑποβαλέσθαι. ἐν ὅσῳ δὲ οὗτος ἀνεδίδασκε τὰ ἐς αὐτήν, ἐν τοσῷδε ὁ Λυκίσκος ἀπαγόμενος ἅμα καὶ τὴν παρθένον ηὐτομόλησεν ἐς Σπάρτην.", "st": "4.9"}, {"sp": "N", "t": "ἐχόντων δὲ ἀθύμως τῶν Μεσσηνίων ὡς Λυκίσκον ἀποδράντα ᾔσθοντο, ἐνταῦθά σφισιν Ἀριστόδημος ἀνὴρ καὶ γένους τοῦ Αἰπυτιδῶν καὶ Λυκίσκου τῇ τε ἄλλῃ δόξῃ καὶ τὰ ἐς πόλεμον ἐπιφανέστερος ἐδίδου τὴν θυγατέρα ἑκὼν θῦσαι. τὰ δὲ ἀνθρώπων καὶ οὐχ ἥκιστα τὸ πρόθυμον ἡ πεπρωμένη κατὰ ταὐτὰ ἐπικρύπτει καὶ εἰ ψηφῖδα ἐπιλαβοῦσα ἰλὺς ποταμοῦ, ὅπου καὶ τότε Ἀριστοδήμῳ διασώσασθαι Μεσσήνην ἀγώνισμα ποιουμένῳ [τὸ] ἐμπόδιον ἐπήγαγε τοιόνδε.", "st": "4.9"}, {"sp": "N", "t": "ἀνὴρ τῶν Μεσσηνίων—τὸ δὲ ὄνομα οὐ λέγουσιν—ἐρῶν ἔτυχε τοῦ Ἀριστοδήμου τῆς θυγατρός, τότε δὲ ἤδη ἔμελλε καὶ γυναῖκα ἄξεσθαι. οὗτος κατ’ ἀρχὰς μὲν ἐς ἀμφισβήτησιν Ἀριστοδήμῳ προῆλθεν, ἐκεῖνον μὲν ἐγγυήσαντά οἱ μηκέτι εἶναι κύριον τῆς παιδός, αὐτὸς δὲ ἐγγυησάμενος κυριώτερος ἐκείνου γίνεσθαι. δεύτερα δὲ ὡς τοῦτο οὐχ ἑώρα οἱ κατορθούμενον, ἐπ’ ἀναίσχυντον τρέπεται λόγον·", "st": "4.9"}, {"sp": "N", "t": "ξυγγενέσθαι τε τῇ παιδὶ καὶ κύειν ἐξ αὐτοῦ. τέλος δὲ ἐς τοσοῦτον Ἀριστόδημον προήγαγεν ὡς ἐκμανέντα ὑπὸ τοῦ θυμοῦ τὴν θυγατέρα ἀποκτεῖναι· μετὰ δὲ ἀνέτεμνε καὶ ἐπεδείκνυεν αὐτὴν οὐκ ἔχουσαν ἐν γαστρί. παρὼν δὲ Ἐπήβολος ἐκέλευεν ἄλλον τινὰ τὸν θυγατέρα ἐπιδώσοντα γενέσθαι· τῆς γὰρ τοῦ Ἀριστοδήμου πλέον εἶναί σφισιν ἀποθανούσης οὐδέν· φονεῦσαι γὰρ τὸν πατέρα αὐτήν, θεοῖς δὲ οἷς ἡ Πυθία προσέταξεν οὐ θῦσαι.", "st": "4.9"}, {"sp": "N", "t": "τοιαῦτα εἰπόντος τοῦ μάντεως τὸ πλῆθος τῶν Μεσσηνίων ὥρμησεν ἀποκτενοῦντες τὸν μνηστῆρα τῆς παιδός, ὡς Ἀριστοδήμῳ τε μίασμα εἰκαῖον προσάψαντα καὶ σφίσι τῆς σωτηρίας τὴν ἐλπίδα ἀμφίβολον πεποιηκότα. ἢν δὲ ὁ ἀνὴρ οὗτος ἐς τὰ μάλιστα τῷ Εὐφαεῖ φίλος· πείθει ⟨οὖν⟩ τοὺς Μεσσηνίους Εὐφαὴς τόν τε χρησμὸν ἔχειν τέλος ἀποθανούσης τῆς παιδὸς καὶ σφίσιν ἀποχρᾶν τὰ ὑπὸ Ἀριστοδήμου πεποιημένα.", "st": "4.9"}, {"sp": "N", "t": "λέγοντος δὲ ταῦτα ἔφασαν τὰ ὄντα λέγειν ὅσοι τοῦ Αἰπυτιδῶν γένους ἦσαν· ἀπεῖναι γάρ σφισι τὸ δέος τὸ ἐπὶ τῇ θυγατρὶ ἕκαστος ἔσπευδε. καὶ οἱ μὲν τοῦ βασιλέως τῇ παραινέσει πειθόμενοι τὴν ἐκκλησίαν διαλύουσι καὶ ἀπ’ αὐτῆς πρός τε θυσίας θεῶν καὶ ἑορτὴν τρέπονται·", "st": "4.9"}, {"sp": "N", "t": "Λακεδαιμόνιοι δὲ ἀκούσαντες τὸν γενόμενον Μεσσηνίοις χρησμὸν ἀθύμως διέκειντο καὶ αὐτοὶ καὶ οἱ βασιλεῖς ἔς τε τὰ λοιπὰ καὶ ἄρχειν ὀκνοῦντες μάχης. ἔτει δὲ ἕκτῳ μετὰ τὸν ἐξ Ἰθώμης Λυκίσκου δρασμὸν οἱ Λακεδαιμόνιοι—τὰ γὰρ ἱερὰ ἐγίνετο αὐτοῖς αἴσια —στρατεύουσιν ἐπὶ τὴν Ἰθώμην· οἱ δὲ Κρῆτες οὐκέτι παρόντες σφίσιν ἔτυχον. ὑστέρησαν δὲ καὶ οἱ τῶν Μεσσηνίων σύμμαχοι—δι’ ὑποψίας γὰρ οἱ Σπαρτιᾶται καὶ ἄλλοις ἤδη Πελοποννησίων καὶ Ἀρκάσιν ἦσαν καὶ Ἀργείοις μάλιστα—καὶ οἱ μὲν Ἀργεῖοι κρύφα ἔμελλον τῶν Λακεδαιμονίων ἀφίξεσθαι καὶ ἰδίᾳ δὴ μᾶλλον ⟨ἢ⟩ μετὰ δόγματος κοινοῦ, τοῖς δὲ Ἀρκάσιν ἡ στρατεία μὲν ἀνείρητο ἐκ τοῦ φανεροῦ, παρέτυχον δὲ οὐδ’ οὗτοι. τοὺς γὰρ Μεσσηνίους καὶ ἄνευ συμμάχων κινδυνεῦσαι προήγαγεν ἡ δόξα τοῦ χρησμοῦ.", "st": "4.10"}, {"sp": "N", "t": "τὰ μὲν οὖν πολλὰ οὐδέν τι ἐγένετο διάφορα ἢ καὶ ἐπὶ τῆς προτέρας μάχης, ἥ τε ἡμέρα καὶ τότε μαχομένους προαπέλιπεν· οὐ μέντοι βιασθῆναί γε οὐδέτερον κέρας ἢ καὶ λόχον μνημονεύουσιν, ἐπεὶ μηδὲ τὴν τάξιν, ὡς ἀπ’ ἀρχῆς ἐτάχθησαν, συμμεῖναί φασιν, ἀλλ’ ἀφ’ ἑκατέρων τοὺς ἀρίστους συνελθόντας ἐς τὸ μεσαίτατον ἐνταῦθα τὸν πάντα ἔχειν πόνον.", "st": "4.10"}, {"sp": "N", "t": "ὁ γὰρ Εὐφαὴς πλέον τι ἢ βασιλέα εἰκὸς ἦν προθυμούμενος καὶ ἀφειδῶς τοῖς περὶ τὸν Θεόπομπον ἐγκείμενος τραύματα [τε] πολλά τε καὶ οὐκ ἰάσιμα λαμβάνει· λιποψυχήσαντα δὲ αὐτὸν καὶ πεσόντα οἱ Λακεδαιμόνιοι καὶ ὀλίγον ὅμως ἐμπνέοντα ἐποιοῦντο παρ’ αὑτοὺς ἑλκύσαι σπουδήν. ἐπήγειρε δὲ καὶ τοὺς Μεσσηνίους ἥ τε ἐς τὸν Εὐφαῆ προϋπάρχουσα εὔνοια καὶ τὰ ὀνείδη τὰ μέλλοντα· φονευομένοις τε ὑπὲρ τοῦ βασιλέως ἄμεινόν σφισιν ἐφαίνετο προΐεσθαι τὰς ψυχὰς ἢ ἐκεῖνον προεμένων ἀποσωθῆναί τινα.", "st": "4.10"}, {"sp": "N", "t": "τότε μὲν δὴ πεσὼν ὁ Εὐφαὴς τήν τε μάχην ἐπεμήκυνε καὶ προήγαγεν ἐς πλέον παρὰ ἑκατέρων τὰ τολμήματα· ὕστερον δὲ ἀνήνεγκε μὲν καὶ ᾔσθετο ὅτι οὐκ ἔλαττον ἐσχήκασιν ἐν τῷ ἔργῳ, ἡμέραις δὲ οὐ πολλαῖς ἀποθνήσκει, βασιλεύσας Μεσσηνίων τρία ἔτη καὶ δέκα καὶ πολεμήσας Λακεδαιμονίοις τὸν πάντα τῆς βασιλείας χρόνον.", "st": "4.10"}, {"sp": "N", "t": "Εὐφαεῖ δὲ οὐκ ὄντων παίδων τὸν αἱρεθέντα ὑπὸ τοῦ δήμου κατελείπετο ἔχειν τὴν ἀρχήν, Κλέοννίς τε καὶ Δᾶμις ἐς ἀμφισβήτησιν Ἀριστοδήμῳ προῆλθον, τά τε ἄλλα καὶ τὰ ἐς πόλεμον διαφέρειν νομιζόμενοι· τὸν δὲ Ἄντανδρον οἱ πολέμιοι κατειργάσαντο ἐν τῇ μάχῃ προκινδυνεύοντα Εὐφαοῦς. ἦσαν δὲ καὶ τῶν μάντεων αἱ γνῶμαι κατὰ ταὐτὰ ἀμφοτέρων, Ἐπηβόλου καὶ Ὀφιονέως, μὴ σφᾶς ἀνδρὶ ἐναγεῖ καὶ θυγατρὸς μίασμα ἐπικειμένῳ δοῦναι τὴν Αἰπύτου καὶ τῶν ἀπογόνων τιμήν·", "st": "4.10"}, {"sp": "N", "t": "ᾑρέθη δὲ ὅμως καὶ ἐβασίλευσεν Ἀριστόδημος. ὁ δὲ Ὀφιονεὺς οὗτος ὁ τῶν Μεσσηνίων μάντις τυφλὸς ὢν εὐθὺς ἐκ γενετῆς μαντικήν τινα εἶχε τοιαύτην· πυνθανόμενος τὰ γινόμενα ἑκάστοις ἰδίᾳ τε καὶ ἐν κοινῷ προέλεγεν οὕτω τὰ μέλλοντα. οὗτος μὲν τρόπον ἐμαντεύετο τὸν εἰρημένον, Ἀριστόδημος δὲ βασιλεύσας τῷ τε δήμῳ διέμεινε τὰ εἰκότα χαρίζεσθαι προθυμούμενος καὶ τοὺς ἐν τέλει τούς τε ἄλλους καὶ μάλιστα Κλέοννιν καὶ Δᾶμιν ἦγεν ἐν τιμῇ· διὰ θεραπείας δὲ εἶχε καὶ τὰ τῶν συμμάχων, Ἀρκάδων τε τοῖς δυνατοῖς καὶ ἐς Ἄργος καὶ Σικυῶνα ἀποστέλλων δῶρα.", "st": "4.10"}, {"sp": "N", "t": "τὸν δὲ πόλεμον ἐπὶ τῆς Ἀριστοδήμου βασιλείας ἐπολέμουν λῃστείαις τε κατ’ ὀλίγους ἀεὶ καὶ περὶ τὴν ὡραίαν καταδρομαῖς ἐς τὴν ἀλλήλων χρώμενοι, συνεσέβαλλον δὲ καὶ παρὰ τῶν Ἀρκάδων τοῖς Μεσσηνίοις ἐς τὴν Λακωνικήν· Ἀργεῖοι δὲ προαναφῆναι μὲν τὸ ἐς τοὺς Λακεδαιμονίους ἔχθος οὐκ ἠξίουν, γινομένου δὲ ἀγῶνος παρεσκευάζοντο ὡς μεθέξοντες.", "st": "4.10"}, {"sp": "N", "t": "πέμπτῳ δὲ ἔτει τῆς Ἀριστοδήμου ⟨βασιλείας⟩ μελλόντων ἐκ προρρήσεως συμβολὴν ποιήσεσθαι—τῷ τε γὰρ μήκει τοῦ πολέμου καὶ τοῖς δαπανήμασιν ἀπειρήκεσαν—οὕτω παρεγένοντο ἀμφοτέροις καὶ οἱ σύμμαχοι, Λακεδαιμονίοις μὲν Κορίνθιοι Πελοποννησίων μόνοι, τοῖς δὲ Μεσσηνίοις οἵ τε Ἀρκάδες πανστρατιᾷ καὶ Ἀργείων καὶ Σικυωνίων λογάδες. Λακεδαιμόνιοι μὲν οὖν Κορινθίοις καὶ τοῖς εἵλωσι καὶ ὅσοι περίοικοι συνεστρατεύοντο τὸ μέσον ἐπιτρέψαντες, ἐπὶ τοῖς κέρασιν αὐτοί τε καὶ οἱ βασιλεῖς ἐτάσσοντο βαθείᾳ τε ὡς οὔπω πρότερον καὶ πυκνῇ τῇ φάλαγγι.", "st": "4.11"}, {"sp": "N", "t": "τῷ δὲ Ἀριστοδήμῳ καὶ τοῖς περὶ αὐτὸν διετάχθη τὰ ἐς τὴν μάχην οὕτως. ὅσοι τῶν Ἀρκάδων ἢ τῶν Μεσσηνίων τὰ μὲν σώματα ἦσαν ἐρρωμένοι καὶ ἀγαθοὶ τὰς ψυχάς, ὅπλα δὲ οὐκ εἶχον ἰσχυρά, τούτοις τῶν ὅπλων τὰ χρησιμώτατα ἐπέλεξε, καὶ ὡς τὸ ἔργον ἤπειγεν, ὁμοῦ τοῖς Ἀργείοις καὶ Σικυωνίοις καὶ τούτους ἔτασσε· τὴν δὲ φάλαγγα ἐπὶ πλέον ἥπλωσεν, ὡς μὴ κυκλωθεῖεν ὑπὸ τῶν ἐναντίων. προείδετο δὲ καὶ ὅπως τεταγμένοις σφίσι τὸ ὄρος ἡ Ἰθώμη κατὰ νώτου γίνοιτο. καὶ τούτοις μὲν Κλέοννιν ἐπέταξεν ἡγεμόνα·", "st": "4.11"}, {"sp": "N", "t": "αὐτὸς δὲ καὶ ὁ Δᾶμις ὑπέμενον ἔχοντες τοὺς ψιλούς, σφενδονήτας μὲν ἢ τοξότας ὀλίγους, ὁ δὲ ὄχλος ὁ πολὺς τοῖς τε σώμασιν ἦσαν ἐς τὰς ἐπιδρομὰς καὶ ἀναχωρήσεις ἐπιτήδειοι καὶ τῇ ὁπλίσει κοῦφοι· θώρακα γὰρ ἢ ἀσπίδα εἶχεν ⟨οὐχ⟩ ἕκαστος, ὅσοι δὲ ἠπόρουν τούτων, περιεβέβληντο αἰγῶν νάκας καὶ προβάτων, οἱ δὲ καὶ θηρίων δέρματα καὶ μάλιστα οἱ ὀρεινοὶ τῶν Ἀρκάδων λύκων τε καὶ ἄρκτων.", "st": "4.11"}, {"sp": "N", "t": "ἀκόντια δὲ ἕκαστος πολλά, οἱ δὲ καὶ λόγχας αὐτῶν ἔφερον. καὶ οὗτοι μὲν ἐλόχων τῆς Ἰθώμης ἔνθα ἔμελλον ἥκιστα ἔσεσθαι σύνοπτοι· οἱ δὲ ὁπλῖται τῶν Μεσσηνίων καὶ συμμάχων τήν τε ἔφοδον τὴν πρώτην τῶν Λακεδαιμονίων ὑπέμειναν καὶ μετὰ τοῦτο ἦσαν ἤδη καὶ τὰ ἄλλα ἀνδρεῖοι. ἀριθμῷ μὲν δὴ τῶν ἐναντίων ἀπελείποντο, λογάδες δὲ ὄντες ἐμάχοντο πρὸς δῆμον καὶ οὐχ ὁμοίως πρὸς κρείττους, ᾗ καὶ μᾶλλον τῇ τε ἄλλῃ προθυμίᾳ καὶ ταῖς ἐμπειρίαις ἐπὶ πολὺ ἀντεῖχον.", "st": "4.11"}, {"sp": "N", "t": "ἐνταῦθα καὶ ὁ στρατὸς τῶν Μεσσηνίων ὁ εὔζωνος, ἀφ’ οὗ καὶ τούτοις ἤρθη τὰ σημεῖα, ἐχρῶντο ἐπὶ τοὺς Λακεδαιμονίους δρόμῳ καὶ περιστάντες ἠκόντιζον ἐς τὰ πλάγια· ὅσοις δὲ καὶ ἐπὶ πλέον μετῆν τόλμης, προσέθεόν τε καὶ ἔτυπτον ἐκ χειρός. οἱ δὲ Λακεδαιμόνιοι, κίνδυνόν σφισι δεύτερον ἐν τῷ αὐτῷ καὶ οὕτως ἀνέλπιστον ὁρῶντες παρόντα, ὅμως οὔτε ἐταράχθησαν ἐπιστρεφόμενοί τε ἐς τοὺς ψιλοὺς ἀμύνεσθαι μὲν ἐπειρῶντο, διὰ δὲ τὴν κουφότητα οὐ χαλεπῶς ἀποφευγόντων ἀπορία τοῖς Λακεδαιμονίοις καὶ ἀπ’ αὐτῆς ἤδη καὶ ὀργὴ γίνεται.", "st": "4.11"}, {"sp": "N", "t": "πεφύκασι δέ πως οἱ ἄνθρωποι μάλιστα ἔχειν ἀκρατῶς πρὸς τὰ παρ’ ἀξίαν· καὶ δὴ καὶ τότε οἵ τε ἤδη τραύματα τῶν Σπαρτιατῶν εἰληφότες καὶ ὅσοι κειμένων τῶν παραστατῶν ἐγίνοντο πρὸς τὴν ἔφοδον τῶν ψιλῶν πρῶτοι προεξέθεόν τε, ὁπότε ἴδοιεν ἐπιφερομένους τοὺς ψιλούς, καὶ ὑπὸ θυμοῦ μακροτέρας τὰς διώξεις ἐποιοῦντο ἀποχωρούντων. οἱ δὲ ψιλοὶ τῶν Μεσσηνίων ὡς τὸ πρῶτον ἤρξαντο, κατὰ χώραν τε μένοντας ἔτυπτον καὶ ἐσηκόντιζον καὶ διωκόντων ἔφθανον ἀποφεύγοντες καὶ πειρωμένοις ἀναστρέφειν αὖθις ἐπῄεσαν.", "st": "4.11"}, {"sp": "N", "t": "ταῦτα δὲ ἔδρων σποράδην καὶ ἄλλοι κατ’ ἄλλο τῆς τῶν ἐναντίων τάξεως· οἵ τε ὁπλῖται τῶν Μεσσηνίων καὶ συμμάχων θρασύτερον ἐν τῷ τοιῷδε τοῖς κατὰ στόμα αὐτῶν ἐπέκειντο. τέλος δὲ οἱ Λακεδαιμόνιοι τῷ τε χρόνῳ καὶ τοῖς τραύμασιν ἀπαγορεύοντες καὶ ἅμα παρὰ τὸ εἰωθὸς ὑπὸ τῶν ψιλῶν ταρασσόμενοι διαλύουσι τὴν τάξιν· τραπέντων δέ, ἐνταῦθά σφισι πλείω παρεῖχον κακὰ οἱ ψιλοί.", "st": "4.11"}, {"sp": "N", "t": "τοὺς δὲ τῶν Λακεδαιμονίων διαφθαρέντας ἐν τῇ μάχῃ συλλαβεῖν μὲν οὐχ οἷά τε ἦν ἀριθμῷ, πείθομαι δὲ εἶναι καὶ αὐτὸς πολλούς. ἡ δὲ οἴκαδε ἀναχώρησις τοῖς μὲν ἄλλοις καθ’ ἡσυχίαν, Κορινθίοις δὲ ἔμελλεν ἔσεσθαι χαλεπή· διὰ πολεμίας γὰρ ἐγίνετο ὁμοίως διά τε τῆς Ἀργείας πειρωμένοις καὶ παρὰ Σικυῶνα ἀνασωθῆναι.", "st": "4.11"}, {"sp": "N", "t": "Λακεδαιμονίους δὲ ἐλύπει μὲν καὶ τὸ γεγονὸς πταῖσμα, τεθνεώτων ἐν τῇ μάχῃ πολλῶν τε καὶ ἀξίων λόγου, παρίστατο δὲ καὶ ἐς τὴν πᾶσαν ἐλπίδα τοῦ πολέμου σφίσιν ἀθύμως ἔχειν· καὶ διὰ τοῦτο θεωροὺς ἀποστέλλουσιν ἐς Δελφούς. τούτοις ἐλθοῦσιν ἡ Πυθία χρᾷ τάδε·<br>οὔ σε μάχης μόνον ἔργ’ ἐφέπειν χερὶ Φοῖβος ἄνωγεν,<br>ἀλλ’ ἀπάτῃ μὲν ἔχει γαῖαν Μεσσηνίδα λαός,<br>ταῖς δ’ αὐταῖς τέχναισιν ἁλώσεται αἷσπερ ὑπῆρξεν.", "st": "4.12"}, {"sp": "N", "t": "[ὁ] πρὸς ταῦτα τοῖς βασιλεῦσι καὶ τοῖς ἐφόροις τέχνας μὲν [οὖν] προθυμουμένοις οὐκ ἐγίνετο ἀνευρεῖν· οἱ δὲ Ὀδυσσέως τῶν ἔργων ἀπομιμούμενοι τὸ ἐπὶ Ἰλίῳ πέμπουσιν ἄνδρας ἑκατὸν ἐς Ἰθώμην συνήσοντας ἃ μηχανῶνται, λόγῳ δὲ αὐτομόλους· ἦν δὲ καὶ φυγὴ τῶν ἀνδρῶν ἐκ τοῦ φανεροῦ κατεγνωσμένη. τούτους ἥκοντας ἀπέπεμπεν αὐτίκα Ἀριστόδημος, Λακεδαιμονίων φήσας τὰ ἀδικήματα καινὰ εἶναι, τὰ δὲ σοφίσματα ἀρχαῖα.", "st": "4.12"}, {"sp": "N", "t": "ἁμαρτόντες δὲ οἱ Λακεδαιμόνιοι τοῦ ἐγχειρήματος δεύτερα ἐπειρῶντο τῶν Μεσσηνίων διαλῦσαι τὸ συμμαχικόν· ἀντειπόντων δὲ τῶν Ἀρκάδων —παρὰ γὰρ τούτους πρότερον ἀφίκοντο οἱ πρέσβεις —οὕτω τὴν ἐπ’ Ἄργος ἐπέσχον πορείαν. Ἀριστόδημος δὲ πυνθανόμενος τὰ πρασσόμενα ὑπὸ τῶν Λακεδαιμονίων πέμπει καὶ αὐτὸς ἐρησομένους τὸν θεόν, ἡ δὲ Πυθία σφίσιν ἔχρησε·", "st": "4.12"}, {"sp": "N", "t": "κῦδός σοι πολέμοιο διδοῖ θεός· ἀλλ’ ἀπάταισι<br>φράζεο μὴ Σπάρτης δόλιος λόχος ἐχθρὸς ἀνέλθῃ<br>κρείσσων· ἦ γὰρ Ἄρης κείνων εὐήρεα τεύχη<br>καί ⟨τὸ⟩ χορῶν στεφάνωμα πικροὺς οἰκήτορας ἕξει,<br>τῶν δύο συντυχίαις κρυπτὸν λόχον ἐξαναδύντων.<br>οὐ πρόσθεν δὲ τέλος τόδ’ ἐπόψεται ἱερὸν ἦμαρ,<br>πρὶν τὰ παραλλά⟨ξαν⟩τα φύσιν τὸ[ξαν] χρεὼν ἀφίκηται.<br>τότε μὲν δὴ Ἀριστόδημος καὶ οἱ μάντεις ἀπείρως εἶχον συμβαλέσθαι τὸ εἰρημένον· ἔτεσι δὲ ὕστερον οὐ πολλοῖς ἀναφαίνειν τε καὶ ἐς τέλος ἄξειν ἔμελλεν ὁ θεός.", "st": "4.12"}, {"sp": "N", "t": "ἕτερα δὲ ἐν τῷ τότε τοῖς Μεσσηνίοις συνέβαινε τοιαῦτα. Λυκίσκου μετοικοῦντος ἐν Σπάρτῃ τὴν θυγατέρα ἐπέλαβεν ἀποθανεῖν, ἣν ἅμα ἀγόμενος ἔφυγεν ἐκ Μεσσήνης. πολλάκις δὲ αὐτὸν φοιτῶντα ἐπὶ τὸ μνῆμα τῆς παιδὸς λοχήσαντες ἱππεῖς τῶν Ἀρκάδων αἱροῦσιν· ἀναχθεὶς δὲ ἐς τὴν Ἰθώμην καὶ ἐς ἐκκλησίαν καταστὰς ἀπελογεῖτο ὡς οὐ προδιδοὺς τὴν πατρίδα ἀποχωρήσαι, πειθόμενος δὲ τοῖς ῥηθεῖσιν ὑπὸ τοῦ μάντεως ἐς τὴν παῖδα ὡς οὖσαν οὐ γνησίαν.", "st": "4.12"}, {"sp": "N", "t": "ταῦτα ἀπολογούμενος οὐ πρότερον ἔδοξεν ἀληθῆ λέγειν πρὶν ἢ παρῆλθεν ἐς τὸ θέατρον ἡ τὴν ἱερωσύνην τότε τῆς Ἥρας ἔχουσα. αὕτη δὲ τεκεῖν τε τὴν παῖδα ὡμολόγει καὶ τῇ Λυκίσκου γυναικὶ ὑποβαλέσθαι δοῦναι· “νῦν δὲ” ἔφη “τό τε ἀπόρρητον ἐκφαίνουσα ἥκω καὶ παύσουσα ἐμαυτὴν ἱερωμένην.” ταῦτα δὲ ἔλεγεν, ὅτι ἦν ἐν τῇ Μεσσήνῃ καθεστηκός, ἢν γυναικὸς ἱερωμένης ἢ καὶ ἀνδρὸς προαποθάνῃ τις τῶν παίδων, ἐς ἄλλον τὴν ἱερωσύνην μεταχωρεῖν. νομίζοντες οὖν τὴν γυναῖκα ἀληθῆ λέγειν, τῇ θεῷ τε εἵλοντο ἱερατευσομένην ἀντ’ ἐκείνης καὶ Λυκίσκον συγγνωστὰ ἔφασαν εἰργάσθαι.", "st": "4.12"}, {"sp": "N", "t": "μετὰ δὲ ταῦτα ἐδόκει σφίσι—καὶ γὰρ εἰκοστὸν ἔτος ἐπῄει τῷ πολέμῳ—πέμπειν αὖθις ἐς Δελφοὺς ἐρησομένους ὑπὲρ νίκης. ἐρομένοις δὲ ἔχρησεν ἡ Πυθία·<br>τοῖς τρίποδας περὶ βωμὸν Ἰθωμάτᾳ Διὶ πρώτοις<br>στήσασιν δεκάδων ἀριθμὸν δὶς πέντε δίδωσι<br>σὺν κύδει πολέμου γαῖαν Μεσσηνίδα δαίμων.<br>Ζεὺς γὰρ ἔνευσ’ οὕτως. ἀπάτη δέ σε πρόσθε τίθησιν<br>ἥ τ’ ὀπίσω τίσις ἐστί, καὶ ἔνθεον ἐξαπατῴης.<br>ἕρδ’ ὅππῃ τὸ χρεών· ἄτη δ’ ἄλλοισι πρὸ ἄλλων.", "st": "4.12"}, {"sp": "N", "t": "ταῦτ’ ἀκούσαντες γεγονέναι τε ἡγοῦντο ὑπὲρ αὑτῶν τὴν μαντείαν καὶ σφίσι διδόναι ⟨τὸ⟩ τοῦ πολέμου κράτος· οὐ γὰρ αὐτῶν γε ἐχόντων ἐντὸς τείχους τοῦ Ἰθωμάτα τὸ ἱερὸν Λακεδαιμονίους προτέρους ἀναθέντας φθήσεσθαι. καὶ οἱ μὲν ξυλίνους κατασκευάσεσθαι τρίποδας ἔμελλον, οὐ γάρ σφισι περιῆν χρήματα ὡς χαλκοῦς ποιήσασθαι· τῶν δέ τις Δελφῶν τὸν χρησμὸν ἐξήγγειλεν ἐς Σπάρτην. πυθομένοις δὲ ἐν κοινῷ μὲν οὐδέν σφισιν ἐξεγένετο ἀνευρεῖν σοφόν, Οἴβαλος δὲ", "st": "4.12"}, {"sp": "N", "t": "τὰ μὲν ἄλλα οὐ τῶν ἐπιφανῶν, γνώμην δὲ ὡς ἐδήλωσεν ἀγαθός, ποιησάμενος ὡς ἔτυχε πηλοῦ τρίποδας ἑκατόν, τούτους τε ἀποκεκρυμμένους ἐν πήρᾳ καὶ δίκτυα ἅμα αὐτοῖς ἔφερεν ὡς ἀνὴρ θηρευτής. ἅτε δὲ ὢν ἀγνὼς καὶ Λακεδαιμονίων τοῖς πολλοῖς, ῥᾷον Μεσσηνίους ἐλάνθανεν· ἀναμίξας δὲ αὑτὸν ἀνδράσιν ἀγροίκοις ἐσῆλθέ τε μετ’ αὐτῶν ἐς τὴν Ἰθώμην καὶ ὡς νὺξ τάχιστα ἐπελάμβανεν ἀναθεὶς τοὺς τρίποδας τῷ θεῷ τούτους δὴ τοὺς πηλίνους αὖθις ἐς Σπάρτην ἀπαγγελῶν Λακεδαιμονίοις ᾤχετο.", "st": "4.12"}, {"sp": "N", "t": "Μεσσηνίους δέ, ὡς εἶδον, ἐτάραξε μὲν μεγάλως, καὶ εἴκαζον—ὥσπερ ἦν—παρὰ Λακεδαιμονίων εἶναι· παρεμυθεῖτο δὲ ὅμως αὐτοὺς ὁ Ἀριστόδημος λέγων ἄλλα τε ἃ ἐν τοῖς παροῦσιν εἰκὸς ἦν καὶ τοὺς ξυλίνους τρίποδας—ἐπεποίηντο γὰρ ἤδη —περὶ τοῦ Ἰθωμάτα τὸν βωμὸν ἔστησε. συνέβη δὲ καὶ Ὀφιονέα τὸν μάντιν τοῦτον, τὸν ἐκ γενετῆς τυφλόν, ἀναβλέψαι παραλόγως δὴ μάλιστα ἀνθρώπων· ἐπέλαβε γὰρ τῆς κεφαλῆς ἄλγημα αὐτὸν ἰσχυρόν, καὶ ἀνέβλεψεν ἀπ’ αὐτοῦ.", "st": "4.12"}, {"sp": "N", "t": "τὰ δὲ ἐντεῦθεν—ἔρρεπε γὰρ ἤδη τὸ χρεὼν ἐς ἅλωσιν τῶν Μεσσηνίων—προεσήμαινεν αὐτοῖς τὰ μέλλοντα ὁ θεός. τό τε γὰρ τῆς Ἀρτέμιδος ἄγαλμα, ὂν χαλκοῦν καὶ αὐτὸ καὶ τὰ ὅπλα, παρῆκε τὴν ἀσπίδα· καὶ Ἀριστοδήμου τῷ Διὶ τῷ Ἰθωμάτᾳ θύειν μέλλοντος τὰ ἱερεῖα, οἱ κριοὶ ἐπὶ τὸν βωμὸν αὐτόματοι καὶ βίᾳ τὰ κέρατα ἐνράξαντες ἀποθνήσκουσιν ὑπὸ τῆς πληγῆς. τρίτον δὲ ἄλλο συνέβη σφίσιν· οἱ κύνες συνιόντες ἐς τὸ αὐτὸ ἀνὰ πᾶσαν νύκτα ὠρύοντο, τέλος δὲ καὶ ἀπεχώρησαν ἀθρόοι πρὸς τὸ τῶν Λακεδαιμονίων στρατόπεδον.", "st": "4.13"}, {"sp": "N", "t": "ταῦτά τε δὴ τὸν Ἀριστόδημον ἐτάρασσε καὶ ὀνείρατος ὄψις ἐπιγενομένη τοιάδε. ἔδοξεν ἐξιέναι οἱ μέλλοντι ἐς μάχην καὶ ὡπλισμένῳ τῶν ἱερείων τὰ σπλάγχνα ἐπὶ τραπέζῃ προκεῖσθαι, τὴν δέ οἱ θυγατέρα ἐπιφανῆναι μέλαιναν ἐσθῆτα ἔχουσαν καὶ φαίνουσαν τό τε στέρνον καὶ τὴν γαστέρα ἀνατετμημένα, ἀναφανεῖσαν δὲ ἀπορρῖψαι μὲν τὰ ἀπὸ τῆς τραπέζης, ἀφελέσθαι δὲ αὐτοῦ τὰ ὅπλα, ἀντὶ τούτων δὲ στέφανον ἐπιθεῖναι χρυσοῦν καὶ ἱμάτιον ἐπιβαλεῖν λευκόν.", "st": "4.13"}, {"sp": "N", "t": "ἔχοντος δὲ Ἀριστοδήμου τά τε ἄλλα ἀθύμως καὶ τὸν ὄνειρον ἡγουμένου προλέγειν οἱ τοῦ βίου τελευτήν, ὅτι οἱ Μεσσήνιοι τῶν ἐπιφανῶν τὰς ἐκφορὰς ἐποιοῦντο ἐστεφανωμένων καὶ ἱμάτια ἐπιβεβλημένων λευκά, ἀπαγγέλλει τις Ὀφιονέα τὸν μάντιν οὐχ ὁρᾶν ἔτι ἀλλ’ ἐξαίφνης γενέσθαι τυφλόν, ὥσπερ γε καὶ ἦν τὸ ἐξ ἀρχῆς. συνιᾶσι δὴ καὶ τοῦ χρησμοῦ τότε, ὡς τοὺς ἀναδύντας δύο ἐκ τοῦ λόχου καὶ ἐς τὸ χρεὼν αὖθις ἐλθόντας τοῦ Ὀφιονέως τοὺς ὀφθαλμοὺς εἶπεν ἡ Πυθία.", "st": "4.13"}, {"sp": "N", "t": "ἐνταῦθα Ἀριστόδημος τά τε οἰκεῖα ἀναλογιζόμενος, ὡς οὐδὲν ὠφέλιμον γένοιτο φονεὺς θυγατρός, καὶ τῇ πατρίδι οὐχ ὁρῶν ἔτι ὑποῦσαν σωτηρίας ἐλπίδα, ἐπικατέσφαξεν ἑαυτὸν τῆς παιδὸς τῷ τάφῳ, τὰ μὲν ἐς ἀνθρώπου λογισμὸν ἥκοντα Μεσσηνίους σώσας, τῆς τύχης δὲ ἐς τὸ μηδὲν ἀγαγούσης τά τε ἔργα αὐτοῦ καὶ τὰ βουλεύματα. ἀπέθανε δὲ βασιλεύσας ἔτη τε ἓξ καὶ ἐκ τοῦ ἑβδόμου μῆνας ἐπιλαβὼν ⟨οὐ⟩ πολλούς.", "st": "4.13"}, {"sp": "N", "t": "τοῖς δὲ Μεσσηνίοις ἀπεγνωκέναι τὰ πράγματα παρίστατο, ὥστε καὶ ὥρμησαν ἱκεσίαν ἐς τοὺς Λακεδαιμονίους ἀποστέλλειν· οὕτω σφόδρα κατέπληξεν αὐτοὺς ἡ τοῦ Ἀριστοδήμου τελευτή. καὶ τοῦτο μὲν ὁ θυμὸς ἐπέσχεν αὐτοὺς μὴ ποιῆσαι· συλλεγέντες δὲ ἐς ἐκκλησίαν βασιλέα μὲν οὐδένα, Δᾶμιν δὲ στρατηγὸν αὐτοκράτορα εἵλοντο. ὁ δὲ Κλέοννίν τε αὑτῷ καὶ Φυλέα ἑλόμενος συνάρχοντας παρεσκευάζετο ὡς καὶ ἐκ τῶν παρόντων συνάψων [ἐς] μάχην· ἐπηνάγκαζε γὰρ ἥ τε πολιορκία καὶ οὐχ ἥκιστα ὁ λιμὸς καὶ ἀπ’ αὐτοῦ δέος, μὴ καὶ προδιαφθαρῶσιν ὑπὸ ἐνδείας.", "st": "4.13"}, {"sp": "N", "t": "ἀρετῇ μὲν δὴ καὶ τολμήμασιν οὐδὲ τότε ἀπεδέησε τὰ τῶν Μεσσηνίων· ἀπέθανον δὲ οἵ τε στρατηγοί σφισιν ἅπαντες καὶ τῶν ἄλλων οἱ λόγου μάλιστα ἄξιοι. τὸ δὲ ἀπὸ τούτου μῆνας μέν που πέντε μάλιστα ἀντέσχον, περὶ δὲ τὸν ἐνιαυτὸν λήγοντα ἐξέλιπον τὴν Ἰθώμην, πολεμήσαντες ἔτη τὰ πάντα εἴκοσι, καθὰ καὶ Τυρταίῳ πεποιημένα ἐστίν·<br>εἰκοστῷ δ’ οἱ μὲν κατὰ πίονα ἔργα λιπόντες<br>φεῦγον Ἰθωμαίων ἐκ μεγάλων ὀρέων.", "st": "4.13"}, {"sp": "N", "t": "ὁ δὲ πόλεμος ἔλαβεν οὗτος τέλος ἔτει πρώτῳ τῆς τετάρτης καὶ δεκάτης Ὀλυμπιάδος, ἣν Δάσμων Κορίνθιος ἐνίκα στάδιον, Ἀθήνῃσι Μεδοντιδῶν τὴν ἀρχὴν ἔτι ἐχόντων τὴν δεκέτιν καὶ ἔτους Ἱππομένει τετάρτου τῆς ἀρχῆς ἠνυσμένου.", "st": "4.13"}, {"sp": "N", "t": "Μεσσηνίων δὲ ὅσοις μὲν ἔτυχον ἐν Σικυῶνι οὖσαι καὶ ἐν Ἄργει προξενίαι καὶ παρὰ τῶν Ἀρκάδων τισίν, οὗτοι μὲν ἐς ταύτας τὰς πόλεις ἀπεχώρησαν, ἐς Ἐλευσῖνα δὲ οἱ τοῦ γένους τῶν ἱερέων καὶ θεαῖς ταῖς Μεγάλαις τελοῦντες τὰ ὄργια· ὁ δὲ ὄχλος ὁ πολὺς κατὰ τὰς πατρίδας ἕκαστοι τὰς ἀρχαίας ἐσκεδάσθησαν.", "st": "4.14"}, {"sp": "N", "t": "Λακεδαιμόνιοι δὲ πρῶτα μὲν τὴν Ἰθώμην καθεῖλον ἐς ἔδαφος, ἔπειτα καὶ τὰς λοιπὰς πόλεις ἐπιόντες ᾕρουν. ἀνέθεσαν δὲ καὶ ἀπὸ τῶν λαφύρων τῷ Ἀμυκλαίῳ τρίποδας χαλκοῦς· Ἀφροδίτης ἄγαλμά ἐστιν ἑστηκὸς ὑπὸ τῷ τρίποδι τῷ πρώτῳ, Ἀρτέμιδος δὲ ὑπὸ τῷ δευτέρῳ, Κόρης δὲ ἢ Δήμητρος ὑπὸ τῷ τρίτῳ.", "st": "4.14"}, {"sp": "N", "t": "ταῦτα μὲν δὴ ἀνέθεσαν ἐνταῦθα, τῆς δὲ γῆς τῆς Μεσσηνίας Ἀσιναίοις μὲν ἀνεστηκόσιν ὑπὸ Ἀργείων διδόασιν ἐπὶ θαλάσσῃ ταύτην ἣν καὶ νῦν ἔτι οἱ Ἀσιναῖοι νέμονται· τοῖς δὲ Ἀνδροκλέους ἀπογόνοις—ἦν γὰρ δὴ καὶ θυγάτηρ Ἀνδροκλεῖ καὶ παῖδες τῆς θυγατρός, φεύγοντες δὲ ὑπὸ τὴν τελευτὴν τοῦ Ἀνδροκλέους ᾤχοντο ἐς Σπάρτην— τούτοις τὴν Ὑαμίαν καλουμένην ἀπονέμουσι.", "st": "4.14"}, {"sp": "N", "t": "τὰ δὲ ἐς αὐτοὺς Μεσσηνίους παρὰ Λακεδαιμονίων ἔσχεν οὕτως. πρῶτον μὲν αὐτοῖς ἐπάγουσιν ὅρκον μήτε ἀποστῆναί ποτε ἀπ’ αὐτῶν μήτε ἄλλο ἐργάσασθαι νεώτερον μηδέν· δεύτερα δὲ φόρον μὲν οὐδένα ἐπέταξαν εἰρημένον, οἳ δὲ τῶν γεωργουμένων τροφῶν σφισιν ἀπέφερον ἐς Σπάρτην πάντων τὰ ἡμίσεα. προείρητο δὲ καὶ ἐπὶ τὰς ἐκφορὰς τῶν βασιλέων καὶ ἄλλων τῶν ἐν τέλει καὶ ἄνδρας ἐκ τῆς Μεσσηνίας καὶ τὰς γυναῖκας ἐν ἐσθῆτι ἥκειν μελαίνῃ· καὶ τοῖς παραβᾶσιν ἐπέκειτο ποινή.", "st": "4.14"}, {"sp": "N", "t": "⟨ἐς⟩ τιμωρίας δὲ ἃς ὕβριζον ἐς τοὺς Μεσσηνίους, Τυρταίῳ πεποιημένα ἐστὶν<br>ὥσπερ ὄνοι μεγάλοις ἄχθεσι τειρόμενοι,<br>δεσποσύνοισι φέροντες ἀναγκαίης ὑπὸ λυγρῆς<br>ἥμισυ πᾶν ὅσσων καρπὸν ἄρουρα φέρει.<br>ὅτι δὲ καὶ συμπενθεῖν ἔκειτο αὐτοῖς ἀνάγκη, δεδήλωκεν ἐν τῷδε·<br>δεσπότας οἰμώζοντες, ὁμῶς ἄλοχοί τε καὶ αὐτοί,<br>εὖτέ τιν’ οὐλομένη μοῖρα κίχοι θανάτου.", "st": "4.14"}, {"sp": "N", "t": "τοιούτων οὖν οἱ Μεσσήνιοι κατειληφότων καὶ ἅμα ἐς τὰ μέλλοντα οὐδὲν ἐνορῶντες παρὰ τῶν Λακεδαιμονίων φιλάνθρωπον, πρό τε δὴ τῶν παρόντων τεθνάναι μαχομένους ἢ καὶ τὸ παράπαν ἐκ Πελοποννήσου φεύγοντας οἴχεσθαι νομίζοντες αἱρετώτερα, ἀφίστασθαι πάντως ἐγίνωσκον. ἐνῆγον δὲ οὐχ ἥκιστα ἐς τοῦτο καὶ οἱ νεώτεροι, πολέμου μὲν ἔτι ἀπείρως ἔχοντες, λαμπροὶ δὲ ὄντες τὰ φρονήματα καὶ ἀποθανεῖν προτιμῶντες ἐν ἐλευθέρᾳ τῇ πατρίδι, εἰ καὶ τὰ ἄλλα εὐδαιμόνως δουλεύειν παρείη.", "st": "4.14"}, {"sp": "N", "t": "ἐπετράφη δὲ νεότης καὶ ἀλλαχοῦ τῆς Μεσσηνίας, οἱ δὲ ἄριστοι καὶ ἀριθμὸν πλεῖστοι περὶ τὴν Ἀνδανίαν, ἐν δὲ αὐτοῖς καὶ Ἀριστομένης, ὃς καὶ νῦν ἔτι ὡς ἥρως ἔχει παρὰ Μεσσηνίοις τιμάς. καί οἱ καὶ τὰ τῆς γενέσεως ἐπιφανέστερα ὑπάρξαι νομίζουσι· Νικοτελείᾳ γὰρ τῇ μητρὶ αὐτοῦ δαίμονα ἢ θεὸν δράκοντι εἰκασμένον συγγενέσθαι λέγουσι. τοιαῦτα δὲ καὶ Μακεδόνας ἐπὶ Ὀλυμπιάδι καὶ ἐπὶ Ἀριστοδάμᾳ Σικυωνίους οἶδα εἰρηκότας, διάφορα δὲ τοσόνδε ἦν·", "st": "4.14"}, {"sp": "N", "t": "Μεσσήνιοι γὰρ οὐκ ἐσποιοῦσιν Ἀριστομένην Ἡρακλεῖ παῖδα ἢ Διί, ὥσπερ Ἀλέξανδρον Ἄμμωνι οἱ Μακεδόνες καὶ Ἄρατον Ἀσκληπιῷ Σικυώνιοι· Ἀριστομένει δὲ πατέρα Ἑλλήνων μὲν οἱ πολλοὶ Πύρρον φασὶν εἶναι, Μεσσηνίους δὲ οἶδα αὐτὸς ἐπὶ ταῖς σπονδαῖς Ἀριστομένην Νικομήδους καλοῦντας. οὗτος μὲν οὖν ἀκμάζων ἡλικίᾳ καὶ τόλμῃ καὶ ἄλλοι τῶν ἐν τέλει παρώξυνον ἐπὶ τὴν ἀπόστασιν· ἐπράσσετο δὲ ταῦτα οὐκ εὐθὺς ἐκ τοῦ φανεροῦ, κρύφα δὲ ἐς Ἄργος καὶ παρὰ τοὺς Ἀρκάδας ἀπέστελλον, εἴ σφισιν ἀπροφασίστως καὶ μηδὲν ἐνδεεστέρως ἢ ἐπὶ τοῦ πολέμου τοῦ προτέρου ἀμῦναι θελήσουσιν.", "st": "4.14"}, {"sp": "N", "t": "ὡς δὲ τά τε ἄλλα ἐς τὸν πόλεμον ἕτοιμα ἦν αὐτοῖς καὶ τὰ ἀπὸ τῶν συμμάχων προθυμότερα ἢ προσεδόκων—καὶ γὰρ Ἀργείοις ἤδη καὶ Ἀρκάσι λαμπρῶς τὸ ἐς τοὺς Λακεδαιμονίους ἔχθος ἐξῆπτο—οὕτως ἀπέστησαν ἔτει τριακοστῷ μὲν καὶ ἐνάτῳ μετὰ Ἰθώμης ἅλωσιν, τετάρτῳ δὲ τῆς τρίτης Ὀλυμπιάδος καὶ εἰκοστῆς, ἣν Ἴκαρος Ὑπερησιεὺς ἐνίκα στάδιον· Ἀθήνῃσι δὲ οἱ κατ’ ἐνιαυτὸν ἦσαν ἤδη τότε ἄρχοντες, καὶ Ἀθηναίοις Τλησίας ἦρχεν.", "st": "4.15"}, {"sp": "N", "t": "ἐν δὲ Λακεδαίμονι οἵ τινες τηνικαῦτα ἔτυχον βασιλεύοντες, Τυρταῖος μὲν τὰ ὀνόματα οὐκ ἔγραψε, Ῥιανὸς δ’ ἐποίησεν ἐν τοῖς ἔπεσι Λεωτυχίδην βασιλέα ἐπὶ τοῦδε εἶναι τοῦ πολέμου. Ῥιανῷ μὲν οὖν ἔγωγε οὐδαμῶς κατά γε τοῦτο συνθήσομαι· Τυρταῖον δὲ καὶ οὐ λέγοντα ὅμως εἰρηκέναι τις ἂν ἐν τῷδε ἡγοῖτο. ἐλεγεῖα γὰρ ἐς τὸν πρότερόν ἐστιν αὐτῷ πόλεμον·<br>ἀμφ’ αὐτῇ δ’ ἐμάχοντ’ ἐννέα καὶ δέκ’ ἔτη<br>νωλεμέως, αἰεὶ ταλασίφρονα θυμὸν ἔχοντες,<br>αἰχμηταὶ πατέρων ἡμετέρων πατέρες.", "st": "4.15"}, {"sp": "N", "t": "δῆλα οὖν ἐστιν ὡς ὕστερον τρίτῃ γενεᾷ τὸν πόλεμον οἱ Μεσσήνιοι τόνδε ἐπολέμησαν, ἀποδείκνυσί τε τοῦ χρόνου τὸ συνεχὲς βασιλεύοντας τηνικαῦτα ἐν Σπάρτῃ Ἀνάξανδρον Εὐρυκράτους τοῦ Πολυδώρου, τῆς δὲ οἰκίας τῆς ἑτέρας Ἀναξίδαμον Ζευξιδάμου τοῦ Ἀρχιδάμου τοῦ Θεοπόμπου. κατέβην δὲ ἐς ἀπόγονον Θεοπόμπου τέταρτον, ὅτι Ἀρχίδαμος ὁ Θεοπόμπου προαπέθανε τοῦ πατρὸς καὶ ἐς Ζευξίδαμον υἱιδοῦν ὄντα ἡ Θεοπόμπου περιῆλθεν ἀρχή. Λεωτυχίδης δὲ μετὰ Δημάρατον βασιλεύσας φαίνεται τὸν Ἀρίστωνος· Θεοπόμπου δὲ Ἀρίστων ἀπόγονος ἕβδομος.", "st": "4.15"}, {"sp": "N", "t": "τότε δὲ οἱ Μεσσήνιοι Λακεδαιμονίοις συμβάλλουσιν ἐν Δέραις καλουμέναις τῆς σφετέρας, ἔτει πρώτῳ μετὰ τὴν ἀπόστασιν· ἀπῆσαν δὲ ἀμφοτέροις οἱ σύμμαχοι. καὶ νίκη μὲν ἐγένετο οὐδετέρων σαφής, Ἀριστομένην δὲ ἔργα φασὶν ἀποδείξασθαι πλέον τι ἢ ἄνδρα ἕνα εἰκὸς ἦν, ὥστε καὶ βασιλέα μετὰ τὴν μάχην ᾑροῦντο αὐτόν, ἦν γὰρ καὶ γένους τῶν Αἰπυτιδῶν·", "st": "4.15"}, {"sp": "N", "t": "παραιτουμένου τε, οὕτω στρατηγὸν αὐτοκράτορα εἵλοντο. Ἀριστομένει δὲ παρίστατο μηδ’ ἂν ἄλλον ἀπαξιῶσαι παθεῖν τι ἐν πολέμῳ δράσαντα ἄξια μνήμης· αὑτῷ μέντοι καὶ πρὸ παντὸς ἐνόμιζεν εἶναι, ἔτι ἀρχομένου τοῦ πολέμου Λακεδαιμονίους καταπλήξαντα φαίνεσθαι καὶ ἐς τὰ μέλλοντά σφισι φοβερώτερον. ἅτε δὲ οὕτως ἔχων, ἀφικόμενος νύκτωρ ἐς τὴν Λακεδαίμονα ἀνατίθησιν ἀσπίδα πρὸς τὸν τῆς Χαλκιοίκου ναόν· ἐπεγέγραπτο δὲ Ἀριστομένην ἀπὸ Σπαρτιατῶν διδόναι τῇ θεῷ.", "st": "4.15"}, {"sp": "N", "t": "ἐγένετο δὲ καὶ Λακεδαιμονίοις μάντευμα ἐκ Δελφῶν τὸν Ἀθηναῖον ἐπάγεσθαι σύμβουλον. ἀποστέλλουσιν οὖν παρὰ τοὺς Ἀθηναίους τόν τε χρησμὸν ἀπαγγελοῦντας καὶ ἄνδρα αἰτοῦντας παραινέσοντα ἃ χρή σφισιν. Ἀθηναῖοι δὲ οὐδέτερα θέλοντες, οὔτε Λακεδαιμονίους ἄνευ μεγάλων κινδύνων προσλαβεῖν μοῖραν τῶν ἐν Πελοποννήσῳ τὴν ἀρίστην οὔτε αὐτοὶ παρακοῦσαι τοῦ θεοῦ, πρὸς ταῦτα ἐξευρίσκουσι· καὶ ἦν γὰρ Τυρταῖος διδάσκαλος γραμμάτων νοῦν τε ἥκιστα ἔχειν δοκῶν καὶ τὸν ἕτερον τῶν ποδῶν χωλός, τοῦτον ἀποστέλλουσιν ἐς Σπάρτην. ὁ δὲ ἀφικόμενος ἰδίᾳ τε τοῖς ἐν τέλει καὶ συνάγων ὁπόσους τύχοι καὶ τὰ ἐλεγεῖα καὶ τὰ ἔπη σφίσι τὰ ἀνάπαιστα ᾖδεν.", "st": "4.15"}, {"sp": "N", "t": "ἐνιαυτῷ δὲ ὕστερον τοῦ περὶ τὰς Δέρας ἀγῶνος, ἡκόντων ἀμφοτέροις καὶ τῶν συμμάχων, παρεσκευάζοντο ὡς μάχην συνάψοντες ἐπὶ τῷ καλουμένῳ Κάπρου σήματι. Μεσσηνίοις μὲν οὖν Ἠλεῖοι καὶ Ἀρκάδες, ἔτι δὲ ἐξ Ἄργους ἀφίκετο καὶ Σικυῶνος βοήθεια. παρῆσαν δὲ καὶ ὅσοι πρότερον τῶν Μεσσηνίων ἔφευγον ἑκουσίως, ἐξ Ἐλευσῖνός τε, οἷς πάτριον δρᾶν τὰ ὄργια τῶν Μεγάλων θεῶν, καὶ οἱ Ἀνδροκλέους ἀπόγονοι· καὶ γὰρ οἱ συσπεύσαντες μάλιστά σφισιν ἦσαν οὗτοι.", "st": "4.15"}, {"sp": "N", "t": "Λακεδαιμονίοις δὲ ἦλθον Κορίνθιοι συμμαχήσοντες καὶ Λεπρεατῶν τινες κατὰ ἔχθος τὸ Ἠλείων· Ἀσιναίοις δὲ ὅρκοι πρὸς ἀμφοτέρους ἦσαν. τὸ δὲ χωρίον τοῦτο, Κάπρου σῆμα, ἔστι μὲν ἐν Στενυκλήρῳ τῆς Μεσσηνίας, Ἡρακλέα δὲ αὐτόθι ὅρκον ἐπὶ τομίων κάπρου τοῖς Νηλέως παισὶ δοῦναι καὶ λαβεῖν παρὰ ἐκείνων λέγουσιν.", "st": "4.15"}, {"sp": "N", "t": "ὡς δὲ ἀμφοτέροις προεθύσαντο οἱ μάντεις, Λακεδαιμονίοις μὲν Ἕκας ἀπόγονός τε καὶ ὁμώνυμος Ἕκα τοῦ σὺν τοῖς Ἀριστοδήμου παισὶν ἐλθόντος ἐς Σπάρτην, τοῖς δὲ Μεσσηνίοις Θέοκλος—ἐγεγόνει δὲ ὁ Θέοκλος οὗτος ἀπὸ Εὐμάντιδος, Εὔμαντιν δὲ ὄντα Ἠλεῖον τῶν Ἰαμιδῶν Κρεσφόντης ἐπηγάγετο ἐς Μεσσήνην—τότε δὲ παρόντων καὶ τῶν μάντεων σὺν φρονήματι ἀμφότεροι μᾶλλον ἠπείγοντο ἐς τὴν μάχην.", "st": "4.16"}, {"sp": "N", "t": "καὶ ἦν μὲν καὶ τὰ τῶν ἄλλων πρόθυμα, ὡς ἡλικίας ἕκαστος εἶχεν ἢ ῥώμης, μάλιστα δὲ Ἀνάξανδρός τε ὁ τῶν Λακεδαιμονίων βασιλεὺς καὶ οἱ περὶ αὐτὸν τῶν Σπαρτιατῶν· παρὰ Μεσσηνίων δὲ οἱ Ἀνδροκλέους ἀπόγονοι Φίντας καὶ Ἀνδροκλῆς καὶ οἱ συντεταγμένοι σφίσιν ἐπειρῶντο ἄνδρες ἀγαθοὶ γίνεσθαι. Τυρταῖος δὲ καὶ οἱ τῶν θεῶν ἱεροφάνται τῶν Μεγάλων ἔργου μὲν ἥπτοντο οὐδενός, τοὺς τελευταίους δὲ τῆς ἑαυτῶν ἑκάτεροι στρατιᾶς ἐπήγειρον.", "st": "4.16"}, {"sp": "N", "t": "κατὰ δὲ αὐτὸν Ἀριστομένην εἶχεν οὕτω. λογάδες περὶ αὐτὸν ὀγδοήκοντα ἦσαν Μεσσηνίων, ἡλικίαν τε γεγονότες ἐκείνῳ τὴν αὐτὴν καὶ ἕκαστος προτετιμῆσθαι μεγάλως νομίζων ὅτι ἠξίωτο Ἀριστομένει συντετάχθαι· ἦσαν δὲ καὶ αἰσθέσθαι δι’ ὀλίγου δεινοὶ τά τε παρ’ ἀλλήλων καὶ μάλιστα ἐκείνου καὶ ἀρχομένου τι δρᾶν καὶ ἔτι μέλλοντος. οὗτοι μὲν πρῶτον καὶ αὐτοὶ καὶ Ἀριστομένης πόνον εἶχον πολὺν κατ’ Ἀνάξανδρον καὶ τῶν Λακεδαιμονίων τεταγμένοι τοὺς ἀρίστους· λαμβάνοντες δὲ τραύματα ἀφειδῶς καὶ ἐς πᾶν προϊόντες ἀπονοίας τῷ τε χρόνῳ καὶ τοῖς τολμήμασιν ἐτρέψαντο τοὺς περὶ Ἀνάξανδρον.", "st": "4.16"}, {"sp": "N", "t": "τούτοις μὲν δὴ φεύγουσι διώκειν ἐπέταξεν ὁ Ἀριστομένης ἕτερον τῶν Μεσσηνίων λόχον· αὐτὸς δὲ ὁρμήσας πρὸς τὸ μάλιστα ἀνθεστηκός, ὡς ἐβιάσατο καὶ τούτους, ἐπ’ ἄλλους ἐτράπετο αὖθις. ταχὺ δὲ καὶ τούτους ὠσάμενος ἑτοιμότερον ἤδη πρὸς τοὺς ὑπομένοντας ἐπεφέρετο, ἐς ὃ πᾶσαν τῶν Λακεδαιμονίων τὴν τάξιν καὶ αὐτῶν ⟨καὶ⟩ τῶν συμμάχων συνέχεε· καὶ οὐχὶ σὺν αἰδοῖ φευγόντων οὐδὲ ἀναμένειν θελόντων ἔτι ἀλλήλους, ἐπέκειτό σφισι φοβερώτερος ἢ κατὰ ἀνδρὸς ἑνὸς εἶναι μανίαν.", "st": "4.16"}, {"sp": "N", "t": "ἔνθα δὴ καὶ παρ’ ἀχράδα πεφυκυῖάν που τοῦ πεδίου, παρὰ ταύτην Ἀριστομένην οὐκ εἴα παραθεῖν ὁ μάντις Θέοκλος· καθέζεσθαι γὰρ τοὺς Διοσκούρους ἔφασκεν ἐπὶ τῇ ἀχράδι. Ἀριστομένης δὲ εἴκων τῷ θυμῷ καὶ οὐκ ἀκροώμενος τὰ πάντα τοῦ μάντεως ὡς κατὰ τὴν ἀχράδα ἐγίνετο, ἀπόλλυσι τὴν ἀσπίδα, Λακεδαιμονίοις τε τὸ ἁμάρτημα τοῦ Ἀριστομένους παρέσχεν αὐτῶν ἀποσωθῆναί τινας ἐκ τῆς φυγῆς· διέτριψε γὰρ τὴν ἀσπίδα ἀνευρεῖν πειρώμενος.", "st": "4.16"}, {"sp": "N", "t": "Λακεδαιμονίων δὲ ἐχόντων ἀθύμως μετὰ τὴν πληγὴν καὶ ὡρμημένων καταθέσθαι τὸν πόλεμον, Τυρταῖός τε ἐλεγεῖα ᾄδων μετέπειθεν αὐτοὺς καὶ ἐς τοὺς λόχους ἀντὶ τῶν τεθνεώτων κατέλεγεν ἄνδρας ἐκ τῶν εἱλώτων. Ἀριστομένει δέ, ὡς ἀνέστρεψεν ἐς τὴν Ἀνδανίαν, ταινίας αἱ γυναῖκες καὶ τὰ ὡραῖα ἐπιβάλλουσαι τῶν ἀνθῶν ἐπέλεγον ᾆσμα τὸ καὶ ἐς ἡμᾶς ἔτι ᾀδόμενον<br>ἔς τε μέσον πεδίον Στενυκλήριον ἔς τ’ ὄρος ἄκρον<br>εἵπετ’ Ἀριστομένης τοῖς Λακεδαιμονίοις.<br>ἀνεσώσατο δὲ καὶ τὴν ἀσπίδα ἐκείνην, ἔς τε Δελφοὺς", "st": "4.16"}, {"sp": "N", "t": "ἀφικόμενος καὶ ὥς οἱ προσέταξεν ἡ Πυθία καταβὰς ἐς τὸ ἄδυτον ἱερὸν τοῦ Τροφωνίου τὸ ἐν Λεβαδείᾳ. ὕστερον δὲ τὴν ἀσπίδα ἀνέθηκεν ἐς Λεβάδειαν φέρων, ᾗ δὴ καὶ αὐτὸς εἶδον ἀνακειμένην· ἐπίθημα δέ ἐστιν αὐτῆς ἀετὸς τὰ πτερὰ ἑκατέρωθεν ἐκτετακὼς ἐς ἄκραν τὴν ἴτυν. τότε δὲ Ἀριστομένης ὡς ἐπανῆκεν ἐκ Βοιωτίας εὑρών τε παρὰ τῷ Τροφωνίῳ καὶ κομισάμενος τὴν ἀσπίδα, αὐτίκα ἔργων μειζόνων ἥπτετο.", "st": "4.16"}, {"sp": "N", "t": "συλλέξας δὲ ἄλλους τε τῶν Μεσσηνίων καὶ τοὺς περὶ ἑαυτὸν ἅμα ἔχων λογάδας, φυλάξας τὰ μετὰ ἑσπέραν ἦλθεν ἐπὶ πόλιν τῆς Λακωνικῆς, τὸ μὲν ἀρχαῖον ὄνομα καὶ ἐν Ὁμήρου καταλόγῳ Φᾶριν, ὑπὸ δὲ τῶν Σπαρτιατῶν καὶ προσοίκων καλουμένην Φαράς· ἐπὶ ταύτην ἀφικόμενος τούς τε πειρωμένους ἀμύνεσθαι διέφθειρε καὶ λείαν περιβαλλόμενος ἀπήλαυνεν ἐς τὴν Μεσσήνην. Λακεδαιμονίων δὲ ὁπλιτῶν καὶ Ἀναξάνδρου τοῦ βασιλέως ἐπιθεμένων καθ’ ὁδόν, ἐτρέψατό τε καὶ τούτους καὶ διώκειν τὸν Ἀνάξανδρον ὥρμητο· βληθεὶς δὲ ἀκοντίῳ τὸν γλουτὸν τὴν δίωξιν ἐπέσχεν, οὐ μέντοι τὴν λείαν γε ἣν ἤλαυνεν ἀφῃρέθη.", "st": "4.16"}, {"sp": "N", "t": "διαλιπὼν δὲ ὅσον ἀκεσθῆναι τὸ τραῦμα, ἐς μὲν αὐτὴν Σπάρτην ἔξοδον ποιούμενος νύκτωρ ἀπετράπετο ὑπὸ φασμάτων Ἑλένης καὶ Διοσκούρων, τὰς δ’ ἐν Καρύαις παρθένους χορευούσας τῇ Ἀρτέμιδι. ἐλόχησε μεθ’ ἡμέραν καὶ συνέλαβεν ὅσαι χρήμασιν αὐτῶν καὶ ἀξιώματι πατέρων προεῖχον· ἀγαγὼν δὲ ἐς κώμην τῆς Μεσσηνίας τὴν νύκτα ἀνεπαύετο, ἀνδράσι τῶν ἐκ τοῦ λόχου τὴν φρουρὰν ἐπιτρέψας τῶν παρθένων.", "st": "4.16"}, {"sp": "N", "t": "ἐνταῦθα ὑπὸ μέθης οἱ νεανίσκοι δοκεῖν ἐμοὶ καὶ ἄλλως ἀκρατῶς ἔχοντες λογισμοῦ πρὸς βίαν ἐτρέποντο τῶν παρθένων, Ἀριστομένους δὲ ἀπείργοντος οὐ νομιζόμενα Ἕλλησι δρῶντας οὐδένα ἐποιοῦντο λόγον, ὥστε ἠναγκάσθη καὶ ἀποκτεῖναι τοὺς παροινοῦντας μάλιστα ἐξ αὐτῶν. τὰς δὲ αἰχμαλώτους λαβὼν ἀπέλυσε χρημάτων πολλῶν, παρθένους ὥσπερ γε καὶ εἷλεν.", "st": "4.16"}, {"sp": "N", "t": "ἔστι δὲ Αἴγιλα τῆς Λακωνικῆς, ἔνθα ἱερὸν ἵδρυται ἅγιον Δήμητρος. ἐνταῦθα ἐπιστάμενος ὁ Ἀριστομένης καὶ οἱ σὺν αὐτῷ τὰς γυναῖκας ἀγούσας ἑορτὴν … ἀμύνεσθαι τῶν γυναικῶν οὐκ ἄνευ τῆς θεοῦ προαχθεισῶν λαμβάνουσιν οἱ πολλοὶ τῶν Μεσσηνίων τραύματα μαχαίραις τε, αἷς τὰ ἱερεῖα αἱ γυναῖκες ἔθυον, καὶ ὀβελοῖς, οἷς τὰ κρέα ἔπειρον ὀπτῶσαι· τὸν δὲ Ἀριστομένην τύπτουσαι ταῖς δᾳσὶ ζῶντα αἱροῦσιν. ἀπεσώθη δὲ ὅμως τῆς αὐτῆς ἐκείνης νυκτὸς ἐς τὴν Μεσσηνίαν. ἀφεῖναι δὲ αὐτὸν ἱέρεια τῆς Δήμητρος αἰτίαν ἔσχεν Ἀρχιδάμεια· ἀφῆκε δὲ οὐκ ἐπὶ χρήμασιν, ἀλλὰ ἐρῶσα ἔτυχεν αὐτοῦ πρότερον ἔτι, προὐφασίζετο δὲ ὡς Ἀριστομένης διακούσας τὰ δεσμὰ ἀποδρὰς οἴχοιτο.", "st": "4.17"}, {"sp": "N", "t": "τρίτῳ δὲ ἔτει τοῦ πολέμου μελλούσης γίνεσθαι συμβολῆς ἐπὶ τῇ καλουμένῃ Μεγάλῃ τάφρῳ καὶ Μεσσηνίοις Ἀρκάδων βεβοηθηκότων ἀπὸ πασῶν τῶν πόλεων, Ἀριστοκράτην τὸν Ἱκέτα Τραπεζούντιον, βασιλέα τῶν Ἀρκάδων καὶ στρατηγὸν ὄντα ἐν τῷ τότε, διαφθείρουσιν οἱ Λακεδαιμόνιοι χρήμασι. πρῶτοι γὰρ ὧν ἴσμεν Λακεδαιμόνιοι πολεμίῳ ἀνδρὶ δῶρα ἔδοσαν, καὶ ὤνιον πρῶτοι κατεστήσαντο εἶναι τὸ κράτος τὸ ἐν τοῖς ὅπλοις·", "st": "4.17"}, {"sp": "N", "t": "πρὶν δὲ ἢ παρανομῆσαι Λακεδαιμονίους ἐς τὸν Μεσσηνίων πόλεμον καὶ Ἀριστοκράτους τοῦ Ἀρκάδος τὴν προδοσίαν, ἀρετῇ τε οἱ μαχόμενοι καὶ τύχαις ἐκ τοῦ θεοῦ διεκρίνοντο. φαίνονται δὲ οἱ Λακεδαιμόνιοι καὶ ὕστερον, ἡνίκα ἐπὶ Αἰγὸς ποταμοῖς ταῖς Ἀθηναίων ναυσὶν ἀνθώρμουν, ἄλλους τε τῶν στρατηγούντων Ἀθηναίοις καὶ Ἀδείμαντον ἐξωνησάμενοι.", "st": "4.17"}, {"sp": "N", "t": "περιῆλθε μέντοι καὶ αὐτοὺς Λακεδαιμονίους ἀνὰ χρόνον ἡ Νεοπτολέμειος καλουμένη τίσις. Νεοπτολέμῳ γὰρ τῷ Ἀχιλλέως, ἀποκτείναντι Πρίαμον ἐπὶ τῇ ἐσχάρᾳ τοῦ Ἑρκείου, συνέπεσε καὶ αὐτὸν ἐν Δελφοῖς πρὸς τῷ βωμῷ τοῦ Ἀπόλλωνος ἀποσφαγῆναι· καὶ ἀπὸ τούτου τὸ παθεῖν ὁποῖόν τις καὶ ἔδρασε Νεοπτολέμειον τίσιν ὀνομάζουσι.", "st": "4.17"}, {"sp": "N", "t": "τοῖς οὖν Λακεδαιμονίοις, ὅτε δὴ μάλιστα ἤνθησαν καὶ Ἀθηναίων τε τὸ ναυτικὸν καθῃρήκεσαν καὶ Ἀγησίλαος κεχείρωτο τὰ πολλὰ ἤδη τῆς Ἀσίας, τότε σφίσι τὴν ἀρχὴν πᾶσαν οὐκ ἐξεγένετο ἀφελέσθαι τὸν Μῆδον, ἀλλὰ σφᾶς ὁ βάρβαρος περιῆλθε τῷ ἐκείνων εὑρήματι, ἐς Κόρινθον καὶ Ἄργος καὶ ἐς Ἀθήνας τε καὶ Θήβας χρήματα ἀποστείλας· ὅ τε ὀνομαζόμενος Κορινθιακὸς πόλεμος ἀπὸ τούτων ἐξήφθη τῶν χρημάτων, ὡς ἀπολείπειν Ἀγησίλαον ἀναγκασθῆναι τὰ ἐν τῇ Ἀσίᾳ.", "st": "4.17"}, {"sp": "N", "t": "Λακεδαιμονίοις μὲν τὸ ἐς Μεσσηνίους σόφισμα ὁ δαίμων ἔμελλεν αὐτοῖς ἀποφανεῖν συμφοράν· Ἀριστοκράτης δὲ ὡς τὰ χρήματα ἐδέξατο ἐκ Λακεδαίμονος, τὸ μὲν παραυτίκα ἔκρυπτεν ἐς τοὺς Ἀρκάδας οἷα ἐπεβούλευε, μελλόντων δὲ ἐς χεῖρας ἤδη συνέρχεσθαι, τηνικαῦτα ἐξεφόβησεν αὐτοὺς ὡς ἐν δυσχωρίᾳ τέ εἰσιν ἀπειλημμένοι καὶ ἀναχώρησις οὐκ ἔσται αὐτοῖς, ἢν κρατηθῶσιν, τά τε ἱερά σφισιν οὐκ ἔφη γεγονέναι κατὰ γνώμην. ἐκέλευεν οὖν πάντα τινά, ἐπειδὰν αὐτὸς σημήνῃ, φυγῇ χρῆσθαι.", "st": "4.17"}, {"sp": "N", "t": "ὡς δὲ οἱ Λακεδαιμόνιοι συνέμισγον καὶ ἦσαν ἐς τὸ κατ’ αὐτοὺς οἱ Μεσσήνιοι τετραμμένοι, ἐνταῦθα Ἀριστοκράτης ἀρχομένης τῆς μάχης ἀπῆγε τοὺς Ἀρκάδας, καὶ τοῖς Μεσσηνίοις τό τε ἀριστερὸν καὶ μέσον ἠρήμωτο· οἱ γὰρ Ἀρκάδες σφίσιν εἶχον ἀμφότερα ἅτε ἀπόντων μὲν Ἠλείων τῆς μάχης, ἀπόντων δὲ Ἀργείων καὶ Σικυωνίων. προσεξειργάσθη δὲ καὶ ἄλλο τῷ Ἀριστοκράτει· διὰ γὰρ Μεσσηνίων ἐποιεῖτο τὴν φυγήν.", "st": "4.17"}, {"sp": "N", "t": "οἱ δὲ πρὸς τὸ ἀνέλπιστον τῶν παρόντων ἐγένοντο ἔκφρονες καὶ ἅμα ὑπὸ τῆς διεξόδου τῆς κατὰ σφᾶς τῶν Ἀρκάδων ἐταράσσοντο, ὥστε αὐτῶν ἐδέησαν οἱ πολλοὶ καὶ ἐπιλαθέσθαι τῶν ἐν χερσίν· ἀντὶ γὰρ τῶν Λακεδαιμονίων ἐπιφερομένων ἤδη πρὸς τοὺς Ἀρκάδας ἀφεώρων φεύγοντας, καὶ οἱ μὲν παραμεῖναί σφισιν ἱκέτευον, οἱ δὲ καὶ λοιδορίαις ἐς αὐτοὺς ὡς ἐς ἄνδρας προδότας καὶ οὐ δικαίους ἐχρῶντο.", "st": "4.17"}, {"sp": "N", "t": "Λακεδαιμονίοις δὲ ἥ τε κύκλωσις τῶν Μεσσηνίων μονωθέντων ἐγένετο οὐ χαλεπὴ καὶ νίκην ἑτοιμοτάτην πασῶν καὶ ἀπονώτατα ἀνείλοντο. Ἀριστομένης δὲ καὶ οἱ σὺν αὐτῷ συνέμειναν μὲν καὶ τῶν Λακεδαιμονίων τοὺς μάλιστα ἐγκειμένους ἀνείργειν ἐπειρῶντο, ὀλίγοι δὲ ὄντες οὐ μεγάλα ὠφέλουν. τῶν δὲ Μεσσηνίων τοῦ μὲν δήμου τοσοῦτον πλῆθος ἀνηλώθησαν, ὡς τὰ πρῶτα Λακεδαιμονίων δεσπότας ἀντὶ δούλων ἔσεσθαι νομίζοντας τότε μηδὲ ἐς τὴν σωτηρίαν αὐτὴν ἔτι ἔχειν ἐλπίδα· ἀπέθανον δὲ καὶ τῶν πρωτευόντων ἄλλοι τε καὶ Ἀνδροκλῆς καὶ Φίντας καὶ λόγου μάλιστα ἀξίως ἀγωνισάμενος Φάνας, ὃς πρότερον τούτων ἔτι δολίχου νίκην Ὀλυμπίασιν ἦν ἀνῃρημένος.", "st": "4.17"}, {"sp": "N", "t": "Ἀριστομένης δὲ μετὰ τὴν μάχην τοὺς διαπεφευγότας τῶν Μεσσηνίων συνήθροιζε, καὶ Ἀνδανίαν μὲν καὶ εἴ τι ἄλλο ἐν μεσογαίᾳ πόλισμα ἔπεισε τὰ πολλὰ ἐκλείπειν, ἐς δὲ τὴν Εἶραν τὸ ὄρος ἀνοικίζεσθαι. συνεληλαμένοις δὲ ἐς τοῦτο τὸ χωρίον προσεκάθηντο οἱ Λακεδαιμόνιοι πολιορκίᾳ σφᾶς αὐτίκα ἐξαιρήσειν νομίζοντες· ἀντήρκεσαν δὲ ὅμως οἱ Μεσσήνιοι καὶ μετὰ τὴν ἐν τῇ τάφρῳ συμφορὰν ἑνί τε καὶ δέκα ἔτεσιν ἀμυνόμενοι.", "st": "4.17"}, {"sp": "N", "t": "τὸν δὲ χρόνον τῆς πολιορκίας γενέσθαι τοσοῦτον δηλοῖ καὶ τάδε ἔπη Ῥιανοῦ πεποιημένα ἐς τοὺς Λακεδαιμονίους·<br>οὔρεος ἀργεννοῖο περὶ πτύχας ἐστρατόωντο<br>χείματά τε ποίας τε δύω καὶ εἴκοσι πάσας·<br>χειμῶνας γὰρ καὶ θέρη κατέλεξε, πόας εἰπὼν τὸν χλωρὸν σῖτον ἢ ὀλίγον πρὸ ἀμητοῦ.", "st": "4.17"}, {"sp": "N", "t": "Μεσσήνιοι δὲ ὡς ἐς τὴν Εἶραν ⟨ἀνῳκίσθησαν,⟩ τῆς δὲ ἄλλης ἐξείργοντο πλὴν ὅσον σφίσιν οἱ Πύλιοι τὰ ἐπὶ θαλάσσῃ καὶ οἱ Μοθωναῖοι διέσωζον, [ἢ] ἐλῄστευον τήν τε Λακωνικὴν καὶ τὴν σφετέραν, πολεμίαν ἤδη καὶ ταύτην νομίζοντες· ἄλλοι τε δὴ συνίσταντο ἐς τὰς καταδρομάς, ὡς ἕκαστοι τύχοιεν, καὶ Ἀριστομένης δὲ τοὺς περὶ αὑτὸν λογάδας ἐς τριακοσίων ἀριθμὸν προήγαγεν.", "st": "4.18"}, {"sp": "N", "t": "ἦγον μὲν δὴ τὰ Λακεδαιμονίων καὶ ἔφερον ὅ τι καὶ δύναιτο αὐτῶν ἕκαστος, ἑλόντες δὲ σῖτον καὶ βοσκήματα καὶ οἶνον ἀνήλισκον, ἔπιπλα δὲ καὶ ἀνθρώπους ἀπεδίδοσαν χρημάτων· ὥστε καὶ ἐποιήσαντο οἱ Λακεδαιμόνιοι δόγμα, ἅτε τοῖς ἐν τῇ Εἴρᾳ μᾶλλον ἢ σφίσιν αὐτοῖς γεωργοῦντες, τὴν Μεσσηνίαν καὶ τῆς Λακωνικῆς τὴν προσεχῆ, ἕως ἂν πολεμῶσιν, ἐᾶν ἄσπορον.", "st": "4.18"}, {"sp": "N", "t": "καὶ ἀπὸ τούτου σιτοδεία ἐγένετο ἐν Σπάρτῃ καὶ ὁμοῦ τῇ σιτοδείᾳ στάσις· οὐ γὰρ ἠνείχοντο οἱ ταύτῃ τὰ κτήματα ἔχοντες τὰ σφέτερα ἀργὰ εἶναι. καὶ τούτοις μὲν τὰ διάφορα διέλυε Τυρταῖος· Ἀριστομένης δὲ ἔχων τοὺς λογάδας τὴν μὲν ἔξοδον περὶ βαθεῖαν ἐποιήσατο ἑσπέραν, ἔφθη δὲ ὑπὸ τάχους τὴν ἐς Ἀμύκλας ἀνύσας πρὸ ἀνίσχοντος ἡλίου, καὶ Ἀμύκλας τὸ πόλισμα εἷλέ τε καὶ διήρπασε καὶ τὴν ἀποχώρησιν ἐποιήσατο πρὶν ἢ τοὺς ἐκ τῆς Σπάρτης προσβοηθῆσαι.", "st": "4.18"}, {"sp": "N", "t": "κατέτρεχε δὲ καὶ ὕστερον τὴν χώραν, ἐς ὃ Λακεδαιμονίων λόχοις πλέον ἢ τοῖς ἡμίσεσι καὶ τοῖς βασιλεῦσιν ἀμφοτέροις συμβαλὼν ἄλλα τε ἔσχεν ἀμυνόμενος τραύματα καὶ πληγέντι ὑπὸ λίθου τὴν κεφαλὴν αὐτῷ σκοτοδινιῶσιν οἱ ὀφθαλμοί. καὶ πεσόντα ἀθρόοι τῶν Λακεδαιμονίων ἐπιδραμόντες ζῶντα αἱροῦσιν· ἥλωσαν δὲ καὶ τῶν περὶ αὐτὸν ἐς πεντήκοντα. τούτους ἔγνωσαν οἱ Λακεδαιμόνιοι ῥῖψαι πάντας ἐς τὸν Κεάδαν· ἐμβάλλουσι δὲ ἐνταῦθα οὓς ἂν ἐπὶ μεγίστοις τιμωρῶνται.", "st": "4.18"}, {"sp": "N", "t": "οἱ μὲν δὴ ἄλλοι Μεσσηνίων ἐσπίπτοντες ἀπώλλυντο αὐτίκα, Ἀριστομένην δὲ ἔς τε τὰ ἄλλα θεῶν τις καὶ δὴ καὶ τότε ἐφύλασσεν· οἱ δὲ ἀποσεμνύνοντες τὰ κατ’ αὐτὸν Ἀριστομένει φασὶν ἐμβληθέντι ἐς τὸν Κεάδαν ὄρνιθα τὸν ἀετὸν ὑποπέτεσθαι καὶ ἀνέχειν ταῖς πτέρυξιν, ἐς ὃ κατήνεγκεν αὐτὸν ἐς τὸ πέρας οὔτε πηρωθέντα οὐδὲν τοῦ σώματος οὔτε τραῦμά τι λαβόντα. ἔμελλε δὲ ἄρα καὶ αὐτόθεν ὁ δαίμων ἔξοδον ἀποφαίνειν αὐτῷ.", "st": "4.18"}, {"sp": "N", "t": "καὶ ὁ μὲν ὡς ἐς τὸ τέρμα ἦλθε τοῦ βαράθρου, κατεκλίθη τε καὶ ἐφελκυσάμενος τὴν χλαμύδα ἀνέμενεν ὡς πάντως οἱ ἀποθανεῖν πεπρωμένον· τρίτῃ δὲ ὕστερον ἡμέρᾳ ψόφου τε αἰσθάνεται καὶ ἐκκαλυψάμενος—ἐδύνατο δὲ ἤδη διὰ τοῦ σκότους διορᾶν—ἀλώπεκα εἶδεν ἁπτομένην τῶν νεκρῶν. ὑπονοήσας δὲ ἔσοδον εἶναι τῷ θηρίῳ ποθέν, ἀνέμενεν ἐγγύς οἱ τὴν ἀλώπεκα γενέσθαι, γενομένης δὲ λαμβάνεται· τῇ δὲ ἑτέρᾳ χειρί, ὁπότε ἐς αὐτὸν ἐπιστρέφοιτο, τὴν χλαμύδα προὔβαλλέν οἱ καὶ δάκνειν παρεῖχε. τὰ μὲν δὴ πλείω θεούσῃ συνέθει, τὰ δὲ ἄγαν δυσέξοδα καὶ ἐφείλκετο ὑπ’ αὐτῆς· ὀψὲ δέ ποτε ὀπήν τε εἶδεν ἀλώπεκι ἐς διάδυσιν ἱκανὴν καὶ φέγγος δι’ αὐτῆς.", "st": "4.18"}, {"sp": "N", "t": "καὶ τὴν μέν, ὡς ἀπὸ τοῦ Ἀριστομένους ἠλευθερώθη, τὸ φωλίον ἔμελλεν ὑποδέξεσθαι· Ἀριστομένης δὲ—οὐ γάρ τι ἡ ὀπὴ καὶ τούτῳ παρέχειν ἐδύνατο ἔξοδον—εὐρυτέραν τε ταῖς χερσὶν ἐποίησε καὶ οἴκαδε ἐς τὴν Εἶραν ἀποσώζεται, παραδόξῳ μὲν τῇ τύχῃ καὶ ἐς τὴν ἅλωσιν χρησάμενος, τὸ γάρ οἱ φρόνημα ἦν καὶ τὰ τολμήματα μείζονα ἢ ὡς ἐλπίσαι τινὰ Ἀριστομένην αἰχμάλωτον ἂν γενέσθαι, παραδοξοτέρα δέ ἐστι καὶ πάντων προδηλότατα οὐκ ἄνευ θεοῦ ἡ ἐκ τοῦ Κεάδα σωτηρία.", "st": "4.18"}, {"sp": "N", "t": "Λακεδαιμονίοις δὲ παραυτίκα μὲν ὑπὸ ἀνδρῶν ἀπηγγέλλετο αὐτομόλων, ὡς Ἀριστομένης ἐπανήκοι σῶς· νομιζομένου δὲ ἀπίστου κατὰ ταὐτὰ ἢ εἴ τινα τεθνεῶτα ἐλέγετο ἀναβιῶναι, παρ’ αὐτοῦ τοιόνδε Ἀριστομένους ὑπῆρξεν ἐς πίστιν. Κορίνθιοι Λακεδαιμονίοις δύναμιν ὡς συνεξαιρήσοντας τὴν Εἶραν ἀποστέλλουσι.", "st": "4.19"}, {"sp": "N", "t": "τούτους παρὰ τῶν κατασκόπων πυνθανόμενος ὁ Ἀριστομένης τῇ πορείᾳ τε ἀτακτότερον χρῆσθαι καὶ ταῖς στρατοπεδείαις ἀφυλάκτως, ἐπιτίθεται νύκτωρ σφίσι· καὶ τῶν τε ἄλλων καθευδόντων ἔτι ἐφόνευσε τοὺς πολλοὺς καὶ τοὺς ἡγεμόνας Ὑπερμενίδην καὶ Ἀχλαδαῖον καὶ Λυσίστρατον καὶ Σίδεκτον ἀποκτίννυσι. διαρπάσας δὲ καὶ τὴν σκηνὴν τὴν στρατηγίδα παρέστησεν εὖ εἰδέναι Σπαρτιάταις ὡς Ἀριστομένης καὶ οὐκ ἄλλος Μεσσηνίων ἐστὶν ὁ ταῦτα εἰργασμένος.", "st": "4.19"}, {"sp": "N", "t": "ἔθυσε δὲ καὶ τῷ Διὶ τῷ Ἰθωμάτᾳ τὴν θυσίαν ἣν ἑκατομφόνια ὀνομάζουσιν. αὕτη δὲ καθεστήκει μὲν ἐκ παλαιοτάτου, θύειν δὲ αὐτὴν Μεσσηνίων ἐνομίζετο ὁπόσοι πολεμίους ἄνδρας κατεργάσαιντο ἑκατόν. Ἀριστομένει δέ, ὅτε ἐπὶ Κάπρου σήματι ἐμαχέσατο, θύσαντι ἑκατομφόνια πρῶτον, δεύτερα ἤδη θῦσαι καὶ ὁ ἐν τῇ νυκτὶ τῶν Κορινθίων παρέσχε φόνος. τοῦτον μὲν δὴ λέγουσι καὶ ἐπὶ ταῖς ὕστερον θῦσαι καταδρομαῖς θυσίαν τρίτην, Λακεδαιμόνιοι δὲ—ἐπῄει γὰρ", "st": "4.19"}, {"sp": "N", "t": "Ὑακίνθια—πρὸς τοὺς ἐν τῇ Εἴρᾳ τεσσαράκοντα ἐποιήσαντο ἡμερῶν σπονδάς· καὶ αὐτοὶ μὲν ἀναχωρήσαντες οἴκαδε ἑώρταζον, Κρῆτες δὲ τοξόται— μετεπέμψαντο γὰρ ἔκ τε Λύκτου καὶ ἑτέρων πόλεων μισθωτούς—οὗτοί σφισιν ἀνὰ τὴν Μεσσηνίαν ἐπλανῶντο. Ἀριστομένην οὖν, ἅτε ἐν σπονδαῖς ἀπωτέρω τῆς Εἴρας γενόμενον καὶ προϊόντα ἀδεέστερον, ἑπτὰ ἄνδρες ἀπὸ τῶν τοξοτῶν τούτων ἐλόχησαν, συλλαβόντες δὲ τοῖς ἱμᾶσιν οἷς εἶχον ἐπὶ ταῖς φαρέτραις δέουσιν·", "st": "4.19"}, {"sp": "N", "t": "ἑσπέρα γὰρ ἐπῄει. δύο μὲν οὖν ἐς Σπάρτην ἀπ’ αὐτῶν ἐλθόντες Λακεδαιμονίοις Ἀριστομένην εὐηγγελίζοντο ἡλωκέναι· οἱ λοιποὶ δὲ ἀποχωροῦσιν ἐς ἀγρὸν τῶν ἐν τῇ Μεσσηνίᾳ. ἐνταῦθα ᾤκει κόρη σὺν μητρὶ παρθένος, πατρὸς ὀρφανή. τῇ δὲ προτέρᾳ νυκτὶ εἶδεν ὄψιν ἡ παῖς· λέοντα ἐς τὸν ἀγρὸν λύκοι σφίσιν ἤγαγον δεδεμένον καὶ οὐκ ἔχοντα ὄνυχας, αὐτὴ δὲ τοῦ δεσμοῦ τὸν λέοντα ἀπέλυσε καὶ ἀνευροῦσα ἔδωκε τοὺς ὄνυχας, οὕτω τε διασπασθῆναι τοὺς λύκους ἔδοξεν ὑπὸ τοῦ λέοντος.", "st": "4.19"}, {"sp": "N", "t": "τότε δὲ ὡς τὸν Ἀριστομένην ἐσάγουσιν οἱ Κρῆτες, συνεφρόνησεν ἡ παρθένος ὕπαρ ἥκειν τὸ ἐν τῇ νυκτί οἱ πεφηνὸς καὶ ἀνηρώτα τὴν μητέρα ὅστις εἴη· μαθοῦσα δὲ ἐπερρώσθη τε καὶ ἀπιδοῦσα ἐς αὐτὸν τὸ προσταχθὲν συνῆκεν. οἶνον οὖν τοῖς Κρησὶν ἐγχέουσα ἀνέδην, ὡς σφᾶς ἡ μέθη κατελάμβανεν, ὑφαιρεῖται τοῦ μάλιστα ὑπνωμένου τὸ ἐγχειρίδιον· τὰ μὲν δὴ δεσμὰ τοῦ Ἀριστομένους ἔτεμεν ἡ παρθένος, ὁ δὲ παραλαβὼν τὸ ξίφος ⟨ἐκείνους⟩ διειργάσατο. ταύτην τὴν παρθένον λαμβάνει γυναῖκα Γόργος Ἀριστομένους· ἐδίδου δὲ Ἀριστομένης τῇ παιδὶ ἐκτίνων σῶστρα, ἐπεὶ Γόργῳ οὐκ ἦν πω δέκατον καὶ ὄγδοον ἔτος, ὅτε ἔγημεν.", "st": "4.19"}, {"sp": "N", "t": "ἑνδεκάτῳ δὲ ἔτει τῆς πολιορκίας τήν τε Εἶραν ἐπέπρωτο ἁλῶναι καὶ ἀναστάτους γενέσθαι Μεσσηνίους, καὶ δή σφισιν ἐπετέλεσεν ὁ θεὸς Ἀριστομένει καὶ Θεόκλῳ χρησθέν τι. τούτοις γὰρ ἐλθοῦσιν ἐς Δελφοὺς μετὰ τὴν ἐπὶ τῇ τάφρῳ πληγὴν καὶ ἐπερομένοις ὑπὲρ σωτηρίας τοσόνδε εἶπεν ἡ Πυθία·<br>εὖτε τράγος πίνῃσι Νέδης ἑλικόρροον ὕδωρ,<br>οὐκέτι Μεσσήνην ῥύομαι· σχεδόθεν γὰρ ὄλεθρος.", "st": "4.20"}, {"sp": "N", "t": "εἰσὶ δὲ αἱ πηγαὶ τῆς Νέδας ἐν ὄρει τῷ Λυκαίῳ· προελθὼν δὲ ὁ ποταμὸς διὰ τῆς Ἀρκάδων καὶ ἐπιστρέψας αὖθις ἐς τὴν Μεσσηνίαν ὁρίζει τὰ ἐπὶ θαλάσσῃ Μεσσηνίοις καὶ Ἠλείοις τὴν γῆν. τότε δὲ οἳ μὲν τοὺς αἶγας τοὺς ἄρρενας ἐδεδοίκεσαν μὴ πίνωσιν ἀπὸ τῆς Νέδας· τοῖς δὲ ἄρα ὁ δαίμων προεσήμαινε τοιόνδε. τὸ δένδρον τὸν ἐρινεόν εἰσιν Ἑλλήνων οἳ καλοῦσιν ὀλύνθην, Μεσσήνιοι δὲ αὐτοὶ τράγον. τότε οὖν πρὸς τῇ Νέδᾳ πεφυκὼς ἐρινεὸς οὐκ ἐς εὐθὺ ηὔξητο, ἀλλὰ ἔς τε τὸ ῥεῦμα ἐπέστρεφε καὶ τοῦ ὕδατος ἄκροις τοῖς φύλλοις ἐπέψαυε.", "st": "4.20"}, {"sp": "N", "t": "θεασάμενος δὲ ὁ μάντις Θέοκλος συνεβάλετο ὡς τὸν τράγον τὸν πίνοντα ἐκ τῆς Νέδας προεῖπεν ἡ Πυθία τὸν ἐρινεὸν τοῦτον καὶ ὡς ἤδη Μεσσηνίοις ἥκει τὸ χρεών· καὶ ἐς μὲν τοὺς ἄλλους εἶχεν ἐν ἀπορρήτῳ, Ἀριστομένην δὲ πρός τε τὸν ἐρινεὸν ἤγαγε καὶ ἀνεδίδασκεν ὡς τῆς σωτηρίας ἐξήκοι σφίσιν ὁ χρόνος. Ἀριστομένης δὲ ἔχειν οὕτω πείθεται καὶ ἀναβολὴν οὐκέτι εἶναί σφισι, προενοήσατο δὲ καὶ ἐκ τῶν παρόντων.", "st": "4.20"}, {"sp": "N", "t": "καὶ ἦν γάρ τι ἐν ἀπορρήτῳ τοῖς Μεσσηνίοις, ἔμελλε δὲ ἀφανισθὲν ὑποβρύχιον τὴν Μεσσήνην κρύψειν τὸν πάντα αἰῶνα, φυλαχθὲν δὲ οἱ Λύκου τοῦ Πανδίονος χρησμοὶ Μεσσηνίους ἔλεγον χρόνῳ ποτὲ ἀνασώσεσθαι τὴν χώραν· τοῦτο δὴ ὁ Ἀριστομένης ἅτε ἐπιστάμενος τοὺς χρησμούς, ἐπεὶ νὺξ ἐγίνετο, ἐκόμιζε. παραγενόμενος δὲ ἔνθα τῆς Ἰθώμης ἦν τὸ ἐρημότατον, κατώρυξεν ἐς Ἰθώμην τὸ ὄρος, καὶ Δία Ἰθώμην ἔχοντα καὶ θεοὺς οἳ Μεσσηνίους ⟨ἐς⟩ ἐκεῖνο ἔσωζον φύλακας μεῖναι τῆς παρακαταθήκης αἰτούμενος, μηδὲ ἐπὶ Λακεδαιμονίοις ποιῆσαι τὴν μόνην καθόδου Μεσσηνίοις ἐλπίδα.", "st": "4.20"}, {"sp": "N", "t": "μετὰ δὲ τοῦτο τοῖς Μεσσηνίοις ἤρχετο, καθὸ καὶ Τρωσὶν ἔτι πρότερον, γίνεσθαι κακὰ ἀπὸ μοιχείας. ἐπεκράτουν μὲν αὐτοὶ [ἐπεὶ ἐκράτουν] τοῦ τε ὄρους καὶ τοῦ πρὸς τὴν Εἶραν ἄχρι τῆς Νέδας, ἦσαν δὲ οἰκήσεις καὶ ἔξω πυλῶν ἐνίοις. αὐτόμολος δὲ ἐς αὐτοὺς ἐκ τῆς Λακωνικῆς ἄλλος μὲν ἀφίκετο οὐδείς, οἰκέτης δὲ Ἐμπεράμου βουκόλος ἐλαύνων τοῦ δεσπότου τὰς βοῦς· ὁ δὲ Ἐμπέραμος ἦν ἀνὴρ ἐν Σπάρτῃ δόκιμος.", "st": "4.20"}, {"sp": "N", "t": "οὗτος ὁ βουκόλος ἔνεμεν οὐ πόρρω τῆς Νέδας. ἀνδρὸς οὖν τῶν Μεσσηνίων τῶν οὐκ ἐντὸς τείχους ἐχόντων οἴκησιν γυναῖκα εἶδεν ἐφ’ ὕδωρ ἐλθοῦσαν· ἐρασθεὶς δὲ διαλεχθῆναί τε ἐτόλμησε καὶ δοὺς δῶρα συγγίνεται. καὶ ἀπὸ τούτου τὸν ἄνδρα παρεφύλασσεν αὐτῆς, ὁπότε ἀποχωρήσειεν ἐς τὴν φρουράν. ἀνὰ μέρος δὲ τοῖς Μεσσηνίοις τῆς ἀκροπόλεως ἐπήγετο ἡ φυλακή· ταύτῃ γὰρ τοὺς πολεμίους μάλιστα ἐδεδοίκεσαν μὴ ὑπερβῶσιν αὐτοῖς ἐς τὴν πόλιν. ὁπότε οὖν οὗτος ἀποχωρήσειε, τηνικαῦτα ὁ βουκόλος ἐφοίτα παρὰ τὴν γυναῖκα.", "st": "4.20"}, {"sp": "N", "t": "καί ποτε ἔτυχε σὺν ἄλλοις ἐς ἐκεῖνον περιήκουσα ἐν τῇ νυκτὶ ⟨ἡ⟩ φυλακή, ἔτυχε δὲ καὶ ὕειν πολλῷ τὸν θεόν, καὶ ἐκλείπουσιν οἱ Μεσσήνιοι τὴν φρουράν· τὸ γὰρ ὕδωρ ἐβιάζετο σφᾶς ἀθρόον ἐκ τοῦ οὐρανοῦ καταχεόμενον, οὔτε ἐπάλξεων ἐνῳκοδομημένων οὔτε πύργων ὑπὸ σπουδῆς τοῦ τειχισμοῦ, καὶ ἅμα οὐδὲ κινήσεσθαι τοὺς Λακεδαιμονίους ἤλπιζον ἐν ἀσελήνῳ νυκτὶ καὶ οὕτω χειμερίῳ.", "st": "4.20"}, {"sp": "N", "t": "Ἀριστομένης δὲ οὐ πολλαῖς πρότερον ἡμέραις Κεφαλλῆνα ἔμπορον, ἑαυτῷ ξένον καὶ ἐσάγοντα ἐς τὴν Εἶραν ὁπόσων ἐδέοντο, ἑαλωκότα ὑπὸ Λακεδαιμονίων καὶ τοξοτῶν Ἀπτεραίων ὧν ἦρχεν Εὐρύαλος Σπαρτιάτης, τοῦτον τὸν Κεφαλλῆνα ἀφαιρούμενος ἐκεῖνον μὲν καὶ τὰ χρήματα ὁπόσα ἦγεν ἀπέσωσεν, αὐτὸς δὲ ἐτέτρωτο καὶ οὐκ ἐδύνατο ἐπιφοιτᾶν τοῖς φυλάσσουσι καθάπερ εἰώθει. τοῦτο μάλιστα αἴτιον ἐγένετο ἐκλειφθῆναι τὴν ἀκρόπολιν·", "st": "4.20"}, {"sp": "N", "t": "τῶν τε δὴ ἄλλων ἕκαστος ἀνεχώρησεν ἀπὸ τῆς φρουρᾶς καὶ τῆς ὑπὸ τοῦ βουκόλου μοιχευομένης ὁ ἀνήρ. ἡ δὲ τηνικαῦτα ἔνδον εἶχε τὸν βουκόλον, αἰσθάνεταί τε τοῦ ἀνδρὸς ἐπιόντος καὶ αὐτίκα ὡς τάχους εἶχεν ἀποκρύπτει τὸν ἄνθρωπον. ἐσελθόντα δὲ τὸν ἄνδρα ἐφιλοφρονεῖτο ὡς οὔπω πρότερον καὶ ἠρώτα καθ’ ἥν τινα αἰτίαν ἥκοι. ὁ δὲ οὔτε μεμοιχευμένην εἰδὼς οὔτε ἔνδον ὄντα τὸν βουκόλον ἐχρῆτο τῷ ἀληθεῖ λόγῳ, καὶ αὐτός τε διὰ τοῦ ὄμβρου τὸ βίαιον καὶ τῶν ἄλλων ἕκαστον ἔφασκεν ἀπολελοιπέναι τὴν φρουράν.", "st": "4.20"}, {"sp": "N", "t": "ἐπηκροᾶτο δὲ λέγοντος ὁ βουκόλος, καὶ ὡς ἀκριβῶς ἐπύθετο ἕκαστα, αὖθις ἐκ τῶν Μεσσηνίων ἐς τοὺς Λακεδαιμονίους ἀφίκετο αὐτόμολος. Λακεδαιμονίοις δὲ οἱ μὲν βασιλεῖς ἀπὸ στρατοπέδου τηνικαῦτα ἀπῆσαν, πολεμαρχῶν δὲ τότε Ἐμπέραμος ὁ τοῦ βουκόλου δεσπότης προσεκάθητο τῇ Εἴρᾳ. ἀφικόμενος οὖν ἐς τοῦτον πρῶτα μὲν τὸ ἐπὶ τῷ δρασμῷ παρῃτεῖτο ἁμάρτημα, δεύτερα δὲ ἀνεδίδασκεν ὡς τὴν Εἶραν ἐν τῷ παρόντι μάλιστα αἱρήσουσιν, αὐτὰ ἕκαστα ὁπόσα ᾔσθετο τοῦ Μεσσηνίου διηγούμενος.", "st": "4.20"}, {"sp": "N", "t": "ἔδοξέ τε δὴ λέγειν πιστὰ καὶ ἡγεῖτο Ἐμπεράμῳ καὶ τοῖς Σπαρτιάταις. ἦν δὲ ἡ πορεία χαλεπή σφισιν ἅτε ἐν σκότῳ καὶ οὐκ ἀνιέντος τοῦ ὑετοῦ· ὅμως δὲ ὑπὸ προθυμίας ἤνυσαν, καὶ ὡς κατὰ τὴν ἀκρόπολιν τῆς Εἴρας ἐγένοντο, ὑπερέβαινον κλίμακάς τε προστιθέντες καὶ ὅτῳ τις ἐδύνατο ἄλλῳ τρόπῳ. τοῖς δὲ Μεσσηνίοις παρείχετο μὲν τοῦ παρόντος κακοῦ καὶ ἄλλα αἴσθησιν, μάλιστα δὲ οἱ κύνες οὐ κατὰ τὰ εἰωθότα ὑλακτοῦντες, ἀλλὰ συνεχεστέρᾳ καὶ βιαιοτέρᾳ τῇ κραυγῇ χρώμενοι. γνόντες οὖν τὸν ὕστατον ὁμοῦ καὶ ἀναγκαιότατον σφᾶς ἀγῶνα ἐπειληφότα, οὐδὲ τὰ ὅπλα ἅπαντα ἀνελάμβανον, ἀλλ’ ὅτῳ προχείρῳ μάλιστα ἐντύχοι τις, ἁρπάζοντες ἤμυνον τῇ πατρίδι, ἣ μόνη σφίσιν ἐλείπετο ἐκ τῆς Μεσσηνίας πάσης.", "st": "4.21"}, {"sp": "N", "t": "πρῶτοι δὲ ᾔσθοντο ἔνδον τῶν πολεμίων ὄντων καὶ ἐβοήθουν ἐπ’ αὐτοὺς πρῶτοι Γόργος τε ὁ Ἀριστομένους καὶ Ἀριστομένης αὐτὸς Θέοκλός τε ὁ μάντις καὶ Μάντικλος ὁ Θεόκλου, σὺν δὲ αὐτοῖς Εὐεργετίδας ἀνὴρ καὶ ἄλλως ἐν Μεσσήνῃ τιμώμενος καὶ διὰ τὴν γυναῖκα ἐπὶ πλέον ἀξιώματος ἥκων· ἀδελφὴν γὰρ εἶχεν Ἀριστομένους Ἁγναγόραν. τότε δὲ οἱ μὲν ἄλλοι, συνιέντες ὡς ἐν δικτύοις εἰσὶν ἐσχημένοι, ὅμως καὶ ἐκ τῶν παρόντων εἶχόν τινα ἐλπίδα·", "st": "4.21"}, {"sp": "N", "t": "Ἀριστομένης δὲ καὶ ὁ μάντις ἠπίσταντο μὲν οὐδεμίαν ἔτι ἀναβολὴν ὀλέθρου Μεσσηνίοις οὖσαν, ἅτε εἰδότες καὶ τὸν χρησμὸν ὃν ᾐνίξατο ἐς τὸν τράγον· ἡ Πυθία, ἐπέκρυπτον δὲ οὐδὲν ἧσσον, καὶ ἦν σφισιν ἐς τοὺς ἄλλους ἀπόρρητον. ἐπιόντες δὲ τὴν πόλιν σπουδῇ καὶ ἐπὶ πάντας ἐρχόμενοι τοῖς τε ἐντυγχάνουσιν, ὁπότε αἰσθάνοιντο ὄντας Μεσσηνίους, παρεκελεύοντο ἄνδρας ἀγαθοὺς εἶναι καὶ ἐκ τῶν οἰκιῶν ἀνεκάλουν τοὺς ἔτι ὑπολειπομένους.", "st": "4.21"}, {"sp": "N", "t": "ἐν μὲν δὴ νυκτὶ οὐδὲν ἄξιον ἐπράχθη λόγου παρ’ οὐδετέρων· τοῖς μὲν γὰρ ἡ ἀπειρία τῶν τόπων καὶ ἡ τόλμα τοῦ Ἀριστομένους παρεῖχε μελλησμόν, τοῖς δὲ Μεσσηνίοις οὔτε παρὰ τῶν στρατηγῶν σύνθημα ἐγεγόνει φθάνοντας εἰληφέναι τάς τε δᾷδας, ἢ εἴ τινα λαμπτῆρα ἀλλοῖον ἅψαιτό τις, ὕων ἂν ἐσβέννυεν ὁ θεός.", "st": "4.21"}, {"sp": "N", "t": "ἐπειδὴ δὲ ἡμέρα τε ἦν καὶ ἀλλήλους καθορᾶν ἐδύναντο, ἐνταῦθα Ἀριστομένης καὶ Θέοκλος ἐπειρῶντο ἐς πᾶσαν ἀπόνοιαν προάγειν τοὺς Μεσσηνίους, ἄλλα τε ὁπόσα εἰκὸς ἦν διδάσκοντες καὶ Σμυρναίων τὰ τολμήματα ἀναμιμνήσκοντες, ὡς Ἰώνων μοῖρα ὄντες Γύγην τὸν Δασκύλου καὶ Λυδοὺς ἔχοντας σφῶν τὴν πόλιν ὑπὸ ἀρετῆς καὶ προθυμίας ἐκβάλοιεν.", "st": "4.21"}, {"sp": "N", "t": "οἱ Μεσσήνιοι δὲ ἀκούοντες ἀπονοίας τε ἐνεπίμπλαντο καὶ συνιστάμενοι καθ’ ὁπόσους ἕκαστοι τύχοιεν ἐφέροντο ἐς τοὺς Λακεδαιμονίους· ὥρμησαν δὲ καὶ γυναῖκες τῷ κεράμῳ καὶ ὅτῳ δύναιτο ἑκάστη τοὺς πολεμίους βάλλειν. τοῦτο μὲν δὴ μὴ δρᾶσαι σφᾶς μηδὲ ἐπιβῆναι τῶν τεγῶν τοῦ ὄμβρου τὸ βίαιον ἐπεκώλυε· λαβεῖν δὲ ὅπλα ἐτόλμησαν καὶ τοῖς ἀνδράσιν ἐπὶ πλέον αὗται τὴν τόλμαν ἐξῆψαν, ὁπότε καὶ τὰς γυναῖκας ἑώρων προτιμώσας συναπολέσθαι τῇ πατρίδι ἢ ἀχθῆναι δούλας ἐς Λακεδαίμονα, ὥστε κἂν παρελθεῖν ἐδυνήθησαν τὸ πεπρωμένον·", "st": "4.21"}, {"sp": "N", "t": "ἀλλὰ ὁ θεὸς τὸ ὕδωρ ἐπήγαγεν ἀθρόον μᾶλλον μετὰ ἰσχυροῦ τῶν βροντῶν τοῦ ψόφου καὶ τοὺς ὀφθαλμοὺς αὐτῶν ἐναντίαις ταῖς ἀστραπαῖς ἐξέπλησσε. τοῖς δὲ Λακεδαιμονίοις ταῦτα πάντα παρίστη φρόνημα, καὶ αὐτὸν ἀμύνειν σφίσιν ἔφασαν τὸν θεόν· καὶ—ἤστραπτε γὰρ τούτοις κατὰ δεξιὰ—ἀπέφαινεν Ἕκας ὁ μάντις ὡς αἴσιον εἴη τὸ σημεῖον.", "st": "4.21"}, {"sp": "N", "t": "οὗτος δὲ καὶ στρατήγημα ἐξεῦρε τοιόνδε. ἀριθμῷ καὶ πολὺ οἱ Λακεδαιμόνιοι περιῆσαν· ἅτε δὲ οὐκ ἐν εὐρυχωρίᾳ σφίσιν οὐδὲ κατὰ σύνταγμα ἐγγινομένης τῆς μάχης, ἄλλων δὲ ἐν ἄλλῳ τῆς πόλεως ποιουμένων τὸν ἀγῶνα, ἀχρείους ἀπὸ ἑκάστης τάξεως συνέβαινεν εἶναι τοὺς τελευταίους. τούτους ἐκέλευεν ἀποχωρήσαντας ἐς τὸ στρατόπεδον σιτίων μεταλαβεῖν καὶ ὕπνου καὶ αὖθις πρὸ ἑσπέρας ἥκειν τοῖς ὑπομενοῦσιν αὐτῶν διαδεξομένους τὸν πόνον.", "st": "4.21"}, {"sp": "N", "t": "καὶ οἳ μὲν ἀναπαυόμενοί τε καὶ ἀνὰ μέρος μαχόμενοι μᾶλλον ἀντήρκουν, τοῖς δὲ Μεσσηνίοις πανταχόθεν παρίστατο ἀπορία· μεθ’ ἡμέραν γὰρ ἀεὶ καὶ νύκτα συνεχῶς οἱ αὐτοὶ τρίτην ἠμύνοντο. ἤδη τε ἡμέρα ἦν καὶ ἥ τε ἀυπνία καὶ ἐκ τοῦ οὐρανοῦ τὸ ὕδωρ τε καὶ ῥῖγος ἐπίεζε σφᾶς, ὅ τε λιμὸς καὶ ἡ δίψα ἐπέκειτο· μάλιστα δὲ αἱ γυναῖκες ἀηθείᾳ τε πολέμου καὶ τῇ συνεχείᾳ τῆς ταλαιπωρίας ἀπειρήκεσαν.", "st": "4.21"}, {"sp": "N", "t": "παραστὰς οὖν ὁ μάντις Θέοκλος πρὸς Ἀριστομένην εἶπε· “τί μάτην τόνδε ἔχεις τὸν πόνον; ἁλῶναι Μεσσήνην πάντως ἐστὶ πεπρωμένον, συμφορὰν δὲ τὴν ἐν ὀφθαλμοῖς πάλαι τε ἡμῖν προεσήμαινεν ἡ Πυθία καὶ ἔναγχος ὁ ἐρινεὸς ἔδειξεν. ἐμοὶ μὲν οὖν ὁ θεὸς αὐτῷ κοινὴν πρὸς τὴν πατρίδα ἐπάγει τὴν τελευτήν· σὺ δὲ σώζειν μὲν ὡς δυνάμεως ἥκεις Μεσσηνίους, σώζειν δὲ καὶ σαυτόν.” ἐπεὶ δὲ εἶπε πρὸς τοῦτον, ἐπὶ τοὺς πολεμίους ἔθει· καί οἱ καὶ ἐς τοὺς Λακεδαιμονίους ἔπεισιν ἐκβοῆσαι τοσόνδε· “ἀλλ’ οὔ τοι τὸν πάντα γε χρόνον χαίροντες καρπώσεσθε τὰ Μεσσηνίων.”", "st": "4.21"}, {"sp": "N", "t": "μετὰ τοῦτο τοῖς καθ’ αὑτὸν ἀνθεστηκόσιν ἐμπεσὼν ἐκείνους τε ἔκτεινε καὶ αὐτὸς ἐτιτρώσκετο, προεμπλήσας δὲ τὸν θυμὸν τῷ φόνῳ τῶν ἐχθρῶν ἀφίησι τὴν ψυχήν. Ἀριστομένης δὲ ἀπὸ τῆς μάχης ὀπίσω τοὺς Μεσσηνίους ἀνεκάλει, πλὴν ὅσοι κατὰ ἀνδραγαθίαν αὐτῶν προεμάχοντο· τούτους δὲ εἴα κατὰ χώραν μένειν· τοῖς δὲ λοιποῖς προσέταξε τὰς γυναῖκας καὶ τὰ τέκνα ἐντὸς τῆς τάξεως ἔχοντας ἐπακολουθεῖν, ᾗπερ ἂν αὐτὸς παρέχηται διέξοδον.", "st": "4.21"}, {"sp": "N", "t": "καὶ τούτων μὲν τοῖς τελευταίοις Γόργον καὶ Μάντικλον ἐπέστησεν ἄρχοντας· αὐτὸς δὲ ἀναδραμὼν ἐς τοὺς προτεταγμένους τῆς τε κεφαλῆς τῷ νεύματι καὶ τοῦ δόρατος τῇ κινήσει δῆλος ἦν διέξοδόν τε αἰτούμενος καὶ ἀποχωρεῖν ἤδη βεβουλευμένος. τῷ τε οὖν Ἐμπεράμῳ καὶ Σπαρτιατῶν τοῖς παροῦσι διεῖναι τοὺς Μεσσηνίους ἤρεσκε μηδὲ λυσσῶντας ἀνθρώπους καὶ ἐς τὸ ἔσχατον ἀπονοίας ἥκοντας ἐξαγριᾶναι πέρα· καὶ ἅμα οὕτω σφᾶς ποιεῖν Ἕκας ὁ μάντις ἐκέλευεν.", "st": "4.21"}, {"sp": "N", "t": "οἱ δὲ Ἀρκάδες παραυτίκα τε τὴν κατάληψιν ἐπυνθάνοντο τῆς Εἴρας καὶ αὐτίκα τὸν Ἀριστοκράτην ἐκέλευον σφᾶς ἄγειν ὡς ἢ σώσοντας Μεσσηνίους ἢ σὺν αὐτοῖς ἀπολουμένους. ὁ δὲ ἅτε ἐκ τῆς Λακεδαίμονος δεδεγμένος δῶρα, οὔτε ἄγειν ἤθελεν εἰδέναι τε ἔφασκεν οὐδένα ἔτι Μεσσηνίων ὅτῳ καὶ ἀμυνοῦσιν ὄντα ὑπόλοιπον.", "st": "4.22"}, {"sp": "N", "t": "τότε δὲ ὡς σαφέστερον ᾐσθάνοντο περιόντας καὶ ἐκλείπειν τὴν Εἶραν βεβιασμένους, αὐτοὶ μὲν περὶ τὸ ὄρος σφᾶς τὸ Λύκαιον ἔμελλον ὑποδέξεσθαι, προετοιμασάμενοι καὶ ἐσθῆτα καὶ σιτία, ἄνδρας δὲ τῶν ἐν τέλει πέμπουσι παραμυθεῖσθαί τε τοὺς Μεσσηνίους καὶ ἡγεμόνας ἅμα τῆς πορείας γενέσθαι. καὶ τοὺς μέν, ὡς ἐς τὸ Λύκαιον ἀνεσώθησαν, ἐξένιζον καὶ τὰ ἄλλα εὐνοϊκῶς περιεῖπον οἱ Ἀρκάδες, κατανέμειν τε ἐς τὰς πόλεις ἤθελον καὶ ἀναδάσασθαι δι’ ἐκείνους τὴν γῆν·", "st": "4.22"}, {"sp": "N", "t": "Ἀριστομένει δὲ ὅ τε οἶκτος διαρπαζομένης τῆς Εἴρας καὶ τὸ μῖσος τὸ ἐς τοὺς Λακεδαιμονίους βούλευμα παρίστησι τοιόνδε. πεντακοσίους τῶν Μεσσηνίων, οὓς μάλιστα ἠπίστατο αὑτῶν ἀφειδῶς ἔχοντας, ἀποκρίνας ἀπὸ τοῦ πλήθους, ἤρετο σφᾶς ἐν ἐπηκόῳ τῶν τε ἄλλων Ἀρκάδων καὶ Ἀριστοκράτους, ἅτε ὄντα προδότην οὐκ εἰδώς—ἀνανδρίᾳ γὰρ καὶ ὑπὸ δειλίας φυγεῖν τότε ἤδη [Ἀριστοκράτην] τῆς μάχης καὶ οὐ διὰ κακίαν οὐδεμίαν ἐδόξαζεν αὐτόν, ὥστε ἐναντίον καὶ τούτου τοὺς πεντακοσίους ἤρετο—, εἰ τιμωροῦντες τῇ πατρίδι ἀποθνήσκειν σὺν αὑτῷ ἐθελήσουσι.", "st": "4.22"}, {"sp": "N", "t": "φαμένων δὲ ἐθέλειν ἀπεγύμνου τὸ πᾶν, ὡς πάντως τῆς ἐπιούσης ἑσπέρας ἐπὶ τὴν Σπάρτην ἄγειν μέλλοι· Λακεδαιμονίων γὰρ τότε δὴ μάλιστα ἐς τὴν Εἶραν ἀπῆσαν οἱ πολλοί, καὶ ἄλλοι τε ἐπεφοίτων φέροντες καὶ ἄγοντες τὰ Μεσσηνίων. “καὶ ἢν μὲν ἑλεῖν τὴν Σπάρτην καὶ κατασχεῖν δυνηθῶμεν”, ἔφασκεν ὁ Ἀριστομένης, “ἔστιν ἡμῖν ἀποδόντας Λακεδαιμονίοις τὰ ἐκείνων κομίσασθαι τὰ οἰκεῖα· ἁμαρτάνοντες δὲ ὁμοῦ ἀποθανούμεθά γε μνήμης καὶ τοῖς ἔπειτα ἄξια ἐργασάμενοι.”", "st": "4.22"}, {"sp": "N", "t": "ταῦτα εἰπόντος τῶν Ἀρκάδων ὅσον τριακόσιοι μετέχειν καὶ αὐτοὶ τοῦ τολμήματος ἤθελον. καὶ τότε μὲν ἐπεῖχον τῆς ἐξόδου, τὰ γὰρ ἱερὰ ἐγίνετο αὐτοῖς οὐ κατὰ γνώμην, τῇ δὲ ἐπιούσῃ τό τε ἀπόρρητον ἔγνωσαν σφῶν τοὺς Λακεδαιμονίους προπεπυσμένους καὶ αὐτοὶ δεύτερον ὑπὸ Ἀριστοκράτους προδεδομένοι· τὰ γὰρ τοῦ Ἀριστομένους βουλεύματα αὐτίκα ὁ Ἀριστοκράτης ἐγγράψας βιβλίῳ, καὶ τὸ βιβλίον ἐπιθεὶς τῶν οἰκετῶν ὃν ἠπίστατο ὄντα εὐνούστατον, παρὰ Ἀνάξανδρον ἀπέστελλεν ἐς Σπάρτην.", "st": "4.22"}, {"sp": "N", "t": "ἐπανιόντα δὲ τὸν οἰκέτην λοχῶσιν ἄνδρες τῶν Ἀρκάδων διάφοροι καὶ πρότερον τῷ Ἀριστοκράτει, σχόντες δέ τι καὶ ὕποπτον τότε ἐς αὐτόν. λοχήσαντες δὲ τὸν οἰκέτην ἐπανάγουσιν ἐς τοὺς Ἀρκάδας καὶ ἐπεδείκνυον ἐς τὸν δῆμον τὰ ἀντεπεσταλμένα ἐκ Λακεδαίμονος· ἐπέστελλε δὲ ὁ Ἀνάξανδρος, φυγήν τε αὐτῷ τὴν πρότερον ἀπὸ τῆς Μεγάλης τάφρου φάμενος οὐκ ἀνόνητον ἐκ Λακεδαιμονίων γενέσθαι, προσέσεσθαι δέ οἱ χάριν καὶ τῶν ἐν τῷ παρόντι μηνυμάτων.", "st": "4.22"}, {"sp": "N", "t": "ὡς δὲ ἀπηγγέλθη ταῦτα ἐς ἅπαντας, αὐτοί τε τὸν Ἀριστοκράτην ἔβαλλον οἱ Ἀρκάδες καὶ τοῖς Μεσσηνίοις διεκελεύοντο· οἱ δὲ ἐς τὸν Ἀριστομένην ἀπέβλεπον. καὶ ὁ μὲν ἐς τὴν γῆν ἀφορῶν ἔκλαιεν· τὸν δὲ Ἀριστοκράτην οἱ Ἀρκάδες καταλιθώσαντες τὸν μὲν τῶν ὅρων ἐκτὸς ἐκβάλλουσιν ἄταφον, στήλην δὲ ἀνέθεσαν ἐς τὸ τέμενος τοῦ Λυκαίου λέγουσαν πάντως ὁ χρόνος εὗρε δίκην ἀδίκῳ βασιλῆι,<br>εὗρε δὲ Μεσσήνης σὺν Διὶ τὸν προδότην<br>ῥηιδίως. χαλεπὸν δὲ λαθεῖν θεὸν ἄνδρ’ ἐπίορκον.<br>χαῖρε Ζεῦ βασιλεῦ, καὶ σάω Ἀρκαδίαν.", "st": "4.22"}, {"sp": "N", "t": "τῶν δὲ Μεσσηνίων ὁπόσοι περὶ τὴν Εἶραν ἢ καὶ ἑτέρωθί που τῆς Μεσσηνίας ἐγκατελήφθησαν, τούτους μὲν οἱ Λακεδαιμόνιοι προσένειμαν ἐς τὸ εἱλωτικόν· Πύλιοι δὲ καὶ Μοθωναῖοι καὶ ὅσοι τὰ παραθαλάσσια ᾤκουν, [καὶ] ναυσὶν ὑπὸ τὴν ἅλωσιν τῆς Εἴρας ἀπαίρουσιν ἐς Κυλλήνην τὸ ἐπίνειον τὸ Ἠλείων. ἐκεῖθεν δὲ παρὰ τοὺς ἐν Ἀρκαδίᾳ Μεσσηνίους ἀπέστελλον, ἐθέλοντες κοινῷ στόλῳ χώραν ἔνθα οἰκήσουσιν ἀναζητεῖν, καὶ Ἀριστομένην ἐκέλευον ἡγεῖσθαί σφισιν ἐς ἀποικίαν.", "st": "4.23"}, {"sp": "N", "t": "ὁ δὲ αὐτὸς μὲν ἕως ἂν περιῇ, πολεμήσειν Λακεδαιμονίοις ἔφασκεν, ἐπίστασθαι δὲ ἀκριβῶς ὡς ἀεί τι ἀναφύσεται τῇ Σπάρτῃ δι’ αὐτοῦ κακόν· ἐκείνοις δὲ Γόργον καὶ Μάντικλον ἔδωκεν ἡγεμόνας. ὁ δὲ Εὐεργετίδας ἐς μὲν τὸ Λύκαιον σὺν τοῖς ἄλλοις Μεσσηνίοις καὶ αὐτὸς ἀπεχώρησεν· ἐκεῖθεν δέ, ὡς ἑώρα τὸ βούλευμα διαπεπτωκὸς τῷ Ἀριστομένει τὸ ἐς τὴν κατάληψιν τῆς Σπάρτης, ἀναπείσας τῶν Μεσσηνίων ὡς πεντήκοντα ἐπάνεισιν ἐπὶ τοὺς Λακεδαιμονίους ἐς τὴν Εἶραν, καὶ ἐντυχὼν διαρπάζουσιν ἔτι τὰ ἐπινίκια", "st": "4.23"}, {"sp": "N", "t": "πένθος σφίσιν ἐποίησε. καὶ τὸν μὲν ἐνταῦθα ἐπιλαμβάνει τὸ χρεών, Ἀριστομένης δὲ ὡς τοὺς ἡγεμόνας τοῖς Μεσσηνίοις ἐπέταξεν ⟨ἰέναι⟩ ἐς Κυλλήνην, ὅστις ἐθέλοι μετέχειν τῆς ἀποικίας. καὶ μετέσχον ἅπαντες, πλὴν εἰ γῆράς τινα ἀπεῖργεν ἢ μηδὲ εὐπορῶν ἔτυχεν ἐς τὴν ἀποδημίαν· οὗτοι δὲ αὐτοῦ κατέμειναν παρὰ τοῖς Ἀρκάσιν.", "st": "4.23"}, {"sp": "N", "t": "ἑάλω δὲ ἡ Εἶρα καὶ ὁ πόλεμος ὁ δεύτερος Λακεδαιμονίων καὶ Μεσσηνίων τέλος ἔσχεν Ἀθηναίοις ἄρχοντος Αὐτοσθένους, ἔτει πρώτῳ τῆς ὀγδόης τε καὶ εἰκοστῆς Ὀλυμπιάδος, ἣν ἐνίκα Χίονις Λάκων.", "st": "4.23"}, {"sp": "N", "t": "ὡς δὲ ἐς τὴν Κυλλήνην οἱ Μεσσήνιοι συνελέχθησαν, τὸν μὲν παρόντα χειμῶνα ἔδοξεν αὐτοῦ χειμάζειν, καὶ τὴν ἀγοράν σφισι καὶ χρήματα οἱ Ἠλεῖοι παρεῖχον· ἅμα δὲ τῷ ἦρι ἐβουλεύοντο ποῖ χρὴ σταλῆναι. γνῶμαι δὲ ἦσαν Γόργου μὲν Ζάκυνθον τὴν ὑπὲρ Κεφαλληνίας καταλαβόντας καὶ νησιώτας ἀντὶ ἠπειρωτῶν γενομένους ναυσὶν ἐς τὰ παραθαλάσσια τῆς Λακωνικῆς ἐπιπλέοντας κακοῦν τὴν γῆν· Μάντικλος δὲ ἐκέλευε Μεσσήνης μὲν καὶ τοῦ Λακεδαιμονίων ἔχθους λαβεῖν λήθην, πλεύσαντας δὲ ἐς Σαρδὼ κτήσασθαι μεγίστην τε νῆσον καὶ εὐδαιμονίᾳ πρώτην.", "st": "4.23"}, {"sp": "N", "t": "ἐν τοσούτῳ δὲ Ἀναξίλας παρὰ τοὺς Μεσσηνίους ἀπέστελλεν ἐς Ἰταλίαν καλῶν. ὁ δὲ Ἀναξίλας ἐτυράννει μὲν Ῥηγίου, τέταρτος δὲ ἀπόγονος ἦν Ἀλκιδαμίδου· μετῴκησε δὲ Ἀλκιδαμίδας ἐκ Μεσσήνης ἐς Ῥήγιον μετὰ τὴν Ἀριστοδήμου τοῦ βασιλέως τελευτὴν καὶ Ἰθώμης τὴν ἅλωσιν. οὗτος οὖν ὁ Ἀναξίλας τοὺς Μεσσηνίους μετεπέμπετο· ἐλθοῦσί τε ἔλεγεν ὡς Ζαγκλαῖοι διάφοροι μέν εἰσιν αὐτῷ, χώραν δὲ εὐδαίμονα καὶ πόλιν ἐν καλῷ τῆς Σικελίας ἔχουσιν, ἃ δὴ σφίσιν ἐθέλειν ἔφη συγκατεργασάμενος δοῦναι. προσεμένων δὲ τὸν λόγον, οὕτως Ἀναξίλας διεβίβασεν ἐς Σικελίαν αὐτούς.", "st": "4.23"}, {"sp": "N", "t": "Ζάγκλην δὲ τὸ μὲν ἐξ ἀρχῆς κατέλαβον λῃσταί, καὶ ἐν ἐρήμῳ τῇ γῇ τειχίσαντες ὅσον περὶ τὸν λιμένα ὁρμητηρίῳ πρὸς τὰς καταδρομὰς καὶ ἐς τοὺς ἐπίπλους ἐχρῶντο· ἡγεμόνες δὲ ἦσαν αὐτῶν Κραταιμένης Σάμιος καὶ Περιήρης ἐκ Χαλκίδος. Περιήρει δὲ ὕστερον καὶ Κραταιμένει καὶ ἄλλους ἐπαγαγέσθαι τῶν Ἑλλήνων ἔδοξεν οἰκήτορας.", "st": "4.23"}, {"sp": "N", "t": "τότε δὲ τοὺς Ζαγκλαίους ὅ τε Ἀναξίλας ναυσὶν ἀνταναγομένους ἐνίκησε καὶ οἱ Μεσσήνιοι μάχῃ πεζῇ· Ζαγκλαῖοι δὲ κατὰ γῆν τε ὑπὸ Μεσσηνίων καὶ ναυσὶν ἅμα ἐκ θαλάσσης ὑπὸ Ῥηγίνων πολιορκούμενοι, καὶ ἁλισκομένου σφίσιν ἤδη τοῦ τείχους, ἐπί τε βωμοὺς θεῶν καὶ πρὸς τὰ ἱερὰ καταφεύγουσιν. Ἀναξίλας μὲν οὖν τοῖς Μεσσηνίοις παρεκελεύετο τούς τε ἱκετεύοντας Ζαγκλαίων ἀποκτείνειν καὶ τοὺς λοιποὺς γυναιξὶν ὁμοῦ καὶ παισὶν ἀνδραποδίσασθαι·", "st": "4.23"}, {"sp": "N", "t": "Γόργος δὲ καὶ Μάντικλος παρῃτοῦντο Ἀναξίλαν μὴ σφᾶς, ὑπὸ συγγενῶν ἀνδρῶν πεπονθότας ἀνόσια, ὅμοια αὐτοὺς ἐς ἀνθρώπους Ἕλληνας ἀναγκάσαι δρᾶσαι. μετὰ δὲ τοῦτο ἤδη τοὺς Ζαγκλαίους ἀνίστασαν ἀπὸ τῶν βωμῶν καὶ ὅρκους δόντες καὶ αὐτοὶ παρ’ ἐκείνων λαβόντες ᾤκησαν ἀμφότεροι κοινῇ· ὄνομα δὲ τῇ πόλει μετέθεσαν Μεσσήνην ἀντὶ Ζάγκλης καλεῖσθαι.", "st": "4.23"}, {"sp": "N", "t": "ταῦτα δὲ ἐπὶ τῆς Ὀλυμπιάδος ἐπράχθη τῆς ἐνάτης καὶ εἰκοστῆς, ἣν Χίονις Λάκων τὸ δεύτερον ἐνίκα, Μιλτιάδου παρ’ Ἀθηναίοις ἄρχοντος. Μάντικλος δὲ καὶ τὸ ἱερὸν Μεσσηνίοις τοῦ Ἡρακλέους ἐποίησε, καὶ ἔστιν ἐκτὸς τείχους ὁ θεὸς ἱδρυμένος, Ἡρακλῆς καλούμενος Μάντικλος, καθάπερ γε καὶ Ἄμμων ἐν Λιβύῃ καὶ ὁ ἐν Βαβυλῶνι Βῆλος ὁ μὲν ἀπὸ ἀνδρὸς Αἰγυπτίου Βήλου τοῦ Λιβύης ὄνομα ἔσχεν, Ἄμμων δὲ ἀπὸ τοῦ ἱδρυσαμένου ποιμένος. Μεσσηνίοις μὲν οὖν τοῖς φεύγουσιν ἐγεγόνει πέρας τῆς ἄλης·", "st": "4.23"}, {"sp": "N", "t": "Ἀριστομένης δὲ ὡς τὴν ἡγεμονίαν ἀπείπατο τῶν ἐς τὴν ἀποικίαν στελλομένων, τὰς θυγατέρας τὴν πρεσβυτάτην καὶ τὴν ἐπὶ ταύτῃ καὶ Ἁγναγόραν τὴν ἀδελφὴν τὴν μὲν Θάρυκι ἐς Φιγαλίαν, Δαμοθοΐδᾳ δὲ Λεπρεάτῃ καὶ Ἡραιεῖ Θεοπόμπῳ τὰς θυγατέρας συνῴκισεν· αὐτὸς δὲ ἀφικόμενος ἐς Δελφοὺς ἐχρῆτο τῷ θεῷ. καὶ τὸ μὲν τῷ Ἀριστομένει γενόμενον μάντευμα οὐ λέγεται·", "st": "4.24"}, {"sp": "N", "t": "Δαμαγήτῳ δὲ Ῥοδίῳ βασιλεύοντι ἐν Ἰαλυσῷ, τότε δὲ ἥκοντι παρὰ τὸν Ἀπόλλωνα καὶ ἐρωτῶντι ὁπόθεν ἀγαγέσθαι χρὴ γυναῖκα, ἔχρησεν ἡ Πυθία θυγατέρα ἀνδρὸς τῶν Ἑλλήνων τοῦ ἀρίστου λαβεῖν. ὁ δὲ—ἦν γὰρ καὶ τρίτη τῷ Ἀριστομένει θυγάτηρ— γαμεῖ ταύτην, Ἑλλήνων τῶν τότε ἐκεῖνον μακρῷ δή τινι ἄριστον νομίζων. Ἀριστομένης δὲ ἐς μὲν τὴν Ῥόδον ἀφίκετο σὺν τῇ θυγατρί, ἐκεῖθεν δὲ ἔς τε Σάρδεις ἐνενόει παρὰ Ἄρδυν τὸν Γύγου καὶ ἐς Ἐκβάτανα τὰ Μηδικὰ ἀναβῆναι παρὰ τὸν βασιλέα Φραόρτην·", "st": "4.24"}, {"sp": "N", "t": "ἀλλὰ γὰρ πρότερον τούτων συνέπεσεν ἀποθανεῖν αὐτῷ νοσήσαντι, οὐ γὰρ ἔδει συμφορὰν οὐδεμίαν Λακεδαιμονίοις ἔτι ἐξ Ἀριστομένους γενέσθαι. τελευτήσαντι δὲ αὐτῷ Δαμάγητος καὶ οἱ Ῥόδιοι μνῆμά τε ἐπιφανὲς ἐποίησαν καὶ ἔνεμον ἀπὸ ἐκείνου τιμάς. τὰ μὲν δὴ λεγόμενα ἐς τοὺς Διαγορίδας καλουμένους ἐν Ῥόδῳ, γεγονότας δὲ ἀπὸ Διαγόρου τοῦ Δαμαγήτου τοῦ Δωριέως τοῦ Δαμαγήτου τε καὶ τῆς Ἀριστομένους θυγατρός, παρῆκα, μὴ οὐ κατὰ καιρὸν δοκοίην γράφειν·", "st": "4.24"}, {"sp": "N", "t": "Λακεδαιμόνιοι δὲ τότε, ὡς ἐπεκράτησαν τῆς Μεσσηνίας, τὴν μὲν ἄλλην πλὴν τῆς Ἀσιναίων αὐτοὶ διελάγχανον, Μοθώνην δὲ Ναυπλιεῦσιν ἐδίδοσαν ἐκπεπτωκόσιν ἐκ Ναυπλίας ἔναγχος ὑπὸ Ἀργείων.", "st": "4.24"}, {"sp": "N", "t": "Μεσσηνίων δὲ τοὺς ἐγκαταληφθέντας ἐν τῇ γῇ, συντελοῦντας κατὰ ἀνάγκην ἐς τοὺς εἵλωτας, ἐπέλαβεν ἀπὸ Λακεδαιμονίων ὕστερον ἀποστῆναι κατὰ τὴν ἐνάτην Ὀλυμπιάδα καὶ ἑβδομηκοστήν, ἣν Κορίνθιος ἐνίκα Ξενοφῶν, Ἀρχιμήδους Ἀθήνῃσιν ἄρχοντος· ἀπέστησαν δὲ καιρὸν τοιόνδε εὑρόντες. Λακεδαιμονίων ἄνδρες ἀποθανεῖν ἐπὶ ἐγκλήματι ὅτῳ δὴ καταγνωσθέντες ἱκέται καταφεύγουσιν ἐς Ταίναρον· ἐντεῦθεν δὲ ἡ ἀρχὴ τῶν ἐφόρων ἀπὸ τοῦ βωμοῦ σφᾶς ἀποσπάσασα ἀπέκτεινε.", "st": "4.24"}, {"sp": "N", "t": "Σπαρτιάταις δὲ ἐν οὐδενὶ λόγῳ θεμένοις τοὺς ἱκέτας ἀπήντησεν ἐκ Ποσειδῶνος μήνιμα, καί σφισιν ἐς ἔδαφος τὴν πόλιν πᾶσαν κατέβαλεν ὁ θεός. ἐπὶ δὲ τῇ συμφορᾷ ταύτῃ καὶ τῶν εἱλώτων ὅσοι Μεσσήνιοι τὸ ἀρχαῖον ἦσαν, ἐς τὸ ὄρος τὴν Ἰθώμην ἀπέστησαν. Λακεδαιμόνιοι δὲ ἄλλα τε μετεπέμποντο συμμαχικὰ ἐπ’ αὐτοὺς καὶ Κίμωνα τὸν Μιλτιάδου πρόξενόν σφισιν ὄντα καὶ Ἀθηναίων δύναμιν· ἀφικομένους δὲ τοὺς Ἀθηναίους ὑποπτεῦσαι δοκοῦσιν ὡς τάχα νεωτερίσοντας καὶ ὑπὸ τῆς ὑποψίας ἀποπέμψασθαι μετ’ οὐ πολὺ ἐξ Ἰθώμης.", "st": "4.24"}, {"sp": "N", "t": "Ἀθηναῖοι δὲ τὴν ἐς αὐτοὺς τῶν Λακεδαιμονίων ὑπόνοιαν συνέντες Ἀργείοις τε φίλοι δι’ αὐτὸ ἐγένοντο καὶ Μεσσηνίων τοῖς ἐν Ἰθώμῃ πολιορκουμένοις ἐκπεσοῦσιν ὑποσπόνδοις ἔδοσαν Ναύπακτον, ἀφελόμενοι Λοκροὺς τοὺς πρὸς Αἰτωλίᾳ καλουμένους Ὀζόλας. τοῖς δὲ Μεσσηνίοις παρέσχεν ἀπελθεῖν ἐξ Ἰθώμης τοῦ τε χωρίου τὸ ἐχυρὸν καὶ ἅμα Λακεδαιμονίοις προεῖπεν ἡ Πυθία ἦ μὴν εἶναί σφισι δίκην ἁμαρτοῦσιν ἐς τοῦ Διὸς τοῦ Ἰθωμάτα τὸν ἱκέτην. ὑπόσπονδοι μὲν ἐκ Πελοποννήσου τούτων ἕνεκα ἀφείθησαν·", "st": "4.24"}, {"sp": "N", "t": "ἐπεὶ δὲ ἔσχον τὴν Ναύπακτον, οὐκ ἀπέχρη πόλιν τε αὐτοῖς καὶ χώραν εἰληφέναι παρὰ Ἀθηναίων, ἀλλὰ σφᾶς πόθος εἶχεν ἰσχυρὸς χερσὶ ταῖς αὑτῶν φανῆναι λόγου τι κεκτημένους ἄξιον. καὶ ἠπίσταντο γὰρ Οἰνιάδας Ἀκαρνάνων γῆν τε ἔχοντας ἀγαθὴν καὶ Ἀθηναίοις διαφόρους τὸν πάντα ὄντας χρόνον, στρατεύουσιν ἐπ’ αὐτούς. ὄντες δὲ ἀριθμῷ μὲν οὐ πλείους, ἀρετῇ δὲ καὶ πολὺ ἀμείνονες [ὄντες] τῇ σφετέρᾳ νικῶσι, καὶ ἐπολιόρκουν κατακεκλειμένους ἐς τὸ τεῖχος.", "st": "4.25"}, {"sp": "N", "t": "τὸ δὲ ἐντεῦθεν, οὐ γάρ τι τῶν τοῖς ἀνθρώποις εὑρημένων ἐς πολιορκίαν οἱ Μεσσήνιοι παρίεσαν, ἀλλὰ καὶ κλίμακας προστιθέντες ἐπειρῶντο ὑπερβαίνειν ἐς τὴν πόλιν καὶ ὑπώρυσσον κάτωθεν τὸ τεῖχος, μηχανήματά τε, ὁποῖα ἐνῆν δι’ ὀλίγου παρασκευάσασθαι, προσαγαγόντες ἀεί τι ἤρειπον· δείσαντες δὲ οἱ ἔνδον μὴ ἁλούσης τῆς πόλεως αὐτοί τε ἀπόλωνται καὶ αἱ γυναῖκές σφισι καὶ οἱ παῖδες ἐξανδραποδισθῶσιν, εἵλοντο ἀπελθεῖν ὑπόσπονδοι.", "st": "4.25"}, {"sp": "N", "t": "καὶ ἐνιαυτὸν μὲν μάλιστα οἱ Μεσσήνιοι κατέσχον τὴν πόλιν καὶ ἐνέμοντο τὴν χώραν· τῷ δὲ ἔτει τῷ ὑστέρῳ δύναμιν οἱ Ἀκαρνᾶνες ἀπὸ πασῶν συλλέξαντες τῶν πόλεων ἐβουλεύοντο ἐπὶ τὴν Ναύπακτον στρατεύειν. καὶ τοῦτο μὲν ἀπέδοξεν αὐτοῖς τήν τε πορείαν ὁρῶσιν, ὅτι ἔσεσθαι δι’ Αἰτωλῶν ἔμελλε πολεμίων ἀεί ποτε ὄντων, καὶ ἅμα τοὺς Ναυπακτίους κεκτῆσθαί τι ναυτικὸν ὑπώπτευον, ὥσπερ γε καὶ εἶχον, ἐπικρατούντων δὲ ἐκείνων τῆς θαλάσσης οὐδὲν εἶναι κατεργάσασθαι μέγα οὐδὲ στρατῷ πεζῷ·", "st": "4.25"}, {"sp": "N", "t": "μετεβουλεύετό τε δή σφισι ⟨καὶ⟩ αὐτίκα ἐπὶ Μεσσηνίους τρέπονται τοὺς ἐν Οἰνιάδαις. καὶ οἱ μὲν ὡς πολιορκήσοντες παρεσκευάζοντο· οὐ γάρ ποτε ὑπελάμβανον ἄνδρας οὕτως ὀλίγους ἐς τοσοῦτον ἀπονοίας ἥξειν ὡς μαχέσασθαι πρὸς τὴν Ἀκαρνάνων ἁπάντων στρατιάν. οἱ δὲ Μεσσήνιοι προητοιμασμένοι μὲν καὶ σῖτον καὶ τὰ ἄλλα ἦσαν ὁπόσα εἰκὸς ἦν, πολιορκίας πειράσεσθαι μακροτέρας ἐλπίζοντες·", "st": "4.25"}, {"sp": "N", "t": "παρίστατο δέ σφισι πρὸ τῆς μελλούσης πολιορκίας ἀγῶνα ἐκ τοῦ φανεροῦ ποιήσασθαι, μηδὲ ὄντας Μεσσηνίους, οἳ μηδὲ Λακεδαιμονίων ἀνδρίᾳ, τύχῃ δὲ ἠλαττώθησαν, καταπεπλῆχθαι τὸν ἥκοντα ὄχλον ἐξ Ἀκαρνανίας· τό τε Ἀθηναίων ἐν Μαραθῶνι ἔργον ἀνεμιμνήσκοντο, ὡς μυριάδες τριάκοντα ἐφθάρησαν τῶν Μήδων ὑπὸ ἀνδρῶν οὐδὲ ἐς μυρίους ἀριθμόν.", "st": "4.25"}, {"sp": "N", "t": "καθίσταντό τε δὴ τοῖς Ἀκαρνᾶσιν ἐς ἀγῶνα καὶ ὁ τρόπος λέγεται τῆς μάχης γενέσθαι τοιόσδε. οἳ μέν, ἅτε πλήθει προέχοντες πολύ, οὐ χαλεπῶς περιέβαλον τοὺς Μεσσηνίους, πλὴν ὅσον αἱ πύλαι τε ἀπεῖργον κατὰ νώτου τοῖς Μεσσηνίοις γινόμεναι καὶ οἱ ἀπὸ τοῦ τείχους τοῖς σφετέροις προθύμως ἀμύνοντες· ταύτῃ μὲν δὴ μὴ περισχεθῆναι σφᾶς ἐκώλυε, τὰ δὲ πλευρὰ ἀμφότερα ἐκυκλώσαντο αὐτῶν οἱ Ἀκαρνᾶνες καὶ ἐσηκόντιζον πανταχόθεν.", "st": "4.25"}, {"sp": "N", "t": "οἱ δὲ Μεσσήνιοι συνεστραμμένοι μετ’ ἀλλήλων, ὁπότε ἀθρόοι τοῖς Ἀκαρνᾶσιν ἐμπέσοιεν, ἐτάρασσον μὲν τοὺς κατὰ ταὐτὸ ἑστηκότας καὶ ἐφόνευόν τε αὐτῶν καὶ ἐτίτρωσκον πολλούς, τελέαν δὲ οὐκ ἐδύναντο ἐργάσασθαι φυγήν· ὅπου γὰρ τῆς τάξεως αἴσθοιντό τι οἱ Ἀκαρνᾶνες τῆς αὑτῶν ὑπὸ τῶν Μεσσηνίων διασπώμενον, κατὰ τοῦτο ἀμύνοντες τοῖς βιαζομένοις αὑτῶν ἀνεῖργον τοὺς Μεσσηνίους ἐπικρατοῦντες τῷ πλήθει.", "st": "4.25"}, {"sp": "N", "t": "οἱ δὲ ὁπότε ἀνακοπεῖεν, κατ’ ἄλλο αὖθις πειρώμενοι διακόψαι τὴν Ἀκαρνάνων φάλαγγα τὸ αὐτὸ ἂν ἔπασχον· ὅτῳ μὲν προσβάλλοιεν, διέσειόν τε καὶ τροπὴν ἐπὶ βραχὺ ἐποίουν, ἐπιρρεόντων δὲ αὖθις κατὰ τοῦτο σπουδῇ τῶν Ἀκαρνάνων ἀπετρέποντο ἄκοντες. γενομένου δὲ ἰσορρόπου τοῦ ἀγῶνος ἄχρι ἑσπέρας καὶ Ἀκαρνᾶσιν ὑπὸ τὴν ἐπιοῦσαν νύκτα ἐπελθούσης δυνάμεως ἀπὸ τῶν πόλεων, οὕτω τοῖς Μεσσηνίοις περιειστήκει πολιορκία.", "st": "4.25"}, {"sp": "N", "t": "καὶ ἁλῶναι μὲν κατὰ κράτος τὸ τεῖχος ἢ ὑπερβάντων τῶν Ἀκαρνάνων ἢ καὶ ἀπολιπεῖν βιασθεῖσιν αὐτοῖς τὴν φρουρὰν δέος ἦν οὐδέν· τὰ δὲ ἐπιτήδειά σφισι πάντα ὁμοίως ὀγδόῳ μηνὶ ἐξανήλωτο. ἐς μὲν δὴ τοὺς Ἀκαρνᾶνας ἐχρῶντο ἀπὸ τοῦ τείχους χλευασίᾳ, μὴ σφᾶς τὰ σιτία προδοῦναί ποτε ἂν μηδὲ ἐς ἔτος δέκατον πολιορκουμένους·", "st": "4.25"}, {"sp": "N", "t": "αὐτοὶ δὲ περὶ ὕπνον πρῶτον ἐξελθόντες ἐκ τῶν Οἰνιαδῶν, ⟨καὶ⟩ γενομένης τοῦ δρασμοῦ σφῶν τοῖς Ἀκαρνᾶσιν αἰσθήσεως [καὶ] ἐς μάχην ἀναγκασθέντες ἀφικέσθαι, περὶ τριακοσίους μὲν ἀποβάλλουσι καὶ πλείονας ἔτι αὐτοὶ τῶν ἐναντίων κατεργάζονται, τὸ δὲ πολὺ αὐτῶν διεκπίπτουσι διὰ τῶν Ἀκαρνάνων καὶ ἐπιλαμβανόμενοι τῆς Αἰτωλῶν ἐχόντων σφίσιν ἐπιτηδείως ἐς τὴν Ναύπακτον ἀνασώζονται.", "st": "4.25"}, {"sp": "N", "t": "τὸ δὲ ἀπὸ τούτου τόν τε ἄλλον χρόνον ἐνέκειτό σφισι τὸ ἐς Λακεδαιμονίους μῖσος καὶ τὴν ἔχθραν ἐς αὐτοὺς μάλιστα ἐπεδείξαντο ἐπὶ τοῦ γενομένου Πελοποννησίοις πρὸς Ἀθηναίους πολέμου· τήν τε γὰρ Ναύπακτον ὁρμητήριον ἐπὶ τῇ Πελοποννήσῳ παρείχοντο καὶ τοὺς ἐν τῇ Σφακτηρίᾳ Σπαρτιατῶν ἀποληφθέντας Μεσσηνίων σφενδονῆται τῶν ἐκ Ναυπάκτου συνεξεῖλον.", "st": "4.26"}, {"sp": "N", "t": "ἐπεὶ δὲ τὸ πταῖσμα ἐγένετο ⟨τὸ⟩ Ἀθηναίων ἐν Αἰγὸς ποταμοῖς, οὕτω καὶ ἐκ Ναυπάκτου τοὺς Μεσσηνίους ἐκβάλλουσιν οἱ Λακεδαιμόνιοι ναυσὶν ἐπικρατοῦντες, οἳ ἐς Σικελίαν τε παρὰ τοὺς συγγενεῖς καὶ ἐς Ῥήγιον ἐστάλησαν, τὸ πλεῖστον δὲ αὐτῶν ἔς τε Λιβύην ἀφίκετο καὶ Λιβύης ἐς Εὐεσπερίτας· οἱ γὰρ Εὐεσπερῖται πολέμῳ κακωθέντες ὑπὸ βαρβάρων προσοίκων πάντα τινὰ Ἕλληνα ἐπεκαλοῦντο σύνοικον. ἐς τούτους τῶν Μεσσηνίων τὸ πολὺ ἀπεχώρησεν· ἡγεμὼν δέ σφισιν ἦν Κόμων, ὃς καὶ περὶ τὴν Σφακτηρίαν ἐστρατήγησεν αὐτοῖς.", "st": "4.26"}, {"sp": "N", "t": "ἐνιαυτῷ δὲ πρότερον ἢ κατορθῶσαι Θηβαίους τὰ ἐν Λεύκτροις, προεσήμαινεν ὁ δαίμων Μεσσηνίοις τὴν ἐς Πελοπόννησον κάθοδον. τοῦτο μὲν γὰρ ἐν Μεσσήνῃ ⟨τῇ⟩ πρὸς τῷ πορθμῷ τὸν ἱερέα τοῦ Ἡρακλέους λέγουσιν ὀνείρατος ἰδεῖν ὄψιν—τὸν Ἡρακλέα ἔδοξε κληθῆναι τὸν Μάντικλον ἐπὶ ξενίᾳ ἐς Ἰθώμην ὑπὸ τοῦ Διός—, τοῦτο δὲ ἐν Εὐεσπερίταις Κόμων συγγενέσθαι νεκρᾷ τῇ μητρὶ ἐδόκει, συγγενομένου δὲ αὖθίς οἱ τὴν μητέρα ἀναβιῶναι. καὶ ὁ μὲν ἐπήλπιζεν Ἀθηναίων δυνηθέντων ναυτικῷ κάθοδον ἔσεσθαί σφισιν ἐς Ναύπακτον· τὸ δὲ ἄρα ἐδήλου τὸ ὄνειρον ἀνασώσεσθαι Μεσσήνην.", "st": "4.26"}, {"sp": "N", "t": "ἐγένετό τε οὐ μετὰ πολὺ ἐν Λεύκτροις Λακεδαιμονίων τὸ ἀτύχημα ὀφειλόμενον ἐκ παλαιοῦ· Ἀριστοδήμῳ γὰρ τῷ βασιλεύσαντι Μεσσηνίων ἐπὶ τελευτῇ τοῦ χρησμοῦ τοῦ δοθέντος ἐστὶν<br>ἕρδ’ ὅππῃ τὸ χρεών· ἄτη δ’ ἄλλοισι πρὸ ἄλλων·<br>ὡς ἐν μὲν τῷ παρόντι ἐκεῖνον δέον καὶ Μεσσηνίους κακῶς πρᾶξαι, χρόνῳ δὲ ὕστερον καὶ Λακεδαίμονα ἐπιληψομένης τῆς ἄτης.", "st": "4.26"}, {"sp": "N", "t": "τότε δὲ ἐν Λεύκτροις οἱ Θηβαῖοι νενικηκότες ἀγγέλους ἐς Ἰταλίαν τε καὶ Σικελίαν καὶ παρὰ τοὺς Εὐεσπερίτας ἀπέστελλον, ἔκ τε τῆς ἄλλης, εἴ πού τις Μεσσηνίων εἴη, πανταχόθεν ἀνεκάλουν ἐς Πελοπόννησον. οἱ δὲ θᾶσσον ἢ ὡς ἄν τις ἤλπισε συνελέχθησαν γῆς τε τῆς πατρίδος πόθῳ καὶ διὰ τὸ ἐς Λακεδαιμονίους μῖσος παραμεῖναν ἀεί σφισιν.", "st": "4.26"}, {"sp": "N", "t": "Ἐπαμινώνδᾳ δὲ οὔτε ἄλλως ἐφαίνετο ῥᾴδια ἀξιόμαχον πόλιν ἐποικίσαι Λακεδαιμονίοις οὔτε ὅπου χρὴ κτίσαι τῆς χώρας ἐξευρίσκει· τὴν γὰρ Ἀνδανίαν οἱ Μεσσήνιοι καὶ Οἰχαλίαν οὐκ ἔφασαν ἀνοικιεῖν, ὅτι αἱ συμφοραί σφισιν ἐγεγόνεσαν ἐνταῦθα οἰκοῦσιν. ἀποροῦντι οὖν αὐτῷ πρεσβύτην ἄνδρα, ἱεροφάντῃ μάλιστα εἰκασμένον, νύκτωρ φασὶν ἐπιστάντα εἰπεῖν· “σοὶ μὲν δῶρά ἐστι παρ’ ἐμοῦ κρατεῖν ὅτῳ ἂν μεθ’ ὅπλων ἐπέρχῃ· καὶ ἢν ἐξ ἀνθρώπων γένῃ, ἔγωγε ὦ Θηβαῖε ποιήσω μή ποτε ἀνώνυμον μηδὲ ἄδοξόν ⟨σε⟩ γενέσθαι. σὺ δὲ Μεσσηνίοις γῆν τε πατρίδα καὶ πόλεις ἀπόδος, ἐπειδὴ καὶ τὸ μήνιμα ἤδη σφίσι πέπαυται τὸ Διοσκούρων”.", "st": "4.26"}, {"sp": "N", "t": "Ἐπαμινώνδᾳ μὲν ταῦτα ἔλεγεν, Ἐπιτέλει δὲ τῷ Αἰσχίνου τάδε ἐμήνυε—στρατηγεῖν δὲ αὐτὸν οἱ Ἀργεῖοι τὸν Ἐπιτέλην καὶ Μεσσήνην ἀνοικίζειν ᾕρηντο— τοῦτον οὖν τὸν ἄνδρα ἐκέλευεν ὁ ὄνειρος, ἔνθα ἂν τῆς Ἰθώμης εὕρῃ πεφυκυῖαν σμίλακα καὶ μυρσίνην, τὸ μέσον ὀρύξαντα αὐτῶν ἀνασῶσαι τὴν γραῦν· κάμνειν γὰρ ἐν τῷ χαλκῷ καθειργμένην θαλάμῳ καὶ ἤδη λιποψυχεῖν αὐτήν. ὁ δὲ Ἐπιτέλης, ὡς ἐπελάμβανεν ἡμέρα, παραγενόμενος ἐς τὸ εἰρημένον χωρίον ἐπέτυχεν ὀρύσσων ὑδρίᾳ χαλκῇ, καὶ αὐτίκα παρὰ τὸν Ἐπαμινώνδαν", "st": "4.26"}, {"sp": "N", "t": "κομίσας τό τε ἐνύπνιον ἐξηγεῖτο καὶ αὐτὸν ἐκεῖνον τὸ πῶμα ἀφελόντα ἐκέλευεν ὅ τι ἐνείη σκοπεῖσθαι. ὁ δὲ θύσας καὶ εὐξάμενος τῷ πεφηνότι ὀνείρατι ἤνοιγε τὴν ὑδρίαν, ἀνοίξας δὲ εὗρε κασσίτερον ἐληλασμένον ἐς τὸ λεπτότατον· ἐπείλικτο δὲ ὥσπερ τὰ βιβλία. ἐνταῦθα τῶν Μεγάλων θεῶν ἐγέγραπτο ἡ τελετή, καὶ τοῦτο ἦν παρακαταθήκη τοῦ Ἀριστομένους. τοῦτον τὸν ἐπελθόντα τῷ Ἐπιτέλει καὶ Ἐπαμινώνδᾳ καθεύδουσι Καύκωνα εἶναι λέγουσιν, ὃς ἀφίκετο ἐξ Ἀθηνῶν ἐς Ἀνδανίαν παρὰ Μεσσήνην τὴν Τριόπα.", "st": "4.26"}, {"sp": "N", "t": "τὸ δὲ τῶν Τυνδάρεω παίδων μήνιμα ἐς τοὺς Μεσσηνίους ἤρξατο μὲν πρὸ τῆς ἐν Στενυκλήρῳ μάχης, γενέσθαι ⟨δὲ⟩ αὐτὸ δι’ αἰτίαν τοιάνδε εἰκάζω. μειράκια ὡραῖα ἐξ Ἀνδανίας, Πάνορμος καὶ Γώνιππος, τά τε ἄλλα οἰκείως εἶχον ἀλλήλοις καὶ κοινὰς ἐπὶ τὰς μάχας ἐξόδους καὶ καταδρομὰς ἐποιοῦντο ἐς τὴν Λακωνικήν.", "st": "4.27"}, {"sp": "N", "t": "Λακεδαιμονίων δὲ ἐπὶ στρατοπέδου Διοσκούροις ἑορτὴν ἀγόντων καὶ ἤδη πρὸς πότον καὶ παιδιὰς τετραμμένων μετὰ τὸ ἄριστον, ὁ Γώνιππος καὶ ὁ Πάνορμος χιτῶνας λευκοὺς καὶ χλαμύδας πορφυρᾶς ἐνδύντες ἐπί τε ἵππων τῶν καλλίστων ὀχούμενοι καὶ ἐπὶ ταῖς κεφαλαῖς πίλους, ἐν δὲ ταῖς χερσὶ δόρατα ἔχοντες ἐπιφαίνονται Λακεδαιμονίοις. οἱ δὲ ὡς εἶδον, προσεκύνουν τε καὶ εὔχοντο, ἀφῖχθαι δοκοῦντές σφισιν αὐτοὺς ἐς τὴν θυσίαν τοὺς Διοσκούρους.", "st": "4.27"}, {"sp": "N", "t": "οἱ νεανίσκοι δὲ ὡς ἅπαξ ἀνεμίχθησαν, διεξήλαυνον διὰ πάντων παίοντες τοῖς δόρασι, καὶ ἤδη κειμένων πολλῶν ἀποχωροῦσιν ἐς Ἀνδανίαν, καθυβρίσαντες τῶν Διοσκούρων τῇ θυσίᾳ. τοῦτο ἐμοὶ δοκεῖν προήγαγε τοὺς Διοσκούρους ἐς τὸ ἔχθος τὸ Μεσσηνίων· τότε δέ, ὡς ἐδήλου τῷ Ἐπαμινώνδᾳ τὸ ὄνειρον, οὐκ ἦν ἔτι τοῖς Διοσκούροις ἀκούσιος τῶν Μεσσηνίων ἡ κάθοδος.", "st": "4.27"}, {"sp": "N", "t": "μάλιστα δὲ τὸν Ἐπαμινώνδαν ἐς τὸν οἰκισμὸν οἱ Βάκιδος ἐνῆγον χρησμοί. Βάκιδι γὰρ μανέντι ἐκ Νυμφῶν ἐς ἄλλους τέ ἐστιν Ἑλλήνων καὶ ἐς τὴν Μεσσηνίων κάθοδον προειρημένα<br>καὶ τότε δὴ Σπάρτης μὲν ἀπ’ ἀγλαὸν ἄνθος ὀλεῖται,<br>Μεσσήνη δ’ αὖτις οἰκήσεται ἤματα πάντα.<br>ἐγὼ δὲ καὶ περὶ τῆς Εἴρας, ὅντινα ἁλώσοιτο τρόπον, Βάκιν ἐφώρασα εἰρηκότα· καί οἱ καὶ τόδε ἐστὶ τῶν χρησμῶν,<br>οἵ τ’ ἀπὸ Μεσσήνης πατάγῳ κρουνοῖς τε δαμείσης.", "st": "4.27"}, {"sp": "N", "t": "ὡς δὲ ἡ τελετή σφισιν ἀνεύρητο, ταύτην μέν, ὅσοι τοῦ γένους τῶν ἱερέων ἦσαν, κατετίθεντο ἐς βίβλους· Ἐπαμινώνδας δέ, ὥς οἱ τὸ χωρίον, ἔνθα νῦν ἔχουσιν οἱ Μεσσήνιοι τὴν πόλιν, μάλιστα ἐς οἰκισμὸν ἐφαίνετο ἐπιτήδειον, ἐκέλευεν ἀνασκοπεῖσθαι τοῖς μάντεσιν, ⟨εἴ⟩ οἱ βουλήσεται ταύτῃ καὶ τὰ τῶν θεῶν ἐπιχωρῆσαι. φαμένων δὲ καὶ τούτων εἶναι τὰ ἱερὰ αἴσια, οὕτω παρεσκευάζετο ἐς τὸν οἰκισμόν, λίθους τε ἄγεσθαι κελεύων καὶ ἄνδρας μεταπεμπόμενος, οἷς τέχνη στενωποὺς κατατέμνεσθαι καὶ οἰκίας καὶ ἱερὰ οἰκοδομεῖσθαι καὶ τείχη περιβάλλεσθαι.", "st": "4.27"}, {"sp": "N", "t": "ὡς δὲ ἐγεγόνει τὰ πάντα ἐν ἑτοίμῳ, τὸ ἐντεῦθεν—ἱερεῖα γὰρ παρεῖχον οἱ Ἀρκάδες—αὐτὸς μὲν Ἐπαμινώνδας καὶ οἱ Θηβαῖοι Διονύσῳ καὶ Ἀπόλλωνι ἔθυον Ἰσμηνίῳ τὸν νομιζόμενον τρόπον, Ἀργεῖοι δὲ τῇ τε Ἥρᾳ τῇ Ἀργείᾳ καὶ Νεμείῳ Διί, Μεσσήνιοι δὲ Διί τε Ἰθωμάτᾳ καὶ Διοσκούροις, οἱ δέ σφισιν ἱερεῖς θεαῖς ταῖς Μεγάλαις καὶ Καύκωνι. ἐπεκαλοῦντο δὲ ἐν κοινῷ καὶ ἥρωάς σφισιν ἐπανήκειν συνοίκους, Μεσσήνην μὲν τὴν Τριόπα μάλιστα, ἐπὶ ταύτῃ δὲ Εὔρυτον καὶ Ἀφαρέα τε καὶ τοὺς παῖδας, παρὰ δὲ Ἡρακλειδῶν Κρεσφόντην τε καὶ Αἴπυτον· πλείστη δὲ καὶ παρὰ πάντων ἀνάκλησις ἐγίνετο Ἀριστομένους.", "st": "4.27"}, {"sp": "N", "t": "καὶ τὴν μὲν τότε ἡμέραν πρὸς θυσίαις τε καὶ εὐχαῖς ἦσαν, ταῖς δὲ ἐφεξῆς τοῦ τείχους τὸν περίβολον ἤγειρον καὶ ἐντὸς οἰκίας καὶ τὰ ἱερὰ ἐποιοῦντο. εἰργάζοντο δὲ καὶ ὑπὸ μουσικῆς ἄλλης μὲν οὐδεμιᾶς, αὐλῶν δὲ Βοιωτίων καὶ Ἀργείων· τά τε Σακάδα καὶ Προνόμου μέλη τότε δὴ προήχθη μάλιστα ἐς ἅμιλλαν. αὐτῇ μὲν δὴ τῇ πόλει Μεσσήνην ἔθεντο ὄνομα, ἀνῴκιζον δὲ καὶ ἄλλα πολίσματα.", "st": "4.27"}, {"sp": "N", "t": "Ναυπλιεῖς δὲ ἐκ Μοθώνης οὐκ ἀνέστησαν· κατὰ χώραν δὲ καὶ Ἀσιναίους μένειν εἴων, τούτοις μὲν καὶ εὐεργεσίαν ἀπομνημονεύοντες πολεμῆσαι μετὰ Λακεδαιμονίων πρὸς σφᾶς οὐ θελήσασι, Ναυπλιεῖς δὲ κατιοῦσιν ἐς Πελοπόννησον Μεσσηνίοις τε δῶρα ἤγαγον ὁποῖα εἶχον καὶ ἅμα μὲν ὑπὲρ καθόδου τῆς ἐκείνων συνεχέσιν ἐς τὸ θεῖον ταῖς εὐχαῖς, ἅμα δὲ ὑπὲρ σωτηρίας τῆς σφετέρας δεήσεσιν ἐς ἐκείνους ἐχρῶντο.", "st": "4.27"}, {"sp": "N", "t": "κατῆλθον δὲ ἐς Πελοπόννησον οἱ Μεσσήνιοι καὶ ἀνεσώσαντο τὴν αὑτῶν ἑπτὰ καὶ ὀγδοήκοντα καὶ διακοσίοις ἔτεσιν ὕστερον μετὰ Εἴρας ἅλωσιν, Δυσκινήτου μὲν Ἀθήνῃσιν ἄρχοντος, τρίτῳ δὲ ἔτει τῆς δευτέρας καὶ ἑκατοστῆς Ὀλυμπιάδος, ἣν Δάμων Θούριος τὸ δεύτερον ἐνίκα. οὐκ ὀλίγος μὲν οὖν ὁ χρόνος καὶ Πλαταιεῦσιν ἐγένετο, ἐφ’ ὅσον καὶ ἐκεῖνοι τὴν αὑτῶν ἔφευγον, καὶ Δηλίοις, ἡνίκα ᾤκησαν Ἀδραμύττιον ἐκβληθέντες ἐκ τῆς σφετέρας ὑπὸ Ἀθηναίων [καὶ Ὀρχομενίων]·", "st": "4.27"}, {"sp": "N", "t": "οἱ δὲ Μινύαι, μετὰ τὴν μάχην τὴν ἐν Λεύκτροις ἐκπεσόντες ὑπὸ Θηβαίων ἐξ Ὀρχομενοῦ, κατήχθησαν ἐς Βοιωτίαν ὑπὸ Φιλίππου τοῦ Ἀμύντου, καὶ οὗτοι καὶ οἱ Πλαταιεῖς. Θηβαίων δὲ αὐτῶν ἐρημώσαντος Ἀλεξάνδρου τὴν πόλιν, αὖθις ἔτεσιν οὐ πολλοῖς ὕστερον Κάσσανδρος Ἀντιπάτρου τὰς Θήβας ἔκτισεν. φαίνεται μὲν δὴ τῶν κατειλεγμένων ἐπὶ μακρότατον ἡ Πλαταϊκὴ φυγὴ συμβᾶσα, οὐ μέντοι περαιτέρω γε ἢ ἐπὶ δύο ἐγένετο οὐδ’ αὐτὴ γενεάς.", "st": "4.27"}, {"sp": "N", "t": "Μεσσήνιοι δὲ ἐκτὸς Πελοποννήσου τριακόσια ἔτη μάλιστα ἠλῶντο, ἐν οἷς οὔτε ἐθῶν εἰσι δῆλοι παραλύσαντές τι τῶν οἴκοθεν οὔτε τὴν διάλεκτον τὴν Δωρίδα μετεδιδάχθησαν, ἀλλὰ καὶ ἐς ἡμᾶς ἔτι τὸ ἀκριβὲς αὐτῆς Πελοποννησίων μάλιστα ἐφύλασσον.", "st": "4.27"}, {"sp": "N", "t": "κατελθοῦσι δὲ αὐτοῖς κατ’ ἀρχὰς μὲν ἀπὸ Λακεδαιμονίων δεινὸν ἦν οὐδέν· κατεχόμενοι γὰρ οἱ Λακεδαιμόνιοι φόβῳ τῷ Θηβαίων Μεσσήνης τε ἠνείχοντο ἐποικιζομένης καὶ Ἀρκάδων ἐς μίαν ἠθροισμένων πόλιν. ὡς δὲ ὁ πόλεμος ὁ Φωκικός, καλούμενος δὲ ⟨ὁ⟩ αὐτὸς οὗτος καὶ ἱερός, ἀπήγαγεν ἐκ Πελοποννήσου Θηβαίους, ἀνεθάρρησάν τε οἱ Λακεδαιμόνιοι καὶ τῶν Μεσσηνίων οὐκέτι ἐδύναντο ἀπέχεσθαι.", "st": "4.28"}, {"sp": "N", "t": "Μεσσήνιοι δὲ αὐτοί τε μετὰ Ἀργείων καὶ Ἀρκάδων ἀντεῖχον τῷ πολέμῳ καὶ Ἀθηναίων ἀμῦναί σφισιν ἐδεήθησαν· οἱ δὲ ἐς μὲν τὴν Λακωνικὴν οὔποτε μετὰ ἐκείνων ἐσβαλεῖν ἔφασαν, ἀρχόντων δὲ Λακεδαιμονίων πολέμου καὶ ἐπιστρατευόντων τῇ Μεσσηνίᾳ παρέσεσθαι καὶ αὐτοί σφισιν ἐπηγγέλλοντο. τέλος δὲ οἱ Μεσσήνιοι Φιλίππῳ σύμμαχοι τῷ Ἀμύντου καὶ Μακεδόσιν ἐγένοντο, καὶ τοῦτο σφᾶς λέγουσιν ἀποκωλῦσαι τοῦ συμβάντος τοῖς Ἕλλησιν ἀγῶνος ἐν Χαιρωνείᾳ μὴ μετασχεῖν· οὐ μὴν οὐδὲ τοῖς Ἕλλησιν ἐναντία θέσθαι τὰ ὅπλα ἠθέλησαν.", "st": "4.28"}, {"sp": "N", "t": "Ἀλεξάνδρου δὲ ἀποθανόντος καὶ τῶν Ἑλλήνων πόλεμον δεύτερον τότε ἀνῃρημένων πρὸς Μακεδόνας, μετέσχον καὶ οἱ Μεσσήνιοι τοῦ πολέμου, καθὰ καὶ πρότερον ἐδήλωσα ἐν τῇ Ἀτθίδι συγγραφῇ. Γαλάταις δὲ μεθ’ Ἑλλήνων οὐκ ἐμαχέσαντο, Κλεωνύμου καὶ Λακεδαιμονίων σπείσασθαι σπονδάς σφισιν οὐ θελησάντων.", "st": "4.28"}, {"sp": "N", "t": "οὐ πολλῷ δὲ ὕστερον ἔσχον Ἦλιν Μεσσήνιοι, σοφίᾳ τε ὁμοῦ χρησάμενοι καὶ τολμήματι. Ἠλεῖοι γὰρ τὰ μὲν παλαιότατα εὐνομώτατοι Πελοποννησίων ἦσαν· Φιλίππου δὲ τοῦ Ἀμύντου τά τε ἄλλα ὁπόσα εἴρηται κακουργήσαντος τὴν Ἑλλάδα καὶ Ἠλείων τοὺς δυνατοὺς διαφθείραντος χρήμασι, στασιάζουσι πρῶτον τότε Ἠλεῖοι καὶ ἐς ὅπλα, ὡς λέγουσι, χωροῦσι.", "st": "4.28"}, {"sp": "N", "t": "τὸ δὲ ἀπὸ τούτου ῥᾷον ἔτι ἔμελλον ἀπεχθήσεσθαι πρὸς ἀλλήλους, οἷς γε καὶ Λακεδαιμονίων ἕνεκα διέστη τὰ βουλεύματα, καὶ ἐς ἔμφυλον προῆλθον πόλεμον. πυνθανόμενοι δὲ ταῦτα οἱ Λακεδαιμόνιοι παρεσκευάζοντο ὡς Ἠλείων τοῖς φρονοῦσι τὰ σφέτερα ἀμυνοῦντες. καὶ οἱ μὲν κατὰ τέλη τε ἐτάσσοντο καὶ διενέμοντο ἐς τοὺς λόχους· τῶν δὲ Μεσσηνίων λογάδες χίλιοι φθάνουσιν ἀφικόμενοι πρὸς τὴν Ἦλιν, σημεῖα ἐπὶ ταῖς ἀσπίσι Λακωνικὰ ἔχοντες.", "st": "4.28"}, {"sp": "N", "t": "ὡς δὲ τὰς ἀσπίδας ἐθεάσαντο ὅσοι τοῖς Σπαρτιάταις εὖνοι τῶν Ἠλείων ἦσαν, συμμαχίαν τε ἀφῖχθαί σφισιν ἤλπισαν καὶ τοὺς ἄνδρας ἐδέχοντο ἐς τὸ τεῖχος· ἐσελθόντες δὲ τρόπον οἱ Μεσσήνιοι τὸν εἰρημένον τοὺς τὰ Λακεδαιμονίων φρονοῦντας ἐδίωξαν, καὶ ἐπιτρέπουσι τοῖς στασιώταις τοῖς αὑτῶν τὴν πόλιν.", "st": "4.28"}, {"sp": "N", "t": "ἔστι μὲν δὴ τὸ σόφισμα Ὁμήρου, φαίνονται δὲ αὐτὸ ἐν δέοντι μιμησάμενοι καὶ οἱ Μεσσήνιοι, ἐπεὶ Πάτροκλόν γε ἐποίησεν ἐν Ἰλιάδι Ὅμηρος Ἀχιλλέως τὰ ὅπλα ἐνδύντα, καὶ ἐγγενέσθαι τε ἔφη τοῖς βαρβάροις δόξαν ὡς Ἀχιλλεὺς ἐπίοι καὶ τοὺς προτεταγμένους αὐτῶν ταραχθῆναι. εὕρηται δὲ καὶ ἄλλα Ὁμήρῳ στρατηγήματα, δύο τε παρὰ τῶν Ἑλλήνων κατασκόπους ἐν τῇ νυκτὶ ἀνθ’ ἑνὸς ἐς τοὺς Τρῶας ἀφικέσθαι καὶ ἄνδρα ὕστερον λόγῳ μὲν αὐτόμολον, ἔργῳ δὲ τὰ ἀπόρρητα πολυπραγμονήσοντα ἐς τὸ Ἴλιον ἐσελθεῖν.", "st": "4.28"}, {"sp": "N", "t": "ἔτι δὲ τοὺς διὰ νεότητα ἐν τοῖς Τρωσὶν ἢ γῆρας οὐχ ὡραίους μάχεσθαι, τούτους μὲν τὸ τεῖχος φρουρεῖν ἔταξε, τῶν ἐν ἡλικίᾳ τοῖς Ἕλλησιν ἐπηυλισμένων· Ἑλλήνων δὲ οἱ τὰ τραύματα ἔχοντες ὁπλίζουσιν αὐτῷ τὸ μάχιμον, ἵνα μηδὲ αὐτοὶ παντάπασιν ἀργοῖεν. τὰ Ὁμήρου μὲν οὖν ὠφέλιμα ἐγένετο ἐς ἅπαντα ἀνθρώποις·", "st": "4.28"}, {"sp": "N", "t": "μετὰ δὲ οὐ πολὺν χρόνον τοῦ ἔργου τοῦ πρὸς Ἤλιδι Μακεδόνες καὶ Δημήτριος ὁ Φιλίππου τοῦ Δημητρίου Μεσσήνην καταλαμβάνουσι. τὰ μὲν δὴ πολλὰ ἔς τε αὐτὸν Φίλιππον καὶ τὰ ἐς Δημήτριον τὸν Φιλίππου τολμηθέντα ἐκ Περσέως ἐν τοῖς Σικυωνίοις ἔγραψα ἤδη λόγοις· τὰ δὲ ἐς τὴν κατάληψιν τὴν Μεσσήνης ἔσχεν οὕτω.", "st": "4.29"}, {"sp": "N", "t": "χρημάτων ἐσπανίζετο Φίλιππος, καὶ—ἔδει γὰρ πάντως οἱ γενέσθαι χρήματα— ἀποστέλλει Δημήτριον ναυσὶν ἐς Πελοπόννησον. Δημήτριος δὲ κατήγετό που τῆς Ἀργείας ἐς λιμένα τῶν ἐρημοτέρων· αὐτίκα δὲ ὡς εἶχε διὰ τῶν ἐπιτομωτάτων τῆς χώρας τὴν στρατιὰν ἦγεν ἐπὶ Μεσσήνης. προτάξας δὲ ὅσον ἦν τῶν τε ὅπλων τῇ σκευῇ κοῦφον καὶ τῆς ἐς τὴν Ἰθώμην εἶχεν ὁδοῦ οὐκ ἀπείρως, λανθάνει περὶ ὄρθρον μάλιστα ὑπερβὰς τὸ τεῖχος, καθὸ τῆς τε πόλεως μεταξὺ ἦν καὶ ἄκρας τῆς Ἰθώμης.", "st": "4.29"}, {"sp": "N", "t": "ὡς δὲ ἡμέρα τε ἐπέσχε καὶ ἤδη τοῖς ἔνδον αἴσθησις ἐγεγόνει τοῦ κατειληφότος κινδύνου, τὸ μὲν πρῶτον αὐτοὺς ἐσῆλθεν ὑπόνοια ὡς οἱ Λακεδαιμόνιοι σὺν ὅπλοις παρέλθοιεν αὐτῶν ἐς τὴν πόλιν, ὥστε καὶ ὥρμησαν ἐπ’ αὐτοὺς ἀφειδέστερον διὰ τὸ μῖσος τὸ ἐξ ἀρχῆς. ἐπεὶ δὲ ἐκ τε τῶν ὅπλων καὶ τῆς φωνῆς Μακεδόνας καὶ Δημήτριον τὸν Φιλίππου γνωρίζουσιν ὄντας, δεῖμα ἰσχυρὸν παρέστη σφίσι λογιζομένοις τήν τε ἐς τὰ πολεμικὰ τῶν Μακεδόνων μελέτην καὶ τύχην ᾗ πρὸς ἅπαντα ἑώρων χρωμένους αὐτούς.", "st": "4.29"}, {"sp": "N", "t": "ὅμως δὲ τοῦ τε παρόντος κακοῦ τὸ μέγεθος ἐδίδασκεν ἀνδρίαν τινὰ καὶ πέρα τοῦ δυνατοῦ γίνεσθαι καὶ ἅμα τὰ ἀμείνω παρίστατο αὐτοῖς ἐλπίζειν· οὐ γὰρ δὴ ἄνευ θεοῦ διὰ τοσούτου σφίσιν ὑπάρξαι τὴν ἐς Πελοπόννησον κάθοδον. οἵ τε οὖν ἐκ τῆς πόλεως Μεσσήνιοι θυμῷ παντὶ ἐς τοὺς Μακεδόνας ἐχώρουν καὶ οἱ φρουροῦντες τὴν ἀκρόπολιν ἐπέκειντο ἐξ ὑπερδεξίων.", "st": "4.29"}, {"sp": "N", "t": "ὡσαύτως δὲ καὶ οἱ Μακεδόνες ὑπό τε ἀρετῆς καὶ ἐμπειρίας τὸ κατ’ ἀρχὰς ἠμύνοντο ἐρρωμένως· ἅτε δὲ ὁδοιπορίᾳ προαπειρηκότες καὶ ὁμοῦ τῶν τε ἀνδρῶν σφισιν ἐγκειμένων καὶ ὑπὸ τῶν γυναικῶν κεράμῳ καὶ λίθοις βαλλόμενοι, σὺν οὐδενὶ ἔφευγον κόσμῳ. καὶ τὸ μὲν πολὺ αὐτῶν ἀπώλετο ὠθούμενοι κατὰ τῶν κρημνῶν, ἀπότομος γὰρ δὴ ταύτῃ μάλιστά ἐστιν ἡ Ἰθώμη· ὀλίγοι δέ τινες καὶ ῥίψαντες τὰ ὅπλα ἀπεσώθησαν.", "st": "4.29"}, {"sp": "N", "t": "ἐς δὲ τὸ συνέδριον οἱ Μεσσήνιοι τὸ Ἀχαιῶν ἐπὶ τῷδε οὔ μοι δοκοῦσιν ἐσελθεῖν κατ’ ἀρχάς. Λακεδαιμονίοις αὐτεπάγγελτοι βοηθήσοντες ἀφίκοντο ὑπὸ Πύρρου τοῦ Αἰακίδου πολεμουμένοις, καί σφισιν ἀπὸ τῆς εὐεργεσίας ταύτης ἤδη τὰ ἐκ τῆς Σπάρτης εἰρηνικώτερα ὑπῆρχεν. οὔκουν ἀνακινῆσαι τὸ ἔχθος ἐβούλοντο ἐς τὸ συνέδριον συγχωρήσαντες, οἳ Λακεδαιμονίων μάλιστα πολέμιοι ἐκ τοῦ φανεροῦ καθεστήκεσαν.", "st": "4.29"}, {"sp": "N", "t": "ὃ δὲ οὐ λέληθεν ἐμέ, οὐδὲ Μεσσηνίους ἐλελήθει δήπου, καὶ μὴ συντελοῦσιν αὐτοῖς ἐς τὸ συνέδριον ὡς ἐπὶ Λακεδαιμονίους τὰ Ἀχαιῶν ὑπάρχοι· ἐν γὰρ δὴ τοῖς Ἀχαιοῖς καὶ Ἀργεῖοι καὶ τὸ Ἀρκαδικὸν οὐκ ἐλαχίστη μοῖρα ἦσαν. ἀνὰ χρόνον μέντοι προσεχώρησαν ἐς τὸ Ἀχαϊκόν. οὐ πολλῷ δὲ ὕστερον Κλεομένης ὁ Λεωνίδου τοῦ Κλεωνύμου Μεγάλην πόλιν εἷλεν Ἀρκάδων ἐν σπονδαῖς·", "st": "4.29"}, {"sp": "N", "t": "τῶν δὲ οἱ καταληφθέντες οἳ μὲν ἀπώλοντο ὑπὸ τὴν ἅλωσιν, Φιλοποίμενα δὲ τὸν Κραύγιδος καὶ ὅσοι μετὰ Φιλοποίμενος ἀπεχώρησαν—γενέσθαι δὲ τῶν Μεγαλοπολιτῶν τὸ διαφυγὸν καὶ ὑπὲρ τὰς δύο μοίρας λέγουσι—τούτους ὑπεδέξαντο οἱ Μεσσήνιοι τῶν τε ἀρχαίων ἔργων ἕνεκα ὁπόσα ἐπὶ Ἀριστομένους ὑπῆρκτο Ἀρκάσι καὶ ὕστερον ἐπὶ τοῦ οἰκισμοῦ τοῦ Μεσσήνης, ἀποδιδόντες σφίσι τὴν ὁμοίαν.", "st": "4.29"}, {"sp": "N", "t": "πέφυκε δὲ ἄρα ὡς ἐπίπαν μεταπίπτειν τὰ ἀνθρώπινα, εἰ δὴ Μεσσηνίοις Ἀρκάδας τε ἀντισῶσαι καὶ τὸ ἀδοκητότερον ἔτι ἑλεῖν Σπάρτην ὁ δαίμων ἔδωκεν· Κλεομένει γὰρ περὶ Σελλασίαν ἐμαχέσαντο ἐναντία καὶ τὴν Σπάρτην Ἀράτῳ καὶ Ἀχαιοῖς συγκαθεῖλον.", "st": "4.29"}, {"sp": "N", "t": "Λακεδαιμονίοις δὲ ἀπηλλαγμένοις Κλεομένους ἐπανίσταται τύραννος Μαχανίδας, ἐκείνου δὲ ἀποθανόντος Νάβις ἀνέφυ σφίσιν αὖθις τύραννος· ἅτε δὲ οὐ τὰ ἀνθρώπων ἀναρπάζοντι αὐτῷ μόνον, ἀλλὰ καὶ ἱερὰ συλῶντι, ἐν οὐ πολλῷ χρόνῳ χρήματά τε ἄφθονα καὶ ἀπ’ αὐτῶν στρατιὰ συνείλεκτο. τούτου τοῦ Νάβιδος Μεσσήνην καταλαβόντος Φιλοποίμην καὶ οἱ Μεγαλοπολῖται νυκτὸς ἀφίκοντο τῆς αὐτῆς·", "st": "4.29"}, {"sp": "N", "t": "καὶ ὁ μὲν Σπαρτιάτης τύραννος ἀπῆλθεν ὑπόσπονδος, Ἀχαιοὶ δὲ ὕστερον τούτων μεμφόμενοί τι Μεσσηνίοις στρατεύουσιν ἐπ’ αὐτοὺς παρασκευῇ τῇ πάσῃ καὶ τὰ πολλὰ ἔτεμον τῆς χώρας. καὶ οἳ μὲν αὖθις περὶ ἀκμὴν σίτου συνελέγοντο ὡς ἐς τὴν Μεσσηνίαν ἐσβαλοῦντες· Δεινοκράτης δὲ δήμου τε προεστηκὼς καὶ Μεσσηνίων ἄρχειν ἐν τῷ τότε ᾑρημένος Λυκόρταν μὲν καὶ τὴν σὺν αὐτῷ στρατιὰν ἀναχωρῆσαι παρεσκεύασεν ἄπρακτον, τὰς ἐς τὴν Μεσσηνίαν ἐκ τῆς Ἀρκαδίας παρόδους προλαβὼν τοῖς τε ἐκ τῆς πόλεως Μεσσηνίοις καὶ ὅσοι τῶν περιοίκων σφίσιν ἤμυναν·", "st": "4.29"}, {"sp": "N", "t": "Φιλοποίμενος δὲ σὺν ἱππεῦσιν ὀλίγοις ἀφικομένου πολὺ ὕστερον ἢ ὁ μετὰ Λυκόρτα στρατός, πυθέσθαι δὲ οὐδέν πω τῶν ἐς αὐτοὺς δεδυνημένου, νικῶσιν οἱ Μεσσήνιοι γινομένης σφίσιν ⟨ἐξ⟩ ὑπερδεξίων τῆς μάχης καὶ ζῶντα αἱροῦσι Φιλοποίμενα. τρόπον δὲ ὅντινα ὁ Φιλοποίμην ἑάλω καὶ ὡς ἐτελεύτησε, τάδε μὲν ἡμῖν καὶ ὕστερον ὁ Ἀρκαδικὸς λόγος ἐπέξεισι· Μεσσηνίων δὲ οἵ τε Φιλοποίμενι αἴτιοι τῆς τελευτῆς ἔδοσαν δίκας καὶ ἡ Μεσσήνη συνετέλεσεν αὖθις ἐς τὸ Ἀχαϊκόν.", "st": "4.29"}, {"sp": "N", "t": "ἄχρι μὲν δὴ τοῦδε ὁ λόγος ἐπῆλθέ μοι Μεσσηνίων τὰ πολλὰ παθήματα, καὶ ὡς ὁ δαίμων σφᾶς ἐπί τε γῆς τὰ ἔσχατα καὶ ἐπὶ τὰ πορρώτατα Πελοποννήσου σκεδάσας ὕστερον χρόνῳ καὶ ἐς τὴν οἰκείαν ἀνέσωσε· τὸ δὲ ἀπὸ τούτου τῆς χώρας καὶ πόλεων τραπώμεθα ἐς ἀφήγησιν.", "st": "4.29"}, {"sp": "N", "t": "ἔστιν ἐφ’ ἡμῶν ἐν τῇ Μεσσηνίᾳ τῆς νάπης τῆς Χοιρίου στάδια εἴκοσι μάλιστα ἀπέχουσα Ἀβία ἐπὶ θαλάσσῃ πόλις. ταύτην Ἴρην καλεῖσθαι πάλαι καὶ τῶν ἑπτά φασιν εἶναι πόλεων, ἃς Ἀχιλλεῖ πεποίηκεν Ὅμηρος Ἀγαμέμνονα ὑπισχνούμενον. Ὕλλου δὲ καὶ Δωριέων μάχῃ κρατηθέντων ὑπὸ Ἀχαιῶν, ἐνταῦθα Ἀβίαν Γλήνου τοῦ Ἡρακλέους τροφὸν ἀποχωρῆσαι λέγουσιν ἐς τὴν Ἴρην καὶ οἰκῆσαί τε αὐτόθι καὶ Ἡρακλέους ἱερὸν ἱδρύσασθαι, καί οἱ διὰ ταῦτα ὕστερον Κρεσφόντην ἄλλα τε γέρα νεῖμαι καὶ τῇ πόλει μεταθέσθαι τὸ ὄνομα ἀπὸ τῆς Ἀβίας. Ἡρακλεῖον δὲ ἦν αὐτόθι ἐπιφανὲς καὶ Ἀσκληπιεῖον.", "st": "4.30"}, {"sp": "N", "t": "Φαραὶ δὲ ἀφεστήκασιν Ἀβίας σταδίους ἑβδομήκοντα, καὶ ὕδωρ κατὰ τὴν ὁδόν ἐστιν ἁλμυρόν· βασιλεὺς δὲ Αὔγουστος τοὺς ἐν Φαραῖς Μεσσηνίους συντελεῖν ἀπέταξεν ἐς τὸ Λακωνικόν. τὸν δὲ οἰκιστὴν Φᾶριν Ἑρμοῦ τε καὶ Φυλοδαμείας λέγουσιν εἶναι τῆς Δαναοῦ· Φάρει δὲ ἄρρενας μὲν οὔ φασι γενέσθαι, θυγατέρα δὲ Τηλεγόνην. τοὺς δὲ ἐφεξῆς ἐγενεαλόγησεν Ὅμηρος ἐν Ἰλιάδι διδύμους Κρήθωνα καὶ Ὀρτίλοχον εἶναι Διοκλεῖ, Διοκλέα δὲ αὐτὸν Ὀρτιλόχου τοῦ Ἀλφειοῦ· τὰ δὲ ἐς Τηλεγόνην παρεῖδεν, αὕτη γὰρ λόγῳ τῷ Μεσσηνίων ἐστὶν ἡ τεκοῦσα Ἀλφειῷ τὸν Ὀρτίλοχον.", "st": "4.30"}, {"sp": "N", "t": "καὶ τάδε ἄλλα ἤκουσα ἐν Φαραῖς, Διοκλεῖ θυγατέρα ἐπὶ τοῖς διδύμοις παισὶν Ἀντίκλειαν γενέσθαι, τῆς δὲ Νικόμαχόν τε εἶναι καὶ Γόργασον, πατρὸς δὲ Μαχάονος τοῦ Ἀσκληπιοῦ· τούτους καταμεῖναί τε αὐτοῦ καὶ ὡς ὁ Διοκλῆς ἐτελεύτησε τὴν βασιλείαν ἐκδέξασθαι. διαμεμένηκε δὲ αὐτοῖς καὶ ἐς τόδε ἔτι νοσήματά τε καὶ τοὺς πεπηρωμένους τῶν ἀνθρώπων ἰᾶσθαι· καί σφισιν ἀντὶ τούτων θυσίας ἐς τὸ ἱερὸν καὶ ἀναθήματα ἄγουσιν. ἔστι δὲ καὶ Τύχης ναὸς Φαραιάταις καὶ ἄγαλμα ἀρχαῖον.", "st": "4.30"}, {"sp": "N", "t": "πρῶτος δὲ ὧν οἶδα ἐποιήσατο ἐν τοῖς ἔπεσιν Ὅμηρος Τύχης μνήμην· ἐποιήσατο δὲ ἐν ὕμνῳ τῷ ἐς τὴν Δήμητρα ἄλλας τε τῶν Ὠκεανοῦ θυγατέρας καταριθμούμενος, ὡς ὁμοῦ Κόρῃ τῇ Δήμητρος παίζοιεν, καὶ Τύχην ὡς Ὠκεανοῦ καὶ ταύτην παῖδα οὖσαν· καὶ οὕτως ἔχει τὰ ἔπη·<br>ἡμεῖς μὲν μάλα πᾶσαι ἀν’ ἱμερτὸν λειμῶνα,<br>Λευκίππη Φαινώ τε καὶ Ἠλέκτρη καὶ Ἰάνθη<br>Μηλόβοσίς τε Τύχη τε καὶ Ὠκυρόη καλυκῶπις.", "st": "4.30"}, {"sp": "N", "t": "πέρα δὲ ἐδήλωσεν οὐδὲν ἔτι, ὡς ἡ θεός ἐστιν αὕτη μεγίστη θεῶν ἐν τοῖς ἀνθρωπίνοις πράγμασι καὶ ἰσχὺν παρέχεται πλείστην, ὥσπερ γε ἐν Ἰλιάδι ἐποίησεν Ἀθηνᾶν μὲν καὶ Ἐνυὼ πολεμούντων ἡγεμονίαν ἔχειν, Ἄρτεμιν δὲ γυναικῶν ὠδῖσιν εἶναι φοβερὰν, Ἀφροδίτῃ δὲ τὰ ἔργα μέλειν τῶν γάμων. ἀλλ’ οὗτος μὲν οὐδὲν ἄλλο ἐποίησεν ἐς τὴν Τύχην·", "st": "4.30"}, {"sp": "N", "t": "Βούπαλος δέ, ναούς τε οἰκοδομήσασθαι καὶ ζῷα ἀνὴρ ἀγαθὸς πλάσαι, Σμυρναίοις ἄγαλμα ἐργαζόμενος Τύχης πρῶτος ἐποίησεν ὧν ἴσμεν πόλον τε ἔχουσαν ἐπὶ τῇ κεφαλῇ καὶ τῇ ἑτέρᾳ χειρὶ τὸ καλούμενον Ἀμαλθείας κέρας ὑπὸ Ἑλλήνων. οὗτος μὲν ἐπὶ τοσοῦτο ἐδήλωσε τῆς θεοῦ τὰ ἔργα· ᾖσε δὲ καὶ ὕστερον Πίνδαρος ἄλλα τε ἐς τὴν Τύχην καὶ δὴ καὶ Φερέπολιν ἀνεκάλεσεν αὐτήν.", "st": "4.30"}, {"sp": "N", "t": "ὀλίγον δὲ ἀπωτέρω Φαρῶν Ἀπόλλωνος ἄλσος ἐστὶ Καρνείου καὶ ὕδατος ἐν αὐτῷ πηγή· θαλάσσης δὲ ἕξ που στάδια ἀπέχουσιν αἱ Φαραί. ἐντεῦθεν πρὸς μεσόγαιαν τῆς Μεσσηνίας σταδίους προελθόντι ὀγδοήκοντα, ἔστιν ἡ Θουριατῶν πόλις, Ἄνθειαν δὲ αὐτὴν ἐν τοῖς ἔπεσιν ὠνομάσθαι τοῖς Ὁμήρου λέγουσι· Λακεδαιμονίοις δὲ ἔχειν τοῖς ἐν Σπάρτῃ τὴν Θουρίαν ἔδωκεν Αὔγουστος. Αὐγούστῳ γὰρ βασιλεύοντι Ῥωμαίων ἐπολέμησεν Ἀντώνιος, γένει καὶ οὗτος Ῥωμαῖος· καί οἱ τῶν ἐν τῇ Ἑλλάδι ἄλλοι τε καὶ οἱ Μεσσήνιοι προσέθεντο, ὅτι ἐφρόνουν Λακεδαιμόνιοι τὰ Αὐγούστου.", "st": "4.31"}, {"sp": "N", "t": "καὶ ὁ μὲν τούτων ἕνεκα Μεσσηνίοις καὶ τῶν ἄλλων τῶν ἀντιταξαμένων τοῖς μὲν αὐτῶν ἔλαττον, τοῖς δὲ καὶ ἐς πλέον ἐπεξῆλθε· Θουριᾶται δὲ ἐκ τῆς πόλεως ἐν μετεώρῳ τὸ ἀρχαῖον οἰκουμένης ἐς τὸ πεδίον κατελθόντες οἰκοῦσιν. οὐ μὴν παντάπασί γε οὐδὲ τὴν ἄνω πόλιν ἐκλελοίπασιν, ἀλλὰ καὶ τείχους ἐρείπια καὶ ἱερόν ἐστιν αὐτόθι ὀνομαζόμενον θεοῦ Συρίας· τὴν δὲ ἐν τῷ πεδίῳ πόλιν ποταμὸς καλούμενος Ἄρις παρέξεισιν.", "st": "4.31"}, {"sp": "N", "t": "ἔστι δὲ ἐν τῇ μεσογαίῳ κώμη Καλάμαι καὶ Λίμναι χωρίον· ἐν δὲ αὐτῷ Λιμνάτιδος ἱερόν ἐστιν Ἀρτέμιδος, ἔνθα Τηλέκλῳ βασιλεύοντι ἐν Σπάρτῃ τὴν τελευτὴν συμβῆναι λέγουσιν.", "st": "4.31"}, {"sp": "N", "t": "ἰόντι δὲ ἐκ Θουρίας ὡς ἐπὶ Ἀρκαδίας εἰσὶν αἱ πηγαὶ τοῦ Παμίσου· καὶ ἐπ’ αὐταῖς παισὶ μικροῖς ἀκέσματα γίνεται. ἰοῦσι δὲ ἀπὸ τῶν πηγῶν ἐν ἀριστερᾷ καὶ προελθόντι ὡς τεσσαράκοντα στάδια, ἔστι Μεσσηνίοις ἡ ὑπὸ τῇ Ἰθώμῃ πόλις· περιέχεται δὲ οὐ τῇ Ἰθώμῃ μόνον ἀλλὰ καὶ ἐπὶ τὸν Πάμισον τὰ τετραμμένα ὑπὸ τῆς Εὔας· τὸ δὲ ὄνομα γενέσθαι τῷ ὄρει φασὶ Βακχικόν τι ἐπίφθεγμα εὐοῖ Διονύσου πρῶτον ἐνταῦθα αὐτοῦ τε εἰπόντος καὶ τῶν ὁμοῦ τῷ Διονύσῳ γυναικῶν.", "st": "4.31"}, {"sp": "N", "t": "περὶ δὲ τὴν Μεσσήνην τεῖχος, κύκλος μὲν πᾶς λίθου πεποίηται, πύργοι δὲ καὶ ἐπάλξεις εἰσὶν ἐνῳκοδομημένοι. τὰ μὲν οὖν Βαβυλωνίων ἢ τὰ Μεμνόνεια τὰ ἐν Σούσοις τείχη τοῖς Περσικοῖς οὔτε εἶδον οὔτε ἄλλων περὶ αὐτῶν ἤκουσα αὐτοπτούντων· τὰ δὲ ἐν Ἀμβρόσ⟨σ⟩ῳ τῇ Φωκικῇ ἔν τε Βυζαντίῳ καὶ Ῥόδῳ—ταῦτα γὰρ δὴ τετείχισται τὰ χωρία ἄριστα—τούτων Μεσσηνίοις ἐστὶν ἐχυρώτερον.", "st": "4.31"}, {"sp": "N", "t": "Μεσσηνίοις δὲ ἐν τῇ ἀγορᾷ Διός ἐστιν ἄγαλμα Σωτῆρος καὶ Ἀρσινόη κρήνη· τὸ μὲν δὴ ὄνομα ἀπὸ τῆς Λευκίππου θυγατρὸς εἴληφεν, ὑπορρεῖ δὲ ἐς αὐτὴν ὕδωρ ἐκ πηγῆς καλουμένης Κλεψύδρας. θεῶν δὲ ἱερὰ Ποσειδῶνος, τὸ δὲ Ἀφροδίτης ἐστί· καὶ οὗ μάλιστα ἄξιον ποιήσασθαι μνήμην, ἄγαλμα Μητρὸς θεῶν λίθου Παρίου, Δαμοφῶντος δὲ ἔργον, ὃς καὶ τὸν Δία ἐν Ὀλυμπίᾳ διεστηκότος ἤδη τοῦ ἐλέφαντος συνήρμοσεν ἐς τὸ ἀκριβέστατον· καί οἱ δεδομέναι τιμαὶ παρὰ Ἠλείων εἰσί.", "st": "4.31"}, {"sp": "N", "t": "Δαμοφῶντος δέ ἐστι τούτου καὶ ἡ Λαφρία καλουμένη παρὰ Μεσσηνίοις· σέβεσθαι δέ σφισιν ἀπὸ τοιοῦδε αὐτὴν καθέστηκε. Καλυδωνίοις ἡ Ἄρτεμις—ταύτην γὰρ θεῶν μάλιστα ἔσεβον— ἐπίκλησιν εἶχε Λαφρία· Μεσσηνίων δὲ οἱ λαβόντες Ναύπακτον παρὰ Ἀθηναίων—τηνικαῦτα γὰρ Αἰτωλίας ἐγγύτατα ᾤκουν—παρὰ Καλυδωνίων ἔλαβον. τὸ σχῆμα ἑτέρωθι δηλώσω. τὸ μὲν δὴ τῆς Λαφρίας ἀφίκετο ὄνομα ἔς τε Μεσσηνίους καὶ ἐς Πατρεῖς Ἀχαιῶν μόνους, Ἐφεσίαν δὲ Ἄρτεμιν πόλεις τε νομίζουσιν αἱ", "st": "4.31"}, {"sp": "N", "t": "πᾶσαι καὶ ἄνδρες ἰδίᾳ θεῶν μάλιστα ἄγουσιν ἐν τιμῇ· τὰ δὲ αἴτια ἐμοὶ δοκεῖν ἐστὶν Ἀμαζόνων τε κλέος, αἳ φήμην τὸ ἄγαλμα ἔχουσιν ἱδρύσασθαι, καὶ ὅτι ἐκ παλαιοτάτου τὸ ἱερὸν τοῦτο ἐποιήθη. τρία δὲ ἄλλα ἐπὶ τούτοις συνετέλεσεν ἐς δόξαν, μέγεθός τε τοῦ ναοῦ τὰ παρὰ πᾶσιν ἀνθρώποις κατασκευάσματα ὑπερηρκότος καὶ Ἐφεσίων τῆς πόλεως ἡ ἀκμὴ καὶ ἐν αὐτῇ τὸ ἐπιφανὲς τῆς θεοῦ.", "st": "4.31"}, {"sp": "N", "t": "πεποίηται δὲ καὶ Εἰλειθυίας Μεσσηνίοις ναὸς καὶ ἄγαλμα λίθου, πλησίον δὲ Κουρήτων μέγαρον, ἔνθα ζῷα τὰ πάντα ὁμοίως καθαγίζουσιν· ἀρξάμενοι γὰρ ἀπὸ βοῶν τε καὶ αἰγῶν καταβαίνουσιν ἐς τοὺς ὄρνιθας ἀφιέντες ἐς τὴν φλόγα. καὶ Δήμητρος ἱερὸν Μεσσηνίοις ἐστὶν ἅγιον καὶ Διοσκούρων ἀγάλματα φέροντες τὰς Λευκίππου· καί μοι καὶ ταῦτα ἐν τοῖς προτέροις ἐστὶν ἤδη δεδηλωμένα, ὡς οἱ Μεσσήνιοι τοὺς Τυνδάρεω παῖδας ἀμφισβητοῦσιν αὑτοῖς καὶ οὐ Λακεδαιμονίοις προσήκειν.", "st": "4.31"}, {"sp": "N", "t": "πλεῖστα δέ σφισι καὶ θέας μάλιστα ἀγάλματα ἄξια τοῦ Ἀσκληπιοῦ παρέχεται τὸ ἱερόν· χωρὶς μὲν γὰρ τοῦ θεοῦ καὶ τῶν παίδων ἐστὶν ἀγάλματα, χωρὶς δὲ Ἀπόλλωνος καὶ Μουσῶν καὶ Ἡρακλέους· πόλις τε ἡ Θηβαίων καὶ Ἐπαμινώνδας ὁ Κλεόμμιδος Τύχη τε καὶ Ἄρτεμις Φωσφόρος, τὰ μὲν δὴ τοῦ λίθου Δαμοφῶν αὐτοῖς εἰργάσατο—Μεσσήνιον δὲ ὅτι μὴ τοῦτον ἄλλον γε οὐδένα λόγου ποιήσαντα ἀξίως οἶδα ἀγάλματα—, ἡ δὲ εἰκὼν τοῦ Ἐπαμινώνδου ἐκ σιδήρου τέ ἐστι καὶ ἔργον ἄλλου, οὐ τούτου.", "st": "4.31"}, {"sp": "N", "t": "ἔστι δὲ καὶ Μεσσήνης τῆς Τριόπα ναὸς καὶ ἄγαλμα χρυσοῦ καὶ λίθου Παρίου· γραφαὶ δὲ κατὰ τοῦ ναοῦ τὸ ὄπισθεν αἱ βασιλεύσαντές εἰσι Μεσσήνης, πρὶν μὲν ἢ στόλον ἀφικέσθαι τὸν Δωριέων ἐς Πελοπόννησον Ἀφαρεὺς καὶ οἱ παῖδες, κατελθόντων δὲ Ἡρακλειδῶν Κρεσφόντης ἐστίν, ἡγεμὼν καὶ οὗτος τοῦ Δωρικοῦ, τῶν δὲ οἰκησάντων ἐν Πύλῳ Νέστωρ καὶ Θρασυμήδης καὶ Ἀντίλοχος, προτετιμημένοι παίδων τῶν Νέστορος ἡλικίᾳ καὶ ἐπὶ Τροίαν μετεσχηκότες τῆς στρατείας.", "st": "4.31"}, {"sp": "N", "t": "Λεύκιππός τε Ἀφαρέως ἀδελφὸς καὶ Ἱλάειρά ἐστι καὶ Φοίβη, σὺν δέ σφισιν Ἀρσινόη. γέγραπται δὲ καὶ Ἀσκληπιός, Ἀρσινόης ὢν λόγῳ τῷ Μεσσηνίων, καὶ Μαχάων καὶ Ποδαλείριος, ὅτι ἔργου τοῦ πρὸς Ἰλίῳ καὶ τούτοις μέτεστι. ταύτας τὰς γραφὰς ἔγραψεν Ὀμφαλίων, Νικίου τοῦ Νικομήδους μαθητής· οἱ δὲ αὐτὸν καὶ δουλεῦσαι παρὰ τῷ Νικίᾳ καὶ παιδικὰ γενέσθαι φασὶν αὐτοῦ.", "st": "4.31"}, {"sp": "N", "t": "τὸ δὲ ὀνομαζόμενον παρὰ Μεσσηνίων ἱεροθέσιον ἔχει μὲν θεῶν ἀγάλματα ὁπόσους νομίζουσιν Ἕλληνες, ἔχει δὲ χαλκῆν εἰκόνα Ἐπαμινώνδου. κεῖνται δὲ καὶ ἀρχαῖοι τρίποδες· ἀπύρους αὐτοὺς καλεῖ Ὅμηρος. τὰ δὲ ἀγάλματα ⟨τὰ⟩ ἐν τῷ γυμνασίῳ ποιήματά ἐστιν ἀνδρῶν Αἰγυπτίων, Ἑρμῆς καὶ Ἡρακλῆς τε καὶ Θησεύς. τούτους μὲν δὴ τοῖς πᾶσιν Ἕλλησι καὶ ἤδη τῶν βαρβάρων πολλοῖς περί τε γυμνάσια καὶ ἐν παλαίστραις καθέστηκεν ἔχειν ἐν τιμῇ·", "st": "4.32"}, {"sp": "N", "t": "Αἰθίδαν δὲ ἐμαυτοῦ πρεσβύτερον ὄντα εὕρισκον, γενομένῳ δέ οἱ χρήμασιν οὐκ ἀδυνάτῳ τιμαὶ παρὰ Μεσσηνίων ὑπάρχουσιν ἅτε ἥρωι. εἰσὶ δὲ τῶν Μεσσηνίων οἳ τῷ Αἰθίδᾳ χρήματα μὲν γενέσθαι πολλὰ ἔλεγον, οὐ μέντοι τοῦτόν γε εἶναι τὸν ἐπειργασμένον τῇ στήλῃ, πρόγονον δὲ καὶ ὁμώνυμον ἄνδρα τῷ Αἰθίδᾳ· Αἰθίδαν δὲ τὸν πρότερον ἡγήσασθαι τοῖς Μεσσηνίοις φασίν, ἡνίκα ἐν τῇ νυκτὶ Δημήτριός σφισιν ὁ Φιλίππου μηδαμῶς ἐλπίσασιν αὐτός τε καὶ ἡ στρατιὰ λανθάνουσιν ἐσελθόντες ἐς τὴν πόλιν.", "st": "4.32"}, {"sp": "N", "t": "καὶ Ἀριστομένους δὲ μνῆμά ἐστιν ἐνταῦθα· ⟨οὐ⟩ κενὸν δὲ εἶναι τὸ μνῆμα λέγουσιν, ἀλλ’ ἐρομένου μου τρόπον τε ὅντινα καὶ ὁπόθεν Ἀριστομένους κομίσαιντο τὰ ὀστᾶ, μεταπέμψασθαι μὲν ἐκ Ῥόδου φασί, τὸν δὲ ἐν Δελφοῖς θεὸν τὸν κελεύσαντα εἶναι. πρός τε δὴ τούτοις ἐδίδασκόν με ὁποῖα ἐπὶ τῷ τάφῳ δρῶσι. ταῦρον ὅντινα ἐναγίζειν μέλλουσιν, ἀγαγόντες ἐπὶ τὸ μνῆμα ἔδησαν πρὸς τὸν ἑστηκότα ἐπὶ τῷ τάφῳ κίονα· ὁ δὲ ἅτε ἄγριος καὶ ἀήθης δεσμῶν οὐκ ἐθέλει μένειν· θορυβουμένῳ δέ οἱ καὶ σκιρτῶντι ἢν ὁ κίων κινηθῇ, Μεσσηνίοις ἐστὶν αἴσιον, οὐ κινηθέντος δὲ ἀσύμφορα ἐπαγγέλλει τὸ σημεῖον.", "st": "4.32"}, {"sp": "N", "t": "παραγενέσθαι δὲ Ἀριστομένην καὶ τῷ περὶ Λεῦκτρα ἀγῶνι ἐθέλουσιν οὐ μετὰ ἀνθρώπων ἔτι ὄντα, καὶ ἀμῦναί τε αὐτόν φασι Θηβαίοις καὶ μάλιστα γενέσθαι τοῦ ἀτυχήματος Λακεδαιμονίοις αἴτιον. ἐγὼ δὲ Χαλδαίους καὶ Ἰνδῶν τοὺς μάγους πρώτους οἶδα εἰπόντας ὡς ἀθάνατός ἐστιν ἀνθρώπου ψυχή, καί σφισι καὶ Ἑλλήνων ἄλλοι τε ἐπείσθησαν καὶ οὐχ ἥκιστα Πλάτων ὁ Ἀρίστωνος· εἰ δὲ ἀποδέχεσθαι καὶ οἱ πάντες ἐθελήσουσιν, ἐκεῖνό γε ἀντειπεῖν οὐκ ἔνεστι μὴ οὐ τὸν πάντα αἰῶνα Ἀριστομένει τὸ μῖσος τὸ ἐς Λακεδαιμονίους ἐνεστάχθαι.", "st": "4.32"}, {"sp": "N", "t": "ἃ δὲ αὐτὸς ἤκουσα ἐν Θήβαις, εἰκὸς μέν τι παρείχετο ἐς τὸν Μεσσηνίων λόγον, οὐ μὴν παντάπασί γέ ἐστιν αὐτοῖς ὡμολογηκότα. φασὶ δὲ οἱ Θηβαῖοι μελλούσης τῆς μάχης ἔσεσθαί σφισιν ἐν Λεύκτροις ἐς ἄλλα τε ἀποστεῖλαι χρηστήρια καὶ ἐρησομένους τὸν ἐν Λεβαδείᾳ θεόν. λέγεται μὲν οὖν καὶ τὰ παρὰ τοῦ Ἰσμηνίου καὶ τοῦ Πτῴου, πρὸς δὲ τὰ ἐν Ἄβαις τε χρησθέντα καὶ τὰ ἐν Δελφοῖς· Τροφώνιον δέ φασιν εἰπεῖν ἑξαμέτρῳ·<br>πρὶν δορὶ συμβαλέειν ἐχθροῖς, στήσασθε τρόπαιον,<br>ἀσπίδα κοσμήσαντες ἐμήν, τὴν εἵσατο νηῷ<br>θοῦρος Ἀριστομένης Μεσσήνιος. αὐτὰρ ἐγώ τοι<br>ἀνδρῶν δυσμενέων φθίσω στρατὸν ἀσπιστάων.", "st": "4.32"}, {"sp": "N", "t": "ἀφικομένου δὲ τοῦ χρησμοῦ δεηθῆναι Ξενοκράτους λέγουσιν Ἐπαμινώνδαν· ὁ δὲ τήν τε ἀσπίδα μεταπέμπεται τοῦ Ἀριστομένους καὶ ἐκόσμησεν ἀπ’ αὐτῆς τρόπαιον, ὅθεν τοῖς Λακεδαιμονίοις ἔσεσθαι σύνοπτον ἔμελλεν. ᾔδεσαν δὲ ἄρα τὴν ἀσπίδα οἱ μὲν αὐτῶν ἐν Λεβαδείᾳ καθ’ ἡσυχίαν ἑωρακότες, ἀκοῇ δὲ καὶ πάντες· ὡς δὲ ἐγένετο ἡ νίκη Θηβαίοις, ἀποδιδόασιν αὖθις τῷ Τροφωνίῳ τὸ ἀνάθημα. Ἀριστομένους δὲ καὶ χαλκοῦς ἀνδριάς ἐστιν ἐν τῷ Μεσσηνίων σταδίῳ· τοῦ θεάτρου δὲ οὐ πόρω Σαράπιδός ἐστι καὶ Ἴσιδος ἱερόν.", "st": "4.32"}, {"sp": "N", "t": "ἐς δὲ τὴν κορυφὴν ἐρχομένῳ τῆς Ἰθώμης, ἣ δὴ Μεσσηνίοις ἐστὶν ἀκρόπολις, πηγὴ Κλεψύδρα γίνεται. πάντας μὲν οὖν καταριθμήσασθαι καὶ προθυμηθέντι ἄπορον, ὁπόσοι θέλουσι γενέσθαι καὶ τραφῆναι παρὰ σφίσι Δία· μέτεστι δ’ οὖν καὶ Μεσσηνίοις τοῦ λόγου· φασὶ γὰρ καὶ οὗτοι τραφῆναι παρὰ σφίσι τὸν θεόν, Ἰθώμην δὲ εἶναι καὶ Νέδαν τὰς θρεψαμένας, κεκλῆσθαι δὲ ἀπὸ μὲν τῆς Νέδας τὸν ποταμόν, τὴν δὲ ἑτέραν τῷ ὄρει τὴν Ἰθώμην δεδωκέναι τὸ ὄνομα. ταύτας δὲ τὰς νύμφας τὸν Δία, κλαπέντα ὑπὸ Κουρήτων διὰ τὸ ἐκ τοῦ πατρὸς δεῖμα, ἐνταῦθα λοῦσαι λέγουσι καὶ τὸ ὄνομα εἶναι τῷ ὕδατι ἀπὸ τῶν Κουρήτων τῆς κλοπῆς· φέρουσί τε ἀνὰ πᾶσαν ἡμέραν ὕδωρ ἀπὸ τῆς πηγῆς ἐς τοῦ Διὸς τοῦ Ἰθωμάτα τὸ ἱερόν.", "st": "4.33"}, {"sp": "N", "t": "τὸ δὲ ἄγαλμα τοῦ Διὸς Ἀγελάδα μέν ἐστιν ἔργον, ἐποιήθη δὲ ἐξ ἀρχῆς τοῖς οἰκήσασιν ἐν Ναυπάκτῳ Μεσσηνίων· ἱερεὺς δὲ αἱρετὸς κατὰ ἔτος ἕκαστον ἔχει [δὲ] τὸ ἄγαλμα ἐπὶ τῆς οἰκίας. ἄγουσι δὲ καὶ ἑορτὴν ἐπέτειον Ἰθωμαῖα, τὸ δὲ ἀρχαῖον καὶ ἀγῶνα ἐτίθεσαν μουσικῆς· τεκμαίρεσθαι δ’ ἔστιν ἄλλοις τε καὶ Εὐμήλου τοῖς ἔπεσιν, ἐποίησε γοῦν καὶ τάδε ἐν τῷ προσοδίῳ τῷ ἐς Δῆλον·<br>τῷ γὰρ Ἰθωμάτα καταθύμιος ἔπλετο μοῖσα<br>ἁ καθαρὰ⟨ν κιθάραν⟩ καὶ ἐλεύθερα σάμβαλ’ ἔχοισα.<br>οὐκοῦν ποιῆσαί μοι δοκεῖ τὰ ἔπη καὶ μουσικῆς ἀγῶνα ἐπιστάμενος τιθέντας.", "st": "4.33"}, {"sp": "N", "t": "ἰόντι δὲ τὴν ἐπ’ Ἀρκαδίας ἐς Μεγάλην πόλιν ἐστὶν ἐν ταῖς πύλαις Ἑρμῆς τέχνης τῆς Ἀττικῆς· Ἀθηναίων γὰρ τὸ σχῆμα τὸ τετράγωνόν ἐστιν ἐπὶ τοῖς Ἑρμαῖς, καὶ παρὰ τούτων μεμαθήκασιν οἱ ἄλλοι. σταδίους δὲ καταβάντι ἀπὸ τῶν πυλῶν τριάκοντα τὸ ῥεῦμά ἐστι τῆς Βαλύρας. γενέσθαι δὲ τὸ ὄνομα τῷ ποταμῷ λέγουσι Θαμύριδος τὴν λύραν ἐνταῦθα ἀποβαλόντος ἐπὶ τῇ πηρώσει· παῖδα δὲ αὐτὸν Φιλάμμωνος καὶ Ἀργιόπης τῆς νύμφης εἶναι. τὴν δὲ Ἀργιόπην τέως μὲν περὶ τὸν Παρνασσὸν οἰκεῖν, ἐπεὶ δὲ εἶχεν ἐν γαστρί, ἐς Ὀδρύσας λέγουσι μετοικῆσαι· Φιλάμμωνα γὰρ οὐκ ἐθέλειν ἐς τὸν οἶκον αὐτὴν ἄγεσθαι. καὶ Θάμυριν μὲν Ὀδρύσην τε καὶ Θρᾷκα ἐπὶ τούτῳ καλοῦσιν· ἡ δὲ Λευκασία καὶ Ἄμφιτος συμβάλλουσιν ἐς τὸ αὐτὸ τὰ ῥεύματα.", "st": "4.33"}, {"sp": "N", "t": "διαβάντι δὲ τούτους πεδίον ἐστὶν ὀνομαζόμενον Στενυκληρικόν· εἶναι δὲ ἥρωα Στενύκληρον λέγουσι. τοῦ πεδίου δέ ἐστιν ἀπαντικρὺ καλουμένη τὸ ἀρχαῖον Οἰχαλία, τὸ δὲ ἐφ’ ἡμῶν Καρνάσιον ἄλσος, κυπαρίσσων μάλιστα πλῆρες. θεῶν δὲ ἀγάλματα Ἀπόλλωνός ἐστι Καρνείου ⟨καὶ Ἁγνῆς⟩ καὶ Ἑρμῆς φέρων κριόν. ἡ δὲ Ἁγνὴ Κόρης τῆς Δήμητρός ἐστιν ἐπίκλησις· ὕδωρ δὲ ἄνεισιν ἐκ πηγῆς παρ’ αὐτὸ τὸ ἄγαλμα.", "st": "4.33"}, {"sp": "N", "t": "τὰ δὲ ἐς τὰς θεὰς τὰς Μεγάλας—δρῶσι γὰρ καὶ ταύταις ἐν Καρνασίῳ τὴν τελετήν—ἀπόρρητα ἔστω μοι· δεύτερα γάρ σφισι νέμω σεμνότητος μετά γε Ἐλευσίνια. ὅτι δ’ ὑδρία τε ἡ χαλκῆ, τὸ εὕρημα τοῦ Ἀργείου στρατηγοῦ, καὶ Εὐρύτου τοῦ Μελανέως τὰ ὀστᾶ ἐφυλάσσετο ἐνταῦθα, δηλῶσαί με καὶ ἐς ἅπαντας οὐκ ἀπεῖργε τὸ ὄνειρον. ῥεῖ δὲ ποταμὸς παρὰ τὸ Καρνάσιον Χάραδρος, καὶ προελθόντι ἐν ἀριστερᾷ σταδίους ὀκτὼ", "st": "4.33"}, {"sp": "N", "t": "μάλιστα ἐρείπιά ἐστιν Ἀνδανίας. καὶ ὅτι μὲν τῇ πόλει τὸ ὄνομα ἀπὸ γυναικὸς γέγονεν Ἀνδανίας, ὁμολογεῖται ὑπὸ τῶν ἐξηγητῶν· οὐ μὴν τά γε ἐς τοὺς γονέας αὐτῆς οὐδὲ τῷ συνῴκησεν ἔχω λέγειν. ἰόντων δὲ ὡς ἐπὶ Κυπαρισσιὰς ἀπὸ Ἀνδανίας Πολίχνη τέ ἐστι καλουμένη καὶ ποταμὸς Ἠλέκτρα καὶ Κοῖος ῥέουσι· τάχα δ’ ἄν τινα καὶ λόγον ἐς Ἠλέκτραν τὴν Ἄτλαντος λέγοιεν καὶ ἐς Κοῖον τὸν Λητοῦς πατέρα, ἢ καὶ τῶν ἐπιχωρίων ἡρώων εἶεν Ἠλέκτρα τε καὶ Κοῖος.", "st": "4.33"}, {"sp": "N", "t": "διαβάντων δὲ Ἠλέκτραν Ἀχαΐα τε ὀνομαζομένη πηγὴ καὶ πόλεώς ἐστιν ἐρείπια Δωρίου. πεποίηκε δὲ Ὅμηρος μὲν Θαμύριδι ἐνταῦθα ἐν τῷ Δωρίῳ γενέσθαι τὴν συμφοράν, ὅτι καὶ αὐτὰς Μούσας νικήσειν ἔφασκεν ᾀδούσας· Πρόδικος δὲ Φωκαεὺς—εἰ δὴ τούτου τὰ ἐς τὴν Μινυάδα ἔπη—προσκεῖσθαί φησι Θαμύριδι ἐν Ἅιδου δίκην τοῦ ἐς τὰς Μούσας αὐχήματος. διεφθάρη δὲ ὁ Θάμυρις ἐμοὶ δοκεῖν ὑπὸ νόσου τοὺς ὀφθαλμούς, τὸ δὲ αὐτὸ καὶ Ὁμήρῳ συνέπεσεν ὕστερον· ἀλλ’ ὁ μὲν καὶ ἐς ἅπαν διετέλει ποιῶν, οὐ γάρ τι εἶκε τῇ συμφορᾷ, Θάμυρις δὲ καὶ τὴν ᾠδὴν ὑπὸ κακοῦ τοῦ παρόντος ἐξέλιπεν.", "st": "4.33"}, {"sp": "N", "t": "ἐκ δὲ Μεσσήνης ὑπὸ τοῦ Παμίσου τὸ στόμα ὁδὸς μὲν σταδίων ἐστὶν ὀγδοήκοντα, ῥεῖ δὲ ὁ Πάμισος διά τε ἀρουμένης καὶ καθαρὸς καὶ ἀναπλεῖται ναυσὶν ἐκ θαλάσσης ἐπὶ δέκα που σταδίους· ἀναθέουσι δὲ ἐς αὐτὸν καὶ οἱ θαλάσσιοι τῶν ἰχθύων περὶ ὥραν μάλιστα τοῦ ἦρος. τὸ δὲ αὐτὸ ἐς Ῥῆνόν τε καὶ ἐς τὸν Μαίανδρον ποιοῦσιν οἱ ἰχθῦς· μάλιστα δὲ ἀνὰ τὸ ῥεῦμα τὸ Ἀχελῴου νήχονται τοῦ ἐκδιδόντος κατὰ νήσους τὰς Ἐχινάδας.", "st": "4.34"}, {"sp": "N", "t": "διάφοροι δὲ τὸ εἶδος μάλιστα ἰχθῦς ἀναθέουσιν ἐς τὸν Πάμισον ἅτε ἐς ὕδωρ καθαρὸν καὶ οὐ κατὰ ⟨τὰ⟩ αὐτὰ τοῖς κατειλεγμένοις ποταμοῖς ἰλυῶδες· οἱ κέφαλοι δέ, ἅτε ἰχθύων ὄντες τῶν πηλαίων, ποταμῶν φίλοι τῶν θολερωτέρων εἰσί. θηρία δὲ ἐς ὄλεθρον ἀνθρώπων οὐ πεφύκασιν οἱ Ἑλλήνων ποταμοὶ φέρειν, καθάπερ γε Ἰνδὸς καὶ Νεῖλος ὁ Αἰγύπτιος, ἔτι δὲ Ῥῆνος καὶ Ἴστρος Εὐφράτης τε καὶ Φᾶσις· οὗτοι γὰρ δὴ θηρία ὅμοια τοῖς μάλιστα ἀνδροφάγα αὔξουσι, ταῖς ἐν Ἕρμῳ καὶ Μαιάνδρῳ γλάνισιν ἐοικότα ἰδέας πλὴν χρόας τε μελαντέρας καὶ ἀλκῆς· ταῦτα δὲ αἱ γλάνεις ἀποδέουσιν.", "st": "4.34"}, {"sp": "N", "t": "ὁ δὲ Ἰνδὸς καὶ ὁ Νεῖλος κροκοδείλους μὲν ἀμφότεροι, Νεῖλος δὲ παρέχεται καὶ ἵππους, οὐκ ἔλασσον ἢ ὁ κροκόδειλος κακὸν ἀνθρώποις. οἱ δὲ Ἑλλήνων ποταμοὶ δείματα ὡς ἀπὸ θηρίων εἰσὶν οὐδέν, ἐπεὶ καὶ Ἀώῳ τῷ διὰ τῆς Θεσπρωτίδος ῥέοντι ἠπείρου θηρία οὐ ποτάμια οἱ κύνες, ἀλλὰ ἐπήλυδές εἰσιν ἐκ θαλάσσης.", "st": "4.34"}, {"sp": "N", "t": "Κορώνη δέ ἐστι πόλις ἐν δεξιᾷ τοῦ Παμίσου πρὸς θαλάσσῃ τε καὶ ὑπὸ τῷ ὄρει τῇ Μαθίᾳ. κατὰ δὲ τὴν ὁδὸν ταύτην ἐστὶν ἐπὶ θαλάσσῃ χωρίον, ὃ Ἰνοῦς ἱερὸν εἶναι νομίζουσιν· ἐπαναβῆναι γὰρ ἐνταῦθα ἐκ θαλάσσης φασὶν αὐτὴν θεόν τε ἤδη νομιζομένην καὶ Λευκοθέαν καλουμένην ἀντὶ Ἰνοῦς. προελθόντων δὲ οὐ πολὺ Βίας ἐκδίδωσιν ἐς θάλασσαν ποταμός· γενέσθαι δὲ αὐτῷ λέγουσι τὸ ὄνομα ἀπὸ Βίαντος τοῦ Ἀμυθάονος. καὶ Πλατανιστῶνος δὲ ἡ πηγὴ στάδια μὲν εἴκοσίν ἐστιν ἀπωτέρω τῆς ὁδοῦ, ῥεῖ δὲ ἐκ πλατάνου τὸ ὕδωρ πλατείας καὶ τὰ ἐντὸς κοίλης· κατὰ σπήλαιον μάλιστά που μικρὸν τὸ εὖρός ἐστι τοῦ δένδρου, καὶ τὸ ὕδωρ αὐτόθεν ἐς Κορώνην τὸ πότιμον κάτεισι.", "st": "4.34"}, {"sp": "N", "t": "τὸ μὲν δὴ ὄνομα τὸ ἀρχαῖον εἶχεν Αἴπεια· ἐπεὶ δὲ ὑπὸ Θηβαίων κατήχθησαν ἐς Πελοπόννησον, Ἐπιμηλίδην φασὶν ἀποσταλέντα οἰκιστὴν καλέσαι Κορώνειαν, εἶναι γὰρ αὐτὸν ἐκ Κορωνείας τῆς Βοιωτῶν, τοὺς δὲ Μεσσηνίους ἐξ ἀρχῆς τε οὐ κατορθοῦν περὶ τὸ ὄνομα καὶ μᾶλλον ἔτι ἀνὰ χρόνον ἐκνικῆσαι τὸ ἐκείνων ἁμάρτημα. λέγεται δὲ καὶ ἕτερος λόγος, ὡς τοῦ τείχους τὰ θεμέλια ὀρύσσοντες ἐπιτύχοιεν κορώνῃ χαλκῇ.", "st": "4.34"}, {"sp": "N", "t": "θεῶν δέ ἐστιν ἐνταῦθα Ἀρτέμιδός τε καλουμένης Παιδοτρόφου καὶ Διονύσου καὶ Ἀσκληπιοῦ ναός· τῷ μὲν δὴ Ἀσκληπιῷ καὶ Διονύσῳ λίθου, Διὸς δὲ Σωτῆρος χαλκοῦν ἄγαλμα ἐπὶ τῆς ἀγορᾶς πεποίηται. χαλκοῦν δὲ καὶ ἐν ἀκροπόλει τῆς Ἀθηνᾶς τὸ ἄγαλμά ἐστιν ἐν ὑπαίθρῳ, κορώνην ἐν τῇ χειρὶ ἔχουσα. εἶδον δὲ καὶ τοῦ Ἐπιμηλίδου μνῆμα· ἐφ’ ὅτῳ δὲ τὸν λιμένα Ἀχαιῶν καλοῦσιν, οὐκ οἶδα.", "st": "4.34"}, {"sp": "N", "t": "ἐκ Κορώνης δὲ ὡς ὀγδοήκοντα σταδίους προελθόντι Ἀπόλλωνός ἐστιν ἱερὸν πρὸς θαλάσσῃ τιμὰς ἔχον· ἀρχαιότατόν τε γὰρ λόγῳ τῷ Μεσσηνίων ἐστὶ καὶ νοσήματα ὁ θεὸς ἰᾶται, Κόρυνθον δὲ Ἀπόλλωνα ὀνομάζουσι. τοῦτο μὲν δὴ ξόανον, τοῦ Ἀργεώτα δὲ χαλκοῦν ἐστι τὸ ἄγαλμα· ἀναθεῖναι δέ φασι τοὺς ἐν τῇ Ἀργοῖ πλεύσαντας.", "st": "4.34"}, {"sp": "N", "t": "τῇ Κορωναίων δὲ πόλει ἐστὶν ὅμορος Κολωνίδες· οἱ δὲ ἐνταῦθα οὐ Μεσσήνιοί φασιν εἶναι, ἀλλὰ ἐκ τῆς Ἀττικῆς ἀγαγεῖν σφᾶς Κόλαινον λέγουσι, Κολαίνῳ δὲ κόρυδον τὴν ὄρνιθα ἐκ μαντεύματος ἐς τὴν ἀποικίαν ἡγήσασθαι. ἔμελλον δὲ ἄρα διάλεκτόν τε ἀνὰ χρόνον καὶ ἔθη μεταμαθήσεσθαι τὰ Δωριέων. κεῖται δὲ τὸ πόλισμα αἱ Κολωνίδες ἐπὶ ὑψηλοῦ, μικρὸν ἀπὸ θαλάσσης.", "st": "4.34"}, {"sp": "N", "t": "Ἀσιναῖοι δὲ τὸ μὲν ἐξ ἀρχῆς Λυκωρίταις ὅμοροι περὶ τὸν Παρνασσὸν ᾤκουν· ὄνομα δὲ ἦν αὐτοῖς, ὃ δὴ καὶ ἐς Πελοπόννησον διεσώσαντο, ἀπὸ τοῦ οἰκιστοῦ Δρύοπες. γενεᾷ δὲ ὕστερον τρίτῃ βασιλεύοντος Φύλαντος μάχῃ τε οἱ Δρύοπες ὑπὸ Ἡρακλέους ἐκρατήθησαν καὶ τῷ Ἀπόλλωνι ἀνάθημα ἤχθησαν ἐς Δελφούς· ἀναχθέντες δὲ ἐς Πελοπόννησον χρήσαντος Ἡρακλεῖ τοῦ θεοῦ πρῶτα μὲν τὴν πρὸς Ἑρμιόνι Ἀσίνην ἔσχον, ἐκεῖθεν δὲ ἐκπεσόντες ὑπὸ Ἀργείων οἰκοῦσιν ἐν τῇ Μεσσηνίᾳ, Λακεδαιμονίων δόντων καὶ ὡς ἀνὰ χρόνον οἱ Μεσσήνιοι κατήχθησαν οὐ γενομένης σφίσιν ὑπ’ αὐτῶν ἀναστάτου τῆς πόλεως.", "st": "4.34"}, {"sp": "N", "t": "Ἀσιναῖοι δὲ αὐτοὶ περὶ σφῶν οὕτω λέγουσι· κρατηθῆναι μὲν ὑπὸ Ἡρακλέους μάχῃ συγχωροῦσιν ἁλῶναί τε τὴν ἐν τῷ Παρνασσῷ πόλιν, αἰχμάλωτοι δὲ γενέσθαι καὶ ἀχθῆναι παρὰ τὸν Ἀπόλλωνα οὔ φασιν· ἀλλ’ ὡς ἡλίσκετο ὑπὸ τοῦ Ἡρακλέους τὸ τεῖχος, ἐκλιπεῖν τὴν πόλιν καὶ ἀναφυγεῖν ἐς τὰ ἄκρα τοῦ Παρνασσοῦ, διαβάντες δὲ ὕστερον ναυσὶν ἐς Πελοπόννησον γενέσθαι φασὶν Εὐρυσθέως ἱκέται, καὶ σφίσιν Εὐρυσθέα ἅτε ἀπεχθανόμενον τῷ Ἡρακλεῖ δοῦναι τὴν ἐν τῇ Ἀργολίδι Ἀσίνην.", "st": "4.34"}, {"sp": "N", "t": "μόνοι δὲ τοῦ γένους τοῦ Δρυόπων οἱ Ἀσιναῖοι σεμνύνονται καὶ ἐς ἡμᾶς ἔτι τῷ ὀνόματι, οὐδὲν ὁμοίως καὶ Εὐβοέων οἱ Στύρα ἔχοντες. εἰσὶ γὰρ καὶ οἱ Στυρεῖς Δρύοπες τὸ ἐξ ἀρχῆς, ὅσοι τῆς πρὸς τὸν Ἡρακλέα οὐ μετέσχον μάχης, ἀπωτέρω τῆς πόλεως ἔχοντες τὰς οἰκήσεις· ἀλλὰ οἱ μὲν Στυρεῖς καλεῖσθαι Δρύοπες ὑπερφρονοῦσι, καθάπερ γε καὶ οἱ Δελφοὶ πεφεύγασιν ὀνομάζεσθαι Φωκεῖς, Ἀσιναῖοι δὲ Δρύοπές τε τὰ μάλιστα χαίρουσι καλούμενοι καὶ τῶν ἱερῶν τὰ ἁγιώτατά εἰσι δῆλοι κατὰ μνήμην πεποιημένοι τῶν ποτὲ ἐν Παρνασσῷ σφισιν ἱδρυμένων. τοῦτο μὲν γὰρ Ἀπόλλωνός ἐστιν αὐτοῖς ναός, τοῦτο δὲ Δρύοπος ἱερὸν καὶ ἄγαλμα ἀρχαῖον· ἄγουσι καὶ παρὰ ἔτος αὐτῷ τελετήν, παῖδα τὸν Δρύοπα Ἀπόλλωνος εἶναι λέγοντες.", "st": "4.34"}, {"sp": "N", "t": "κεῖται δὲ ἐπὶ θαλάσσῃ καὶ αὐτὴ κατὰ τὰ αὐτὰ τῇ ποτὲ ἐν μοίρᾳ τῇ Ἀργολίδι Ἀσίνῃ· σταδίων δὲ τεσσαράκοντά ἐστιν ἐκ Κολωνίδων ἐς αὐτὴν ὁδός, τοσαύτη δὲ καὶ ἐκ τῆς Ἀσίνης πρὸς τὸν Ἀκρίταν καλούμενον. ἀνέχει δὲ ἐς θάλασσαν ὁ Ἀκρίτας, καὶ νῆσος Θηγανοῦσσά ἐστιν ἔρημος πρὸ αὐτοῦ· μετὰ δὲ τὸν Ἀκρίταν λιμήν τε Φοινικοῦς καὶ νῆσοι κατ’ αὐτὸν Οἰνοῦσσαι.", "st": "4.34"}, {"sp": "N", "t": "Μοθώνη δέ, πρὶν ἢ τὴν στρατιὰν ἐς Τροίαν ἀθροισθῆναι καὶ ἐπὶ τοῦ πρὸς Ἰλίῳ πολέμου καλουμένη Πήδασος, μεταβέβληκεν ὕστερον τὸ ὄνομα, ὡς μὲν αὐτοὶ Μοθωναῖοι λέγουσιν, ἀπὸ τῆς Οἰνέως θυγατρός· Οἰνεῖ γὰρ τῷ Πορθάονος μετὰ ἅλωσιν Ἰλίου παρὰ Διομήδην ἀναχωρήσαντι ἐς Πελοπόννησον θυγατέρα φασὶν ἐκ παλλακῆς Μοθώνην γενέσθαι· δόξῃ δὲ ἐμῇ δέδωκε τῷ χωρίῳ τὸ ὄνομα ὁ Μόθων λίθος. οὗτος δέ σφισι καὶ ὁ ποιῶν τὸν λιμένα ἐστί· τόν τε γὰρ ἔσπλουν στενώτερον ταῖς ναυσὶν ἐργάζεται παρήκων ὕφαλος καὶ ἅμα μὴ ἐκ βυθοῦ ταράσσεσθαι τὸν κλύδωνα ἔρυμα ἕστηκεν.", "st": "4.35"}, {"sp": "N", "t": "ἐδήλωσα δὲ καὶ ἐν τοῖς ἔμπροσθεν λόγοις ὅτι Ναυπλιεῦσιν ἐπὶ λακωνισμῷ διωχθεῖσι Δαμοκρατίδα βασιλεύοντος ἐν Ἄργει Μοθώνην Λακεδαιμόνιοι διδόασι καὶ ὡς οὐδὲ ἐκ τῶν Μεσσηνίων κατελθόντων ἐγένετο οὐδὲν ἐς αὐτοὺς νεώτερον· ἦσαν δὲ οἱ Ναυπλιεῖς ἐμοὶ δοκεῖν Αἰγύπτιοι τὰ παλαιότερα, παραγενόμενοι δὲ ὁμοῦ Δαναῷ ναυσὶν ἐς τὴν Ἀργολίδα ὕστερον γενεαῖς τρισὶν ὑπὸ Ναυπλίου τοῦ Ἀμυμώνης κατῳκίσθησαν ἐν Ναυπλίᾳ.", "st": "4.35"}, {"sp": "N", "t": "Μοθωναίοις δὲ βασιλεὺς μὲν Τραϊανὸς ἔδωκεν ἐλευθέρους ὄντας ἐν αὐτονομίᾳ πολιτεύεσθαι· τὰ δὲ ἔτι παλαιότερα μόνοις σφίσι Μεσσηνίων τῶν ἐπὶ θαλάσσῃ τοιόνδε ἀτύχημα ἰδίᾳ συνέβη γενέσθαι. τὰ ἐν Ἠπείρῳ τῇ Θεσπρωτίδι ὑπὸ ἀναρχίας ἐφθάρη· Δηιδαμείᾳ γὰρ τῇ Πύρρου παῖδες οὐκ ἐγένοντο, ἀλλὰ ὡς τελευτᾶν ἔμελλεν, ἐπιτρέπει τῷ δήμῳ τὰ πράγματα. θυγάτηρ δὲ ἦν Πύρρου τοῦ Πτολεμαίου τοῦ Ἀλεξάνδρου τοῦ Πύρρου·", "st": "4.35"}, {"sp": "N", "t": "τὰ δὲ ἐς Πύρρον τὸν Αἰακίδου πρότερον ἔτι ἐν τῷ λόγῳ τῷ ἐς Ἀθηναίους ἐδήλωσα, Προκλῆς δὲ ὁ Καρχηδόνιος τύχης μὲν χρηστῆς ἕνεκα καὶ διὰ λαμπρότητα ἔργων ἔνεμεν Ἀλεξάνδρῳ τᾷ Φιλίππου πλέον, τάξαι δὲ ὁπλίτας τε καὶ ἱππικὸν καὶ στρατηγήματα ἐπὶ ἄνδρας πολεμίους εὑρεῖν Πύρρον ἔφασκεν ἀμείνονα γενέσθαι.", "st": "4.35"}, {"sp": "N", "t": "Ἠπειρῶται δὲ ὡς ἐπαύσαντο βασιλεύεσθαι, τά τε ἄλλα ὁ δῆμος ὕβριζε καὶ ἀκροᾶσθαι τῶν ἐν ταῖς ἀρχαῖς ὑπερεώρων· καὶ σφᾶς οἱ Ἰλλυριοὶ τὰ πρὸς τοῦ Ἰονίου τὴν Ἤπειρον ὑπεροικοῦντες παρεστήσαντο ἐξ ἐπιδρομῆς. οὐ γάρ πω δημοκρατίαν ἴσμεν ἄλλους γε ἢ Ἀθηναίους αὐξήσαντας, Ἀθηναῖοι δὲ προήχθησαν ἐπὶ μέγα ἀπ’ αὐτῆς· συνέσει γὰρ οἰκείᾳ τὸ Ἑλληνικὸν ὑπερεβάλλοντο καὶ νόμοις τοῖς καθεστηκόσιν ἐλάχιστα ἠπείθουν.", "st": "4.35"}, {"sp": "N", "t": "οἱ δὲ Ἰλλυριοί, ἀρχῆς τε γεγευμένοι καὶ ἐπιθυμοῦντες ἀεὶ τοῦ πλείονος, ναῦς τε ἐπήξαντο καὶ ἐληίζοντο ἄλλους τε ὡς ἑκάστους τύχοιεν καὶ ἐς τὴν Μοθωναίαν σχόντες ὡρμίσαντο οἷα ἐς φιλίαν· στείλαντες δὲ ἄγγελον ἐς τὴν πόλιν ἄγειν σφίσιν οἶνον ἐπὶ τὰ πλοῖα ἐδεήθησαν. ὡς δὲ ἄγοντες ἀφίκοντο ἄνδρες οὐ πολλοί, τόν τε οἶνον ὠνοῦντο ἐπιτιμώντων τῶν Μοθωναίων καὶ αὐτοί σφισιν ἐπίπρασκον ὧν ἐπήγοντο.", "st": "4.35"}, {"sp": "N", "t": "ἐς δὲ τὴν ἐπιοῦσαν ἀφικομένων ἐκ τῆς πόλεως πλειόνων παρέχουσι καὶ τοῖσδε κερδᾶναι· τέλος δὲ γυναῖκες καὶ ἄνδρες κατίασιν ἐπὶ τὰ πλοῖα οἶνόν τε ἀποδόσθαι καὶ ἐκ τῶν βαρβάρων ἀντιληψόμενοι. ἔνθα νῦν ἀποτολμήσαντες οἱ Ἰλλυριοὶ καὶ ἄνδρας πολλοὺς καὶ ἔτι πλείονας τῶν γυναικῶν ἁρπάζουσιν· ἐσθέμενοι δὲ ἐς τὰς ναῦς ἔπλεον τὴν ἐπὶ Ἰονίου, Μοθωναίων ἐρημώσαντες τὸ ἄστυ.", "st": "4.35"}, {"sp": "N", "t": "ἐν Μοθώνῃ δὲ ναός ἐστιν Ἀθηνᾶς Ἀνεμώτιδος· Διομήδην δὲ τὸ ἄγαλμα ἀναθεῖναι καὶ τὸ ὄνομα τῇ θεῷ φασι θέσθαι. βιαιότεροι γὰρ καὶ οὐ κατὰ καιρὸν πνέοντες ἐλυμαίνοντο οἱ ἄνεμοι τὴν χώραν· Διομήδους δὲ εὐξαμένου τῇ Ἀθηνᾷ, τὸ ἀπὸ τούτου συμφορά σφισιν οὐδεμία ἀνέμων γε ἕνεκα ἦλθεν ἐς τὴν γῆν. καὶ Ἀρτέμιδος δ’ ἱερόν ἐστιν ἐνταῦθα καὶ ὕδωρ ἐν φρέατι κεκραμένον πίσσῃ, Κυζικηνῷ μύρῳ μάλιστα ἰδεῖν ἐμφερές· παράσχοιτο δ’ ἂν πᾶσαν καὶ χρόαν ὕδωρ καὶ ὀσμήν.", "st": "4.35"}, {"sp": "N", "t": "γλαυκότατον μὲν οἶδα ὕδωρ θεασάμενος τὸ ἐν Θερμοπύλαις, οὔτι που πᾶν, ἀλλ’ ὅσον κάτεισιν ἐς τὴν κολυμβήθραν ἥντινα ὀνομάζουσιν οἱ ἐπιχώριοι Χύτρους γυναικείους· ξανθὸν δὲ ὕδωρ, οὐδέν τι ἀποδέον τὴν χρόαν αἵματος, Ἑβραίων ἡ γῆ παρέχεται πρὸς Ἰόππῃ πόλει· θαλάσσης μὲν ἐγγυτάτω τὸ ὕδωρ ἐστί, λόγον δὲ ἐς τὴν πηγὴν λέγουσιν οἱ ταύτῃ, Περσέα ἀνελόντα τὸ κῆτος, ᾧ τὴν παῖδα προκεῖσθαι τοῦ Κηφέως, ἐνταῦθα τὸ αἷμα ἀπονίψασθαι.", "st": "4.35"}, {"sp": "N", "t": "ὕδωρ δὲ ἀπὸ πηγῶν ἀνερχόμενον μέλαν ἰδὼν οἶδα ἐν Ἀστύροις· τὰ δὲ Ἄστυρα ἀπαντικρὺ Λέσβου λουτρά ἐστι θερμὰ ἐν τῷ Ἀταρνεῖ καλουμένῳ. τὸ δὲ χωρίον ἐστὶν ὁ Ἀταρνεὺς ὁ Χίων μισθός, ὃν παρὰ τοῦ Μήδου λαμβάνουσιν ἄνδρα ἐκδόντες ἱκέτην, Πακτύην τὸν Λυδόν. τοῦτο μὲν δὴ μελαίνεται, Ῥωμαίοις δὲ ὑπὲρ τὴν πόλιν, διαβάντων τὸν Ἄνιον ὀνομαζόμενον ποταμόν, ὕδωρ λευκόν ἐστιν· ἀνδρὶ δὲ ἐσβάντι ἐς αὐτὸ τὸ μὲν παραυτίκα ψυχρόν τε πρόσεισι καὶ ἐμποιεῖ φρίκην, ἐπισχόντι δὲ ὀλίγον ἅτε φάρμακον θερμαίνει τὸ πυρωδέστατον.", "st": "4.35"}, {"sp": "N", "t": "καὶ ὅσαις μὲν πηγαῖς θαῦμά τι ἦν καὶ ἰδόντι, τοσαύτας θεασάμενος οἶδα, τὰς γὰρ δὴ ἐλάσσονος θαύματος ἐπιστάμενος παρίημι· ἁλμυρὸν δὲ ὕδωρ καὶ στρυφνὸν οὐ μέγα θαῦμα ἐξευρεῖν. δύο δὲ ἀλλοῖα· τὸ μὲν τῆς Καρίας ἐν πεδίῳ καλουμένῳ Λευκῷ θερμόν ἐστιν ὕδωρ παρὰ κώμην ὀνομαζομένην Δασκύλου, πιεῖν καὶ γάλακτος ἥδιον· τὸν δὲ Ἡρόδοτον οἶδα εἰπόντα ὡς ἐς τὸν ποταμὸν τὸν Ὕπανιν ἐκδίδωσιν ὕδατος πικροῦ πηγή. πῶς δ’ ἂν οὐκ ἀποδεξαίμεθα ἀληθεύειν αὐτῷ τὸν λόγον, ὅπου γε καὶ ἐφ’ ἡμῶν ἐν Δικαιαρχίᾳ τῇ Τυρρηνῶν ἐξεύρηται ὕδωρ σφίσι θερμὸν οὕτω δή τι ὀξὺ ὥστε τὸν μόλυβδον—διεξῄει γὰρ διὰ μολύβδου ῥέον —ἔτεσι κατέτηξεν οὐ πολλοῖς;", "st": "4.35"}, {"sp": "N", "t": "ἔστι δὲ ἐκ Μοθώνης ὁδὸς σταδίων μάλιστα ἑκατὸν ἐπὶ τὴν ἄκραν τὸ Κορυφάσιον· ἐπ’ αὐτῇ δὲ ἡ Πύλος κεῖται. ταύτην ᾤκισε Πύλος ὁ Κλήσωνος ἀγαγὼν ἐκ τῆς Μεγαρίδος τοὺς ἔχοντας τότε αὐτὴν Λέλεγας· καὶ τῆς μὲν οὐκ ὤνατο ὑπὸ Νηλέως καὶ τῶν ἐξ Ἰωλκοῦ Πελασγῶν ἐκβληθείς, ἀποχωρήσας δὲ ἐς τὴν ὅμορον ἔσχεν ἐνταῦθα Πύλον τὴν ἐν τῇ Ἠλείᾳ. Νηλεὺς δὲ βασιλεύσας ἐς τοσοῦτο προήγαγεν ἀξιώματος τὴν Πύλον ὡς καὶ Ὅμηρον ἐν τοῖς ἔπεσιν ἄστυ ἐπονομάσαι Νηλήιον.", "st": "4.36"}, {"sp": "N", "t": "ἐνταῦθα ἱερόν ἐστιν Ἀθηνᾶς ἐπίκλησιν Κορυφασίας καὶ οἶκος καλούμενος Νέστορος· ἐν δὲ αὐτῷ καὶ ὁ Νέστωρ γέγραπται· καὶ μνῆμα ἐντὸς τῆς πόλεώς ἐστιν αὐτῷ, τὸ δὲ ὀλίγον ἀπωτέρω τῆς Πύλου Θρασυμήδους φασὶν εἶναι. καὶ σπήλαιόν ἐστιν ἐντὸς τῆς πόλεως· βοῦς δὲ ἐνταῦθα τὰς Νέστορος καὶ ἔτι πρότερον Νηλέως φασὶν αὐλίζεσθαι.", "st": "4.36"}, {"sp": "N", "t": "εἴη δ’ ἂν Θεσσαλικὸν τὸ γένος τῶν βοῶν τούτων, Ἰφίκλου ποτὲ τοῦ Πρωτεσιλάου πατρός· ταύτας γὰρ δὴ τὰς βοῦς Νηλεὺς ἕδνα ἐπὶ τῇ θυγατρὶ ᾔτει τοὺς μνωμένους, καὶ τούτων ἕνεκα ὁ Μελάμπους χαριζόμενος τῷ ἀδελφῷ Βίαντι ἀφίκετο ἐς τὴν Θεσσαλίαν, καὶ ἐδέθη μὲν ὑπὸ τῶν βουκόλων τοῦ Ἰφίκλου, λαμβάνει δὲ μισθὸν ἐφ’ οἷς αὐτῷ δεηθέντι ἐμαντεύσατο. ἐσπουδάκεσαν δὲ ἄρα οἱ τότε πλοῦτόν τινα συλλέγεσθαι τοιοῦτον, ἵππων καὶ βοῶν ἀγέλας, εἰ δὴ Νηλεύς τε γενέσθαι οἱ βοῦς ἐπεθύμησε τὰς Ἰφίκλου καὶ Ἡρακλεῖ κατὰ δόξαν τῶν ἐν Ἰβηρίᾳ βοῶν προσέταξεν Εὐρυσθεὺς ἐλάσαι τῶν Γηρυόνου βοῶν τὴν ἀγέλην.", "st": "4.36"}, {"sp": "N", "t": "φαίνεται δὲ καὶ Ἔρυξ τότε ἐν Σικελίᾳ δυναστεύων δριμὺν οὕτως ἔχων ἐς τὰς βοῦς τὰς ἐξ Ἐρυθείας ἔρωτα, ὥστε καὶ ἐπάλαισε πρὸς τὸν Ἡρακλέα ἆθλα ἐπὶ τῇ πάλῃ καταθέμενος τάς τε βοῦς ταύτας καὶ ἀρχὴν τὴν ἑαυτοῦ. πεποίηκε δὲ καὶ Ὅμηρος ἐν Ἰλιάδι, ὡς Ἰφιδάμας ὁ Ἀντήνορος τὰ πρῶτα τῶν ἕδνων ἑκατὸν βοῦς τῷ πενθερῷ δοίη. ταῦτα μὲν τὸν λόγον μοι βεβαιοῖ, βουσὶ τοὺς τότε χαίρειν μάλιστα ἀνθρώπους·", "st": "4.36"}, {"sp": "N", "t": "ἐνέμοντο δὲ ἐμοὶ δοκεῖν αἱ τοῦ Νηλέως βοῦς ἐν τῇ ὑπερορίᾳ τὰ πολλά· ὑπόψαμμός τε γάρ ἐστιν ὡς ἐπίπαν ἡ τῶν Πυλίων χώρα καὶ πόαν βουσὶν οὐχ ἱκανὴ τοσαύτην παρασχέσθαι. μαρτυρεῖ δέ μοι καὶ Ὅμηρος ἐν μνήμῃ Νέστορος ἐπιλέγων ἀεὶ βασιλέα αὐτὸν ἠμαθόεντος εἶναι Πύλου.", "st": "4.36"}, {"sp": "N", "t": "τοῦ λιμένος δὲ ἡ Σφακτηρία νῆσος προβέβληται, καθάπερ τοῦ ὅρμου τοῦ Δηλίων ἡ Ῥήνεια· ἐοίκασι δὲ αἱ ἀνθρώπειαι τύχαι καὶ χωρία τέως ἄγνωστα ἐς δόξαν προῆχθαι. Καφηρέως τε γάρ ἐστιν ὄνομα τοῦ ἐν Εὐβοίᾳ τοῖς σὺν Ἀγαμέμνονι Ἕλλησιν ἐπιγενομένου χειμῶνος ἐνταῦθα, ὡς ἐκομίζοντο ἐξ Ἰλίου· Ψυττάλειάν τε τὴν ἐπὶ Σαλαμῖνι ἴσμεν ἀπολομένων ἐν αὐτῇ τῶν Μήδων. ὡσαύτως δὲ καὶ τὴν Σφακτηρίαν τὸ ἀτύχημα τὸ Λακεδαιμονίων γνώριμον τοῖς πᾶσιν ἐποίησεν· Ἀθηναῖοι δὲ καὶ Νίκης ἀνέθηκαν ἄγαλμα ἐν ἀκροπόλει χαλκοῦν ἐς μνήμην τῶν ἐν τῇ Σφακτηρίᾳ.", "st": "4.36"}, {"sp": "N", "t": "ἀφικομένων δὲ ἐς Κυπαρισσιὰς ἐκ Πύλου σφίσι πηγὴ ὑπὸ τῇ πόλει πλησίον θαλάσσης ἐστί· ῥυῆναι δὲ Διονύσῳ τὸ ὕδωρ λέγουσι θύρσῳ πλήξαντι ἐς τὴν γῆν, καὶ ἐπὶ τούτῳ Διονυσιάδα ὀνομάζουσι τὴν πηγήν. ἔστι δὲ καὶ Ἀπόλλωνος ἐν Κυπαρισσιαῖς ἱερὸν καὶ Ἀθηνᾶς ἐπίκλησιν Κυπαρισσίας. ἐν δὲ Αὐλῶνι καλουμένῳ ναὸς Ἀσκληπιοῦ καὶ ἄγαλμά ἐστιν Αὐλωνίου· κατὰ τοῦτο ὁ ποταμὸς ἡ Νέδα μεταξὺ τῆς τε Μεσσηνίας ἤδη καὶ τῆς Ἠλείας διέξεισιν.", "st": "4.36"}], []);})();
